INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pmagnomuller/ai-workflow-cursor-config/pr-with-docs', 'pr-with-docs', 'pmagnomuller', 'ai-workflow-cursor-config', 'community', 'pr-with-docs pmagnomuller ai-workflow-cursor-config community The pr-with-docs skill automates the process of creating pull requests and updating AGENTS.md for AI agents. It benefits developers by simplifying the Git workflow. PR with Docs 是一个结构化的自动化系统，用于分析代码变更、更新文档和创建拉取请求 PR with Docs は、コード変更を分析し、ドキュメントを更新し、プルリクエストを作成するための構造化された自動化システムです PR with Docs 는 코드 변경을 분석하고 문서를 업데이트하고 풀 리퀘스트를 생성하기 위한 구조화된 자동화 시스템입니다 El agente pr-with-docs es un sistema de automatización estructurado para el editor de código Cursor AI, que analiza cambios y actualiza AGENTS.md L''agent pr-with-docs est un système d''automatisation structuré pour l''éditeur de code Cursor AI, qui analyse les modifications et met à jour AGENTS.md Der Agent pr-with-docs ist ein strukturiertes Automatisierungssystem für den Code-Editor Cursor AI, das Änderungen analysiert und AGENTS.md aktualisiert O PR com documentos é um sistema de automação estruturado para o editor de código Cursor AI, permitindo a análise de alterações e atualização de documentos PR с документами - это структурированная система автоматизации для редактора кода Cursor AI, позволяющая анализировать изменения и обновлять документы طلب السحب مع الوثائق هو نظام تلقائي متكامل لتعديل Cursor AI، يسمح بتحليل التغييرات وتحديث الوثائق how to use pr-with-docs pr-with-docs setup guide automated pull request workflow pr-with-docs vs manual git workflow what is pr-with-docs pr-with-docs install pr-with-docs alternative pr-with-docs tutorial pr-with-docs and AGENTS.md pr-with-docs for AI agents PR with Docs AI 工作流程配置 代码审查 文档更新 自动化工具 Git 工作流程 拉取请求 代码变更分析 Analyzes changes in modified, added, and deleted files in the current branch Identifies scope of changes, including features, bug fixes, and refactors Detects changes that require updates to AGENTS.md Runs the Git workflow to create a pull request Updates .cursor/rules if relevant changes are detected Examines files to determine the need for AGENTS.md updates pr-with-docs is a structured automation system for analyzing changes, updating AGENTS.md, and creating pull requests in the Cursor AI code-editor.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('segal-noam/p2cs_project/add-step', 'community', 'segal-noam', 'p2cs_project', 'segal-noam/p2cs_project', 'add-step', 0, 0, 50, '2026-03-08T01:57:15.473Z', '2026-03-08T02:09:40.111Z', '6a4d989c7df144796bc61a72660cbe42611404eb358bd21ad5f8ce0c891193a4', '{"id":"segal-noam/p2cs_project/add-step","name":"add-step","description":{"en":"The add-step skill enables developers to add new pipeline steps under code/step_{N}_{name}/ and manage existing steps. It benefits developers working on the p2cs_project.","zh":"Add Step技能用于在p2cs_project中添加新管道步骤，包括重新编号和依赖项配置","ja":"Add Step AIエージェントは、p2cs_projectに新しいパイプラインステップを追加し、再番号付けと依存関係の構成を行います","ko":"Add Step 기술은 p2cs_project에 새로운 파이프라인 단계를 추가하고 재번호 및 의존성 구성합니다","es":"El skill ''add-step'' permite agregar nuevos pasos en p2cs_project, insertándolos entre pasos existentes y renumerando los posteriores.","fr":"Le skill ''add-step'' permet d''ajouter de nouvelles étapes dans p2cs_project, en les insérant entre des étapes existantes et en renumérotant les suivantes.","de":"Das Skill ''add-step'' ermöglicht das Hinzufügen neuer Schritte in p2cs_project, indem es sie zwischen bestehenden Schritten einfügt und die nachfolgenden umnummeriert.","pt":"O add-step é uma habilidade para adicionar etapas de pipeline em projetos p2cs_project, permitindo a inserção de novas etapas e renumerando as existentes.","ru":"Add-step - это навык для вставки шагов в pipeline проектов p2cs_project, позволяющий добавлять новые шаги и перенумеровать существующие.","ar":"أداة add-step هي مهارة لإضافة خطوات إلى أنابيب العمل في مشاريع p2cs_project، مما يسمح بإضافة خطوات جديدة وإعادة ترقيم الخطوات الحالية."},"seo":{"title":{"en":"add-step: Pipeline Step Management Setup Guide | AI Agent...","zh":"添加步骤设置指南 - Add Step 技术文档","ja":"ステップ追加セットアップガイド - Add Step AIエージェント","ko":"단계 추가 설정 가이드 - Add Step 기술 문서","es":"Guía de configuración para agregar pasos en p2cs_project","fr":"Guide d''installation pour ajouter des étapes dans p2cs_pr...","de":"Einrichtungsleitfaden zum Hinzufügen von Schritten in p2c...","pt":"Guia de Configuração do add-step: Adicionando Etapas de P...","ru":"ИИ Агенты: Настройка add-step для Вставки Шагов в Pipeline","ar":"إعداد أداة add-step: إضافة خطوات إلى أنابيب العمل"},"description":{"en":"Discover how to efficiently manage pipeline steps with add-step. Learn to insert, renumber, and configure steps with ease. Get started now!","zh":"了解如何使用Add Step技能在p2cs_project中添加新管道步骤，包括重新编号和依赖项配置","ja":"Add Step AIエージェントを使用してp2cs_projectに新しいパイプラインステップを追加する方法を学びます","ko":"Add Step 기술을 사용하여 p2cs_project에 새로운 파이프라인 단계를 추가하고 재编号 및 의존성 구성하는 방법","es":"Aprende a agregar pasos en p2cs_project con nuestra guía paso a paso. Descubre cómo insertar nuevos pasos y renumerar los existentes.","fr":"Découvrez comment ajouter des étapes dans p2cs_project avec notre guide étape par étape. Apprenez à insérer de nouvelles étapes et à renuméroter les existantes.","de":"Erfahren Sie, wie Sie Schritte in p2cs_project hinzufügen, mit unserer Schritt-für-Schritt-Anleitung. Entdecken Sie, wie Sie neue Schritte einfügen und beste...","pt":"Aprenda a usar o add-step para adicionar etapas de pipeline em projetos p2cs_project, incluindo renumerando etapas existentes e configurando classes de etapas.","ru":"Откройте для себя, как использовать add-step для вставки шагов в pipeline проектов p2cs_project, включая перенумерацию существующих шагов и настройку классов...","ar":"تعرف على كيفية استخدام أداة add-step لإضافة خطوات إلى أنابيب العمل في مشاريع p2cs_project، بما في ذلك إعادة ترقيم الخطوات الحالية وتكوين فئات الخطوات."},"definition":{"en":"add-step is a project-specific skill for managing pipeline steps in the p2cs_project, allowing for efficient insertion and renumbering of steps.","zh":"Add Step是一种用于在p2cs_project中添加新管道步骤的技能","ja":"Add Stepは、p2cs_projectに新しいパイプラインステップを追加するためのAIエージェントです","ko":"Add Step는 p2cs_project에 새로운 파이프라인 단계를 추가하는 기술입니다","es":"El skill ''add-step'' es una herramienta de AI que permite agregar pasos en p2cs_project de manera eficiente.","fr":"Le skill ''add-step'' est un outil d''IA qui permet d''ajouter des étapes dans p2cs_project de manière efficace.","de":"Das Skill ''add-step'' ist ein AI-Tool, das das Hinzufügen von Schritten in p2cs_project auf effiziente Weise ermöglicht.","pt":"O add-step é uma habilidade de IA que adiciona etapas de pipeline em projetos p2cs_project.","ru":"Add-step - это навык ИИ, который вставляет шаги в pipeline проектов p2cs_project.","ar":"أداة add-step هي مهارة ذكاء اصطناعي لإضافة خطوات إلى أنابيب العمل في مشاريع p2cs_project."},"features":{"en":["Adds new pipeline steps under code/step_{N}_{name}/","Inserts steps between existing steps with automatic renumbering","Provides a checklist for creating step classes, substeps, and README files","Supports exploration with explore.ipynb","Manages wiring dependencies and configuration"],"zh":["支持在code/step_{N}_{name}/下添加新管道步骤","可以插入现有步骤之间并重新编号后续步骤","提供创建步骤类、子步骤、README、explore.ipynb和依赖项配置的检查清单","支持p2cs_project架构","可以配置依赖项和步骤之间的关系"],"ja":["code/step_{N}_{name}/以下に新しいパイプラインステップを追加することをサポート","既存のステップの間に挿入し、後のステップを再番号付けすることができる","ステップクラス、サブステップ、README、explore.ipynb、依存関係の構成の作成チェックリストを提供","p2cs_projectアーキテクチャをサポート","依存関係とステップ間の関係を構成することができる"],"ko":["code/step_{N}_{name}/以下에 새로운 파이프라인 단계를 추가하는 것을 지원","기존 단계 사이에 삽입하고 이후 단계를 재번호하는 것이 가능","단계 클래스, 서브 단계, README, explore.ipynb, 의존성 구성의 생성 체크리스트를 제공","p2cs_project 아키텍처를 지원","의존성과 단계 간의 관계를 구성하는 것이 가능"],"es":["Agregra nuevos pasos en p2cs_project","Inserta pasos entre existentes y renumera los posteriores","Crea una clase de paso y subpasos","Genera un archivo README y explore.ipynb","Configura dependencias y parámetros"],"fr":["Ajoute de nouvelles étapes dans p2cs_project","Insère des étapes entre des étapes existantes et renumérote les suivantes","Crée une classe d''étape et des sous-étapes","Génère un fichier README et explore.ipynb","Configure les dépendances et les paramètres"],"de":["Fügt neue Schritte in p2cs_project hinzu","Fügt Schritte zwischen bestehenden Schritten ein und nummeriert die nachfolgenden um","Erstellt eine Schritt-Klasse und Unter-Schritte","Erzeugt eine README-Datei und explore.ipynb","Konfiguriert Abhängigkeiten und Parameter"],"pt":["Adiciona etapas de pipeline em projetos p2cs_project","Permite a inserção de novas etapas entre etapas existentes","Renumerando etapas existentes","Configuração de classes de etapas","Criação de checklist para etapas","Suporte a arquitetura de pipeline personalizada"],"ru":["Вставляет шаги в pipeline проектов p2cs_project","Позволяет добавлять новые шаги между существующими шагами","Перенумерация существующих шагов","Настройка классов шагов","Создание чек-листа для шагов","Поддержка настраиваемой архитектуры pipeline"],"ar":["تضيف خطوات إلى أنابيب العمل في مشاريع p2cs_project","تمكن من إضافة خطوات جديدة بين الخطوات الحالية","إعادة ترقيم الخطوات الحالية","تكوين فئات الخطوات","إنشاء قائمة مراجعة للخطوات","دعم بنية أنابيب العمل المخصصة"]},"keywords":{"en":["how to use add-step","add-step setup guide","add-step pipeline step management","p2cs_project pipeline steps","add-step vs pipeline management tools","add-step install for p2cs_project"],"zh":["Add Step","p2cs_project","管道步骤","重新编号","依赖项配置","AI技术","技能文档","设置指南"],"ja":["Add Step","p2cs_project","パイプラインステップ","再番号付け","依存関係の構成","AIエージェント","技術文書","セットアップガイド"],"ko":["Add Step","p2cs_project","파이프라인 단계","재번호","의존성 구성","AI기술","기술문서","설정 가이드"],"es":["agregar pasos en p2cs_project","herramientas de AI para desarrollo","p2cs_project tutorial","configuración de pasos","renumeración de pasos","creación de clases de paso","generación de archivos README"],"fr":["ajouter des étapes dans p2cs_project","outils d''IA pour le développement","tutoriel p2cs_project","configuration d''étapes","renumérotation d''étapes","création de classes d''étape","génération de fichiers README"],"de":["Schritte in p2cs_project hinzufügen","AI-Tools für die Entwicklung","p2cs_project-Tutorial","Schritt-Konfiguration","Umnummerierung von Schritten","Erstellung von Schritt-Klassen","Erzeugung von README-Dateien"],"pt":["add-step","pipeline","p2cs_project","etapas de pipeline","inserção de etapas","renumerando etapas","configuração de classes de etapas","criação de checklist","arquitetura de pipeline personalizada"],"ru":["add-step","pipeline","p2cs_project","шаги pipeline","вставка шагов","перенумерация шагов","настройка классов шагов","создание чек-листа","настраиваемая архитектура pipeline","ИИ Агенты"],"ar":["add-step","أنابيب العمل","p2cs_project","خطوات أنابيب العمل","إضافة خطوات","إعادة ترقيم الخطوات","تكوين فئات الخطوات","إنشاء قائمة مراجعة","بنية أنابيب العمل المخصصة","أدوات الذكاء الاصطناعي"]}},"owner":"segal-noam","repo":"p2cs_project","repoPath":"segal-noam/p2cs_project","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.473Z","topics":[],"category":"community","skillMd":{"name":"add-step","description":"Add or insert a new numbered pipeline step in the p2cs_project, following the standardized Step/DataFile/explore notebook patterns and safely renumbering subsequent steps (code, data, figures, tests, config, dependencies, and imports) when inserting in the middle of the pipeline. Use when creating a new step_* directory, inserting a step between existing ones, or updating step numbers across the project.","bodyPreview":"# Add Step (p2cs_project)\n\n## When to Use\n\nUse this skill when:\n\n- A new pipeline step needs to be added under `code/step_{N}_{name}/`.\n- A step should be **inserted between existing steps**, requiring **renumbering** of later steps.\n- You need a checklist for creating the step class, substeps, README, `explore.ipynb`, and wiring dependencies/config.\n\nThis skill is **project-specific** to `p2cs_project` and assumes the architecture described in the root `README.md`.\n\n---\n\n## Overview: Step Patte","body":"# Add Step (p2cs_project)\n\n## When to Use\n\nUse this skill when:\n\n- A new pipeline step needs to be added under `code/step_{N}_{name}/`.\n- A step should be **inserted between existing steps**, requiring **renumbering** of later steps.\n- You need a checklist for creating the step class, substeps, README, `explore.ipynb`, and wiring dependencies/config.\n\nThis skill is **project-specific** to `p2cs_project` and assumes the architecture described in the root `README.md`.\n\n---\n\n## Overview: Step Pattern\n\nEach numbered step follows the same high-level pattern:\n\n- Directory: `code/step_{N}_{snake_name}/`\n  - `step.py`: main `Step{N}{CamelName}` class inheriting from `base.Step`.\n  - `data_classes.py`: data classes inheriting from `DataFile` subclasses (when the step has new artifacts).\n  - `__init__.py`: re-exports the main step class (and sometimes helper symbols).\n  - `README.md`: step-specific documentation (inputs, outputs, substeps, external tools).\n  - `explore.ipynb`: exploration notebook following the **standard notebook structure** from the root `README.md`.\n  - Numbered substeps: `1_*.py`, `2_*.py`, etc., each implementing focused logic.\n- Outputs in `data/step_{N}_{snake_name}/` and figures in `figures/step_{N}_{snake_name}/` are routed via `base.paths`.\n- The step is registered in:\n  - `pipeline_config.yaml` under `steps: step_{N}_{snake_name}: ...`\n  - Tests in `code/tests/test_step_{N}.py`.\n\n**Good templates to copy from:**\n\n- Simple single-substep data step: `step_4_prepare_pairs/`\n- Multi-substep data/tooling step: `step_2_organism_distance/`\n- Modeling/evaluation step: `step_6_train_model/`, `step_7_crosstalk_estimation/`\n\n---\n\n## Workflow A: Append a New Step at the End\n\n1. **Determine the new step index and name**\n   - Inspect existing numbered steps under `code/step_*`.\n   - Let `N_max` be the largest index (currently `8` for `step_8_generate_paper`).\n   - Choose:\n     - New index: `N_new = N_max + 1`\n     - Snake name: `step_{N_new}_{snake_name}`\n     - Class name: `Step{N_new}{CamelName}`\n\n2. **Create the step directory**\n   - Create `code/step_{N_new}_{snake_name}/` with at least:\n     - `__init__.py` (re-export the main step class).\n     - `step.py` (main step implementation).\n     - `README.md` (step documentation).\n     - `explore.ipynb` (exploration notebook).\n     - One or more numbered substeps `1_*.py`, `2_*.py`, etc.\n     - `data_classes.py` and/or `config.json` if this step defines new data types or config.\n   - **Recommended pattern:** Copy the closest existing step directory (e.g., `step_4_prepare_pairs/`) and rename/trim to match the new step’s responsibilities.\n\n3. **Implement the main step class**\n   - In `step.py`:\n     - Import `Step` and path helpers from `code/base/step.py` and `code/base/paths.py`.\n     - Define a class like:\n       - `class Step{N_new}{CamelName}(Step):`\n     - Implement:\n       - `name` and `description` properties (or class attributes).\n       - `dependencies` property returning a `List[str]` of upstream steps, using canonical IDs like `\"step_1_get_p2cs_data\"`.\n       - `get_input_paths()` and `get_output_paths()` using data classes and `get_step_input_path` / `get_step_output_path`.\n       - `run()` orchestrating any substeps via `self.run_substeps(...)`.\n\n4. **Define data classes (if needed)**\n   - In `data_classes.py`:\n     - Inherit from appropriate `DataFile` subclasses (e.g., `PickleDataFile`, `CSVDataFile`, `NumpyDataFile`).\n     - Define schemas, descriptions, and default loaders/savers as in existing steps.\n   - Use these data classes in `get_input_paths()` / `get_output_paths()` and in substeps.\n\n5. **Create numbered substeps**\n   - Add scripts `1_*.py`, `2_*.py`, etc. inside the new step directory.\n   - Follow existing substep patterns:\n     - Each substep is a small class/function using the step’s data classes and `paths` helpers.\n     - The main step’s `run()` calls `self.run_substeps(...)` with:\n       - Substep objects\n       - `step_numbers=[1, 2, ...]`\n       - `descriptions=[...]`\n       - Appropriate `on_failure` mode (`\"strict\"` or `\"warning\"`).\n\n6. **Create the step README**\n   - In `README.md`, mirror the structure used in other steps:\n     - Short description.\n     - Inputs (data classes, upstream steps).\n     - Outputs and their data classes.\n     - Substeps and what they do.\n     - Any external tools / configs required.\n\n7. **Create the `explore.ipynb` notebook**\n   - Follow the standard structure from the root `README.md`:\n     - `# Imports` (path setup + step/data class imports).\n     - `# Load Data`\n       - `## Load Inputs` (using `step.get_input_paths()` + data classes).\n       - `## Load Outputs`.\n     - `# Plot`\n       - Display saved figures from visualization substeps first.\n       - Put any extra exploratory plots after those.\n     - `# Notes` (short list of exploration ideas).\n   - Respect the **collapsible headings rule** (heading-only markdown cells).\n\n8. **Wire the step into `pipeline_config.yaml`**\n   - Under `steps:`, add a new entry:\n     - Key: `step_{N_new}_{snake_name}:`\n     - Fields: `enabled`, `description`, `overwrite_outputs`, optional `fast_plots`, and `substeps:`.\n   - Add a `substeps:` section keyed by the filenames (without `.py`), matching patterns in other steps.\n\n9. **Add tests**\n   - Create `code/tests/test_step_{N_new}.py` by copying a nearby test (e.g., `test_step_4.py`) and adjusting:\n     - Imports to the new step and data classes.\n     - Test names and assertions to cover the new step’s behavior.\n\n10. **Run tests / pipeline checks**\n    - Run `pytest code/tests/test_step_{N_new}.py`.\n    - Optionally run the step via:\n      - `cd code && python run_pipeline.py --step step_{N_new}_{snake_name}`\n\n---\n\n## Workflow B: Insert a Step in the Middle (with Renumbering)\n\nUse this when inserting a new step **between** existing steps (e.g., between `step_3_embed_proteins` and `step_4_prepare_pairs`).\n\n### B1. Plan the new ordering\n\n1. **Identify current step order**\n   - List existing `code/step_*` directories and their indices (including `step_0_draw_theoretical`).\n\n2. **Choose insertion point**\n   - Let:\n     - `N_insert_after` = index of the step **before** the new one.\n     - `N_new = N_insert_after + 1`.\n   - All steps with index `> N_insert_after` must be shifted **up by 1**:\n     - Old `k` → new `k + 1` for all `k > N_insert_after`.\n\n3. **Decide the new step’s ID**\n   - Choose:\n     - New directory name: `step_{N_new}_{snake_name}`.\n     - New class name: `Step{N_new}{CamelName}`.\n\n### B2. Renumber existing steps (highest → lowest)\n\nPerform renaming **from highest index down to `N_insert_after + 1`** to avoid collisions.\n\nFor each step index `k` in descending order where `k > N_insert_after`:\n\n1. **Compute new index**\n   - `k_new = k + 1`.\n\n2. **Rename step directories**\n   - Code: `code/step_{k}_{name}/` → `code/step_{k_new}_{name}/`.\n   - Data: `data/step_{k}_{name}/` → `data/step_{k_new}_{name}/` (if exists).\n   - Figures: `figures/step_{k}_{name}/` → `figures/step_{k_new}_{name}/` (if exists).\n\n3. **Rename tests**\n   - `code/tests/test_step_{k}.py` → `code/tests/test_step_{k_new}.py`.\n\n4. **Update configuration keys**\n   - In `pipeline_config.yaml`, change:\n     - `step_{k}_{name}:` → `step_{k_new}_{name}:`.\n\n5. **Update string references and imports**\n   - Use text search for `step_{k}_{name}` and `test_step_{k}` across the repo and update to the new IDs:\n     - Imports like `from step_{k}_{name}...`.\n     - Dependency lists in `dependencies` properties (e.g., `return [\"step_{k}_{name}\", ...]`).\n     - Any key strings that reference `step_{k}_{name}`.\n\n6. **Update doc references**\n   - In `README.md` files and notebooks, update any textual references to the old step name or number, if present.\n\n### B3. Add the new step\n\nAfter all affected steps `k > N_insert_after` have been shifted to `k + 1`:\n\n1. **Create `code/step_{N_new}_{snake_name}/`**\n   - Follow **Workflow A, steps 2–7** to:\n     - Implement `step.py` and `data_classes.py`.\n     - Add numbered substeps.\n     - Add `README.md`.\n     - Add `explore.ipynb`.\n\n2. **Wire into `pipeline_config.yaml`**\n   - Under `steps:` add:\n     - `step_{N_new}_{snake_name}:` with its configuration and `substeps`.\n\n3. **Update dependencies**\n   - For the new step:\n     - Set `dependencies` to the upstream steps, using the **renumbered IDs**.\n   - For downstream steps:\n     - Review their `dependencies` properties:\n       - Replace any old IDs that were shifted, and add the new step as a dependency where appropriate.\n\n4. **Add test file**\n   - Create `code/tests/test_step_{N_new}.py` following neighboring step tests.\n\n5. **Sanity check references**\n   - Run a repo-wide search for any **old** step IDs (`step_{k}_{name}` where `k` was renumbered) and ensure:\n     - All references are either removed or updated to the new IDs.\n\n### B4. Validate after renumbering\n\n1. **Run targeted tests**\n   - Run:\n     - `cd code && pytest tests/test_step_{N_new}.py`\n     - Plus tests for all renumbered steps: `test_step_{k_new}.py`.\n\n2. **Run a dry pipeline**\n   - Optionally run:\n     - `cd code && python run_pipeline.py --list-steps` to confirm updated IDs and ordering.\n     - `cd code && python run_pipeline.py --step step_{N_new}_{snake_name}` to test the new step in context.\n\n---\n\n## Notebook Guidelines (Quick Reference)\n\nWhen creating or editing `explore.ipynb` for a step:\n\n- Follow the standard sections:\n  - `# Imports`\n  - `# Load Data`\n    - `## Load Inputs`\n    - `## Load Outputs`\n  - `# Plot`\n  - `# Notes`\n- Ensure each heading is in its **own markdown cell** to enable collapsible sections.\n- Use the data classes for loading inputs/outputs, not raw paths.\n- Display visualization substep figures first under `# Plot`; additional exploratory plots come after.\n\n---\n\n## Usage Summary\n\nWhen asked to **add a new step**:\n\n1. Decide whether it is an **append** (Workflow A) or **insert with renumbering** (Workflow B).\n2. Follow the appropriate workflow carefully, especially:\n   - Directory and file naming: `step_{N}_{snake_name}`, `test_step_{N}.py`.\n   - Dependency updates and imports.\n   - `pipeline_config.yaml` step and substep entries.\n   - `explore.ipynb` structure and data class usage.\n3. Always finish by running the relevant tests and, if feasible, a pipeline run of the new step.\n\n"},"lastSynced":"2026-03-08T02:09:40.111Z","agentAnalysis":{"suitability":{"en":"Perfect for Pipeline Management Agents needing to dynamically add and manage pipeline steps under code/step_{N}_{name}/.","zh":"Perfect for Pipeline Management Agents 需要动态添加和管理 pipeline 步骤 under code/step_{N}_{name}/。","ja":"Pipeline Management Agents がパイプラインのステップを動的に追加および管理する必要がある場合に適しています。code/step_{N}_{name}/ 下で。","ko":"파이프라인 관리 에이전트가 코드/step_{N}_{name}/ 아래에서 동적으로 파이프라인 단계를 추가 및 관리해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Gestión de Pipeline que necesitan agregar y gestionar dinámicamente los pasos del pipeline bajo code/step_{N}_{name}/.","fr":"Idéal pour les Agents de Gestion de Pipeline ayant besoin d''ajouter et de gérer dynamiquement les étapes du pipeline sous code/step_{N}_{name}/.","de":"Perfekt für Pipeline-Management-Agents, die Pipeline-Schritte dynamisch unter code/step_{N}_{name}/. hinzufügen und verwalten müssen.","pt":"Perfeito para Agentes de Gerenciamento de Pipeline que precisam adicionar e gerenciar dinamicamente etapas de pipeline em code/step_{N}_{name}/.","ru":"Идеально подходит для агентов управления конвейером, которым необходимо динамически добавлять и управлять шагами конвейера в code/step_{N}_{name}/.","ar":"مثالي لعميل إدارة أنابيب يحتاج إلى إضافة وإدارة خطوات الأنابيب بشكل ديناميكي في code/step_{N}_{name}/."},"recommendation":{"en":"Empowers agents to efficiently insert new pipeline steps, renumber existing steps, and manage dependencies, utilizing project-specific architecture and checklist-driven development with README, explore.ipynb, and wiring dependencies/config.","zh":"赋予代理高效地插入新建的 pipeline 步骤、重新编号现有的步骤以及管理依赖，利用项目特定的架构和带有 README、explore.ipynb 和 wiring 依赖/config 的清单驱动开发。","ja":"エージェントが新しいパイプラインのステップを効率的に挿入し、既存のステップを再番号付けし、依存関係を管理することを可能にします。プロジェクト固有のアーキテクチャと README、explore.ipynb、wiring 依存関係/config を使用したチェックリスト駆動開発を使用します。","ko":"에이전트가 새로운 파이프라인 단계를 효율적으로 삽입하고 기존 단계를 다시 번호 매기고 의존성을 관리할 수 있도록 합니다. 프로젝트 특정 아키텍처 및 README, explore.ipynb 및 wiring 의존성/config을 사용한 체크리스트 주도 개발을 사용합니다.","es":"Permite a los agentes insertar eficientemente nuevas etapas del pipeline, renumerar etapas existentes y gestionar dependencias, utilizando arquitectura específica del proyecto y desarrollo impulsado por listas de verificación con README, explore.ipynb y dependencias/config.","fr":"Permet aux agents d''insérer efficacement de nouvelles étapes du pipeline, de renuméroter les étapes existantes et de gérer les dépendances, en utilisant l''architecture spécifique du projet et le développement piloté par des listes de vérification avec README, explore.ipynb et les dépendances/config.","de":"Ermöglich es den Agenten, neue Pipeline-Schritte effizient einzufügen, bestehende Schritte umzunummerieren und Abhängigkeiten zu verwalten, unter Verwendung der projektspezifischen Architektur und der checklistengesteuerten Entwicklung mit README, explore.ipynb und Abhängigkeiten/config.","pt":"Habilita os agentes a inserir novas etapas de pipeline de forma eficiente, renumerar etapas existentes e gerenciar dependências, utilizando arquitetura específica do projeto e desenvolvimento orientado por lista de verificação com README, explore.ipynb e dependências/config.","ru":"Позволяет агентам эффективно вставлять новые шаги конвейера, перенумеровать существующие шаги и управлять зависимостями, используя архитектуру конкретного проекта и разработку, ориентированную на список проверки с README, explore.ipynb и зависимостями/config.","ar":"يمنح العملاء القدرة على إدراج خطوات أنابيب جديدة بفعالية، وإعادة ترقيم الخطوات الحالية، وإدارة التبعيات، باستخدام هندسة مشروع محددة وتطوير مدفوع بالتحقق من قائمة التحقق مع README، explore.ipynb وتبعيات /config."},"useCases":{"en":["Inserting new pipeline steps between existing ones","Renumbering later steps after insertion","Managing step class, substeps, and dependencies"],"zh":["在现有的步骤之间插入新的 pipeline 步骤","在插入后重新编号后续步骤","管理步骤类、子步骤和依赖"],"ja":["既存のステップの間に新しいパイプラインのステップを挿入する","挿入後に後のステップを再番号付けする","ステップ クラス、サブステップ、依存関係を管理する"],"ko":["기존 단계 사이에 새로운 파이프라인 단계 삽입","삽입 후 후속 단계를 다시 번호 매기기","단계 클래스, 서브 단계 및 의존성 관리"],"es":["Insertar nuevas etapas del pipeline entre las existentes","Renumerar etapas posteriores después de la inserción","Gestionar la clase de etapa, subetapas y dependencias"],"fr":["Insérer de nouvelles étapes du pipeline entre les étapes existantes","Renumberoter les étapes ultérieures après l''insertion","Gérer la classe d''étape, les sous-étapes et les dépendances"],"de":["Neue Pipeline-Schritte zwischen bestehenden einfügen","Spätere Schritte nach dem Einfügen umnumeronieren","Schrittklasse, Teilschritte und Abhängigkeiten verwalten"],"pt":["Inserindo novas etapas de pipeline entre as existentes","Renumerando etapas posteriores após a inserção","Gerenciando classe de etapa, subetapas e dependências"],"ru":["Вставка новых шагов конвейера между существующими","Перенумерация последующих шагов после вставки","Управление классом шага, подшагами и зависимостями"],"ar":["إدراج خطوات أنابيب جديدة بين الخطوات الحالية","إعادة ترقيم الخطوات اللاحقة بعد الإدراج","إدارة فئة الخطوة والخطوات الفرعية والتبعيات"]},"limitations":{"en":["Project-specific to p2cs_project","Requires adherence to architecture described in root README.md"],"zh":["特定于 p2cs_project 项目","需要遵守根目录下的 README.md 中描述的架构"],"ja":["p2cs_project プロジェクトに特有のものです","ルート ディレクトリの README.md で記述されているアーキテクチャに従う必要があります"],"ko":["p2cs_project 프로젝트에 특정","루트 디렉토리의 README.md에 설명된 아키텍처를 따라야 합니다"],"es":["Específico del proyecto p2cs_project","Requiere adherirse a la arquitectura descrita en el archivo README.md de la raíz"],"fr":["Spécifique au projet p2cs_project","Nécessite de se conformer à l''architecture décrite dans le fichier README.md de la racine"],"de":["Projektspezifisch für p2cs_project","Erfordert die Einhaltung der in der root-README.md beschriebenen Architektur"],"pt":["Específico do projeto p2cs_project","Exige aderência à arquitetura descrita no arquivo README.md raiz"],"ru":["Конкретный для проекта p2cs_project","Требует соблюдения архитектуры, описанной в корневом файле README.md"],"ar":["محدد لمشروع p2cs_project","يتطلب الالتزام بالهندسة الموصوفة في ملف README.md الجذري"]},"version":4},"contentHash":"6a4d989c7df144796bc61a72660cbe42611404eb358bd21ad5f8ce0c891193a4","qualityScore":50}');
