INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('segal-noam/p2cs_project/add-step', 'add-step', 'segal-noam', 'p2cs_project', 'community', 'add-step segal-noam p2cs_project community The add-step skill enables developers to add new pipeline steps under code/step_{N}_{name}/ and manage existing steps. It benefits developers working on the p2cs_project. Add Step技能用于在p2cs_project中添加新管道步骤，包括重新编号和依赖项配置 Add Step AIエージェントは、p2cs_projectに新しいパイプラインステップを追加し、再番号付けと依存関係の構成を行います Add Step 기술은 p2cs_project에 새로운 파이프라인 단계를 추가하고 재번호 및 의존성 구성합니다 El skill ''add-step'' permite agregar nuevos pasos en p2cs_project, insertándolos entre pasos existentes y renumerando los posteriores. Le skill ''add-step'' permet d''ajouter de nouvelles étapes dans p2cs_project, en les insérant entre des étapes existantes et en renumérotant les suivantes. Das Skill ''add-step'' ermöglicht das Hinzufügen neuer Schritte in p2cs_project, indem es sie zwischen bestehenden Schritten einfügt und die nachfolgenden umnummeriert. O add-step é uma habilidade para adicionar etapas de pipeline em projetos p2cs_project, permitindo a inserção de novas etapas e renumerando as existentes. Add-step - это навык для вставки шагов в pipeline проектов p2cs_project, позволяющий добавлять новые шаги и перенумеровать существующие. أداة add-step هي مهارة لإضافة خطوات إلى أنابيب العمل في مشاريع p2cs_project، مما يسمح بإضافة خطوات جديدة وإعادة ترقيم الخطوات الحالية. how to use add-step add-step setup guide add-step pipeline step management p2cs_project pipeline steps add-step vs pipeline management tools add-step install for p2cs_project Add Step p2cs_project 管道步骤 重新编号 依赖项配置 AI技术 技能文档 设置指南 Adds new pipeline steps under code/step_{N}_{name}/ Inserts steps between existing steps with automatic renumbering Provides a checklist for creating step classes, substeps, and README files Supports exploration with explore.ipynb Manages wiring dependencies and configuration add-step is a project-specific skill for managing pipeline steps in the p2cs_project, allowing for efficient insertion and renumbering of steps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gpu-cli/gpu/gpu-cli', 'community', 'gpu-cli', 'gpu', 'gpu-cli/gpu', 'gpu-cli', 0, 0, 50, '2026-03-08T01:57:15.499Z', '2026-03-08T02:10:16.259Z', 'c91139ea2d07263dbc37f9b4b3889baf0c1676b4116dedd81d4fcb11eea03b46', '{"id":"gpu-cli/gpu/gpu-cli","name":"gpu-cli","description":{"en":"The gpu-cli is a command-line interface that enables developers to run local commands on remote NVIDIA GPUs by prefixing them with `gpu`. It automates provisioning a pod, syncing code, streaming logs, and syncing outputs back, transforming workflows like `uv run python train.py`.","zh":"GPU CLI 是一个命令行工具，允许您在远程 NVIDIA GPU 上运行本地命令。它支持快速诊断和命令家族","ja":"GPU CLI は、リモート NVIDIA GPU でローカル コマンドを実行できるコマンドライン ツールです。クイック診断とコマンド ファミリをサポート","ko":"GPU CLI는 원격 NVIDIA GPU에서 로컬 명령을 실행할 수 있는 명령줄 도구입니다. 빠른 진단과 명령어 패밀리를 지원","es":"gpu-cli es una herramienta que permite ejecutar comandos locales en GPUs remotas de NVIDIA. Permite provisionar pods, sincronizar código y streams de logs","fr":"gpu-cli est un outil qui permet d''exécuter des commandes locales sur des GPU NVIDIA distants. Il permet de provisionner des pods, de synchroniser du code et des flux de logs","de":"gpu-cli ist ein Tool, das die Ausführung von lokalen Befehlen auf remote NVIDIA-GPUs ermöglicht. Es ermöglicht die Provisionierung von Pods, die Synchronisation von Code und Log-Streams","pt":"O gpu-cli é uma ferramenta de linha de comando que permite executar comandos locais em GPUs remotas NVIDIA, com recursos como provisionamento de pods e streaming de logs","ru":"gpu-cli - это инструмент командной строки, который позволяет выполнять локальные команды на удаленных GPU NVIDIA, с функциями как provisionamento подов и потоковое ведение журналов","ar":"gpu-cli هو أداة سطر أوامر تسمح بتشغيل أوامر محلية على وحدات رسومات نيفيديا البعيدة، مع ميزات مثل توفير بودات وتمرير سجلات"},"seo":{"title":{"en":"gpu-cli: Remote NVIDIA GPU Command Execution | AI Agent S...","zh":"GPU CLI 设置指南 - 远程 NVIDIA GPU 命令行工具","ja":"GPU CLI セットアップガイド - リモート NVIDIA GPU コマンドラインツール","ko":"GPU CLI 설정 가이드 - 원격 NVIDIA GPU 명령줄 도구","es":"Guía de configuración de gpu-cli para desarrolladores","fr":"Guide de démarrage rapide pour gpu-cli","de":"gpu-cli-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do gpu-cli: Ferramenta de Linha de C...","ru":"Настройка gpu-cli: Инструмент командной строки для удален...","ar":"دليل إعداد gpu-cli: أداة سطر الأوامر للوحدات الرسومية الب..."},"description":{"en":"Execute local commands on remote NVIDIA GPUs with the gpu-cli. This CLI tool provisions pods, syncs code, and streams logs. Learn how to run `uv run python t...","zh":"使用 GPU CLI 运行本地命令 на 远程 NVIDIA GPU，简化您的开发流程","ja":"GPU CLI を使用してリモート NVIDIA GPU でローカル コマンドを実行し、開発プロセスを簡素化","ko":"GPU CLI를 사용하여 원격 NVIDIA GPU에서 로컬 명령을 실행하고 개발 프로세스를 간소화","es":"Aprende a utilizar gpu-cli para ejecutar comandos locales en GPUs remotas de NVIDIA y optimiza tus flujos de trabajo","fr":"Découvrez comment utiliser gpu-cli pour exécuter des commandes locales sur des GPU NVIDIA distants et améliorer vos flux de travail","de":"Erfahren Sie, wie Sie gpu-cli verwenden, um lokale Befehle auf remote NVIDIA-GPUs auszuführen und Ihre Workflows zu optimieren","pt":"Aprenda a usar o gpu-cli para executar comandos locais em GPUs remotas NVIDIA, com recursos como provisionamento de pods e streaming de logs","ru":"Узнайте, как использовать gpu-cli для выполнения локальных команд на удаленных GPU NVIDIA, с функциями как provisionamento подов и потоковое ведение журналов","ar":"تعرف على كيفية استخدام gpu-cli لتشغيل أوامر محلية على وحدات رسومات نيفيديا البعيدة، مع ميزات مثل توفير بودات وتمرير سجلات"},"definition":{"en":"gpu-cli is a public-facing CLI tool for running local commands on remote NVIDIA GPUs. It works by prefixing any command with `gpu`, which triggers automatic pod provisioning, code synchronization, log streaming, and output retrieval for machine learning and development workflows.","zh":"GPU CLI 是一个用于远程 NVIDIA GPU 的命令行工具，提供快速诊断和命令执行","ja":"GPU CLI は、リモート NVIDIA GPU 用のコマンドライン ツールで、クイック診断とコマンド実行を提供","ko":"GPU CLI는 원격 NVIDIA GPU용 명령줄 도구로 빠른 진단과 명령어 실행을 제공","es":"gpu-cli es una interfaz de línea de comandos que permite ejecutar comandos locales en GPUs remotas de NVIDIA","fr":"gpu-cli est une interface de ligne de commande qui permet d''exécuter des commandes locales sur des GPU NVIDIA distants","de":"gpu-cli ist eine Kommandozeilen-Schnittstelle, die die Ausführung von lokalen Befehlen auf remote NVIDIA-GPUs ermöglicht","pt":"O gpu-cli é uma ferramenta de linha de comando que permite executar comandos locais em GPUs remotas NVIDIA","ru":"gpu-cli - это инструмент командной строки, который позволяет выполнять локальные команды на удаленных GPU NVIDIA","ar":"gpu-cli هو أداة سطر أوامر تسمح بتشغيل أوامر محلية على وحدات رسومات نيفيديا البعيدة"},"features":{"en":["Runs local commands on remote NVIDIA GPUs via command prefixing (e.g., `gpu run uv run python train.py`)","Automatically provisions a remote pod for execution","Synchronizes local code to the remote environment","Streams logs from the remote pod in real-time","Synchronizes output files back to the local machine","Provides diagnostic commands like `gpu doctor --json` to check setup health"],"zh":["快速诊断：支持 `gpu doctor` 和 `gpu status` 命令","命令家族：支持 `gpu run` 命令","远程 NVIDIA GPU 支持","代码同步和日志流","输出同步"],"ja":["クイック診断：`gpu doctor` と `gpu status` コマンドをサポート","コマンド ファミリ：`gpu run` コマンドをサポート","リモート NVIDIA GPU サポート","コード同期とログストリーム","出力同期"],"ko":["빠른 진단：`gpu doctor`와 `gpu status` 명령어 지원","명령어 패밀리：`gpu run` 명령어 지원","원격 NVIDIA GPU 지원","코드 동기화와 로그 스트림","출력 동기화"],"es":["Ejecución de comandos locales en GPUs remotas de NVIDIA","Provisionamiento de pods","Sincronización de código","Stream de logs","Comandos de diagnóstico rápidos como `gpu doctor` y `gpu status`"],"fr":["Exécution de commandes locales sur des GPU NVIDIA distants","Provisionnement de pods","Synchronisation de code","Flux de logs","Commandes de diagnostic rapides comme `gpu doctor` et `gpu status`"],"de":["Ausführung von lokalen Befehlen auf remote NVIDIA-GPUs","Provisionierung von Pods","Synchronisation von Code","Log-Streams","Schnelle Diagnose-Befehle wie `gpu doctor` und `gpu status`"],"pt":["Provisionamento de pods para execução de comandos","Streaming de logs para monitoramento","Sincronização de saídas para obtenção de resultados","Comando ''gpu doctor'' para diagnóstico de problemas","Comando ''gpu status'' para visualização de pods e custos","Comando ''gpu inventory'' para visualização de GPUs disponíveis e preços"],"ru":["Проставление подов для выполнения команд","Потоковое ведение журналов для мониторинга","Синхронизация выводов для получения результатов","Команда ''gpu doctor'' для диагностики проблем","Команда ''gpu status'' для просмотра подов и затрат","Команда ''gpu inventory'' для просмотра доступных GPU и цен"],"ar":["توفير بودات لتشغيل الأوامر","تمرير سجلات للرصد","مزامنة الإخراج للحصول على النتائج","أمر ''gpu doctor'' لتشخيص المشكلات","أمر ''gpu status'' لعرض البودات والتكاليف","أمر ''gpu inventory'' لعرض وحدات الرسومات المتاحة وأسعارها"]},"keywords":{"en":["gpu-cli install","gpu-cli setup guide","how to use gpu-cli","what is gpu-cli","gpu-cli vs kubectl","gpu-cli alternative","remote NVIDIA GPU command execution","gpu run command","gpu doctor --json","gpu status --json"],"zh":["GPU CLI","远程 NVIDIA GPU","命令行工具","快速诊断","代码同步","日志流","输出同步","AIエージェント","AI工具"],"ja":["GPU CLI","リモート NVIDIA GPU","コマンドライン ツール","クイック診断","コード同期","ログストリーム","出力同期","AIエージェント","AIツール"],"ko":["GPU CLI","원격 NVIDIA GPU","명령줄 도구","빠른 진단","코드 동기화","로그 스트림","출력 동기화","AI 에이전트","AI 툴"],"es":["gpu-cli","NVIDIA GPU","comandos locales","GPUs remotas","provisionamiento de pods","sincronización de código","stream de logs","herramientas de desarrollo","desarrollo de AI"],"fr":["gpu-cli","GPU NVIDIA","commandes locales","GPU distants","provisionnement de pods","synchronisation de code","flux de logs","outils de développement","développement d''IA"],"de":["gpu-cli","NVIDIA-GPU","lokale Befehle","remote GPUs","Provisionierung von Pods","Synchronisation von Code","Log-Streams","Entwicklungstools","KI-Entwicklung"],"pt":["gpu-cli","ferramenta de linha de comando","GPUs remotas","NVIDIA","provisionamento de pods","streaming de logs","sincronização de saídas","comando gpu doctor","comando gpu status","comando gpu inventory"],"ru":["gpu-cli","инструмент командной строки","удаленные GPU","NVIDIA","простановка подов","потоковое ведение журналов","синхронизация выводов","команда gpu doctor","команда gpu status","команда gpu inventory"],"ar":["gpu-cli","أداة سطر الأوامر","وحدات رسومات بعيدة","نيفيديا","توفير بودات","تمرير سجلات","مزامنة الإخراج","أمر gpu doctor","أمر gpu status","أمر gpu inventory"]}},"owner":"gpu-cli","repo":"gpu","repoPath":"gpu-cli/gpu","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.499Z","topics":[],"category":"community","skillMd":{"name":"gpu-cli","description":"Run ML training, LLM inference, and ComfyUI workflows on remote NVIDIA GPUs (A100, H100, RTX 4090). Cloud GPU compute with smart file sync — prefix any command with gpu to run it remotely.","version":"0.14.0","tags":"","bodyPreview":"# GPU CLI\n\nGPU CLI runs local commands on remote NVIDIA GPUs by prefixing with `gpu`. It provisions a pod, syncs your code, streams logs, and syncs outputs back: `uv run python train.py` becomes `gpu run uv run python train.py`.\n\n## Quick diagnostics\n\n```bash\ngpu doctor --json       # Check if setup is healthy (daemon, auth, provider keys)\ngpu status --json       # See running pods and costs\ngpu inventory --json    # See available GPUs and pricing\n```\n\n## Command families\n\n### Getting started\n\n|","body":"# GPU CLI\n\nGPU CLI runs local commands on remote NVIDIA GPUs by prefixing with `gpu`. It provisions a pod, syncs your code, streams logs, and syncs outputs back: `uv run python train.py` becomes `gpu run uv run python train.py`.\n\n## Quick diagnostics\n\n```bash\ngpu doctor --json       # Check if setup is healthy (daemon, auth, provider keys)\ngpu status --json       # See running pods and costs\ngpu inventory --json    # See available GPUs and pricing\n```\n\n## Command families\n\n### Getting started\n\n| Command | Purpose |\n|---|---|\n| `gpu login` | Browser-based authentication |\n| `gpu logout [-y]` | Remove session |\n| `gpu init [--gpu-type T] [--force]` | Initialize project config |\n| `gpu upgrade` | Open subscription upgrade page |\n\n### Running code\n\n| Command | Purpose |\n|---|---|\n| `gpu run <command>` | Execute on remote GPU (main command) |\n| `gpu run -d <command>` | Run detached (background) |\n| `gpu run -a <job_id>` | Reattach to running job |\n| `gpu run --cancel <job_id>` | Cancel a running job |\n| `gpu status [--json]` | Show project status, pods, costs |\n| `gpu logs [-j JOB] [-f] [--tail N] [--json]` | View job output |\n| `gpu attach <job_id>` | Reattach to job output stream |\n| `gpu stop [POD_ID] [-y]` | Stop active pod |\n\nKey `gpu run` flags: `--gpu-type`, `--gpu-count <1-8>`, `--min-vram`, `--rebuild`, `-o/--output`, `--no-output`, `--sync`, `-p/--publish <PORT>`, `-e <KEY=VALUE>`, `-i/--interactive`.\n\n### GPU inventory\n\n| Command | Purpose |\n|---|---|\n| `gpu inventory [--available] [--min-vram N] [--max-price P] [--json]` | List GPUs with pricing |\n\n### Volumes\n\n| Command | Purpose |\n|---|---|\n| `gpu volume list [--detailed] [--json]` | List network volumes |\n| `gpu volume create [--name N] [--size GB] [--datacenter DC]` | Create volume |\n| `gpu volume delete <VOL> [--force]` | Delete volume |\n| `gpu volume extend <VOL> --size <GB>` | Increase size |\n| `gpu volume set-global <VOL>` | Set default volume |\n| `gpu volume status [--volume V] [--json]` | Volume usage |\n| `gpu volume migrate <VOL> --to <DC>` | Migrate to datacenter |\n| `gpu volume sync <SRC> <DEST>` | Sync between volumes |\n\n### Vault (encrypted storage)\n\n| Command | Purpose |\n|---|---|\n| `gpu vault list [--json]` | List encrypted output files |\n| `gpu vault export <PATH> <DEST>` | Export decrypted file |\n| `gpu vault stats [--json]` | Storage usage stats |\n\n### Configuration\n\n| Command | Purpose |\n|---|---|\n| `gpu config show [--json]` | Show merged config |\n| `gpu config validate` | Validate against schema |\n| `gpu config schema` | Print JSON schema |\n| `gpu config set <KEY> <VALUE>` | Set global config option |\n| `gpu config get <KEY>` | Get global config value |\n\n### Authentication\n\n| Command | Purpose |\n|---|---|\n| `gpu auth login [--profile P]` | Authenticate with cloud provider |\n| `gpu auth logout` | Remove credentials |\n| `gpu auth status` | Show auth status |\n| `gpu auth add <HUB>` | Add hub credentials (hf, civitai) |\n| `gpu auth remove <HUB>` | Remove hub credentials |\n| `gpu auth hubs` | List configured hubs |\n\n### Organizations\n\n| Command | Purpose |\n|---|---|\n| `gpu org list` | List organizations |\n| `gpu org create <NAME>` | Create organization |\n| `gpu org switch [SLUG]` | Set active org context |\n| `gpu org invite <EMAIL>` | Invite member |\n| `gpu org service-account create --name N` | Create service token |\n| `gpu org service-account list` | List service accounts |\n| `gpu org service-account revoke <ID>` | Revoke token |\n\n### LLM inference\n\n| Command | Purpose |\n|---|---|\n| `gpu llm run [--ollama\\|--vllm] [--model M] [-y]` | Launch LLM inference |\n| `gpu llm info [MODEL] [--url URL] [--json]` | Show model info |\n\n### ComfyUI workflows\n\n| Command | Purpose |\n|---|---|\n| `gpu comfyui list [--json]` | Browse available workflows |\n| `gpu comfyui info <WORKFLOW> [--json]` | Show workflow details |\n| `gpu comfyui validate <WORKFLOW> [--json]` | Pre-flight checks |\n| `gpu comfyui run <WORKFLOW>` | Run workflow on GPU |\n| `gpu comfyui generate \"<PROMPT>\"` | Text-to-image generation |\n| `gpu comfyui stop [WORKFLOW] [--all]` | Stop ComfyUI pod |\n\n### Notebooks\n\n| Command | Purpose |\n|---|---|\n| `gpu notebook [FILE] [--run] [--new NAME]` | Run Marimo notebook on GPU |\n\nAlias: `gpu nb`\n\n### Serverless endpoints\n\n| Command | Purpose |\n|---|---|\n| `gpu serverless deploy [--template T] [--json]` | Deploy endpoint |\n| `gpu serverless status [ENDPOINT] [--json]` | Endpoint status |\n| `gpu serverless logs [ENDPOINT]` | View request logs |\n| `gpu serverless list [--json]` | List all endpoints |\n| `gpu serverless delete [ENDPOINT]` | Delete endpoint |\n| `gpu serverless warm [--cpu\\|--gpu]` | Pre-warm endpoint |\n\n### Templates\n\n| Command | Purpose |\n|---|---|\n| `gpu template list [--json]` | Browse official templates |\n| `gpu template clear-cache` | Clear cached templates |\n\n### Daemon control\n\n| Command | Purpose |\n|---|---|\n| `gpu daemon status [--json]` | Show daemon health |\n| `gpu daemon start` | Start daemon |\n| `gpu daemon stop` | Stop daemon |\n| `gpu daemon restart` | Restart daemon |\n| `gpu daemon logs [-f] [-n N]` | View daemon logs |\n\n### Tools and utilities\n\n| Command | Purpose |\n|---|---|\n| `gpu dashboard` | Interactive TUI for pods and jobs |\n| `gpu doctor [--json]` | Diagnostic checks |\n| `gpu agent-docs` | Print agent reference to stdout |\n| `gpu update [--check]` | Update CLI |\n| `gpu changelog [VERSION]` | View release notes |\n| `gpu issue [\"desc\"]` | Report issue |\n| `gpu desktop` | Desktop app management |\n| `gpu support` | Open community Discord |\n\n## Common workflows\n\n1. **Setup**: `gpu login` then `gpu init`\n2. **Run job**: `gpu run python train.py --epochs 10`\n3. **With specific GPU**: `gpu run --gpu-type \"RTX 4090\" python train.py`\n4. **Detached job**: `gpu run -d python long_training.py` then `gpu status --json`\n5. **Check status**: `gpu status --json`\n6. **View logs**: `gpu logs --json`\n7. **Stop pods**: `gpu stop -y`\n8. **LLM inference**: `gpu llm run --ollama --model llama3 -y`\n9. **ComfyUI**: `gpu comfyui run flux_schnell`\n10. **Diagnose issues**: `gpu doctor --json`\n\n`gpu run` is pod-reuse oriented: after a command completes, the next `gpu run` reuses the existing pod until you `gpu stop` or cooldown ends.\n\n## JSON output\n\nMost commands support `--json` for machine-readable output. Structured data goes to stdout; human-oriented status and progress messages go to stderr.\n\nCommands with `--json`: `status`, `logs`, `doctor`, `inventory`, `config show`, `daemon status`, `volume list`, `volume status`, `vault list`, `vault stats`, `comfyui list`, `comfyui info`, `comfyui validate`, `serverless deploy`, `serverless status`, `serverless list`, `template list`, `llm info`.\n\n## Exit codes\n\n| Code | Meaning | Recovery |\n|---|---|---|\n| `0` | Success | Proceed |\n| `1` | General error | Read stderr |\n| `2` | Usage error | Fix command syntax |\n| `10` | Auth required | `gpu auth login` |\n| `11` | Quota exceeded | `gpu upgrade` or wait |\n| `12` | Not found | Check resource ID |\n| `13` | Daemon unavailable | `gpu daemon start`, retry |\n| `14` | Timeout | Retry |\n| `15` | Cancelled | Re-run if needed |\n| `130` | Interrupted | Re-run if needed |\n\n## Configuration\n\n- Project config: `gpu.toml`, `gpu.jsonc`, or `pyproject.toml [tool.gpu]`\n- Global config: `~/.gpu-cli/config.toml` (via `gpu config set/get`)\n- Sync model: `.gitignore` controls upload; `outputs` patterns control download\n- Secrets and credentials must stay in the OS keychain, never plaintext project files\n- CI env vars: `GPU_RUNPOD_API_KEY`, `GPU_SSH_PRIVATE_KEY`, `GPU_SSH_PUBLIC_KEY`\n\n## References\n\n- Project generation and task setup: `references/create.md`\n- Debugging and common failures: `references/debug.md`\n- Config schema and field examples: `references/config.md`\n- Cost and GPU selection guidance: `references/optimize.md`\n- Persistent storage and volumes: `references/volumes.md`\n"},"lastSynced":"2026-03-08T02:10:16.259Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing remote NVIDIA GPU acceleration for machine learning workflows.","zh":"非常适合需要远程NVIDIA GPU加速的AI Agents进行机器学习工作流","ja":"リモートNVIDIA GPU加速が必要なAIエージェントのマシンラーニングワークフローに最適","ko":"원격 NVIDIA GPU 가속이 필요한 AI 에이전트의 기계 학습 워크플로에 적합","es":"Perfecto para agentes de IA que necesitan aceleración de GPU de NVIDIA remota para flujos de trabajo de aprendizaje automático.","fr":"Parfait pour les agents IA nécessitant une accélération de GPU NVIDIA à distance pour les flux de travail d''apprentissage automatique.","de":"Perfekt für KI-Agenten, die eine Remote-NVIDIA-GPU-Beschleunigung für Machine-Learning-Workflows benötigen.","pt":"Perfeito para Agentes de IA que precisam de aceleração de GPU NVIDIA remota para fluxos de trabalho de aprendizado de máquina.","ru":"Идеально для агентов ИИ, которым требуется удаленное ускорение NVIDIA GPU для рабочих процессов машинного обучения.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تعزيز NVIDIA GPU عن بعد لتدفقات العمل من التعلم الآلي."},"recommendation":{"en":"Empowers agents to run local commands on remote NVIDIA GPUs, stream logs, and sync outputs back, leveraging protocols like uv and provisioning tools, all by prefixing commands with `gpu`.","zh":"使得代理能够在远程NVIDIA GPU上运行本地命令、流式传输日志并同步输出，利用诸如uv和提供工具的协议，所有这些都可以通过命令前缀`gpu`实现","ja":"エージェントがリモートNVIDIA GPUでローカルコマンドを実行し、ログをストリーミングし、出力を同期させることができるようにし、uvやプロビジョニングツールなどのプロトコルを利用し、すべて`gpu`コマンドを接頭辞として実現","ko":"에이전트가 원격 NVIDIA GPU에서 로컬 명령을 실행하고 로그를 스트리밍하고 출력을 동기화 시키는 것을 가능하게 하며 uv 및 프로비저닝 도구와 같은 프로토콜을 활용하여 모든 것을 `gpu` 명령어를 접두사로实现","es":"Habilita a los agentes a ejecutar comandos locales en GPUs de NVIDIA remotas, transmitir registros y sincronizar salidas de regreso, aprovechando protocolos como uv y herramientas de aprovisionamiento, todo prefixando comandos con `gpu`.","fr":"Permet aux agents d''exécuter des commandes locales sur des GPU NVIDIA à distance, de diffuser des journaux et de synchroniser les sorties, en exploitant des protocoles comme uv et des outils de provisionnement, le tout en prefixant les commandes avec `gpu`.","de":"Ermöglicht es Agenten, lokale Befehle auf Remote-NVIDIA-GPUs auszuführen, Protokolle zu streamen und Ausgaben zurück zu synchronisieren, indem Protokolle wie uv und Bereitstellungstools genutzt werden, alles durch das Prefixen von Befehlen mit `gpu`.","pt":"Habilita os agentes a executar comandos locais em GPUs NVIDIA remotas, transmitir logs e sincronizar saídas de volta, aproveitando protocolos como uv e ferramentas de provisionamento, tudo prefixando comandos com `gpu`.","ru":"Позволяет агентам запускать локальные команды на удаленных GPU NVIDIA, передавать журналы и синхронизировать выводы, используя протоколы, такие как uv, и инструменты предоставления, все путем добавления префикса `gpu` к командам.","ar":"تمكّن الوكلاء من تشغيل الأوامر المحلية على وحدات معالجة الرسومات NVIDIA عن بعد، ونسخ سجلات وتزامن الإخراج مرة أخرى، واستخدام بروتوكولات مثل uv وأدوات التزويد، وجميعها عن طريق إضافة بادئة `gpu` للأوامر."},"useCases":{"en":["Automating machine learning model training on remote GPUs","Debugging GPU-accelerated workflows with `gpu doctor` and `gpu status`","Optimizing costs by monitoring running pods and available GPUs with `gpu inventory`"],"zh":["在远程GPU上自动化机器学习模型训练","使用`gpu doctor`和`gpu status`调试GPU加速工作流","通过`gpu inventory`监控运行的pod和可用的GPU来优化成本"],"ja":["リモートGPU上でのマシンラーニングモデルトレーニングの自動化","`gpu doctor`および`gpu status`を使用したGPU加速ワークフローのデバッグ","`gpu inventory`を使用して実行中のポッドと利用可能なGPUを監視してコストを最適化"],"ko":["원격 GPU에서 기계 학습 모델 훈련 자동화","`gpu doctor` 및 `gpu status` 사용하여 GPU 가속 워크플로 디버깅","`gpu inventory` 사용하여 실행 중인 pod 및 사용 가능한 GPU 모니터링을 통해 비용 최적화"],"es":["Automatizar la formación de modelos de aprendizaje automático en GPUs remotas","Depurar flujos de trabajo acelerados por GPU con `gpu doctor` y `gpu status`","Optimizar costos mediante la supervisión de pods en ejecución y GPUs disponibles con `gpu inventory`"],"fr":["Automatiser la formation de modèles d''apprentissage automatique sur des GPU à distance","Déboguer des flux de travail accélérés par GPU avec `gpu doctor` et `gpu status`","Optimiser les coûts en surveillant les pods en cours d''exécution et les GPU disponibles avec `gpu inventory`"],"de":["Automatisieren des Trainings von Machine-Learning-Modellen auf Remote-GPUs","Debuggen von GPU-beschleunigten Workflows mit `gpu doctor` und `gpu status`","Optimieren von Kosten durch Überwachung von laufenden Pods und verfügbaren GPUs mit `gpu inventory`"],"pt":["Automatizar o treinamento de modelos de aprendizado de máquina em GPUs remotas","Depurar fluxos de trabalho acelerados por GPU com `gpu doctor` e `gpu status`","Otimizar custos monitorando pods em execução e GPUs disponíveis com `gpu inventory`"],"ru":["Автоматизировать обучение моделей машинного обучения на удаленных GPU","Отлаживать рабочие процессы, ускоренные GPU, с помощью `gpu doctor` и `gpu status`","Оптимизировать затраты, отслеживая запущенные pods и доступные GPU с помощью `gpu inventory`"],"ar":["تحسين تدريب نموذج التعلم الآلي على وحدات معالجة الرسومات عن بعد","تصحيح الأخطاء في تدفقات العمل المتسارعة بواسطة وحدات معالجة الرسومات مع `gpu doctor` و `gpu status`","تحسين التكاليف عن طريق مراقبة حاويات التشغيل ووحدات معالجة الرسومات المتاحة مع `gpu inventory`"]},"limitations":{"en":["Requires NVIDIA GPU access","Dependent on `uv` for workflow management","Needs proper setup and authentication for remote GPU provisioning"],"zh":["需要NVIDIA GPU访问","依赖于`uv`进行工作流管理","需要正确的设置和身份验证以进行远程GPU提供"],"ja":["NVIDIA GPUへのアクセスが必要","ワークフローの管理に`uv`に依存","リモートGPUプロビジョニングには適切なセットアップと認証が必要"],"ko":["NVIDIA GPU 액세스가 필요","`uv`에 의존하여 워크플로 관리","원격 GPU 프로비저닝을 위해 적절한 설정 및 인증이 필요"],"es":["Requiere acceso a GPU de NVIDIA","Dependiente de `uv` para la gestión de flujos de trabajo","Necesita una configuración y autenticación adecuadas para el aprovisionamiento de GPU remota"],"fr":["Nécessite un accès à des GPU NVIDIA","Dépend de `uv` pour la gestion des flux de travail","Nécessite une configuration et une authentification appropriées pour l''approvisionnement de GPU à distance"],"de":["Benötigt Zugriff auf NVIDIA-GPU","Abhängig von `uv` für die Workflow-Verwaltung","Benötigt eine ordnungsgemäße Einrichtung und Authentifizierung für die Remote-GPU-Bereitstellung"],"pt":["Requer acesso à GPU NVIDIA","Dependente de `uv` para gerenciamento de fluxos de trabalho","Necessita de configuração e autenticação adequadas para provisionamento de GPU remoto"],"ru":["Требуется доступ к GPU NVIDIA","Зависит от `uv` для управления рабочими процессами","Требуется правильная настройка и аутентификация для удаленного предоставления GPU"],"ar":["يتطلب الوصول إلى وحدة معالجة الرسومات NVIDIA","يعتمد على `uv` لإدارة تدفقات العمل","يحتاج إلى إعداد ومصادقة مناسبين لتزويد وحدة معالجة الرسومات عن بعد"]},"version":4},"contentHash":"c91139ea2d07263dbc37f9b4b3889baf0c1676b4116dedd81d4fcb11eea03b46","qualityScore":50}');
