INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gpu-cli/gpu/gpu-cli', 'gpu-cli', 'gpu-cli', 'gpu', 'community', 'gpu-cli gpu-cli gpu community The gpu-cli is a command-line interface that enables developers to run local commands on remote NVIDIA GPUs by prefixing them with `gpu`. It automates provisioning a pod, syncing code, streaming logs, and syncing outputs back, transforming workflows like `uv run python train.py`. GPU CLI 是一个命令行工具，允许您在远程 NVIDIA GPU 上运行本地命令。它支持快速诊断和命令家族 GPU CLI は、リモート NVIDIA GPU でローカル コマンドを実行できるコマンドライン ツールです。クイック診断とコマンド ファミリをサポート GPU CLI는 원격 NVIDIA GPU에서 로컬 명령을 실행할 수 있는 명령줄 도구입니다. 빠른 진단과 명령어 패밀리를 지원 gpu-cli es una herramienta que permite ejecutar comandos locales en GPUs remotas de NVIDIA. Permite provisionar pods, sincronizar código y streams de logs gpu-cli est un outil qui permet d''exécuter des commandes locales sur des GPU NVIDIA distants. Il permet de provisionner des pods, de synchroniser du code et des flux de logs gpu-cli ist ein Tool, das die Ausführung von lokalen Befehlen auf remote NVIDIA-GPUs ermöglicht. Es ermöglicht die Provisionierung von Pods, die Synchronisation von Code und Log-Streams O gpu-cli é uma ferramenta de linha de comando que permite executar comandos locais em GPUs remotas NVIDIA, com recursos como provisionamento de pods e streaming de logs gpu-cli - это инструмент командной строки, который позволяет выполнять локальные команды на удаленных GPU NVIDIA, с функциями как provisionamento подов и потоковое ведение журналов gpu-cli هو أداة سطر أوامر تسمح بتشغيل أوامر محلية على وحدات رسومات نيفيديا البعيدة، مع ميزات مثل توفير بودات وتمرير سجلات gpu-cli install gpu-cli setup guide how to use gpu-cli what is gpu-cli gpu-cli vs kubectl gpu-cli alternative remote NVIDIA GPU command execution gpu run command gpu doctor --json gpu status --json GPU CLI 远程 NVIDIA GPU 命令行工具 快速诊断 代码同步 日志流 输出同步 AIエージェント AI工具 Runs local commands on remote NVIDIA GPUs via command prefixing (e.g., `gpu run uv run python train.py`) Automatically provisions a remote pod for execution Synchronizes local code to the remote environment Streams logs from the remote pod in real-time Synchronizes output files back to the local machine Provides diagnostic commands like `gpu doctor --json` to check setup health gpu-cli is a public-facing CLI tool for running local commands on remote NVIDIA GPUs. It works by prefixing any command with `gpu`, which triggers automatic pod provisioning, code synchronization, log streaming, and output retrieval for machine learning and development workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Open-Earth-Foundation/Query_mechanism_urbind/repo-doc-audit', 'community', 'Open-Earth-Foundation', 'Query_mechanism_urbind', 'Open-Earth-Foundation/Query_mechanism_urbind', 'repo-doc-audit', 0, 0, 50, '2026-03-08T01:57:15.514Z', '2026-03-08T02:10:31.676Z', 'dddbda7cd0f9ca909104d04068e1c815a797167fc76855e220964ab4d48f5d5d', '{"id":"Open-Earth-Foundation/Query_mechanism_urbind/repo-doc-audit","name":"repo-doc-audit","description":{"en":"The repo-doc-audit skill performs a one-off, repo-wide documentation audit, providing an actionable report on README.md and architecture.md accuracy, benefiting developers and repository maintainers.","zh":"repo-doc-audit是代码仓库文档审计工具，用于检查README.md和architecture.md的准确性","ja":"repo-doc-auditはリポジトリのドキュメント監査ツールで、README.mdとarchitecture.mdの正確性を確認する","ko":"repo-doc-audit는 리포지토리 문서 감사 도구로 README.md 및 architecture.md의 정확성을 확인합니다","es":"repo-doc-audit es una herramienta de auditoría de documentación de repositorio que proporciona un informe de acción y soluciones opcionales para mejorar la documentación.","fr":"repo-doc-audit est un outil d''audit de documentation de référentiel qui fournit un rapport d''action et des solutions optionnelles pour améliorer la documentation.","de":"repo-doc-audit ist ein Tool zur Prüfung der Dokumentation von Repositorys, das einen Aktionsbericht und optionale Lösungen zur Verbesserung der Dokumentation liefert.","pt":"O repo-doc-audit é uma ferramenta de auditoria de documentação que ajuda a manter o código atualizado e preciso","ru":"ИИ Агент repo-doc-audit - это инструмент для аудита документации, помогающий поддерживать код в актуальном и точном состоянии","ar":"repo-doc-audit هو أداة مراجعة توثيق تساعد في الحفاظ على الكود محدثًا ودقيقًا"},"seo":{"title":{"en":"repo-doc-audit: Automated Documentation Audit for AI Agen...","zh":"repo-doc-audit Setup Gu