INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Open-Earth-Foundation/Query_mechanism_urbind/repo-doc-audit', 'repo-doc-audit', 'Open-Earth-Foundation', 'Query_mechanism_urbind', 'community', 'repo-doc-audit Open-Earth-Foundation Query_mechanism_urbind community The repo-doc-audit skill performs a one-off, repo-wide documentation audit, providing an actionable report on README.md and architecture.md accuracy, benefiting developers and repository maintainers. repo-doc-audit是代码仓库文档审计工具，用于检查README.md和architecture.md的准确性 repo-doc-auditはリポジトリのドキュメント監査ツールで、README.mdとarchitecture.mdの正確性を確認する repo-doc-audit는 리포지토리 문서 감사 도구로 README.md 및 architecture.md의 정확성을 확인합니다 repo-doc-audit es una herramienta de auditoría de documentación de repositorio que proporciona un informe de acción y soluciones opcionales para mejorar la documentación. repo-doc-audit est un outil d''audit de documentation de référentiel qui fournit un rapport d''action et des solutions optionnelles pour améliorer la documentation. repo-doc-audit ist ein Tool zur Prüfung der Dokumentation von Repositorys, das einen Aktionsbericht und optionale Lösungen zur Verbesserung der Dokumentation liefert. O repo-doc-audit é uma ferramenta de auditoria de documentação que ajuda a manter o código atualizado e preciso ИИ Агент repo-doc-audit - это инструмент для аудита документации, помогающий поддерживать код в актуальном и точном состоянии repo-doc-audit هو أداة مراجعة توثيق تساعد في الحفاظ على الكود محدثًا ودقيقًا how to use repo-doc-audit repo-doc-audit setup guide what is repo-doc-audit repo-doc-audit alternative repo-doc-audit vs documentation tools repo-doc-audit install automated documentation audit repository documentation audit README.md audit architecture.md audit 代码仓库文档审计 AIエージェント README.md architecture.md 代码仓库监査 文档审计报告 代码仓库管理 代码质量保证 Produces actionable reports on README.md accuracy for setup, run, and configuration Audits architecture.md for accuracy and consistency Optionally provides fixes for identified documentation issues Supports use cases after large refactors, restructurings, or major feature additions Generates reports on troubleshooting documentation in README.md Performs a one-off, repo-wide documentation audit for comprehensive coverage repo-doc-audit is a specialized AI agent skill that conducts a thorough examination of a repository''s documentation, ensuring accuracy and consistency across files like README.md and architecture.md.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gdgeek/murder-mystery-generator/unix-review', 'community', 'gdgeek', 'murder-mystery-generator', 'gdgeek/murder-mystery-generator', 'unix-review', 0, 0, 50, '2026-03-08T01:57:15.559Z', '2026-03-08T02:11:35.415Z', '484af14b0c897efdff55ab0e772e56469cec40cc4b22d0f383d0ec88224c29f2', '{"id":"gdgeek/murder-mystery-generator/unix-review","name":"unix-review","description":{"en":"The unix-review skill applies the Unix philosophy to review code, focusing on modularity and simplicity. It benefits developers by evaluating code against the 17 Unix rules.","zh":"Unix 代码审查工具根据 Eric S. Raymond 的《The Art of Unix Programming》原则审查代码，注重模块化和简单性","ja":"Unix コードレビューツールは、Eric S. Raymond の『The Art of Unix Programming』の原則に基づいてコードをレビューし、モジュール性とシンプルさに焦点を当てています","ko":"유닉스 코드 리뷰 도구는 Eric S. Raymond의『The Art of Unix Programming』원칙에 따라 코드를 리뷰하며 모듈화와 단순성에 중점을 둡니다","es":"unix-review es una herramienta de revisión de código que aplica los principios de la filosofía Unix, como la regla de modularidad y el uso de Glob y Grep","fr":"unix-review est un outil de révision de code qui applique les principes de la philosophie Unix, tels que la règle de modularité et l''utilisation de Glob et Grep","de":"unix-review ist ein Code-Review-Tool, das die Prinzipien der Unix-Philosophie anwendet, wie die Regel der Modularität und die Verwendung von Glob und Grep","pt":"unix-review é uma ferramenta de análise de código que aplica os princípios da filosofia Unix. Ele ajuda a melhorar a modularidade e a simplicidade do código","ru":"unix-review - это инструмент для обзора кода, который применяет принципы философии Unix. Он помогает улучшить модульность и простоту кода","ar":"unix-review هو أداة لمراجعة الكود التي تطبيق مبادئ فلسفة Unix. يساعد على تحسين الوحداتية والبساطة في الكود"},"seo":{"title":{"en":"unix-review: Code Review Setup Guide | AI Agent Skill","zh":"Unix 代码审查工具 - 17 条规则指南","ja":"Unix コードレビューツール - ベストプラクティスガイド","ko":"유닉스 코드 리뷰 도구 - 17가지 규칙 설정 가이드","es":"Guía de configuración de unix-review: Mejores prácticas d...","fr":"Guide de configuration unix-review: Examens de code effic...","de":"Einrichtungsleitfaden für unix-review: Code-Review-Tools","pt":"Guia de Configuração unix-review: Análise de Código com F...","ru":"Руководство по настройке unix-review: Обзор кода с помощь...","ar":"دليل إعداد unix-review: مراجعة الكود باستخدام فلسفة Unix"},"description":{"en":"Discover how unix-review applies Eric S. Raymond''s principles to evaluate code. Learn how to setup and utilize this AI agent skill for efficient code reviews.","zh":"了解 Unix 代码审查工具的优点和 17 条规则，提高代码质量和可维护性","ja":"Unix コードレビューツールの利点と 17 のルールを学び、コードの品質と保守性を高める","ko":"유닉스 코드 리뷰 도구의 장점과 17 가지 규칙을 알아보고 코드 품질과 유지 보수성을 향상시키세요","es":"Aprende a aplicar los principios de la filosofía Unix en tus proyectos con unix-review, una herramienta de revisión de código basada en AI","fr":"Découvrez comment appliquer les principes de la philosophie Unix dans vos projets avec unix-review, un outil de révision de code basé sur l''IA","de":"Erfahren Sie, wie Sie die Prinzipien der Unix-Philosophie in Ihre Projekte mit unix-review integrieren, einem Code-Review-Tool basierend auf KI","pt":"Aprenda a aplicar a filosofia Unix na análise de código com unix-review. Descubra como melhorar a modularidade e a simplicidade do seu código","ru":"Узнайте, как применять философию Unix при обзоре кода с помощью unix-review. Улучшите модульность и простоту вашего кода","ar":"تعرف على كيفية تطبيق فلسفة Unix في مراجعة الكود باستخدام unix-review. تحسين الوحداتية والبساطة في كودك"},"definition":{"en":"unix-review is a code review skill that applies the principles of the Unix philosophy to evaluate code quality and simplicity.","zh":"Unix 代码审查工具是一种根据 Unix 哲学和 17 条规则审查代码的工具","ja":"Unix コードレビューツールは、Unix 哲学と 17 のルールに基づいてコードをレビューするツールです","ko":"유닉스 코드 리뷰 도구는 유닉스 철학과 17가지 규칙을 기반으로 코드를 리뷰하는 도구입니다","es":"unix-review es una herramienta de revisión de código que aplica los principios de la filosofía Unix para evaluar la calidad del código","fr":"unix-review est un outil de révision de code qui applique les principes de la philosophie Unix pour évaluer la qualité du code","de":"unix-review ist ein Code-Review-Tool, das die Prinzipien der Unix-Philosophie anwendet, um die Qualität des Codes zu bewerten","pt":"unix-review é uma ferramenta de análise de código que aplica os 17 princípios da filosofia Unix para melhorar a qualidade do código","ru":"unix-review - это инструмент для обзора кода, который применяет 17 принципов философии Unix для улучшения качества кода","ar":"unix-review هو أداة لمراجعة الكود التي تطبيق 17 مبدأ من مبادئ فلسفة Unix لتحسين جودة الكود"},"features":{"en":["Applies the 17 Unix rules to evaluate code quality","Uses Glob and Grep to discover source files in directories","Reads important source files directly or recursively","Focuses review on language and patterns used in the code","Evaluates code modularity based on the Rule of Modularity"],"zh":["根据 Unix 哲学和 17 条规则审查代码","支持 Glob 和 Grep 来发现源文件","注重模块化和简单性","支持多种编程语言","使用 CLI 进行代码审查"],"ja":["Unix 哲学と 17 のルールに基づいてコードをレビュー","Glob と Grep を使用してソースファイルを発見","モジュール性とシンプルさに焦点を当て","複数のプログラミング言語をサポート","CLI を使用してコードをレビュー"],"ko":["유닉스 철학과 17가지 규칙을 기반으로 코드를 리뷰","Glob과 Grep을 사용하여 소스 파일을 찾기","모듈화와 단순성에 중점을 둡니다","다중 프로그래밍 언어를 지원","CLI를 사용하여 코드를 리뷰"],"es":["Aplicación de la regla de modularidad","Uso de Glob y Grep para descubrir archivos fuente","Análisis de patrones de código","Evaluación de la calidad del código según los 17 principios de la filosofía Unix","Compatibilidad con directorios y archivos individuales","Integración con herramientas de desarrollo como CLI"],"fr":["Application de la règle de modularité","Utilisation de Glob et Grep pour découvrir les fichiers source","Analyse de modèles de code","Évaluation de la qualité du code selon les 17 principes de la philosophie Unix","Compatibilité avec les répertoires et les fichiers individuels","Intégration avec des outils de développement comme CLI"],"de":["Anwendung der Regel der Modularität","Verwendung von Glob und Grep zur Entdeckung von Quellcode-Dateien","Analyse von Code-Mustern","Bewertung der Code-Qualität nach den 17 Prinzipien der Unix-Philosophie","Kompatibilität mit Verzeichnissen und einzelnen Dateien","Integration mit Entwicklungstools wie CLI"],"pt":["Análise de código com base nos 17 princípios da filosofia Unix","Uso de Glob e Grep para descobrir arquivos de código","Leitura de arquivos de código importantes","Foco na linguagem e padrões utilizados no código","Melhoria da modularidade e simplicidade do código"],"ru":["Обзор кода на основе 17 принципов философии Unix","Использование Glob и Grep для обнаружения файлов кода","Чтение важных файлов кода","Фокус на языке и паттернах, используемых в коде","Улучшение модульности и простоты кода"],"ar":["مراجعة الكود باستخدام 17 مبدأ من مبادئ فلسفة Unix","استخدام Glob و Grep لاكتشاف ملفات الكود","قراءة ملفات الكود المهمة","التركيز على اللغة والأنماط المستخدمة في الكود","تحسين الوحداتية والبساطة في الكود"]},"keywords":{"en":["how to use unix-review","unix-review setup guide","what is unix-review","unix-review alternative","unix-review vs code review tools","unix-review install","eric s raymond unix philosophy"],"zh":["Unix 代码审查","代码质量","可维护性","模块化","简单性","Glob","Grep","CLI","代码审查工具"],"ja":["Unix コードレビュー","コード品質","保守性","モジュール性","シンプルさ","Glob","Grep","CLI","コードレビューツール"],"ko":["유닉스 코드 리뷰","코드 품질","유지 보수성","모듈화","단순성","Glob","Grep","CLI","코드 리뷰 도구"],"es":["herramientas de revisión de código","filosofía Unix","regla de modularidad","Glob y Grep","análisis de patrones de código","evaluación de la calidad del código","desarrollo de software","herramientas de desarrollo","CLI"],"fr":["outils de révision de code","philosophie Unix","règle de modularité","Glob et Grep","analyse de modèles de code","évaluation de la qualité du code","développement de logiciels","outils de développement","CLI","agents d''IA"],"de":["Code-Review-Tools","Unix-Philosophie","Regel der Modularität","Glob und Grep","Code-Muster-Analyse","Code-Qualitäts-Bewertung","Software-Entwicklung","Entwicklungstools","CLI","KI-Agents"],"pt":["unix-review","análise de código","filosofia Unix","modularidade","simplicidade","Glob","Grep","linguagem de programação","padrões de código"],"ru":["unix-review","обзор кода","философия Unix","модульность","простота","Glob","Grep","язык программирования","паттерны кода"],"ar":["unix-review","مراجعة الكود","فلسفة Unix","الوحداتية","ال بساطة","Glob","Grep","لغة البرمجة","أنماط الكود"]}},"owner":"gdgeek","repo":"murder-mystery-generator","repoPath":"gdgeek/murder-mystery-generator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.559Z","topics":[],"category":"community","skillMd":{"name":"unix-review","description":"Review code against Eric S. Raymonds Unix philosophy from The Art of Unix Programming","bodyPreview":"# Unix Philosophy Code Review\n\nYou are a code reviewer applying the principles from Eric S. Raymond''s *The Art of Unix Programming*. Review the code at the path provided by the user argument.\n\nIf the argument is a directory, use Glob and Grep to discover source files, then Read the most important ones. If it''s a single file, Read it directly. Focus your review on the language and patterns actually used in the code.\n\n## The 17 Unix Rules to Evaluate\n\n### 1. Rule of Modularity\nWrite simple parts c","body":"# Unix Philosophy Code Review\n\nYou are a code reviewer applying the principles from Eric S. Raymond''s *The Art of Unix Programming*. Review the code at the path provided by the user argument.\n\nIf the argument is a directory, use Glob and Grep to discover source files, then Read the most important ones. If it''s a single file, Read it directly. Focus your review on the language and patterns actually used in the code.\n\n## The 17 Unix Rules to Evaluate\n\n### 1. Rule of Modularity\nWrite simple parts connected by clean interfaces. Look for:\n- Are modules/functions focused on one thing?\n- Are interfaces between components narrow and well-defined?\n- Could a module be understood in isolation?\n\n### 2. Rule of Clarity\nClarity is better than cleverness. Look for:\n- Is the code straightforward to read?\n- Are clever tricks used where simple code would work?\n- Are names descriptive and intention-revealing?\n\n### 3. Rule of Composition\nDesign programs to be connected with other programs. Look for:\n- Can components be combined with others?\n- Are inputs/outputs in standard, parseable formats?\n- Do components avoid unnecessary assumptions about their callers?\n\n### 4. Rule of Separation\nSeparate policy from mechanism; separate interfaces from engines. Look for:\n- Is configuration/policy mixed into core logic?\n- Are UI/API layers entangled with business logic?\n- Could the mechanism be reused with different policy?\n\n### 5. Rule of Simplicity\nDesign for simplicity; add complexity only where you must. Look for:\n- Features that aren''t used or justified\n- Abstractions that don''t earn their complexity\n- Code that could be simpler without losing functionality\n\n### 6. Rule of Parsimony\nWrite a big program only when nothing else will do. Look for:\n- Could this be broken into smaller, independent tools/modules?\n- Are there monolithic components that do too much?\n- Could a library replace custom code?\n\n### 7. Rule of Transparency\nDesign for visibility to make inspection and debugging easy. Look for:\n- Can you tell what the program is doing by looking at its output/logs?\n- Is internal state inspectable?\n- Are data flows easy to trace?\n\n### 8. Rule of Robustness\nRobustness is the child of transparency and simplicity. Look for:\n- Does the code handle edge cases through simplicity rather than special-case logic?\n- Is error handling straightforward?\n- Are failure modes obvious from the code structure?\n\n### 9. Rule of Representation\nFold knowledge into data so program logic can be stupid and robust. Look for:\n- Complex conditional logic that could be replaced by data structures (tables, maps, configs)\n- Hardcoded behavior that could be data-driven\n- State machines encoded as spaghetti if/else instead of transition tables\n\n### 10. Rule of Least Surprise\nIn interface design, always do the least surprising thing. Look for:\n- Functions/methods that do more than their name implies\n- Surprising side effects\n- Inconsistent conventions within the codebase\n- APIs that violate common expectations for the language/framework\n\n### 11. Rule of Silence\nWhen a program has nothing surprising to say, it should say nothing. Look for:\n- Excessive logging or debug output in normal operation\n- Noisy success messages\n- Output that makes it hard to spot important information\n\n### 12. Rule of Repair\nWhen you must fail, fail noisily and as soon as possible. Look for:\n- Silent error swallowing (bare except, empty catch blocks)\n- Errors that propagate far from their source before being noticed\n- Fallback behavior that masks real problems\n- Missing validation at system boundaries\n\n### 13. Rule of Economy\nProgrammer time is expensive; conserve it in preference to machine time. Look for:\n- Premature optimization that hurts readability\n- Manual processes that could be automated\n- Boilerplate that a tool or abstraction could eliminate\n\n### 14. Rule of Generation\nAvoid hand-hacking; write programs to write programs when you can. Look for:\n- Repetitive code that could be generated\n- Boilerplate that a metaprogramming approach could handle\n- Data transformations done manually that could be templated\n\n### 15. Rule of Optimization\nPrototype before polishing. Get it working before you optimize it. Look for:\n- Premature optimization (complex caching, bit manipulation, etc.) without evidence of need\n- Micro-optimizations that sacrifice clarity\n- Missing the actual bottleneck while optimizing the wrong thing\n\n### 16. Rule of Diversity\nDistrust all claims of \"one true way.\" Look for:\n- Unnecessary lock-in to specific implementations\n- Code that can''t adapt to alternative approaches\n- Over-reliance on a single library/framework when the coupling isn''t justified\n\n### 17. Rule of Extensibility\nDesign for the future, because it will be here sooner than you think. Look for:\n- Hardcoded values that should be configurable\n- Closed designs that can''t accommodate new requirements\n- Missing extension points where growth is likely\n\n## Unix-Specific Anti-Patterns\n\nAlso check for these common anti-patterns:\n- **Binary data formats** where text would work — text is universal, inspectable, and composable\n- **Monolithic designs** where pipeable components would work — small tools chained together beat one big program\n- **Configuration baked into code** — separate config from logic so behavior can change without recompilation\n- **Noisy logging** — quiet on success, noisy on failure (Rule of Silence + Rule of Repair)\n- **Silent failures** — swallowing errors instead of failing fast and loud\n\n## Output Format\n\nStructure your review as follows:\n\n### Summary\n1-2 sentences on how well the code follows Unix philosophy.\n\n### Rule Violations\nGroup findings by rule. For each violation:\n- Which rule is violated\n- The specific location (file:line or function/class name)\n- What the violation is\n- A concrete suggestion for improvement\n\nOnly flag genuine violations — do not manufacture issues. If a rule doesn''t meaningfully apply to this code, skip it.\n\n### Unix Anti-Patterns\nList any anti-patterns detected with specific locations and brief explanations.\n\n### Refactoring Suggestions\nConcrete, actionable steps to better align with Unix philosophy. Prioritize by impact.\n\n### What Follows Unix Philosophy Well\nCall out things the code does right — good modularity, clean composition, transparent operation, smart use of data structures, etc. Be specific.\n"},"lastSynced":"2026-03-08T02:11:35.415Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents applying the Unix philosophy to evaluate modularity and simplicity in codebases.","zh":"适用于应用 Unix 哲学评估代码库模块性和简单性的代码审查代理。","ja":"コードレビューエージェントが Unix 哲学を適用してコードベースのモジュール性とシンプルさを評価するのに適しています。","ko":"코드 리뷰 에이전트가 유닉스 철학을 적용하여 코드베이스의 모듈성과 단순성을 평가하는 데 적합합니다.","es":"Ideal para agentes de revisión de código que aplican la filosofía Unix para evaluar la modularidad y la simplicidad en los códigos.","fr":"Idéal pour les agents de révision de code appliquant la philosophie Unix pour évaluer la modularité et la simplicité dans les bases de code.","de":"Ideal für Code-Review-Agents, die die Unix-Philosophie anwenden, um Modularität und Einfachheit in Codebasen zu bewerten.","pt":"Ideal para Agentes de Revisão de Código que aplicam a filosofia Unix para avaliar a modularidade e a simplicidade em repositórios de código.","ru":"Идеально для агентов кодового обзора, применяющих философию Unix для оценки модульности и простоты в базах кода.","ar":"مثالي لعميل مراجعة الكود الذي يطبق فلسفة يونكس لتقييم الوحداتية والبساطة في قواعد البيانات الكودية."},"recommendation":{"en":"Empowers agents to apply the 17 Unix rules, focusing on modularity and simplicity, using Glob and Grep for source file discovery and evaluating code against the Unix philosophy principles, including the Rule of Modularity.","zh":"赋予代理应用 17 条 Unix 规则的能力，专注于模块性和简单性，使用 Glob 和 Grep 进行源文件发现，并根据 Unix 哲学原则评估代码，包括模块性规则。","ja":"エージェントが 17 の Unix ルールを適用する機能を提供し、モジュール性とシンプルさに焦点を当て、Glob と Grep を使用してソースファイルを発見し、Unix 哲学の原則に従ってコードを評価します。モジュール性のルールを含みます。","ko":"에이전트가 17개의 유닉스 규칙을 적용할 수 있는 기능을 제공하여 모듈성과 단순성에 중점을 두고 Glob과 Grep을 사용하여 소스 파일을 발견하고 유닉스 철학의 원칙에 따라 코드를 평가합니다. 모듈성 규칙을 포함합니다.","es":"Permite a los agentes aplicar las 17 reglas de Unix, centrándose en la modularidad y la simplicidad, utilizando Glob y Grep para la detección de archivos fuente y evaluando el código contra los principios de la filosofía Unix, incluida la Regla de Modularidad.","fr":"Permet aux agents d''appliquer les 17 règles Unix, en se concentrant sur la modularité et la simplicité, en utilisant Glob et Grep pour la découverte de fichiers source et en évaluant le code contre les principes de la philosophie Unix, y compris la Règle de Modularité.","de":"Ermöglicht es Agenten, die 17 Unix-Regeln anzuwenden, mit Fokus auf Modularität und Einfachheit, unter Verwendung von Glob und Grep zur Quellcodedetektion und Auswertung des Codes gegen die Prinzipien der Unix-Philosophie, einschließlich der Regel der Modularität.","pt":"Habilita os agentes a aplicarem as 17 regras Unix, com foco na modularidade e simplicidade, utilizando Glob e Grep para descoberta de arquivos de origem e avaliando o código contra os princípios da filosofia Unix, incluindo a Regra da Modularidade.","ru":"Наделяет агентов возможностью применения 17 правил Unix, сосредоточив внимание на модульности и простоте, используя Glob и Grep для обнаружения исходных файлов и оценки кода на соответствие принципам философии Unix, включая Правило Модульности.","ar":"تمكن العملاء من تطبيق القواعد 17 لليونكس، مع التركيز على الوحداتية والبساطة، باستخدام Glob و Grep لاكتشاف ملفات المصدر وتقييم الكود مقابل مبادئ فلسفة يونكس، بما في ذلك قاعدة الوحداتية."},"useCases":{"en":["Evaluating code modularity","Applying the Unix philosophy to simplify codebases","Discovering source files using Glob and Grep"],"zh":["评估代码模块性","应用 Unix 哲学简化代码库","使用 Glob 和 Grep 发现源文件"],"ja":["コードのモジュール性を評価する","Unix 哲学を適用してコードベースを簡素化する","Glob と Grep を使用してソースファイルを発見する"],"ko":["코드 모듈성을 평가한다","유닉스 철학을 적용하여 코드베이스를 단순화한다","Glob과 Grep을 사용하여 소스 파일을 발견한다"],"es":["Evaluación de la modularidad del código","Aplicación de la filosofía Unix para simplificar los códigos","Detección de archivos fuente utilizando Glob y Grep"],"fr":["Évaluation de la modularité du code","Application de la philosophie Unix pour simplifier les bases de code","Découverte de fichiers source en utilisant Glob et Grep"],"de":["Bewertung der Modularität des Codes","Anwendung der Unix-Philosophie zur Vereinfachung von Codebasen","Entdeckung von Quellcode-Dateien unter Verwendung von Glob und Grep"],"pt":["Avaliar a modularidade do código","Aplicar a filosofia Unix para simplificar repositórios de código","Descobrir arquivos de origem usando Glob e Grep"],"ru":["Оценка модульности кода","Применение философии Unix для упрощения баз кода","Обнаружение исходных файлов с помощью Glob и Grep"],"ar":["تقييم الوحداتية الكودية","تطبيق فلسفة يونكس لتسريع قواعد البيانات الكودية","اكتشاف ملفات المصدر باستخدام Glob و Grep"]},"limitations":{"en":["Requires access to file system or code repository","Limited to evaluating code against the 17 Unix rules"],"zh":["需要访问文件系统或代码仓库","仅限于评估代码对 17 条 Unix 规则的遵守"],"ja":["ファイルシステムまたはコードリポジトリへのアクセスが必要","コードを 17 の Unix ルールに対して評価することのみに限定"],"ko":["파일 시스템 또는 코드 저장소에 대한 액세스가 필요합니다","코드를 17개의 유닉스 규칙에 대해 평가하는 것만으로 제한"],"es":["Requiere acceso al sistema de archivos o al repositorio de código","Limitado a la evaluación del código contra las 17 reglas de Unix"],"fr":["Nécessite un accès au système de fichiers ou au référentiel de code","Limité à l''évaluation du code contre les 17 règles Unix"],"de":["Benötigt Zugriff auf Dateisystem oder Code-Repository","Begrenzt auf die Auswertung des Codes gegen die 17 Unix-Regeln"],"pt":["Exige acesso ao sistema de arquivos ou repositório de código","Limitado à avaliação do código contra as 17 regras Unix"],"ru":["Требует доступа к файловой системе или хранилищу кода","Ограничен оценкой кода только по 17 правилам Unix"],"ar":["يتطلب الوصول إلى نظام الملفات أو مستودع الكود","محدود بتقييم الكود مقابل القواعد 17 لليونكس"]},"version":4},"contentHash":"484af14b0c897efdff55ab0e772e56469cec40cc4b22d0f383d0ec88224c29f2","qualityScore":50}');
