INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gdgeek/murder-mystery-generator/unix-review', 'unix-review', 'gdgeek', 'murder-mystery-generator', 'community', 'unix-review gdgeek murder-mystery-generator community The unix-review skill applies the Unix philosophy to review code, focusing on modularity and simplicity. It benefits developers by evaluating code against the 17 Unix rules. Unix 代码审查工具根据 Eric S. Raymond 的《The Art of Unix Programming》原则审查代码，注重模块化和简单性 Unix コードレビューツールは、Eric S. Raymond の『The Art of Unix Programming』の原則に基づいてコードをレビューし、モジュール性とシンプルさに焦点を当てています 유닉스 코드 리뷰 도구는 Eric S. Raymond의『The Art of Unix Programming』원칙에 따라 코드를 리뷰하며 모듈화와 단순성에 중점을 둡니다 unix-review es una herramienta de revisión de código que aplica los principios de la filosofía Unix, como la regla de modularidad y el uso de Glob y Grep unix-review est un outil de révision de code qui applique les principes de la philosophie Unix, tels que la règle de modularité et l''utilisation de Glob et Grep unix-review ist ein Code-Review-Tool, das die Prinzipien der Unix-Philosophie anwendet, wie die Regel der Modularität und die Verwendung von Glob und Grep unix-review é uma ferramenta de análise de código que aplica os princípios da filosofia Unix. Ele ajuda a melhorar a modularidade e a simplicidade do código unix-review - это инструмент для обзора кода, который применяет принципы философии Unix. Он помогает улучшить модульность и простоту кода unix-review هو أداة لمراجعة الكود التي تطبيق مبادئ فلسفة Unix. يساعد على تحسين الوحداتية والبساطة في الكود how to use unix-review unix-review setup guide what is unix-review unix-review alternative unix-review vs code review tools unix-review install eric s raymond unix philosophy Unix 代码审查 代码质量 可维护性 模块化 简单性 Glob Grep CLI 代码审查工具 Applies the 17 Unix rules to evaluate code quality Uses Glob and Grep to discover source files in directories Reads important source files directly or recursively Focuses review on language and patterns used in the code Evaluates code modularity based on the Rule of Modularity unix-review is a code review skill that applies the principles of the Unix philosophy to evaluate code quality and simplicity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('olafkfreund/nixos_config/niri', 'community', 'olafkfreund', 'nixos_config', 'olafkfreund/nixos_config', 'niri', 0, 0, 50, '2026-03-08T01:57:15.564Z', '2026-03-08T02:11:39.228Z', '2a7edfa6a1f51c5348697fa8b54c420a3305f6bd7d1e1fe3af38751d27218ea3', '{"id":"olafkfreund/nixos_config/niri","name":"niri","description":{"en":"The niri skill provides comprehensive support for configuring and customizing the niri Wayland compositor in NixOS, benefiting developers and power users. It offers expert guidance on dynamic workspaces and infinite horizontal desktop paradigm.","zh":"Niri 是一个用于配置和自定义 NixOS 中 Wayland 组合器的技能，提供滚动平铺窗口管理和动态工作空间的支持","ja":"Niri は、NixOS で Wayland コンポジターを設定し、カスタマイズするためのスキルで、スクロール可能なタイルウィンドウ管理と動的ワークスペースを提供","ko":"Niri는 NixOS에서 Wayland 컴포지터를 설정하고 커스터마이즈하는 데 사용되는 기술로, 스크롤 가능한 타일 창 관리와 동적 워크스페이스를 제공","es":"niri es un skill especializado para configurar y personalizar el compositor Wayland en NixOS","fr":"niri est un skill spécialisé pour configurer et personnaliser le compositor Wayland dans NixOS","de":"niri ist ein spezialisierter Skill für die Konfiguration und Anpassung des Wayland-Compositors in NixOS","pt":"O niri é um skill especializado para configurar e personalizar o niri Wayland compositor no NixOS. Fornece orientação especializada sobre gerenciamento de janelas e workspaces.","ru":"Niri - это специализированный навык для конфигурации и настройки niri Wayland compositor в NixOS. Предоставляет экспертные советы по управлению окнами и рабочими пространствами.","ar":"نيري هو مهارة متخصصة لضبط و تخصيص نيري Wayland compositor في نيكس او إس. يوفر إرشادات متخصصة حول إدارة النوافذ و مساحات العمل"},"seo":{"title":{"en":"niri: NixOS Configuration Setup Guide | AI Agent Skill","zh":"Niri 配置指南 - Wayland 组合器设置最佳实践","ja":"Niri Setup Guide - Wayland コンポジターのカスタマイズ","ko":"Niri 설정 가이드 - Wayland 컴포지터 커스터마이즈","e