INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('olafkfreund/nixos_config/niri', 'niri', 'olafkfreund', 'nixos_config', 'community', 'niri olafkfreund nixos_config community The niri skill provides comprehensive support for configuring and customizing the niri Wayland compositor in NixOS, benefiting developers and power users. It offers expert guidance on dynamic workspaces and infinite horizontal desktop paradigm. Niri 是一个用于配置和自定义 NixOS 中 Wayland 组合器的技能，提供滚动平铺窗口管理和动态工作空间的支持 Niri は、NixOS で Wayland コンポジターを設定し、カスタマイズするためのスキルで、スクロール可能なタイルウィンドウ管理と動的ワークスペースを提供 Niri는 NixOS에서 Wayland 컴포지터를 설정하고 커스터마이즈하는 데 사용되는 기술로, 스크롤 가능한 타일 창 관리와 동적 워크스페이스를 제공 niri es un skill especializado para configurar y personalizar el compositor Wayland en NixOS niri est un skill spécialisé pour configurer et personnaliser le compositor Wayland dans NixOS niri ist ein spezialisierter Skill für die Konfiguration und Anpassung des Wayland-Compositors in NixOS O niri é um skill especializado para configurar e personalizar o niri Wayland compositor no NixOS. Fornece orientação especializada sobre gerenciamento de janelas e workspaces. Niri - это специализированный навык для конфигурации и настройки niri Wayland compositor в NixOS. Предоставляет экспертные советы по управлению окнами и рабочими пространствами. نيري هو مهارة متخصصة لضبط و تخصيص نيري Wayland compositor في نيكس او إس. يوفر إرشادات متخصصة حول إدارة النوافذ و مساحات العمل how to use niri niri setup guide niri vs sway niri install niri configuration nixos niri wayland compositor home manager scrollable-tiling window management Niri Wayland 组合器 NixOS Home Manager 滚动平铺窗口管理 动态工作空间 AIエージェント 配置指南 Provides expert guidance on scrollable-tiling window management Supports dynamic workspaces configuration Offers declarative configuration for niri Wayland compositor Enables infinite horizontal desktop paradigm Utilizes Home Manager for NixOS integration Configures niri vi for customized user experience niri is a specialized skill for configuring and customizing the niri Wayland compositor in NixOS using Home Manager.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('khanaleema/PhysicalAI-Book/book-scaffolding', 'community', 'khanaleema', 'PhysicalAI-Book', 'khanaleema/PhysicalAI-Book', 'book-scaffolding', 0, 0, 50, '2026-03-08T01:57:15.569Z', '2026-03-08T02:11:43.868Z', '8c72c59ec67f7c26d29478f0680fc2cbb4d62af2ffe62f3396e2cbaaba77aed9', '{"id":"khanaleema/PhysicalAI-Book/book-scaffolding","name":"book-scaffolding","description":{"en":"The book-scaffolding skill helps developers plan, structure, and scaffold educational books using cognitive load management and pedagogical best practices, benefiting AI agents and educators.","zh":"Book Scaffolding 技术用于计划、结构和搭建大型教育书籍，使用认知负荷管理和教学最佳实践","ja":"Book Scaffolding 技術は、教育書籍の構造と内容を計画、構築するために使用されます","ko":"Book Scaffolding 기술은 교육용 책의 구조와 콘텐츠를 계획하고 구축하는 데 사용됩니다","es":"La herramienta de book-scaffolding permite planificar y estructurar libros educativos grandes utilizando la gestión de la carga cognitiva y las mejores prácticas pedagógicas","fr":"L''outil de book-scaffolding permet de planifier et de structurer de grands livres éducatifs en utilisant la gestion de la charge cognitive et les meilleures pratiques pédagogiques","de":"Das Book-Scaffolding-Tool ermöglicht die Planung und Strukturierung großer Bildungsbücher unter Verwendung der kognitiven Belastungsmanagement und der besten pädagogischen Praktiken","pt":"O skill de estruturação de livros permite planejar e estruturar livros educacionais grandes com gerenciamento de carga cognitiva e práticas pedagógicas","ru":"Навык каркаса книги позволяет планировать и структурировать большие образовательные книги с помощью управления когнитивной нагрузкой и педагогическими лучшими практиками","ar":"مهارة هيكل الكتاب تسمح بتخطيط وتنظيم الكتب التعليمية الكبيرة باستخدام إدارة الحمل المعرفي وأفضل الممارسات البيداغوجية"},"seo":{"title":{"en":"book-scaffolding: Structure Planning Setup Guide 