INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('khanaleema/PhysicalAI-Book/book-scaffolding', 'book-scaffolding', 'khanaleema', 'PhysicalAI-Book', 'community', 'book-scaffolding khanaleema PhysicalAI-Book community The book-scaffolding skill helps developers plan, structure, and scaffold educational books using cognitive load management and pedagogical best practices, benefiting AI agents and educators. Book Scaffolding 技术用于计划、结构和搭建大型教育书籍，使用认知负荷管理和教学最佳实践 Book Scaffolding 技術は、教育書籍の構造と内容を計画、構築するために使用されます Book Scaffolding 기술은 교육용 책의 구조와 콘텐츠를 계획하고 구축하는 데 사용됩니다 La herramienta de book-scaffolding permite planificar y estructurar libros educativos grandes utilizando la gestión de la carga cognitiva y las mejores prácticas pedagógicas L''outil de book-scaffolding permet de planifier et de structurer de grands livres éducatifs en utilisant la gestion de la charge cognitive et les meilleures pratiques pédagogiques Das Book-Scaffolding-Tool ermöglicht die Planung und Strukturierung großer Bildungsbücher unter Verwendung der kognitiven Belastungsmanagement und der besten pädagogischen Praktiken O skill de estruturação de livros permite planejar e estruturar livros educacionais grandes com gerenciamento de carga cognitiva e práticas pedagógicas Навык каркаса книги позволяет планировать и структурировать большие образовательные книги с помощью управления когнитивной нагрузкой и педагогическими лучшими практиками مهارة هيكل الكتاب تسمح بتخطيط وتنظيم الكتب التعليمية الكبيرة باستخدام إدارة الحمل المعرفي وأفضل الممارسات البيداغوجية how to use book-scaffolding book-scaffolding setup guide what is book-scaffolding book-scaffolding alternative book-scaffolding vs traditional teaching methods cognitive load management techniques pedagogical best practices for AI agents book-scaffolding install book-scaffolding tutorial Book Scaffolding AI 工具 教育书籍结构规划 认知负荷管理 4 层教学法 AI 三角色框架 就-in-time 规范 教学最佳实践 Specification Primacy Implements 4-Layer Teaching Method for progressive lesson structure Utilizes Specification Primacy for efficient book planning Applies AI Three Roles Framework for effective teaching Manages cognitive load for improved student understanding Supports just-in-time specification for flexible book development Follows v4.0.1 constitution alignment for standardized book scaffolding book-scaffolding is a technique for planning, structuring, and scaffolding large educational books using cognitive load management and pedagogical best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marswangyang/Roger/resume-latex-pdf-generator', 'community', 'marswangyang', 'Roger', 'marswangyang/Roger', 'resume-latex-pdf-generator', 0, 0, 50, '2026-03-08T01:57:15.574Z', '2026-03-08T02:11:48.223Z', '266111c24a7317a677b241cc9116de2e5d49af92691babbdf0ad7e9cc3755026', '{"id":"marswangyang/Roger/resume-latex-pdf-generator","name":"resume-latex-pdf-generator","description":{"en":"The resume-latex-pdf-generator AI agent generates tailored LaTeX resumes and cover letters based on each job description, benefiting developers and job seekers. It produces high-impact resumes that fit strictly on one page.","zh":"AI智能简历生成器能够根据每个工作描述生成定制的LaTeX简历和求职信，确保简历在US Letter大小的一页内严格排版","ja":"AIエージェントは、各求人に合わせてLaTeX ResumeとCover Letterを生成し、US Letterサイズの1ページ内に厳密に配置します","ko":"AI 인재 채용 관리는 각 채용공고에 맞춘 LaTeX 이력서와 자기소개서를 생성하며, US Letter 크기의 1페이지 내에서 엄격한 배치로 구성합니다","es":"El generador de currículums LaTeX crea currículums y cartas de presentación personalizadas basadas en cada descripción de trabajo, utilizando plantillas LaTeX y el servidor mcp-latex.","fr":"Le générateur de CV LaTeX crée des CV et des lettres de motivation sur mesure en fonction de chaque description de poste, en utilisant des modèles LaTeX et le serveur mcp-latex.","de":"Der LaTeX-Lebenslauf-Generator erstellt individuelle Lebensläufe und Bewerbungsschreiben basierend auf jeder Stellenbeschreibung, unter Verwendung von LaTeX-Vorlagen und dem mcp-latex-Server.","pt":"O gerador de CV em LaTeX é uma ferramenta de AI que cria currículos personalizados em LaTeX, com base em descrições de trabalho, utilizando templates e servidor mcp-latex","ru":"Генератор резюме LaTeX - это инструмент ИИ Агентов, создающий индивидуальные резюме в формате LaTeX на основе описаний работы, используя шаблоны и сервер mcp-latex","ar":"جهاز توليد سيرة ذاتية LaTeX هو أداة ذكاء اصطناعي تقوم بإنشاء سير ذاتية مخصصة باللغة اللاتينية بناءً على وصفات العمل، باستخدام قوالب و خادم mcp-latex"},"seo":{"title":{"en":"resume-latex-pdf-generator: LaTeX Resume Setup Guide | AI...","zh":"AI智能简历生成器：LaTeX PDF 简历制作设置指南","ja":"AIエージェントを使用したLaTeX PDF Resumeの作成ベストプラクティス","ko":"AI 인재 채용 관리: LaTeX PDF 이력서 생성 가이드","es":"Generador de currículums LaTeX: Guía de configuración","fr":"Générateur de CV LaTeX: Meilleures pratiques","de":"LaTeX-Lebenslauf-Generator: Einrichtungsanleitung","pt":"Guia de Configuração do Gerador de CV em LaTeX com Ferram...","ru":"Руководство по настройке генератора резюме LaTeX с помощь...","ar":"دليل إعداد جهاز توليد سيرة ذاتية LaTeX مدعوم بالذكاء الاص..."},"description":{"en":"Discover how to generate tailored LaTeX resumes and cover letters with the resume-latex-pdf-generator AI agent. Learn to create high-impact, one-page resumes...","zh":"使用AI智能简历生成器创建专业的LaTeX PDF简历和求职信，根据每个工作描述量身定制","ja":"AIエージェントを使用して、求人ごとにカスタマイズされたLaTeX PDF ResumeとCover Letterを生成します","ko":"AI 인재 채용 관리를 사용하여 각 채용공고에 맞춘 LaTeX PDF 이력서와 자기소개서를 생성하세요","es":"Crea currículums personalizados con nuestro generador de currículums LaTeX, diseñado para ajustarse a una página de tamaño carta de EE. UU.","fr":"Créez des CV sur mesure avec notre générateur de CV LaTeX, conçu pour tenir sur une page de format lettre américain","de":"Erstellen Sie individuelle Lebensläufe mit unserem LaTeX-Lebenslauf-Generator, der auf eine Seite im US-Letter-Format passt","pt":"Aprenda a criar currículos personalizados em LaTeX com o gerador de CV em LaTeX, utilizando ferramentas de AI para uma apresentação profissional","ru":"Создавайте индивидуальные резюме в формате LaTeX с помощью генератора резюме LaTeX и инструментов ИИ Агентов для профессионального оформления","ar":"تعلم كيفية إنشاء سير ذاتية مخصصة باللغة اللاتينية باستخدام جهاز توليد سيرة ذاتية LaTeX وادوات الذكاء الاصطناعي لتحقيق مظهر احترافي"},"definition":{"en":"resume-latex-pdf-generator is an AI-powered resume generator agent that creates customized LaTeX resumes and cover letters based on job descriptions.","zh":"AI智能简历生成器是一种使用LaTeX模板和mcp-latex-server工具的AI驱动简历生成工具","ja":"AIエージェントは、LaTeXテンプレートとmcp-latex-serverツールを使用したAI駆動のResume生成ツールです","ko":"AI 인재 채용 관리는 LaTeX 템플릿과 mcp-latex-server 툴을 사용하는 AI 기반 이력서 생성 툴입니다","es":"Un agente de inteligencia artificial que genera currículums LaTeX personalizados y cartas de presentación","fr":"Un agent d''intelligence artificielle qui génère des CV LaTeX sur mesure et des lettres de motivation","de":"Ein künstlicher Intelligenz-Agent, der individuelle LaTeX-Lebensläufe und Bewerbungsschreiben generiert","pt":"O que é um gerador de CV em LaTeX? É uma ferramenta de AI que cria currículos personalizados em LaTeX","ru":"Что такое генератор резюме LaTeX? Это инструмент ИИ Агентов, создающий индивидуальные резюме в формате LaTeX","ar":"ما هو جهاز توليد سيرة ذاتية LaTeX؟ هو أداة ذكاء اصطناعي لإنشاء سير ذاتية مخصصة باللغة اللاتينية"},"features":{"en":["Generates LaTeX resumes using the mcp-latex-server tools","Produces resumes strictly on one page (US Letter size, 8.5 x 11 inches)","Utilizes professional serif or sans-serif fonts for readability","Supports template customization via ./templates/*_resume.tex files","Ensures no widows, no orphans, and no spill-over in the generated resume"],"zh":["使用LaTeX模板生成专业的简历","根据每个工作描述量身定制简历","严格控制简历在US Letter大小的一页内排版","支持专业的serif和sans-serif字体","使用mcp-latex-server工具生成PDF文件"],"ja":["LaTeXテンプレートを使用してプロフェッショナルなResumeを生成","各求人に合わせてResumeをカスタマイズ","US Letterサイズの1ページ内に厳密に配置","プロフェッショナルなserifとsans-serifフォントをサポート","mcp-latex-serverツールを使用してPDFファイルを生成"],"ko":["LaTeX 템플릿을 사용하여 전문적인 이력서를 생성","각 채용공고에 맞춘 이력서를 생성","US Letter 크기의 1페이지 내에서 엄격한 배치","전문적인 serif와 sans-serif 글꼴을 지원","mcp-latex-server 툴을 사용하여 PDF 파일을 생성"],"es":["Utiliza plantillas LaTeX personalizadas","Se ajusta estrictamente a una página de tamaño carta de EE. UU.","Soporte para fuentes serifa y sans-serif profesionales","Integración con el servidor mcp-latex","Generación de currículums y cartas de presentación","Diseño responsive para una lectura óptima"],"fr":["Utilise des modèles LaTeX sur mesure","S''adapte strictement à une page de format lettre américain","Prise en charge de polices serifa et sans-serif professionnelles","Intégration au serveur mcp-latex","Génération de CV et de lettres de motivation","Conception réactive pour une lecture optimale"],"de":["Verwendet individuelle LaTeX-Vorlagen","Passt sich streng an eine Seite im US-Letter-Format an","Unterstützung für professionelle Serifen- und Sans-Serif-Schriften","Integration in den mcp-latex-Server","Erstellung von Lebensläufen und Bewerbungsschreiben","Reaktives Design für optimale Lesbarkeit"],"pt":["Utiliza templates em LaTeX para criar currículos personalizados","Suporta servidor mcp-latex para processamento de LaTeX","Gera currículos em tamanho US Letter (8,5 x 11 polegadas)","Limita o tamanho do currículo a uma página","Utiliza fontes serif ou sans-serif profissionais","Compatível com ferramentas de AI para personalização"],"ru":["Использует шаблоны LaTeX для создания индивидуальных резюме","Поддерживает сервер mcp-latex для обработки LaTeX","Генерирует резюме в размере US Letter (8,5 x 11 дюймов)","Ограничивает размер резюме одной страницей","Использует профессиональные шрифты serif или sans-serif","Совместим с инструментами ИИ Агентов для персонализации"],"ar":["يستخدم قوالب اللاتينية لإنشاء سير ذاتية مخصصة","يدعم خادم mcp-latex لمعالجة اللاتينية","ينشئ سير ذاتية بحجم ورقة أمريكية (8.5 × 11 بوصة)","يقيد حجم السيرة الذاتية بصفحة واحدة","يستخدم خطوطاً احترافية من نوع serif أو sans-serif","متوافق مع أدوات الذكاء الاصطناعي للتصميم الشخصي"]},"keywords":{"en":["how to use resume-latex-pdf-generator","resume-latex-pdf-generator setup guide","latex resume generator","resume-latex-pdf-generator alternative","resume-latex-pdf-generator vs other generators","resume-latex-pdf-generator install","what is resume-latex-pdf-generator","resume-latex-pdf-generator template customization","latex resume templates"],"zh":["AI智能简历生成器","LaTeX PDF简历","求职信生成","简历排版","US Letter大小","mcp-latex-server工具","LaTeX模板"],"ja":["AIエージェント","LaTeX PDF Resume","Cover Letter生成","Resume配置","US Letterサイズ","mcp-latex-serverツール","LaTeXテンプレート"],"ko":["AI 인재 채용 관리","LaTeX PDF 이력서","자기소개서 생성","이력서 배치","US Letter 크기","mcp-latex-server 툴","LaTeX 템플릿"],"es":["generador de currículums LaTeX","agente de inteligencia artificial para currículums","currículums personalizados","plantillas LaTeX","mcp-latex","diseño de currículums","currículums en una página","fuentes serifa y sans-serif","integración con servidor"],"fr":["générateur de CV LaTeX","agent d''intelligence artificielle pour CV","CV sur mesure","modèles LaTeX","mcp-latex","conception de CV","CV en une page","polices serifa et sans-serif","intégration au serveur"],"de":["LaTeX-Lebenslauf-Generator","künstlicher Intelligenz-Agent für Lebensläufe","individuelle Lebensläufe","LaTeX-Vorlagen","mcp-latex","Lebenslauf-Design","Lebensläufe auf einer Seite","Serifen- und Sans-Serif-Schriften","Integration in den Server"],"pt":["gerador de cv em latex","ferramentas de ai para cv","templates de latex para cv","servidor mcp-latex","currículos personalizados","latex para cv","ai para cv","ferramentas de latex para cv","cv em uma página"],"ru":["генератор резюме latex","инструменты ии агентов для резюме","шаблоны latex для резюме","сервер mcp-latex","индивидуальные резюме","latex для резюме","ии агенты для резюме","инструменты latex для резюме","резюме на одной странице"],"ar":["جهاز توليد سيرة ذاتية latex","أدوات الذكاء الاصطناعي لسيرة ذاتية","قوالب اللاتينية لسيرة ذاتية","خادم mcp-latex","سير ذاتية مخصصة","اللاتينية لسيرة ذاتية","الذكاء الاصطناعي لسيرة ذاتية","أدوات اللاتينية لسيرة ذاتية","سيرة ذاتية في صفحة واحدة"]}},"owner":"marswangyang","repo":"Roger","repoPath":"marswangyang/Roger","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.574Z","topics":[],"category":"community","skillMd":{"name":"resume-latex-pdf-generator","description":"Generates and compiles a single-page US Letter LaTeX resume using selected experiences.","bodyPreview":"# Instruction\n\nYou are an expert LaTeX Typesetter and Resume Engineer. Your primary constraint is to produce a high-impact resume that fits strictly on **ONE PAGE (US Letter size)**.\n\n## Dependencies\n\n- **Template:** Located at `./templates/*_resume.tex`.\n- **Server:** You must use the `mcp-latex-server` tools.\n\n## Constraints\n\n1.  **Size:** US Letter (8.5 x 11 inches).\n2.  **Length:** STRICTLY 1 Page. No widows, no orphans, no spill-over.\n3.  **Font:** Professional serif or sans-serif, readable","body":"# Instruction\n\nYou are an expert LaTeX Typesetter and Resume Engineer. Your primary constraint is to produce a high-impact resume that fits strictly on **ONE PAGE (US Letter size)**.\n\n## Dependencies\n\n- **Template:** Located at `./templates/*_resume.tex`.\n- **Server:** You must use the `mcp-latex-server` tools.\n\n## Constraints\n\n1.  **Size:** US Letter (8.5 x 11 inches).\n2.  **Length:** STRICTLY 1 Page. No widows, no orphans, no spill-over.\n3.  **Font:** Professional serif or sans-serif, readable size (min 11pt for body, never go below 11pt).\n4.  **Chronological Order:** All experiences MUST be arranged in reverse chronological order (most recent ending date first, oldest last).\n5.  **Space Utilization:** The page should be well-balanced—neither too sparse nor too cramped. Minimize excessive whitespace at the bottom of the page.\n\n## Content Writing Guidelines\n\nWhen crafting resume bullet points, follow these best practices:\n\n### Action Verb Usage\n- **Start with strong action verbs** (past tense for previous roles, present tense for current roles)\n- Examples of strong verbs by category:\n  - **Leadership/Management:** Directed, Orchestrated, Spearheaded, Championed, Mentored\n  - **Technical/Development:** Architected, Engineered, Implemented, Optimized, Debugged, Deployed\n  - **Analysis/Research:** Analyzed, Evaluated, Investigated, Diagnosed, Assessed\n  - **Achievement/Results:** Achieved, Delivered, Exceeded, Improved, Increased, Reduced\n  - **Communication:** Presented, Documented, Collaborated, Coordinated\n- Avoid weak verbs like \"Helped with,\" \"Worked on,\" \"Responsible for\"\n\n### Bullet Point Structure\n- **Format:** [Action Verb] + [What you did] + [How you did it] + [Result/Impact]\n- **Example:** \"Architected microservices infrastructure using Docker and Kubernetes, reducing deployment time from 2 hours to 15 minutes\"\n- **Quantify whenever possible:** Use numbers, percentages, time savings, or scale (e.g., \"serving 10M users\")\n- **Be specific:** Replace \"improved performance\" with \"reduced API latency from 200ms to 120ms\"\n\n### Technical Depth\n- **Name specific technologies:** Instead of \"database optimization,\" write \"optimized PostgreSQL queries with indexing strategies\"\n- **Show scale and complexity:** Mention data volume, user count, system components\n- **Highlight problem-solving:** Briefly mention the challenge before the solution\n\n## Workflow\n\n### Step 1: Content Optimization (Space Management)\n\nReview the \"Targeted Experiences\" provided by `ExperienceSelector`.\n\n- **Chronological Sorting:** Arrange all experiences in **reverse chronological order** by end date. The most recently ended position appears first, the oldest appears last.\n\n- **Volume Check:** If the input content seems too voluminous for a single page:\n  - **Condense:** Merge similar bullet points.\n  - **Trim:** Remove the least significant bullet point from the oldest relevant job.\n  - **Reword:** **(IMPORTANT)** Shorten lines to **eliminate orphans**. An orphan occurs when: \n  \n    - A single word appears on a new line\n    - The second line of any content contains fewer than 25 characters (including spaces and symbols)\n    - Technical Skills section exceeds the LaTeX-defined line width (based on page width and margins). It must fit within a single rendered line in the final PDF\n  - **Bullet Point Length:** Each bullet point MUST NOT exceed 2 lines. Three-line bullet points are NOT acceptable. If a bullet point is too long, condense it or split the information across two separate bullets.\n  - **Acronym:** If a word or noun has a widely recognized professional acronym, then use it (e.g., \"Application Programming Interface\" → \"API\", \"Artificial Intelligence\" → \"AI\"). Avoid creating non-standard abbreviations.\n\n- **Metrics & Data:** When presenting achievements:\n  - **Prefer Absolute Numbers:** Use concrete numbers over percentages when possible (e.g., \"Reduced API latency from 200ms to 120ms\" is better than \"Reduced latency by 40%\"). Absolute values provide more specific, tangible evidence.\n  - **Context Matters:** If percentages are used, include the baseline for clarity (e.g., \"Improved throughput by 60% (from 1000 to 1600 requests/sec)\").\n\n- **Space Balance:** Adjust spacing between sections (`\\vspace{}`) to ensure the page is well-utilized. Avoid leaving excessive whitespace at the bottom—the content should fill most of the page while maintaining readability.\n\n### Step 2: LaTeX Configuration\n\n1.  Read the **complete** template file using `read_file`.\n2.  **IMPORTANT:** The template already contains all necessary preamble (documentclass, packages, geometry, etc.). Use the template''s **entire content** as-is. Do NOT add or generate any additional LaTeX preamble.\n3.  Verify the template has US Letter configuration:\n    - `\\documentclass[letterpaper,11pt]{article}`\n    - `\\usepackage[margin=0.5in]{geometry}` (or similar efficient margins).\n4.  **Map Content:** Replace only the placeholders (e.g., `\\VAR{experience_section}`, `\\VAR{education_section}`) with the optimized experience data. Keep everything else from the template unchanged.\n\n### Step 3: Safety & Sanitization\n\n- **Escape Characters:** You **MUST** escape these characters to prevent compile crashes:\n  - `&` $\\rightarrow$ `\\&`\n  - `%` $\\rightarrow$ `\\%`\n  - `$` $\\rightarrow$ `\\$`\n  - `#` $\\rightarrow$ `\\#`\n  - `_` $\\rightarrow$ `\\_`\n\n### Step 4: Execution (Write & Compile)\n\n1.  **Write:** Use `create_latex_file` with the `content` parameter to provide the **complete template content** (with placeholders replaced). \n    \n    **IMPORTANT:** \n    - **DO NOT** manually create directories or execute shell commands (e.g., `mkdir`). The MCP server will automatically handle directory creation.\n    - The tool will automatically create the `AI_Resume/` folder and timestamped subfolders as needed.\n    \n    **CRITICAL - Prevent Duplicate Preamble:**\n    - **DO NOT** use the `document_type`, `title`, `author`, `packages`, or `geometry` parameters, as these will cause the tool to auto-generate a duplicate preamble\n    - The `content` parameter should contain the complete LaTeX document starting with the template''s **exact first line** (whether it''s a comment, `\\documentclass`, or any other content) and ending with `\\end{document}`\n    - **DO NOT** add any new comments or headers at the beginning (e.g., avoid adding `%-------------------------` or `% Resume in Latex` or `% Author : ...`). If the template already has such comments, keep them; otherwise, start directly with the template''s original first line\n    - **ONLY** replace the placeholders (e.g., `\\VAR{experience_section}`, `\\VAR{name}`, `\\VAR{email}`) with actual content\n    - This ensures no duplicate declarations like extra `\\documentclass{article}`, `\\usepackage[utf8]{inputenc}`, `\\usepackage[T1]{fontenc}`, `\\usepackage[english]{babel}`, or `\\begin{document}` are added\n    \n2.  **Compile:** Use `compile_pdf`.\n3.  **Self-Correction (The Feedback Loop):**\n    - **Syntax Errors:** If `compile_pdf` fails, read the log, fix the syntax, and retry.\n    - **Character Escaping Verification:** After any edit or rewrite, re-verify that all special characters are properly escaped (`&`, `%`, `$`, `#`, `_`). Compilation failures often result from missed escape sequences.\n    - **Vertical Overflow:** If the tool output or log indicates \"Overfull \\vbox\" or explicit overflow warnings:\n      - **Action:** Reduce vertical spacing (`\\vspace{-...}`), condense bullet points, or remove one more bullet point. DO NOT reduce font size below 11pt.\n      - **Retry:** Re-write and Re-compile.\n    - **Orphan Detection (IMPORTANT):** Review the PDF for orphans using these criteria:\n      - Single words on their own line\n      - Any second line with fewer than 25 characters (including spaces and symbols)\n      - Technical Skills section exceeding the LaTeX-defined line width. It must fit within a single rendered line in the PDF (constrained by the page width and margins set in LaTeX)\n      If found, rephrase or condense to eliminate them.\n    - **Bullet Point Length Check:** Verify that no bullet point exceeds 2 lines. If any do, rephrase or split them.\n    - **Space Balance:** If the PDF has excessive whitespace at the bottom (more than 0.5 inches):\n      - **Option 1:** Increase spacing between sections slightly (`\\vspace{0.05in}`).\n      - **Option 2:** Increase paragraph spacing using `\\setlength{\\parskip}{0.05in}` or adjust itemize/enumerate spacing with `\\setlength{\\itemsep}{0.05in}`.\n      - **Option 3:** Return to `experience-selector` and select additional relevant experiences or projects from `/context` to fill the space. The goal is a balanced, professional-looking page that maximizes the use of available space.\n  \n\n## Output\n\nReturn the absolute path of the generated PDF and confirm: \"Resume generated successfully (1 Page).\"\n"},"lastSynced":"2026-03-08T02:11:48.223Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, and Claude Code needing automated LaTeX resume and cover letter generation capabilities.","zh":"非常适合像 Cursor、Windsurf 和 Claude Code 这样的 AI Agents，它们需要自动化 LaTeX 简历和求职信生成功能。","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに適しています。これらは自動化された LaTeX Resume とカバーレター生成機能を必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합합니다. 자동화된 LaTeX 이력서 및 커버레터 생성 기능이 필요한 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA como Cursor, Windsurf y Claude Code que necesitan capacidades de generación automática de currículums y cartas de presentación en LaTeX.","fr":"Parfait pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin de capacités de génération automatique de CV et de lettres de motivation en LaTeX.","de":"Perfekt für KI-Agenten wie Cursor, Windsurf und Claude Code, die eine automatisierte LaTeX-Lebenslauf- und Bewerbungsschreiben-Generierung benötigen.","pt":"Perfeito para Agentes de IA como Cursor, Windsurf e Claude Code que precisam de capacidades de geração automática de currículos e cartas de apresentação LaTeX.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым требуются возможности автоматизированной генерации резюме и сопроводительных писем LaTeX.","ar":"مثالي لعمليات وكيلات الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code التي تحتاج إلى إمكانيات تلقائية لإنشاء سيرة ذاتية ورسائل تقديم LaTeX."},"recommendation":{"en":"Empowers agents to generate high-impact, tailored LaTeX resumes and cover letters in PDF format using the mcp-latex-server tools, strictly fitting on one US Letter-sized page with professional serif or sans-serif fonts.","zh":"赋予代理生成高影响力、定制化的 LaTeX 简历和求职信的能力，以 PDF 格式呈现，使用 mcp-latex-server 工具，严格遵守一张 US Letter 尺寸的页面，采用专业的衬线或无衬线字体。","ja":"エージェントが mcp-latex-server ツールを使用して、高いインパクトを持つカスタマイズされた LaTeX Resume とカバーレターを PDF フォーマットで生成できる力を与えます。厳密に 1 ページ (US レター サイズ: 8.5 x 11 インチ) で、プロフェッショナルなセリフまたはサンセリフ フォントを使用します。","ko":"에이전트가 mcp-latex-server 도구를 사용하여 높은 영향을 미치는 맞춤형 LaTeX 이력서 및 커버레터를 PDF 형식으로 생성할 수 있는 기능을 제공합니다. 엄격히 1ページ(US 레터 크기: 8.5 x 11 인치)로, 전문적인 세리프 또는 산세리프 글꼴을 사용합니다.","es":"Permite a los agentes generar currículums y cartas de presentación en LaTeX de alto impacto y personalizados en formato PDF utilizando las herramientas mcp-latex-server, ajustándose estrictamente a una página de tamaño US Letter con fuentes serifa o sans serifa profesionales.","fr":"Permet aux agents de générer des CV et des lettres de motivation en LaTeX à forte incidence et personnalisés au format PDF en utilisant les outils mcp-latex-server, s''ajustant strictement à une page de taille US Letter avec des polices de caractères serif ou sans serif professionnelles.","de":"Ermöglicht es den Agenten, hochwertige, maßgeschneiderte LaTeX-Lebensläufe und Bewerbungsschreiben im PDF-Format zu erstellen, indem sie die mcp-latex-server-Tools verwenden, die sich strikt auf eine Seite im US-Letter-Format (8,5 x 11 Zoll) mit professionellen Serifen- oder Sans-Serif-Schriften beschränken.","pt":"Habilita os agentes a gerar currículos e cartas de apresentação LaTeX personalizados de alto impacto no formato PDF, utilizando as ferramentas mcp-latex-server, estritamente ajustados a uma página do tamanho US Letter com fontes serif ou sans-serif profissionais.","ru":"Позволяет агентам генерировать резюме и сопроводительные письма LaTeX высокого качества, адаптированные под конкретного получателя, в формате PDF, используя инструменты mcp-latex-server, строго вписывающиеся на одну страницу размера US Letter с профессиональными шрифтами serif или sans-serif.","ar":"تمكّن الوكيل من إنشاء سيرة ذاتية ورسائل تقديم LaTeX ذات تأثير عالٍ ومتوافقة مع الحجم المحدد، باستخدام أدوات mcp-latex-server، ومتوافقة مع حجم ورقة الحرف الأمريكي مع خطوط مهنية من نوع serif أو sans-serif."},"useCases":{"en":["Automating resume generation for job seekers based on specific job descriptions","Generating tailored cover letters to complement LaTeX resumes","Producing high-impact, one-page resumes in PDF format for developers and job applicants"],"zh":["根据具体的工作描述为求职者自动生成简历","生成与 LaTeX 简历相配的定制化求职信","为开发人员和求职者生成高影响力的单页简历，保存为 PDF 格式"],"ja":["特定の仕事の説明に基づいて求職者向けの履歴書を自動生成する","LaTeX Resume に合うようにカスタマイズされたカバーレターを生成する","開発者や求職者向けに高いインパクトを持つ 1 ページの履歴書を PDF フォーマットで生成する"],"ko":["구체적인 작업 설명에 따라 이력서를 자동으로 생성하는 것","LaTeX 이력서를 보완하는 맞춤형 커버레터를 생성하는 것","개발자 및求職자를 위한 높은 영향을 미치는 단일 페이지 이력서를 PDF 형식으로 생성하는 것"],"es":["Automatizar la generación de currículums para buscadores de empleo basados en descripciones de trabajo específicas","Generar cartas de presentación personalizadas para complementar los currículums en LaTeX","Producir currículums de alto impacto de una página en formato PDF para desarrolladores y solicitantes de empleo"],"fr":["Automatiser la génération de CV pour les chercheurs d''emploi en fonction de descriptions de travail spécifiques","Générer des lettres de motivation personnalisées pour compléter les CV en LaTeX","Produire des CV à forte incidence d''une page au format PDF pour les développeurs et les candidats à l''emploi"],"de":["Automatisieren der Generierung von Lebensläufen für Stellenbewerber basierend auf spezifischen Stellenbeschreibungen","Erstellen maßgeschneiderter Bewerbungsschreiben, um LaTeX-Lebensläufe zu ergänzen","Erstellen hochwertiger, einseitiger Lebensläufe im PDF-Format für Entwickler und Stellenbewerber"],"pt":["Automatizar a geração de currículos para candidatos com base em descrições de trabalhos específicas","Gerar cartas de apresentação personalizadas para complementar currículos LaTeX","Produzir currículos de alto impacto em um único página no formato PDF para desenvolvedores e candidatos a emprego"],"ru":["Автоматизировать генерацию резюме для соискателей на основе конкретных описаний вакансий","Генерировать адаптированные сопроводительные письма для дополнения резюме LaTeX","Производить резюме высокого качества на одной странице в формате PDF для разработчиков и соискателей работы"],"ar":["تحويل إنشاء السيرة الذاتية تلقائيًا لمقدمي الطلبات بناءً على وصفات العمل المحددة","إنشاء رسائل تقديم مخصصة لتحقيق توافق مع السيرة الذاتية LaTeX","إنتاج سيرة ذاتية ذات تأثير عالٍ على صفحة واحدة بالحجم المحدد في شكل PDF لمطوري البرامج ومقدمي الطلبات"]},"limitations":{"en":["Requires mcp-latex-server tools","Strictly limited to one page (US Letter size: 8.5 x 11 inches)","Dependent on templates located at ./templates/*_resume.tex"],"zh":["需要 mcp-latex-server 工具","严格限制在一张页面内（US Letter 尺寸: 8.5 x 11 英寸）","依赖于 ./templates/*_resume.tex 中的模板"],"ja":["mcp-latex-server ツールを必要とする","厳密に 1 ページ (US レター サイズ: 8.5 x 11 インチ) 限定","./templates/*_resume.tex にあるテンプレートに依存する"],"ko":["mcp-latex-server 도구가 필요합니다","严格히 1페이지(US 레터 크기: 8.5 x 11 인치)로 제한됩니다","./templates/*_resume.tex에 있는 템플릿에 의존합니다"],"es":["Requiere las herramientas mcp-latex-server","Estrictamente limitado a una página (tamaño US Letter: 8,5 x 11 pulgadas)","Dependiente de plantillas ubicadas en ./templates/*_resume.tex"],"fr":["Nécessite les outils mcp-latex-server","Strictement limité à une page (taille US Letter : 8,5 x 11 pouces)","Dépendant de modèles situés à ./templates/*_resume.tex"],"de":["Benötigt die mcp-latex-server-Tools","Streng limitiert auf eine Seite (US-Letter-Größe: 8,5 x 11 Zoll)","Abhängig von Vorlagen, die sich unter ./templates/*_resume.tex befinden"],"pt":["Exige as ferramentas mcp-latex-server","Estritamente limitado a uma página (tamanho US Letter: 8,5 x 11 polegadas)","Dependente de modelos localizados em ./templates/*_resume.tex"],"ru":["Требует инструментов mcp-latex-server","Строго ограничен одной страницей (размер US Letter: 8,5 x 11 дюймов)","Зависит от шаблонов, расположенных в ./templates/*_resume.tex"],"ar":["يتطلب أدوات mcp-latex-server","محدود строгоً بصفحة واحدة (حجم ورقة الحرف الأمريكي: 8.5 × 11 إنش)","يعتمد على القوالب الموجودة في ./templates/*_resume.tex"]},"version":4},"contentHash":"266111c24a7317a677b241cc9116de2e5d49af92691babbdf0ad7e9cc3755026","qualityScore":50}');
