INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marswangyang/Roger/resume-latex-pdf-generator', 'resume-latex-pdf-generator', 'marswangyang', 'Roger', 'community', 'resume-latex-pdf-generator marswangyang Roger community The resume-latex-pdf-generator AI agent generates tailored LaTeX resumes and cover letters based on each job description, benefiting developers and job seekers. It produces high-impact resumes that fit strictly on one page. AI智能简历生成器能够根据每个工作描述生成定制的LaTeX简历和求职信，确保简历在US Letter大小的一页内严格排版 AIエージェントは、各求人に合わせてLaTeX ResumeとCover Letterを生成し、US Letterサイズの1ページ内に厳密に配置します AI 인재 채용 관리는 각 채용공고에 맞춘 LaTeX 이력서와 자기소개서를 생성하며, US Letter 크기의 1페이지 내에서 엄격한 배치로 구성합니다 El generador de currículums LaTeX crea currículums y cartas de presentación personalizadas basadas en cada descripción de trabajo, utilizando plantillas LaTeX y el servidor mcp-latex. Le générateur de CV LaTeX crée des CV et des lettres de motivation sur mesure en fonction de chaque description de poste, en utilisant des modèles LaTeX et le serveur mcp-latex. Der LaTeX-Lebenslauf-Generator erstellt individuelle Lebensläufe und Bewerbungsschreiben basierend auf jeder Stellenbeschreibung, unter Verwendung von LaTeX-Vorlagen und dem mcp-latex-Server. O gerador de CV em LaTeX é uma ferramenta de AI que cria currículos personalizados em LaTeX, com base em descrições de trabalho, utilizando templates e servidor mcp-latex Генератор резюме LaTeX - это инструмент ИИ Агентов, создающий индивидуальные резюме в формате LaTeX на основе описаний работы, используя шаблоны и сервер mcp-latex جهاز توليد سيرة ذاتية LaTeX هو أداة ذكاء اصطناعي تقوم بإنشاء سير ذاتية مخصصة باللغة اللاتينية بناءً على وصفات العمل، باستخدام قوالب و خادم mcp-latex how to use resume-latex-pdf-generator resume-latex-pdf-generator setup guide latex resume generator resume-latex-pdf-generator alternative resume-latex-pdf-generator vs other generators resume-latex-pdf-generator install what is resume-latex-pdf-generator resume-latex-pdf-generator template customization latex resume templates AI智能简历生成器 LaTeX PDF简历 求职信生成 简历排版 US Letter大小 mcp-latex-server工具 LaTeX模板 Generates LaTeX resumes using the mcp-latex-server tools Produces resumes strictly on one page (US Letter size, 8.5 x 11 inches) Utilizes professional serif or sans-serif fonts for readability Supports template customization via ./templates/*_resume.tex files Ensures no widows, no orphans, and no spill-over in the generated resume resume-latex-pdf-generator is an AI-powered resume generator agent that creates customized LaTeX resumes and cover letters based on job descriptions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brandonlacoste9-tech/korean-AI-compliance-/security-auditor', 'community', 'brandonlacoste9-tech', 'korean-AI-compliance-', 'brandonlacoste9-tech/korean-AI-compliance-', 'security-auditor', 0, 0, 50, '2026-03-08T01:57:15.578Z', '2026-03-08T02:11:50.405Z', '3e8ce87e5756a58bee4a3ab2e3fb69f92ef7f3654334829bf06b6c42ad4a5bc8', '{"id":"brandonlacoste9-tech/korean-AI-compliance-/security-auditor","name":"security-auditor","description":{"en":"The security-auditor skill helps DevSecOps teams run security audits, review SDLC security controls, and investigate vulnerabilities. It benefits companies impacted by Korea''s AI Basic Act.","zh":"安全审计员是一种专门的AI工具，帮助开发人员进行安全审计和风险评估，确保CI/CD和合规性","ja":"セキュリティ監査員は、開発者がセキュリティ監査とリスク評価を実行し、CI/CDとコンプライアンスを確保するのに役立つ専門のAIエージェントです","ko":"보안 감사员은 개발자가 보안 감사를 수행하고 위험을 평가하여 CI/CD 및 규정 준수를 보장하는 전문 AI 도구입니다","es":"El security-auditor es un experto en DevSecOps que ayuda a auditar la seguridad de las aplicaciones y cumplir con las normas de seguridad","fr":"Le security-auditor est un expert en DevSecOps qui aide à auditer la sécurité des applications et à respecter les normes de sécurité","de":"Der Security-Auditor ist ein Experte für DevSecOps, der bei der Überprüfung der Sicherheit von Anwendungen und der Einhaltung von Sicherheitsstandards hilft","pt":"O Security Auditor é uma ferramenta especializada em DevSecOps e segurança de aplicativos, ajudando a identificar vulnerabilidades e melhorar a segurança.","ru":"ИИ Агент безопасности - это специализированная herramienta для DevSecOps и безопасности приложений, помогающая выявлять уязвимости и улучшать безопасность","ar":"مراقب الأمان هو أداة متخصصة في DevSecOps وأمان التطبيقات، تساعد في تحديد الثغرات وأمان التحسين"},"seo":{"title":{"en":"security-auditor: Compliance Setup Guide for AI Agents","zh":"安全审计员设置指南","ja":"セキュリティ監査員のベストプラクティス","ko":"보안 감사员 구축 가이드","es":"Guía de configuración de Security Auditor para DevSecOps","fr":"Guide de mise en place de l''auditeur de sécurité pour Dev...","de":"Einrichtungsleitfaden für Security Auditor in DevSecOps","pt":"Guia de Configuração do Security Auditor para Desenvolved...","ru":"Руководство по настройке ИИ Агента безопасности для разра...","ar":"دليل إعداد مراقب الأمان للמطورين"},"description":{"en":"Discover how security-auditor helps you navigate Korea''s AI Basic Act. Get compliant with our expert guide and avoid ₩30 million penalties. Learn more now!","zh":"了解安全审计员的功能和用途，包括DevSecOps、应用程序安全和综合网络安全实践","ja":"セキュリティ監査員の機能と用途を学び、DevSecOps、应用程序セキュリティ、総合ネットワークセキュリティ実践を理解する","ko":"보안 감사员의 기능과 용도를 이해하고 DevSecOps, 애플리케이션 보안, 포괄적인 네트워크 보안 실무를 학습합니다","es":"Aprende a utilizar el skill de security-auditor para auditar la seguridad de tus aplicaciones y cumplir con las normas de seguridad","fr":"Découvrez comment utiliser le skill de security-auditor pour auditer la sécurité de vos applications et respecter les normes de sécurité","de":"Erfahren Sie, wie Sie das Skill von security-auditor verwenden, um die Sicherheit Ihrer Anwendungen zu überprüfen und die Sicherheitsstandards einzuhalten","pt":"Aprenda a configurar o Security Auditor para garantir a segurança dos seus aplicativos e sistemas, incluindo SDLC e CI/CD","ru":"Узнайте, как настроить ИИ Агента безопасности для обеспечения безопасности ваших приложений и систем, включая SDLC и CI/CD","ar":"تعلم كيفية إعداد مراقب الأمان لتأمين تطبيقاتك ونظمك، بما في ذلك SDLC و CI/CD"},"definition":{"en":"security-auditor is a specialized skill for DevSecOps, application security, and comprehensive cybersecurity practices, ensuring compliance with regulations like Korea''s AI Basic Act.","zh":"安全审计员是指使用DevSecOps、应用程序安全和综合网络安全实践进行安全审计和风险评估的AI工具","ja":"セキュリティ監査員は、DevSecOps、应用程序セキュリティ、総合ネットワークセキュリティ実践を使用してセキュリティ監査とリスク評価を実行するAIエージェントのこと","ko":"보안 감사员은 DevSecOps, 애플리케이션 보안, 포괄적인 네트워크 보안 실무를 사용하여 보안 감사를 수행하고 위험을 평가하는 AI 도구입니다","es":"Un security-auditor es un experto que realiza auditorías de seguridad y evalúa el riesgo de las aplicaciones","fr":"Un auditeur de sécurité est un expert qui effectue des audits de sécurité et évalue le risque des applications","de":"Ein Security-Auditor ist ein Experte, der Sicherheitsaudits durchführt und das Risiko von Anwendungen bewertet","pt":"O Security Auditor é uma ferramenta de segurança que ajuda a identificar e mitigar vulnerabilidades em aplicativos e sistemas","ru":"ИИ Агент безопасности - это инструмент безопасности, помогающий выявлять и смягчать уязвимости в приложениях и системах","ar":"مراقب الأمان هو أداة أمان تساعد في تحديد والتخفيف من الثغرات في التطبيقات والنظم"},"features":{"en":["Runs security audits and risk assessments for compliance readiness","Reviews SDLC security controls, CI/CD, and authentication protocols","Investigates vulnerabilities and designs mitigation plans","Validates authorization, data protection controls, and compliance standards","Supports comprehensive cybersecurity practices for DevSecOps teams"],"zh":["支持DevSecOps和应用程序安全","提供CI/CD和合规性审计","能够进行风险评估和漏洞分析","支持验证身份验证、授权和数据保护控制","提供安全审计和风险评估报告"],"ja":["DevSecOpsと应用程序セキュリティをサポート","CI/CDとコンプライアンス監査を提供","リスク評価と脆弱性分析を実行","認証、認可、データ保護コントロールの検証をサポート","セキュリティ監査とリスク評価レポートを提供"],"ko":["DevSecOps와 애플리케이션 보안을 지원","CI/CD와 규정 준수 감사 제공","위험 평가와 취약성 분석 수행","인증, 인가, 데이터 보호 제어의 검증 지원","보안 감사 및 위험 평가 보고서 제공"],"es":["Análisis de vulnerabilidades y diseño de planes de mitigación","Validación de controles de autenticación, autorización y protección de datos","Revisión de controles de seguridad en el ciclo de vida de desarrollo de software (SDLC)","Evaluación de la preparación para la cumplimiento normativo","Análisis de riesgos y auditorías de seguridad","Integración con herramientas de DevSecOps"],"fr":["Analyse des vulnérabilités et conception de plans de mitigation","Validation des contrôles d''authentification, d''autorisation et de protection des données","Révision des contrôles de sécurité dans le cycle de vie de développement de logiciels (SDLC)","Évaluation de la préparation au respect des normes","Analyse des risques et audits de sécurité","Intégration avec des outils de DevSecOps"],"de":["Analyse von Schwachstellen und Entwurf von Minderungsplänen","Validierung von Authentifizierungs-, Autorisierungs- und Datenschutzkontrollen","Überprüfung von Sicherheitskontrollen im Software-Entwicklungslebenszyklus (SDLC)","Bewertung der Einhaltung von Sicherheitsstandards","Risikoanalyse und Sicherheitsaudits","Integration mit DevSecOps-Tools"],"pt":["Análise de riscos e auditorias de segurança","Revisão de controles de segurança do SDLC","Investigação de vulnerabilidades e design de planos de mitigação","Validação de controles de autenticação, autorização e proteção de dados","Integração com CI/CD para garantir a segurança contínua"],"ru":["Анализ рисков и аудиты безопасности","Проверка контроля безопасности SDLC","Расследование уязвимостей и разработка планов смягчения","Валидация контроля аутентификации, авторизации и защиты данных","Интеграция с CI/CD для обеспечения непрерывной безопасности"],"ar":["تحليل المخاطر والتدقيق الأمني","مراجعة ضوابط أمان SDLC","تحقيق الثغرات وتصميم خطط التخفيف","التحقق من ضوابط التحقق والتفويض وحماية البيانات","التكامل مع CI/CD لضمان الأمان المستمر"]},"keywords":{"en":["how to use security-auditor","security-auditor compliance guide","Korea''s AI Basic Act penalties","security-auditor vs competitors","security-auditor setup guide","DevSecOps security auditor tools","application security best practices","CI/CD security controls","compliance readiness checklist"],"zh":["安全审计员","DevSecOps","应用程序安全","综合网络安全","CI/CD","合规性","风险评估","漏洞分析","身份验证","授权","数据保护"],"ja":["セキュリティ監査員","DevSecOps","应用程序セキュリティ","総合ネットワークセキュリティ","CI/CD","コンプライアンス","リスク評価","脆弱性分析","認証","認可","データ保護"],"ko":["보안 감사员","DevSecOps","애플리케이션 보안","포괄적인 네트워크 보안","CI/CD","규정 준수","위험 평가","취약성 분석","인증","인가","데이터 보호"],"es":["security auditor","DevSecOps","auditoría de seguridad","análisis de vulnerabilidades","cumplimiento normativo","seguridad de aplicaciones","herramientas de seguridad","auditoría de riesgos","plan de mitigación"],"fr":["auditeur de sécurité","DevSecOps","audit de sécurité","analyse de vulnérabilités","respect des normes","sécurité des applications","outils de sécurité","audit de risques","plan de mitigation"],"de":["Security-Auditor","DevSecOps","Sicherheitsaudit","Schwachstellenanalyse","Einhalting von Sicherheitsstandards","Sicherheit von Anwendungen","Sicherheitstools","Risikoaudit","Minderungsplan"],"pt":["Security Auditor","DevSecOps","segurança de aplicativos","análise de riscos","auditorias de segurança","SDLC","CI/CD","vulnerabilidades","mitigação de riscos"],"ru":["ИИ Агент безопасности","DevSecOps","безопасность приложений","анализ рисков","аудиты безопасности","SDLC","CI/CD","уязвимости","смягчение рисков"],"ar":["مراقب الأمان","DevSecOps","أمان التطبيقات","تحليل المخاطر","تدقيق الأمن","SDLC","CI/CD","الثغرات","تخفيف المخاطر"]}},"owner":"brandonlacoste9-tech","repo":"korean-AI-compliance-","repoPath":"brandonlacoste9-tech/korean-AI-compliance-","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.578Z","topics":[],"category":"community","skillMd":{"name":"security-auditor","description":"Expert security auditor specializing in DevSecOps, comprehensive","bodyPreview":"You are a security auditor specializing in DevSecOps, application security, and comprehensive cybersecurity practices.\n\n## Use this skill when\n\n- Running security audits or risk assessments\n- Reviewing SDLC security controls, CI/CD, or compliance readiness\n- Investigating vulnerabilities or designing mitigation plans\n- Validating authentication, authorization, and data protection controls\n\n## Do not use this skill when\n\n- You lack authorization or scope approval for security testing\n- You need l","body":"You are a security auditor specializing in DevSecOps, application security, and comprehensive cybersecurity practices.\n\n## Use this skill when\n\n- Running security audits or risk assessments\n- Reviewing SDLC security controls, CI/CD, or compliance readiness\n- Investigating vulnerabilities or designing mitigation plans\n- Validating authentication, authorization, and data protection controls\n\n## Do not use this skill when\n\n- You lack authorization or scope approval for security testing\n- You need legal counsel or formal compliance certification\n- You only need a quick automated scan without manual review\n\n## Instructions\n\n1. Confirm scope, assets, and compliance requirements.\n2. Review architecture, threat model, and existing controls.\n3. Run targeted scans and manual verification for high-risk areas.\n4. Prioritize findings by severity and business impact with remediation steps.\n5. Validate fixes and document residual risk.\n\n## Safety\n\n- Do not run intrusive tests in production without written approval.\n- Protect sensitive data and avoid exposing secrets in reports.\n\n## Purpose\nExpert security auditor with comprehensive knowledge of modern cybersecurity practices, DevSecOps methodologies, and compliance frameworks. Masters vulnerability assessment, threat modeling, secure coding practices, and security automation. Specializes in building security into development pipelines and creating resilient, compliant systems.\n\n## Capabilities\n\n### DevSecOps & Security Automation\n- **Security pipeline integration**: SAST, DAST, IAST, dependency scanning in CI/CD\n- **Shift-left security**: Early vulnerability detection, secure coding practices, developer training\n- **Security as Code**: Policy as Code with OPA, security infrastructure automation\n- **Container security**: Image scanning, runtime security, Kubernetes security policies\n- **Supply chain security**: SLSA framework, software bill of materials (SBOM), dependency management\n- **Secrets management**: HashiCorp Vault, cloud secret managers, secret rotation automation\n\n### Modern Authentication & Authorization\n- **Identity protocols**: OAuth 2.0/2.1, OpenID Connect, SAML 2.0, WebAuthn, FIDO2\n- **JWT security**: Proper implementation, key management, token validation, security best practices\n- **Zero-trust architecture**: Identity-based access, continuous verification, principle of least privilege\n- **Multi-factor authentication**: TOTP, hardware tokens, biometric authentication, risk-based auth\n- **Authorization patterns**: RBAC, ABAC, ReBAC, policy engines, fine-grained permissions\n- **API security**: OAuth scopes, API keys, rate limiting, threat protection\n\n### OWASP & Vulnerability Management\n- **OWASP Top 10 (2021)**: Broken access control, cryptographic failures, injection, insecure design\n- **OWASP ASVS**: Application Security Verification Standard, security requirements\n- **OWASP SAMM**: Software Assurance Maturity Model, security maturity assessment\n- **Vulnerability assessment**: Automated scanning, manual testing, penetration testing\n- **Threat modeling**: STRIDE, PASTA, attack trees, threat intelligence integration\n- **Risk assessment**: CVSS scoring, business impact analysis, risk prioritization\n\n### Application Security Testing\n- **Static analysis (SAST)**: SonarQube, Checkmarx, Veracode, Semgrep, CodeQL\n- **Dynamic analysis (DAST)**: OWASP ZAP, Burp Suite, Nessus, web application scanning\n- **Interactive testing (IAST)**: Runtime security testing, hybrid analysis approaches\n- **Dependency scanning**: Snyk, WhiteSource, OWASP Dependency-Check, GitHub Security\n- **Container scanning**: Twistlock, Aqua Security, Anchore, cloud-native scanning\n- **Infrastructure scanning**: Nessus, OpenVAS, cloud security posture management\n\n### Cloud Security\n- **Cloud security posture**: AWS Security Hub, Azure Security Center, GCP Security Command Center\n- **Infrastructure security**: Cloud security groups, network ACLs, IAM policies\n- **Data protection**: Encryption at rest/in transit, key management, data classification\n- **Serverless security**: Function security, event-driven security, serverless SAST/DAST\n- **Container security**: Kubernetes Pod Security Standards, network policies, service mesh security\n- **Multi-cloud security**: Consistent security policies, cross-cloud identity management\n\n### Compliance & Governance\n- **Regulatory frameworks**: GDPR, HIPAA, PCI-DSS, SOC 2, ISO 27001, NIST Cybersecurity Framework\n- **Compliance automation**: Policy as Code, continuous compliance monitoring, audit trails\n- **Data governance**: Data classification, privacy by design, data residency requirements\n- **Security metrics**: KPIs, security scorecards, executive reporting, trend analysis\n- **Incident response**: NIST incident response framework, forensics, breach notification\n\n### Secure Coding & Development\n- **Secure coding standards**: Language-specific security guidelines, secure libraries\n- **Input validation**: Parameterized queries, input sanitization, output encoding\n- **Encryption implementation**: TLS configuration, symmetric/asymmetric encryption, key management\n- **Security headers**: CSP, HSTS, X-Frame-Options, SameSite cookies, CORP/COEP\n- **API security**: REST/GraphQL security, rate limiting, input validation, error handling\n- **Database security**: SQL injection prevention, database encryption, access controls\n\n### Network & Infrastructure Security\n- **Network segmentation**: Micro-segmentation, VLANs, security zones, network policies\n- **Firewall management**: Next-generation firewalls, cloud security groups, network ACLs\n- **Intrusion detection**: IDS/IPS systems, network monitoring, anomaly detection\n- **VPN security**: Site-to-site VPN, client VPN, WireGuard, IPSec configuration\n- **DNS security**: DNS filtering, DNSSEC, DNS over HTTPS, malicious domain detection\n\n### Security Monitoring & Incident Response\n- **SIEM/SOAR**: Splunk, Elastic Security, IBM QRadar, security orchestration and response\n- **Log analysis**: Security event correlation, anomaly detection, threat hunting\n- **Vulnerability management**: Vulnerability scanning, patch management, remediation tracking\n- **Threat intelligence**: IOC integration, threat feeds, behavioral analysis\n- **Incident response**: Playbooks, forensics, containment procedures, recovery planning\n\n### Emerging Security Technologies\n- **AI/ML security**: Model security, adversarial attacks, privacy-preserving ML\n- **Quantum-safe cryptography**: Post-quantum cryptographic algorithms, migration planning\n- **Zero-knowledge proofs**: Privacy-preserving authentication, blockchain security\n- **Homomorphic encryption**: Privacy-preserving computation, secure data processing\n- **Confidential computing**: Trusted execution environments, secure enclaves\n\n### Security Testing & Validation\n- **Penetration testing**: Web application testing, network testing, social engineering\n- **Red team exercises**: Advanced persistent threat simulation, attack path analysis\n- **Bug bounty programs**: Program management, vulnerability triage, reward systems\n- **Security chaos engineering**: Failure injection, resilience testing, security validation\n- **Compliance testing**: Regulatory requirement validation, audit preparation\n\n## Behavioral Traits\n- Implements defense-in-depth with multiple security layers and controls\n- Applies principle of least privilege with granular access controls\n- Never trusts user input and validates everything at multiple layers\n- Fails securely without information leakage or system compromise\n- Performs regular dependency scanning and vulnerability management\n- Focuses on practical, actionable fixes over theoretical security risks\n- Integrates security early in the development lifecycle (shift-left)\n- Values automation and continuous security monitoring\n- Considers business risk and impact in security decision-making\n- Stays current with emerging threats and security technologies\n\n## Knowledge Base\n- OWASP guidelines, frameworks, and security testing methodologies\n- Modern authentication and authorization protocols and implementations\n- DevSecOps tools and practices for security automation\n- Cloud security best practices across AWS, Azure, and GCP\n- Compliance frameworks and regulatory requirements\n- Threat modeling and risk assessment methodologies\n- Security testing tools and techniques\n- Incident response and forensics procedures\n\n## Response Approach\n1. **Assess security requirements** including compliance and regulatory needs\n2. **Perform threat modeling** to identify potential attack vectors and risks\n3. **Conduct comprehensive security testing** using appropriate tools and techniques\n4. **Implement security controls** with defense-in-depth principles\n5. **Automate security validation** in development and deployment pipelines\n6. **Set up security monitoring** for continuous threat detection and response\n7. **Document security architecture** with clear procedures and incident response plans\n8. **Plan for compliance** with relevant regulatory and industry standards\n9. **Provide security training** and awareness for development teams\n\n## Example Interactions\n- \"Conduct comprehensive security audit of microservices architecture with DevSecOps integration\"\n- \"Implement zero-trust authentication system with multi-factor authentication and risk-based access\"\n- \"Design security pipeline with SAST, DAST, and container scanning for CI/CD workflow\"\n- \"Create GDPR-compliant data processing system with privacy by design principles\"\n- \"Perform threat modeling for cloud-native application with Kubernetes deployment\"\n- \"Implement secure API gateway with OAuth 2.0, rate limiting, and threat protection\"\n- \"Design incident response plan with forensics capabilities and breach notification procedures\"\n- \"Create security automation with Policy as Code and continuous compliance monitoring\"\n"},"lastSynced":"2026-03-08T02:11:50.405Z","agentAnalysis":{"suitability":{"en":"Ideal for DevSecOps Agents requiring advanced vulnerability assessment and compliance auditing capabilities.","zh":"适合需要高级漏洞评估和合规审计功能的DevSecOps代理。","ja":"高度な脆弱性評価およびコンプライアンス監査機能を必要とするDevSecOpsエージェントに適しています。","ko":"고급 취약점 평가 및 규정 준수 심사 기능을 필요한 DevSecOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevSecOps que requieren una evaluación de vulnerabilidades avanzada y capacidades de auditoría de cumplimiento.","fr":"Idéal pour les agents DevSecOps nécessitant une évaluation avancée des vulnérabilités et des capacités d''audit de conformité.","de":"Ideal für DevSecOps-Agents, die eine erweiterte Schwachstellenbewertung und Konformitätsprüfungsfunktionen erfordern.","pt":"Ideal para Agentes DevSecOps que exigem avaliação avançada de vulnerabilidades e capacidades de auditoria de conformidade.","ru":"Идеально подходит для агентов DevSecOps, требующих продвинутой оценки уязвимостей и возможностей аудита соответствия требованиям.","ar":"مثالي لعميل DevSecOps الذين يتطلبون تقييم متقدم للضعف وأدوات تدقيق الامتثال."},"recommendation":{"en":"Empowers agents to run comprehensive security audits, review SDLC security controls, and investigate vulnerabilities using protocols like CI/CD, while validating authentication, authorization, and data protection controls. It provides benefits for companies impacted by regulations such as Korea''s AI Basic Act, ensuring compliance readiness. By leveraging this skill, agents can enhance their security testing capabilities, including risk assessments and mitigation planning.","zh":"赋予代理运行全面安全审计的能力，审查SDLC安全控制，并使用CI/CD等协议调查漏洞，同时验证身份验证、授权和数据保护控制。它为受到韩国AI基础法等法规影响的公司提供了合规准备的好处。通过利用此技能，代理可以增强其安全测试功能，包括风险评估和缓解规划。","ja":"エージェントが包括的なセキュリティ監査を実行し、SDLCのセキュリティコントロールを確認し、CI/CDなどのプロトコルを使用して脆弱性を調査し、同時に認証、認可、データ保護コントロールを検証する能力を提供します。韓国のAI基本法などの規制の影響を受ける企業に対しては、コンプライアンスの準備を提供します。このスキルを利用することで、エージェントはリスク評価や緩和計画を含むセキュリティテスト機能を強化できます。","ko":"에이전트가 포괄적인 보안 감사를 실행하고, SDLC 보안 통제를 검토하고, CI/CD와 같은 프로토콜을 사용하여 취약점을 조사하며,同時에 인증, 인가 및 데이터 보호 통제를 검증할 수 있는 능력을 제공합니다. 한국의 AI 기본법과 같은 규제의 영향을 받는 회사에게는 규정준수 준비를 제공합니다. 이 기능을 활용함으로써 에이전트는 위험 평가 및 완화 계획을 포함하여 보안 테스트 기능을 강화할 수 있습니다.","es":"Habilita a los agentes a ejecutar auditorías de seguridad integrales, revisar controles de seguridad de SDLC, e investigar vulnerabilidades utilizando protocolos como CI/CD, mientras valida controles de autenticación, autorización y protección de datos. Proporciona beneficios para las empresas afectadas por regulaciones como la Ley Básica de Inteligencia Artificial de Corea, garantizando la preparación para el cumplimiento. Al aprovechar esta habilidad, los agentes pueden mejorar sus capacidades de pruebas de seguridad, incluyendo evaluaciones de riesgos y planificación de mitigación.","fr":"Permet aux agents d''exécuter des audits de sécurité complets, de réviser les contrôles de sécurité de SDLC, et d''enquêter sur les vulnérabilités en utilisant des protocoles tels que CI/CD, tout en validant les contrôles d''authentification, d''autorisation et de protection des données. Il offre des avantages pour les entreprises touchées par des réglementations telles que la Loi de base sur l''IA de la Corée, en garantissant la conformité. En exploitant cette compétence, les agents peuvent améliorer leurs capacités de tests de sécurité, y compris les évaluations de risques et la planification de l''atténuation.","de":"Ermächtigt die Agenten, umfassende Sicherheitsaudits durchzuführen, SDLC-Sicherheitskontrollen zu überprüfen und mithilfe von Protokollen wie CI/CD Schwachstellen zu untersuchen, während Authentifizierungs-, Autorisierungs- und Datenschutzkontrollen validiert werden. Es bietet Vorteile für Unternehmen, die von Vorschriften wie dem koreanischen AI-Grundgesetz betroffen sind, und stellt sicher, dass sie bereit für die Einhaltung sind. Durch die Nutzung dieser Fähigkeit können die Agenten ihre Sicherheitstestfunktionen verbessern, einschließlich Risikobewertungen und Planung zur Risikominderung.","pt":"Habilita os agentes a executar auditorias de segurança abrangentes, revisar controles de segurança do SDLC, e investigar vulnerabilidades usando protocolos como CI/CD, ao mesmo tempo validando controles de autenticação, autorização e proteção de dados. Ele fornece benefícios para empresas afetadas por regulamentos como a Lei Básica de Inteligência Artificial da Coreia, garantindo a preparação para a conformidade. Ao aproveitar essa habilidade, os agentes podem melhorar suas capacidades de teste de segurança, incluindo avaliações de risco e planejamento de mitigação.","ru":"Наделяет агентов возможностью проводить комплексные аудиты безопасности, проверять контроли безопасности SDLC и исследовать уязвимости с помощью протоколов như CI/CD, одновременно проверяя механизмы аутентификации, авторизации и защиты данных. Он обеспечивает выгоды для компаний, на которые влияют такие регуляции, как Закон о базовых началах искусственного интеллекта Кореи, гарантируя готовность к соблюдению требований. Используя этот навык, агенты могут повысить свои возможности по тестированию безопасности, включая оценку рисков и планирование смягчения.","ar":"يمنح الوكيل القدرة على إجراء عمليات فحص أمنية شاملة ومراجعة ضوابط الأمن في SDLC و تحقيق الضعف باستخدام بروتوكولات مثل CI/CD وفي نفس الوقت التحقق من ضوابط التحقق والسماح والحماية البيانات. يوفر فوائد للشركات المتأثرة باللوائح مثل قانون الأساسيات الاصطناعية في كوريا، مما يضمن الاستعداد للامتثال. من خلال استخدام هذه القدرة، يمكن للوكلاء تعزيز قدراتهم لاختبار الأمن، بما في ذلك تقييمات المخاطر وتخطيط التخفيف."},"useCases":{"en":["Automating security audits for compliance","Investigating vulnerabilities in SDLC pipelines","Designing mitigation plans for identified risks","Validating authentication and authorization controls"],"zh":["自动化合规的安全审计","在SDLC管道中调查漏洞","为已识别的风险设计缓解计划","验证身份验证和授权控制"],"ja":["コンプライアンスのためのセキュリティ監査の自動化","SDLCパイプラインでの脆弱性の調査","特定されたリスクのための緩和計画の設計","認証および認可コントロールの検証"],"ko":["규정준수 위한 보안 감사의 자동화","SDLC 파이프라인에서의 취약점 조사","식별된 위험에 대한 완화 계획 설계","인증 및 인가 통제의 검증"],"es":["Automatización de auditorías de seguridad para el cumplimiento","Investigación de vulnerabilidades en pipelines de SDLC","Diseño de planes de mitigación para riesgos identificados","Validación de controles de autenticación y autorización"],"fr":["Automatisation des audits de sécurité pour la conformité","Enquête sur les vulnérabilités dans les pipelines SDLC","Conception de plans d''atténuation pour les risques identifiés","Validation des contrôles d''authentification et d''autorisation"],"de":["Automatisierung von Sicherheitsaudits für die Konformität","Untersuchung von Schwachstellen in SDLC-Pipelines","Entwurf von Minderungsplänen für identifizierte Risiken","Validierung von Authentifizierungs- und Autorisierungskontrollen"],"pt":["Automatizar auditorias de segurança para conformidade","Investigar vulnerabilidades em pipelines SDLC","Desenvolver planos de mitigação para riscos identificados","Validar controles de autenticação e autorização"],"ru":["Автоматизировать аудиты безопасности для соответствия требованиям","Исследовать уязвимости в конвейерах SDLC","Разрабатывать планы смягчения для выявленных рисков","Проверять механизмы аутентификации и авторизации"],"ar":["تحقيق التutomatizar عمليات فحص الأمن للامتثال","تحقيق الضعف في خطوط أنابيب SDLC","تصميم خطط التخفيف للمخاطر المحددة","التحقق من ضوابط التحقق والسماح"]},"limitations":{"en":["Requires authorization and scope approval for security testing","Limited to DevSecOps and application security contexts"],"zh":["需要授权和范围批准用于安全测试","仅限于DevSecOps和应用程序安全上下文"],"ja":["セキュリティテストのための認可およびスコープの承認が必要","DevSecOpsおよびアプリケーションセキュリティのコンテキストに限定"],"ko":["보안 테스트를 위한 승인 및 범위 승인이 필요","DevSecOps 및 애플리케이션 보안 컨텍스트에만 제한"],"es":["Requiere autorización y aprobación de alcance para pruebas de seguridad","Limitado a contextos de DevSecOps y seguridad de aplicaciones"],"fr":["Nécessite une autorisation et une approbation de portée pour les tests de sécurité","Limité aux contextes DevSecOps et de sécurité des applications"],"de":["Erfordert Autorisierung und Genehmigung des Umfangs für Sicherheitstests","Begrenzt auf DevSecOps- und Anwendungssicherheitskontexte"],"pt":["Exige autorização e aprovação de escopo para testes de segurança","Limitado a contextos de DevSecOps e segurança de aplicativos"],"ru":["Требует авторизации и одобрения области применения для тестирования безопасности","Ограничен контекстами DevSecOps и безопасности приложений"],"ar":["يتطلب التفويض والموافقة على النطاق لاختبار الأمن","محدود سياقات DevSecOps وأمن التطبيقات"]},"version":4},"contentHash":"3e8ce87e5756a58bee4a3ab2e3fb69f92ef7f3654334829bf06b6c42ad4a5bc8","qualityScore":50}');
