INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brandonlacoste9-tech/korean-AI-compliance-/security-auditor', 'security-auditor', 'brandonlacoste9-tech', 'korean-AI-compliance-', 'community', 'security-auditor brandonlacoste9-tech korean-AI-compliance- community The security-auditor skill helps DevSecOps teams run security audits, review SDLC security controls, and investigate vulnerabilities. It benefits companies impacted by Korea''s AI Basic Act. 安全审计员是一种专门的AI工具，帮助开发人员进行安全审计和风险评估，确保CI/CD和合规性 セキュリティ監査員は、開発者がセキュリティ監査とリスク評価を実行し、CI/CDとコンプライアンスを確保するのに役立つ専門のAIエージェントです 보안 감사员은 개발자가 보안 감사를 수행하고 위험을 평가하여 CI/CD 및 규정 준수를 보장하는 전문 AI 도구입니다 El security-auditor es un experto en DevSecOps que ayuda a auditar la seguridad de las aplicaciones y cumplir con las normas de seguridad Le security-auditor est un expert en DevSecOps qui aide à auditer la sécurité des applications et à respecter les normes de sécurité Der Security-Auditor ist ein Experte für DevSecOps, der bei der Überprüfung der Sicherheit von Anwendungen und der Einhaltung von Sicherheitsstandards hilft O Security Auditor é uma ferramenta especializada em DevSecOps e segurança de aplicativos, ajudando a identificar vulnerabilidades e melhorar a segurança. ИИ Агент безопасности - это специализированная herramienta для DevSecOps и безопасности приложений, помогающая выявлять уязвимости и улучшать безопасность مراقب الأمان هو أداة متخصصة في DevSecOps وأمان التطبيقات، تساعد في تحديد الثغرات وأمان التحسين how to use security-auditor security-auditor compliance guide Korea''s AI Basic Act penalties security-auditor vs competitors security-auditor setup guide DevSecOps security auditor tools application security best practices CI/CD security controls compliance readiness checklist 安全审计员 DevSecOps 应用程序安全 综合网络安全 CI/CD 合规性 风险评估 漏洞分析 身份验证 授权 数据保护 Runs security audits and risk assessments for compliance readiness Reviews SDLC security controls, CI/CD, and authentication protocols Investigates vulnerabilities and designs mitigation plans Validates authorization, data protection controls, and compliance standards Supports comprehensive cybersecurity practices for DevSecOps teams security-auditor is a specialized skill for DevSecOps, application security, and comprehensive cybersecurity practices, ensuring compliance with regulations like Korea''s AI Basic Act.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('andrueandersoncs/claude-skill-effect-ts/api-doc-lookup', 'community', 'andrueandersoncs', 'claude-skill-effect-ts', 'andrueandersoncs/claude-skill-effect-ts', 'api-doc-lookup', 0, 0, 50, '2026-03-08T01:57:15.655Z', '2026-03-08T02:13:57.470Z', '61f5cefd9ed521c941820618d308c22d67592fc626562766306ab47f00ddd3d7', '{"id":"andrueandersoncs/claude-skill-effect-ts/api-doc-lookup","name":"api-doc-lookup","description":{"en":"The api-doc-lookup skill retrieves API documentation directly from the official Effect-TS documentation site using WebFetch, benefiting developers who need quick access to Effect-TS API docs.","zh":"Effect-TS API 文档查找功能使用 WebFetch 从官方文档站点检索 API 文档，支持 Effect 和 Schema 模块","ja":"Effect-TS API ドキュメント検索機能は、WebFetch を使用して公式ドキュメントサイトから API ドキュメントを取得します。Effect と Schema モジュールをサポートしています","ko":"Effect-TS API 문서 조회 기능은 WebFetch를 사용하여 공식 문서 사이트에서 API 문서를 검색합니다. Effect 및 Schema 모듈을 지원합니다","es":"El agente api-doc-lookup utiliza WebFetch para recuperar documentación de API de Effect-TS","fr":"L''agent api-doc-lookup utilise WebFetch pour récupérer la documentation de l''API Effect-TS","de":"Der api-doc-lookup-Agent verwendet WebFetch, um die Effect-TS-API-Dokumentation abzurufen","pt":"O api-doc-lookup é uma ferramenta que permite buscar documentação de API do Effect-TS de forma rápida e eficiente","ru":"ИИ Агент api-doc-lookup позволяет быстро и эффективно искать документацию API Effect-TS","ar":"أداة api-doc-lookup تمكنك من البحث عن وثائق API Effect-TS بسرعة وفعالية"},"seo":{"title":{"en":"api-doc-lookup: WebFetch API Documentation Lookup Guide |...","zh":"Effect-TS API 文档查找设置指南","ja":"Effect-TS API ドキュメント検索のベストプラクティス","ko":"Effect-TS API 문서 조회 가이드","es":"Guía de configuración de api-doc-lookup para desarrolladores","fr":"Mise en route de l''agent api-doc-lookup pour les développ...","de":"Einrichtungsleitfaden für api-doc-lookup-Entwickler","pt":"Guia de Configuração do api-doc-lookup para Desenvolvedores","ru":"ИИ Агенты: Настройка api-doc-lookup для разработчиков","ar":"إعداد أداة api-doc-lookup للبرمجة"},"description":{"en":"Discover how api-doc-lookup retrieves API docs from Effect-TS using WebFetch. Learn how to setup and use this skill for efficient documentation lookup.","zh":"使用 WebFetch 从 Effect-TS 官方文档站点检索 API 文档，支持 Effect 和 Schema 模块","ja":"WebFetch を使用して Effect-TS 公式ドキュメントサイトから API ドキュメントを取得します。Effect と Schema モジュールをサポートしています","ko":"WebFetch를 사용하여 Effect-TS 공식 문서 사이트에서 API 문서를 검색합니다. Effect 및 Schema 모듈을 지원합니다","es":"Aprende a utilizar el agente api-doc-lookup para recuperar documentación de API de Effect-TS con WebFetch","fr":"Découvrez comment utiliser l''agent api-doc-lookup pour récupérer la documentation de l''API Effect-TS avec WebFetch","de":"Erfahren Sie, wie Sie den api-doc-lookup-Agent verwenden, um Effect-TS-API-Dokumentation mit WebFetch abzurufen","pt":"Aprenda a configurar o api-doc-lookup para buscar documentação de API do Effect-TS de forma eficiente","ru":"Узнайте, как настроить api-doc-lookup для эффективного поиска документации API Effect-TS","ar":"تعرف على إعداد أداة api-doc-lookup للبحث عن وثائق API Effect-TS بفعالية"},"definition":{"en":"api-doc-lookup is a skill that uses WebFetch to retrieve API documentation from the Effect-TS documentation site at https://effect-ts.github.io/effect/","zh":"Effect-TS API 文档查找是使用 WebFetch 从 Effect-TS 官方文档站点检索 API 文档的功能","ja":"Effect-TS API ドキュメント検索は、WebFetch を使用して Effect-TS 公式ドキュメントサイトから API ドキュメントを取得する機能です","ko":"Effect-TS API 문서 조회는 WebFetch를 사용하여 Effect-TS 공식 문서 사이트에서 API 문서를 검색하는 기능입니다","es":"El api-doc-lookup es un agente que busca documentación de API en Effect-TS","fr":"L''api-doc-lookup est un agent qui recherche la documentation de l''API dans Effect-TS","de":"Der api-doc-lookup ist ein Agent, der die API-Dokumentation in Effect-TS suchen","pt":"O que é api-doc-lookup? Uma ferramenta para buscar documentação de API do Effect-TS","ru":"Что такое api-doc-lookup? Инструмент для поиска документации API Effect-TS","ar":"ما هي أداة api-doc-lookup؟ أداة للبحث عن وثائق API Effect-TS"},"features":{"en":["Retrieves API documentation from the official Effect-TS documentation site","Supports WebFetch for efficient documentation lookup","Provides direct access to Effect-TS API documentation for core modules","Follows URL patterns for modules in the main effect package","Includes common modules such as Effect and Schema","Generates URLs for API documentation using the https://effect-ts.github.io/effect/effect/{Module}.ts.html pattern"],"zh":["支持 Effect 和 Schema 模块","使用 WebFetch 从官方文档站点检索 API 文档","支持 URL 模式，例如 https://effect-ts.github.io/effect/effect/{Module}.ts.html","常用模块，如 Effect 和 Schema，有预定义的 URL"],"ja":["Effect と Schema モジュールをサポートしています","WebFetch を使用して公式ドキュメントサイトから API ドキュメントを取得します","URL パターンをサポートしています。例：https://effect-ts.github.io/effect/effect/{Module}.ts.html","一般的なモジュール、たとえば Effect と Schema、には事前に定義された URL があります"],"ko":["Effect 및 Schema 모듈을 지원합니다","WebFetch를 사용하여 공식 문서 사이트에서 API 문서를 검색합니다","URL 패턴을 지원합니다. 예: https://effect-ts.github.io/effect/effect/{Module}.ts.html","일반적인 모듈, 예를 들어 Effect 및 Schema,에는 미리 정의된 URL이 있습니다"],"es":["Recuperación de documentación de API de Effect-TS con WebFetch","Compatibilidad con módulos principales de Effect-TS","Soporte para la búsqueda de documentación en https://effect-ts.github.io/effect/","Patrones de URL personalizables para módulos de Effect-TS","Integración con herramientas de desarrollo como CLI"],"fr":["Récupération de la documentation de l''API Effect-TS avec WebFetch","Compatibilité avec les modules principaux d''Effect-TS","Prise en charge de la recherche de documentation sur https://effect-ts.github.io/effect/","Modèles d''URL personnalisables pour les modules Effect-TS","Intégration avec des outils de développement tels que CLI"],"de":["Abruf der Effect-TS-API-Dokumentation mit WebFetch","Kompatibilität mit den Hauptmodulen von Effect-TS","Unterstützung der Suche nach Dokumentation auf https://effect-ts.github.io/effect/","Anpassbare URL-Muster für Effect-TS-Module","Integration mit Entwicklungstools wie CLI"],"pt":["Suporte ao Effect-TS","Busca de documentação de API via WebFetch","Acesso a módulos principais do Effect-TS","Suporte a módulos comuns como Effect e Schema","URL personalizável para documentação de API"],"ru":["Поддержка Effect-TS","Поиск документации API через WebFetch","Доступ к основным модулям Effect-TS","Поддержка общих модулей, таких как Effect и Schema","Настраиваемый URL для документации API"],"ar":["دعم Effect-TS","بحث وثائق API عبر WebFetch","وصول إلى الوحدات الرئيسية ل Effect-TS","دعم الوحدات الشائعة مثل Effect و Schema","رابط قابل للتعديل لوثائق API"]},"keywords":{"en":["how to use api-doc-lookup","api-doc-lookup setup guide","Effect-TS API documentation","WebFetch API documentation lookup","api-doc-lookup alternative","api-doc-lookup vs other documentation lookup tools","api-doc-lookup install","what is api-doc-lookup","api-doc-lookup for developers","Efficient API documentation lookup"],"zh":["Effect-TS API 文档查找","WebFetch","API 文档","Effect 模块","Schema 模块","AIエージェント","API 文档检索"],"ja":["Effect-TS API ドキュメント検索","WebFetch","API ドキュメント","Effect モジュール","Schema モジュール","AIエージェント","API ドキュメント検索"],"ko":["Effect-TS API 문서 조회","WebFetch","API 문서","Effect 모듈","Schema 모듈","AI 에이전트","API 문서 조회"],"es":["api-doc-lookup","agentes de AI para desarrolladores","Effect-TS","WebFetch","documentación de API","módulos de Effect-TS","patrones de URL","integración con CLI"],"fr":["api-doc-lookup","agents d''IA pour les développeurs","Effect-TS","WebFetch","documentation de l''API","modules d''Effect-TS","modèles d''URL","intégration avec CLI"],"de":["api-doc-lookup","KI-Agents für Entwickler","Effect-TS","WebFetch","API-Dokumentation","Effect-TS-Module","URL-Muster","Integration mit CLI"],"pt":["api-doc-lookup","Effect-TS","documentação de API","WebFetch","desenvolvimento de software","ferramentas de desenvolvimento","busca de documentação","módulos do Effect-TS"],"ru":["api-doc-lookup","Effect-TS","документация API","WebFetch","разработка программного обеспечения","инструменты разработки","поиск документации","модули Effect-TS"],"ar":["api-doc-lookup","Effect-TS","وثائق API","WebFetch","تطوير البرمجيات","أدوات التطوير","بحث وثائق","وحدات Effect-TS"]}},"owner":"andrueandersoncs","repo":"claude-skill-effect-ts","repoPath":"andrueandersoncs/claude-skill-effect-ts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.655Z","topics":[],"category":"community","skillMd":{"name":"api-doc-lookup","description":"This skill should be used when the user asks to look up Effect API, check the Effect docs, find Effect function signature, what does Effect.X do, how to use Effect.X, Effect API reference, fetch Effect documentation, or needs to look up specific function signatures, parameters, or usage examples from the official Effect-TS API documentation.","version":"1.0.0","bodyPreview":"# Effect-TS API Documentation Lookup\n\n## Overview\n\nUse WebFetch to retrieve API documentation directly from the official Effect-TS documentation site at `https://effect-ts.github.io/effect/`.\n\n## URL Patterns\n\n### Core Effect Modules\n\nFor modules in the main `effect` package:\n\n```\nhttps://effect-ts.github.io/effect/effect/{Module}.ts.html\n```\n\n**Common modules:**\n| Module | URL |\n|--------|-----|\n| Effect | `https://effect-ts.github.io/effect/effect/Effect.ts.html` |\n| Schema | `https://effect-t","body":"# Effect-TS API Documentation Lookup\n\n## Overview\n\nUse WebFetch to retrieve API documentation directly from the official Effect-TS documentation site at `https://effect-ts.github.io/effect/`.\n\n## URL Patterns\n\n### Core Effect Modules\n\nFor modules in the main `effect` package:\n\n```\nhttps://effect-ts.github.io/effect/effect/{Module}.ts.html\n```\n\n**Common modules:**\n| Module | URL |\n|--------|-----|\n| Effect | `https://effect-ts.github.io/effect/effect/Effect.ts.html` |\n| Schema | `https://effect-ts.github.io/effect/effect/Schema.ts.html` |\n| Stream | `https://effect-ts.github.io/effect/effect/Stream.ts.html` |\n| Layer | `https://effect-ts.github.io/effect/effect/Layer.ts.html` |\n| Context | `https://effect-ts.github.io/effect/effect/Context.ts.html` |\n| Schedule | `https://effect-ts.github.io/effect/effect/Schedule.ts.html` |\n| Fiber | `https://effect-ts.github.io/effect/effect/Fiber.ts.html` |\n| Queue | `https://effect-ts.github.io/effect/effect/Queue.ts.html` |\n| Ref | `https://effect-ts.github.io/effect/effect/Ref.ts.html` |\n| Scope | `https://effect-ts.github.io/effect/effect/Scope.ts.html` |\n| Option | `https://effect-ts.github.io/effect/effect/Option.ts.html` |\n| Either | `https://effect-ts.github.io/effect/effect/Either.ts.html` |\n| Chunk | `https://effect-ts.github.io/effect/effect/Chunk.ts.html` |\n| HashMap | `https://effect-ts.github.io/effect/effect/HashMap.ts.html` |\n| HashSet | `https://effect-ts.github.io/effect/effect/HashSet.ts.html` |\n| Duration | `https://effect-ts.github.io/effect/effect/Duration.ts.html` |\n| Config | `https://effect-ts.github.io/effect/effect/Config.ts.html` |\n| ConfigProvider | `https://effect-ts.github.io/effect/effect/ConfigProvider.ts.html` |\n| Match | `https://effect-ts.github.io/effect/effect/Match.ts.html` |\n| Data | `https://effect-ts.github.io/effect/effect/Data.ts.html` |\n| Cause | `https://effect-ts.github.io/effect/effect/Cause.ts.html` |\n| Exit | `https://effect-ts.github.io/effect/effect/Exit.ts.html` |\n| Random | `https://effect-ts.github.io/effect/effect/Random.ts.html` |\n| Clock | `https://effect-ts.github.io/effect/effect/Clock.ts.html` |\n| Tracer | `https://effect-ts.github.io/effect/effect/Tracer.ts.html` |\n| Metric | `https://effect-ts.github.io/effect/effect/Metric.ts.html` |\n| Logger | `https://effect-ts.github.io/effect/effect/Logger.ts.html` |\n| Sink | `https://effect-ts.github.io/effect/effect/Sink.ts.html` |\n| PubSub | `https://effect-ts.github.io/effect/effect/PubSub.ts.html` |\n| Deferred | `https://effect-ts.github.io/effect/effect/Deferred.ts.html` |\n| Semaphore | `https://effect-ts.github.io/effect/effect/Semaphore.ts.html` |\n| Request | `https://effect-ts.github.io/effect/effect/Request.ts.html` |\n| RequestResolver | `https://effect-ts.github.io/effect/effect/RequestResolver.ts.html` |\n| Cache | `https://effect-ts.github.io/effect/effect/Cache.ts.html` |\n| TestClock | `https://effect-ts.github.io/effect/effect/TestClock.ts.html` |\n| Runtime | `https://effect-ts.github.io/effect/effect/Runtime.ts.html` |\n| ManagedRuntime | `https://effect-ts.github.io/effect/effect/ManagedRuntime.ts.html` |\n\n### Scoped Packages\n\nFor `@effect/*` packages:\n\n```\nhttps://effect-ts.github.io/effect/{package-name}/{Module}.ts.html\n```\n\n**Examples:**\n| Package | Module | URL |\n|---------|--------|-----|\n| @effect/platform | HttpClient | `https://effect-ts.github.io/effect/platform/HttpClient.ts.html` |\n| @effect/platform | FileSystem | `https://effect-ts.github.io/effect/platform/FileSystem.ts.html` |\n| @effect/platform | KeyValueStore | `https://effect-ts.github.io/effect/platform/KeyValueStore.ts.html` |\n| @effect/cli | Command | `https://effect-ts.github.io/effect/cli/Command.ts.html` |\n| @effect/sql | SqlClient | `https://effect-ts.github.io/effect/sql/SqlClient.ts.html` |\n\n## How to Look Up Documentation\n\n### Step 1: Identify the Module\n\nDetermine which module contains the API:\n\n- `Effect.map` → Effect module\n- `Schema.Struct` → Schema module\n- `Stream.fromIterable` → Stream module\n- `Layer.provide` → Layer module\n\n### Step 2: Construct the URL\n\nUse the URL pattern for the identified module:\n\n```typescript\n// For Effect.retry\nconst url = \"https://effect-ts.github.io/effect/effect/Effect.ts.html\";\n\n// For Schema.transform\nconst url = \"https://effect-ts.github.io/effect/effect/Schema.ts.html\";\n```\n\n### Step 3: Fetch with Targeted Prompt\n\nUse WebFetch with a specific prompt to extract the relevant information:\n\n```\nWebFetch(\n  url: \"https://effect-ts.github.io/effect/effect/Effect.ts.html\",\n  prompt: \"Find the documentation for Effect.retry. Include the function signature, description, parameters, and any usage examples.\"\n)\n```\n\n## Example Queries\n\n### Looking up a specific function\n\n**User asks:** \"What are the parameters for Effect.retry?\"\n\n**Action:**\n\n```\nWebFetch(\n  url: \"https://effect-ts.github.io/effect/effect/Effect.ts.html\",\n  prompt: \"Find documentation for the retry function. Include its complete type signature, all parameters and options, and usage examples.\"\n)\n```\n\n### Looking up a type/interface\n\n**User asks:** \"What fields does Schedule have?\"\n\n**Action:**\n\n```\nWebFetch(\n  url: \"https://effect-ts.github.io/effect/effect/Schedule.ts.html\",\n  prompt: \"Describe the Schedule type and its main combinators. List common schedule functions like exponential, spaced, recurs, etc.\"\n)\n```\n\n### Looking up a module overview\n\n**User asks:** \"What functions are available in the Stream module?\"\n\n**Action:**\n\n```\nWebFetch(\n  url: \"https://effect-ts.github.io/effect/effect/Stream.ts.html\",\n  prompt: \"List the main categories of functions in this module with brief descriptions of each category.\"\n)\n```\n\n### Looking up related functions\n\n**User asks:** \"What are all the catch\\* functions in Effect?\"\n\n**Action:**\n\n```\nWebFetch(\n  url: \"https://effect-ts.github.io/effect/effect/Effect.ts.html\",\n  prompt: \"Find all error handling functions that start with ''catch''. Include catchAll, catchTag, catchTags, catchSome, etc. with their signatures and purposes.\"\n)\n```\n\n## Prompt Patterns\n\nUse these prompt patterns for effective documentation extraction:\n\n### For function signatures:\n\n```\n\"Find the complete type signature for {functionName}. Include all overloads if they exist.\"\n```\n\n### For usage examples:\n\n```\n\"Find documentation and code examples for {functionName}. Focus on practical usage patterns.\"\n```\n\n### For understanding parameters:\n\n```\n\"Explain the parameters and options for {functionName}. What does each parameter do?\"\n```\n\n### For finding related functions:\n\n```\n\"List all functions related to {topic} in this module. Include brief descriptions.\"\n```\n\n### For module overview:\n\n```\n\"Provide an overview of this module. What are the main categories of functions and types?\"\n```\n\n## Tips\n\n1. **Be specific in prompts** - Ask for exactly what you need (signature, examples, parameters)\n2. **Use the right module** - Effect functions are in Effect.ts, Schema functions in Schema.ts, etc.\n3. **Check related functions** - The docs include \"See also\" links to related functions\n4. **Look for examples** - Most functions include practical code examples with expected output\n5. **Note version info** - Functions show \"Since v2.0.0\" or similar version information\n\n## Documentation Site Index\n\nThe main documentation index is at:\n\n```\nhttps://effect-ts.github.io/effect/\n```\n\nUse this to discover available packages and modules if unsure which module contains a specific API.\n\n## Best Practices\n\n1. **Start with the right module** - Identify which module contains the API before fetching\n2. **Use targeted prompts** - Ask for specific information (signature, examples, parameters)\n3. **Check for overloads** - Many Effect functions have multiple signatures\n4. **Look for \"Since\" annotations** - Verify the API is available in your Effect version\n\n## Additional Resources\n\nFor comprehensive Effect documentation beyond API signatures, consult `${CLAUDE_PLUGIN_ROOT}/references/llms-full.txt` which contains tutorials, guides, and in-depth explanations.\n"},"lastSynced":"2026-03-08T02:13:57.470Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring instant access to Effect-TS API documentation for streamlined coding and debugging.","zh":"适用于需要即时访问Effect-TS API文档以实现流畅编码和调试的开发者代理。","ja":"Effect-TS APIドキュメントへの即時アクセスが必要な開発者エージェントに適しています。","ko":"Effect-TS API 문서에 즉시 접근하여 원활한 코딩과 디버깅이 필요한 개발자 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollador que requieren acceso instantáneo a la documentación de la API de Effect-TS para codificación y depuración optimizadas.","fr":"Idéal pour les agents de développement nécessitant un accès instantané à la documentation de l''API Effect-TS pour une codification et une débogage optimisées.","de":"Ideal für Entwickleragenten, die sofortigen Zugriff auf die Effect-TS-API-Dokumentation für optimiertes Codieren und Debuggen benötigen.","pt":"Ideal para Agentes de Desenvolvedor que exigem acesso instantâneo à documentação da API Effect-TS para codificação e depuração otimizados.","ru":"Идеально подходит для агентов-разработчиков, требующих мгновенного доступа к документации API Effect-TS для оптимизированного кодирования и отладки.","ar":"مثالي لعميل المطور الذي يتطلب الوصول الفوري إلى توثيق واجهة برمجة التطبيقات Effect-TS لجعل عملية البرمجة وتصحيح الأخطاء أكثر كفاءة."},"recommendation":{"en":"Empowers agents to directly fetch official Effect-TS documentation using WebFetch, providing quick access to API details for modules like Effect and Schema, and facilitating efficient development with accurate and up-to-date documentation in .ts.html format.","zh":"赋予代理直接使用WebFetch获取官方Effect-TS文档的能力，提供快速访问API详情的途径，例如Effect和Schema模块，并有助于使用准确和最新的文档以.ts.html格式实现高效开发。","ja":"WebFetchを使用して公式のEffect-TSドキュメントを直接取得するエージェントの能力を提供し、EffectやSchemaなどのモジュールのAPIの詳細に迅速にアクセスし、.ts.html形式の正確で最新のドキュメントを使用した効率的な開発を促進します。","ko":"WebFetch를 사용하여 공식 Effect-TS 문서를 직접 가져올 수 있는 에이전트의 능력을 제공하여 Effect 및 Schema와 같은 모듈의 API 세부 정보에 빠르게 액세스하고 .ts.html 형식의 정확하고 최신 문서를 사용하여 효율적인 개발을 촉진합니다.","es":"Habilita a los agentes a recuperar directamente la documentación oficial de Effect-TS utilizando WebFetch, proporcionando un acceso rápido a los detalles de la API para módulos como Effect y Schema, y facilitando un desarrollo eficiente con documentación precisa y actualizada en formato .ts.html.","fr":"Permet aux agents de récupérer directement la documentation officielle d''Effect-TS en utilisant WebFetch, offrant un accès rapide aux détails de l''API pour des modules tels que Effect et Schema, et facilitant un développement efficace avec une documentation précise et à jour au format .ts.html.","de":"Ermächtigt die Agenten, die offizielle Effect-TS-Dokumentation direkt mit WebFetch abzurufen, bietet somit einen schnellen Zugriff auf API-Details für Module wie Effect und Schema und ermöglicht eine effiziente Entwicklung mit genauer und aktueller Dokumentation im .ts.html-Format.","pt":"Habilita os agentes a buscar diretamente a documentação oficial Effect-TS usando WebFetch, fornecendo acesso rápido aos detalhes da API para módulos como Effect e Schema, e facilitando o desenvolvimento eficiente com documentação precisa e atualizada no formato .ts.html.","ru":"Позволяет агентам直接 получать официальную документацию Effect-TS с помощью WebFetch, обеспечивая быстрый доступ к деталям API для модулей như Effect и Schema, и облегчая эффективное развитие с точной и актуальной документацией в формате .ts.html.","ar":"يمنح الوكيل القدرة على استرجاع توثيق Effect-TS الرسمي مباشرة باستخدام WebFetch، ويوفر الوصول السريع إلى تفاصيل واجهة برمجة التطبيقات للمكونات مثل Effect و Schema، ويسهم في جعل التطوير أكثر كفاءة مع توثيق دقيق ومحدث بالشكل .ts.html."},"useCases":{"en":["Retrieving Effect-TS API documentation for specific modules","Automating lookup of core Effect modules like Effect and Schema","Debugging Effect-TS code with direct access to official documentation"],"zh":["检索特定模块的Effect-TS API文档","自动查找Effect核心模块，如Effect和Schema","使用官方文档直接访问来调试Effect-TS代码"],"ja":["特定モジュールのEffect-TS APIドキュメントを取得する","EffectやSchemaなどのEffectコアモジュールの自動検索","公式ドキュメントへの直接アクセスを使用してEffect-TSコードをデバッグする"],"ko":["특정 모듈의 Effect-TS API 문서를 검색하는 것","Effect 및 Schema와 같은 Effect 핵심 모듈의 자동 조회","공식 문서에 직접 액세스하여 Effect-TS 코드를 디버깅하는 것"],"es":["Recuperación de la documentación de la API de Effect-TS para módulos específicos","Automatización de la búsqueda de módulos básicos de Effect como Effect y Schema","Depuración de código Effect-TS con acceso directo a la documentación oficial"],"fr":["Récupération de la documentation de l''API Effect-TS pour des modules spécifiques","Automatisation de la recherche de modules de base d''Effect tels que Effect et Schema","Débogage du code Effect-TS avec un accès direct à la documentation officielle"],"de":["Abrufen der Effect-TS-API-Dokumentation für bestimmte Module","Automatisierung der Suche nach Kernmodulen von Effect wie Effect und Schema","Fehlerbehebung von Effect-TS-Code mit direktem Zugriff auf die offizielle Dokumentation"],"pt":["Recuperar a documentação da API Effect-TS para módulos específicos","Automatizar a busca de módulos core Effect como Effect e Schema","Depurar código Effect-TS com acesso direto à documentação oficial"],"ru":["Получение документации API Effect-TS для конкретных модулей","Автоматизация поиска основных модулей Effect, таких как Effect и Schema","Отладка кода Effect-TS с прямым доступом к официальной документации"],"ar":["استرجاع توثيق واجهة برمجة التطبيقات Effect-TS لمكونات محددة","تأتمتة عملية البحث عن مكونات Effect الأساسية مثل Effect و Schema","تصحيح أخطاء في كود Effect-TS بالوصول المباشر إلى التوثيق الرسمي"]},"limitations":{"en":["Requires WebFetch capability","Limited to Effect-TS official documentation site","Specific URL patterns needed for different modules"],"zh":["需要WebFetch能力","仅限Effect-TS官方文档网站","需要为不同的模块指定特定的URL模式"],"ja":["WebFetchの機能が必要","Effect-TS公式ドキュメントサイトのみ","さまざまなモジュールに特定のURLパターンが必要"],"ko":["WebFetch 기능이 필요합니다.","Effect-TS 공식 문서 사이트만 해당합니다.","다른 모듈에 대한 특정 URL 패턴이 필요합니다."],"es":["Requiere la capacidad de WebFetch","Limitado al sitio de documentación oficial de Effect-TS","Se necesitan patrones de URL específicos para diferentes módulos"],"fr":["Nécessite la capacité de WebFetch","Limité au site de documentation officiel d''Effect-TS","Des modèles d''URL spécifiques sont nécessaires pour différents modules"],"de":["Benötigt die WebFetch-Funktion","Begrenzt auf die offizielle Effect-TS-Dokumentationswebsite","Spezifische URL-Muster werden für unterschiedliche Module benötigt"],"pt":["Exige a capacidade WebFetch","Limitado ao site de documentação oficial Effect-TS","Padrões de URL específicos necessários para diferentes módulos"],"ru":["Требует возможности WebFetch","Ограничен только официальным сайтом документации Effect-TS","Требуются специфические шаблоны URL для разных модулей"],"ar":["يتطلب القدرة على WebFetch","محدود لموقع توثيق Effect-TS الرسمي","أنماط URL محددة مطلوبة للمكونات المختلفة"]},"version":4},"contentHash":"61f5cefd9ed521c941820618d308c22d67592fc626562766306ab47f00ddd3d7","qualityScore":50}');
