INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('andrueandersoncs/claude-skill-effect-ts/api-doc-lookup', 'api-doc-lookup', 'andrueandersoncs', 'claude-skill-effect-ts', 'community', 'api-doc-lookup andrueandersoncs claude-skill-effect-ts community The api-doc-lookup skill retrieves API documentation directly from the official Effect-TS documentation site using WebFetch, benefiting developers who need quick access to Effect-TS API docs. Effect-TS API 文档查找功能使用 WebFetch 从官方文档站点检索 API 文档，支持 Effect 和 Schema 模块 Effect-TS API ドキュメント検索機能は、WebFetch を使用して公式ドキュメントサイトから API ドキュメントを取得します。Effect と Schema モジュールをサポートしています Effect-TS API 문서 조회 기능은 WebFetch를 사용하여 공식 문서 사이트에서 API 문서를 검색합니다. Effect 및 Schema 모듈을 지원합니다 El agente api-doc-lookup utiliza WebFetch para recuperar documentación de API de Effect-TS L''agent api-doc-lookup utilise WebFetch pour récupérer la documentation de l''API Effect-TS Der api-doc-lookup-Agent verwendet WebFetch, um die Effect-TS-API-Dokumentation abzurufen O api-doc-lookup é uma ferramenta que permite buscar documentação de API do Effect-TS de forma rápida e eficiente ИИ Агент api-doc-lookup позволяет быстро и эффективно искать документацию API Effect-TS أداة api-doc-lookup تمكنك من البحث عن وثائق API Effect-TS بسرعة وفعالية how to use api-doc-lookup api-doc-lookup setup guide Effect-TS API documentation WebFetch API documentation lookup api-doc-lookup alternative api-doc-lookup vs other documentation lookup tools api-doc-lookup install what is api-doc-lookup api-doc-lookup for developers Efficient API documentation lookup Effect-TS API 文档查找 WebFetch API 文档 Effect 模块 Schema 模块 AIエージェント API 文档检索 Retrieves API documentation from the official Effect-TS documentation site Supports WebFetch for efficient documentation lookup Provides direct access to Effect-TS API documentation for core modules Follows URL patterns for modules in the main effect package Includes common modules such as Effect and Schema Generates URLs for API documentation using the https://effect-ts.github.io/effect/effect/{Module}.ts.html pattern api-doc-lookup is a skill that uses WebFetch to retrieve API documentation from the Effect-TS documentation site at https://effect-ts.github.io/effect/');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SimHacker/moollm/bartender', 'community', 'SimHacker', 'moollm', 'SimHacker/moollm', 'bartender', 0, 0, 50, '2026-03-08T01:57:15.657Z', '2026-03-08T02:13:58.550Z', 'd4d85310d9cf22eab091948bfa665d8c8a72779bcace4eeb48de9ed344362667', '{"id":"SimHacker/moollm/bartender","name":"bartender","description":{"en":"The bartender skill provides generic bartending capabilities for AI agents, including methods for pouring drinks and managing tabs. This role-based skill is ideal for developers looking to create characters with bartending abilities.","zh":"AI调酒师技能提供基本的调酒服务功能，包括倒饮料、管理订单和处理醉酒客户。","ja":"バーテンダーAIエージェントは、基本的なバーテンダー機能を提供します。飲み物の注ぎ方、注文の管理、酔った客の対応など","ko":"AI 바텐더 에이전트는 기본적인 바텐더 기능을 제공합니다.飲料를倒는 방법, 주문 관리,醉한 고객 처리 등","es":"El bartender es una habilidad de rol que proporciona métodos y comportamientos para la gestión de tabernas, incluyendo la preparación de bebidas y la gestión de cuentas","fr":"Le bartender est une compétence de rôle qui fournit des méthodes et des comportements pour la gestion de bars, notamment la préparation de boissons et la gestion de comptes","de":"Der bartender ist eine Rolle, die Methoden und Verhaltensweisen für die Getränkeverwaltung bereitstellt, einschließlich der Zubereitung von Getränken und der Verwaltung von Konten","pt":"O skill de bartender fornece métodos e comportamentos para gerenciar drinks e tabs. Implemente essas capacidades em seu projeto para melhorar a experiência do usuário.","ru":"Навык бармена предоставляет методы и поведения для управления напитками и счетами. Реализуйте эти возможности в вашем проекте, чтобы улучшить опыт пользователя с помощью ИИ Агентов.","ar":"تمتلك مهارة بارمان أساليب وسلوكيات لتنظيم المشروبات والفواتير. قم بتمكين هذه القدرات في مشروعك لتحسين تجربة المستخدم باستخدام أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"Bartender Skill: Generic Bartending Capabilities for AI A...","zh":"AIエージェント调酒师技能设置指南","ja":"バーテンダーAIエージェントのベストプラクティス","ko":"바텐더 AI 에이전트 기능 설정 가이드","es":"Guía de configuración de bartender: capacidades de gestió...","fr":"Guide de mise en place de bartender: fonctionnalités de g...","de":"Bartender Einrichtungsleitfaden: Funktionen für die Geträ...","pt":"Guia de Configuração do Bartender: Gerenciamento de Drink...","ru":"Настройка ИИ Агента Бармен: Руководство по Созданию","ar":"دليل تثبيت بارمان: إدارة المشروبات والفواتير"},"description":{"en":"Discover how to manage tabs, handle drunks, and pour drinks with the bartender skill - learn more and get started today!","zh":"了解AI调酒师技能的功能和技术细节，包括如何倒饮料、管理订单和处理醉酒客户","ja":"バーテンダーAIエージェントの機能と技術的詳細について学びます。飲み物の注ぎ方、注文の管理、酔った客の対応など","ko":"AI 바텐더 에이전트의 기능과 기술적 세부 정보를了解하세요.飲料를倒는 방법, 주문 관리,醉한 고객 처리 등","es":"Aprende a utilizar las capacidades de bartender para gestionar tu taberna de manera eficiente con nuestra guía de configuración","fr":"Découvrez comment utiliser les fonctionnalités de bartender pour gérer votre bar de manière efficace avec notre guide de mise en place","de":"Erfahren Sie, wie Sie die Funktionen von bartender nutzen können, um Ihre Getränkeverwaltung effizient zu gestalten mit unserem Einrichtungsleitfaden","pt":"Aprenda a configurar o skill de bartender para gerenciar drinks, tabs e lidar com clientes difíceis. Descubra como implementar essas capacidades em seu projeto.","ru":"Узнайте, как настроить навык бармена для управления напитками, счетами и обслуживания клиентов. Откройте для себя, как реализовать эти возможности в вашем пр...","ar":"تعلم كيفية تثبيت مهارة بارمان لإدارة المشروبات والفواتير والتعامل مع العملاء الصعبين. اكتشف كيفية تنفيذ هذه القدرات في مشروعك باستخدام أدوات الذكاء الاصطناعي."},"definition":{"en":"Bartender is a role-based skill that provides methods and behaviors for generic bartending capabilities, including drink pouring and tab management.","zh":"AI调酒师技能是一种ROLE技能，提供基本的调酒服务功能","ja":"バーテンダーAIエージェントは、ROLEスキルであり、基本的なバーテンダー機能を提供する","ko":"AI 바텐더 에이전트는 ROLE 스킬로서 기본적인 바텐더 기능을 제공합니다","es":"Un bartender es una habilidad de rol que se encarga de la gestión de tabernas, incluyendo la preparación de bebidas y la gestión de cuentas","fr":"Un bartender est une compétence de rôle qui se charge de la gestion de bars, notamment la préparation de boissons et la gestion de comptes","de":"Ein bartender ist eine Rolle, die sich mit der Getränkeverwaltung befasst, einschließlich der Zubereitung von Getränken und der Verwaltung von Konten","pt":"O skill de bartender é uma capacidade genérica que fornece métodos para gerenciar drinks e tabs.","ru":"Навык бармена - это общая способность, которая предоставляет методы для управления напитками и счетами.","ar":"مهارة بارمان هي قدرة عامة توفر أساليب لتنظيم المشروبات والفواتير."},"features":{"en":["Provides methods for pouring drinks","Enables management of tabs","Handles drunk behavior","Includes knowledge of existing drinks","Supports role-based character development"],"zh":["倒饮料功能","订单管理功能","醉酒客户处理功能","饮料菜单管理"],"ja":["飲み物の注ぎ方機能","注文の管理機能","酔った客の対応機能","飲み物メニュー管理"],"ko":["飲料를倒는 기능","주문 관리 기능","醉한 고객 처리 기능","飲料 메뉴 관리"],"es":["Preparación de bebidas","Gestión de cuentas","Manejo de borrachos","Conocimiento de bebidas existentes","Gestión de pedidos","Integración con herramientas de gestión de tabernas"],"fr":["Préparation de boissons","Gestion de comptes","Gestion des ivrognes","Connaissance des boissons existantes","Gestion de commandes","Intégration avec des outils de gestion de bars"],"de":["Zubereitung von Getränken","Kontenverwaltung","Umgang mit Betrunkenen","Kenntnis existierender Getränke","Bestellverwaltung","Integration mit Getränkeverwaltungstools"],"pt":["Gerenciamento de drinks","Gerenciamento de tabs","Lidar com clientes difíceis","Conhecimento de drinks existentes","Integração com sistemas de pagamento"],"ru":["Управление напитками","Управление счетами","Обслуживание клиентов","Знание существующих напитков","Интеграция с системами оплаты"],"ar":["إدارة المشروبات","إدارة الفواتير","التعامل مع العملاء الصعبين","معرفة المشروبات المتاحة","التكامل مع أنظمة الدفع"]},"keywords":{"en":["how to use bartender skill","what is bartender skill","bartender skill alternative","bartender skill vs mixology","bartender skill install","bartender skill setup guide","generic bartending capabilities","AI agent bartending"],"zh":["AI调酒师技能","调酒服务功能","ROLE技能","AIエージェント","バーテンダー機能"],"ja":["バーテンダーAIエージェント","バーテンダー機能","ROLEスキル","AIエージェント","飲み物の注ぎ方"],"ko":["AI 바텐더 에이전트","바텐더 기능","ROLE 스킬","AI 에이전트","飲料를倒는 방법"],"es":["bartender AI","herramientas de gestión de tabernas","preparación de bebidas","gestión de cuentas","manejo de borrachos","conocimiento de bebidas","integración con herramientas de gestión de tabernas","desarrollo de aplicaciones de bartender","soluciones de gestión de tabernas"],"fr":["bartender IA","outils de gestion de bars","préparation de boissons","gestion de comptes","gestion des ivrognes","connaissance des boissons","intégration avec des outils de gestion de bars","développement d''applications de bartender","solutions de gestion de bars"],"de":["bartender KI","Getränkeverwaltungstools","Zubereitung von Getränken","Kontenverwaltung","Umgang mit Betrunkenen","Kenntnis existierender Getränke","Integration mit Getränkeverwaltungstools","Entwicklung von Bartender-Anwendungen","Lösungen für die Getränkeverwaltung"],"pt":["bartender skill","gerenciamento de drinks","gerenciamento de tabs","lidar com clientes difíceis","desenvolvimento de aplicativos","integração com sistemas de pagamento"],"ru":["навык бармена","управление напитками","управление счетами","обслуживание клиентов","разработка приложений","интеграция с системами оплаты","ИИ Агенты"],"ar":["مهارة بارمان","إدارة المشروبات","إدارة الفواتير","التعامل مع العملاء الصعبين","تطوير التطبيقات","التكامل مع أنظمة الدفع","أدوات الذكاء الاصطناعي"]}},"owner":"SimHacker","repo":"moollm","repoPath":"SimHacker/moollm","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.657Z","topics":[],"category":"community","skillMd":{"name":"bartender","description":"Generic bartending capabilities — pour drinks, manage tabs, know regulars","tags":["moollm","role","service","social","hospitality"],"bodyPreview":"# Bartender Skill\n\n> *\"The bartender knows everyone''s secrets. The bartender tells no one.\"*\n\nGeneric bartending capabilities that any character can have. This is a ROLE skill — it provides methods and behaviors, not personality.\n\n## The Distinction\n\n| This Skill Provides | This Skill Does NOT Provide |\n|--------------------|-----------------------------|\n| How to pour drinks | WHO is pouring |\n| How to manage tabs | Personality |\n| How to handle drunks | Appearance |\n| What drinks exist | Voice","body":"# Bartender Skill\n\n> *\"The bartender knows everyone''s secrets. The bartender tells no one.\"*\n\nGeneric bartending capabilities that any character can have. This is a ROLE skill — it provides methods and behaviors, not personality.\n\n## The Distinction\n\n| This Skill Provides | This Skill Does NOT Provide |\n|--------------------|-----------------------------|\n| How to pour drinks | WHO is pouring |\n| How to manage tabs | Personality |\n| How to handle drunks | Appearance |\n| What drinks exist | Voice/Catchphrases |\n| Service protocols | Backstory |\n\n**Personality comes from PERSONA. Capability comes from SKILL.**\n\n## Usage\n\nA character with this skill can work as a bartender:\n\n```yaml\n# In character file:\ncharacter:\n  id: marieke\n  skills:\n    - bartender      # She CAN tend bar\n    - budtender      # She ALSO knows cannabis\n  persona: marieke   # She IS Marieke (personality)\n  \n# Or a themed bartender:\ncharacter:\n  id: the-bartender\n  skills:\n    - bartender\n  persona: \"${theme.bartender_persona}\"  # Changes with theme!\n```\n\n## Core Methods\n\n### Service\n\n| Method | Description |\n|--------|-------------|\n| `POUR` | Make and serve a drink |\n| `TAKE-ORDER` | Listen to what customer wants |\n| `SERVE` | Deliver drink to customer |\n| `RECOMMEND` | Suggest drinks based on mood/context |\n| `REFUSE-SERVICE` | Cut someone off |\n| `LAST-CALL` | Announce closing |\n\n### Economics\n\n| Method | Description |\n|--------|-------------|\n| `OPEN-TAB` | Start a tab for customer |\n| `ADD-TO-TAB` | Add item to existing tab |\n| `CLOSE-TAB` | Calculate and collect payment |\n| `COMP` | Give something for free |\n| `CHECK-TAB` | Tell customer their balance |\n\n### Social\n\n| Method | Description |\n|--------|-------------|\n| `LISTEN` | Hear customer''s troubles |\n| `GOSSIP` | Share rumors (carefully) |\n| `INTRODUCE` | Connect two customers |\n| `MEDIATE` | Settle disputes |\n| `EJECT` | Remove troublemakers |\n\n### Knowledge\n\n| Method | Description |\n|--------|-------------|\n| `KNOW-REGULAR` | Recognize repeat customers |\n| `REMEMBER-ORDER` | Know what they usually have |\n| `KNOW-SECRETS` | Have dirt on everyone (use wisely) |\n| `KNOW-MENU` | Explain any drink |\n\n## State\n\n```yaml\nbartender_state:\n  station: \"pub/bar/\"  # Where they work\n  current_tabs: {}     # customer_id → amount\n  regulars: []         # Known repeat customers\n  banned: []           # Not welcome\n  secrets: {}          # What they know (never revealed)\n```\n\n## Advertisements\n\n```yaml\nadvertisements:\n  ORDER-DRINK:\n    score: 90\n    condition: \"Customer at bar, thirsty\"\n    \n  NEED-TO-TALK:\n    score: 70\n    condition: \"Customer seems troubled\"\n    \n  INFORMATION:\n    score: 60\n    condition: \"Customer asking questions\"\n```\n\n## Inheritance\n\nOther skills can inherit from bartender:\n\n```yaml\n# skills/budtender/SKILL.md\ninherits: skills/bartender/SKILL.md\n\nadditional_methods:\n  - RECOMMEND-STRAIN\n  - EXPLAIN-TERPENES\n  - CHECK-ID\n  - ROLL-JOINT\n```\n\n## The Bartender''s Code\n\n1. **Listen more than talk**\n2. **Remember faces, forget conversations**\n3. **Know when to cut off**\n4. **Protect regulars**\n5. **Stay neutral (unless absolutely necessary)**\n6. **The bar is sanctuary**\n\n## Integration\n\nWhen a character has this skill and is at their station:\n\n```yaml\n# They can respond to:\ncustomer: \"What''s good tonight?\"\n# With bartender.RECOMMEND based on:\n#   - Customer''s history\n#   - Current mood\n#   - What''s fresh\n#   - Personal opinion (from persona, not skill!)\n```\n\nThe SKILL provides the capability.\nThe PERSONA provides the flavor.\nThe CHARACTER provides the presence.\n"},"lastSynced":"2026-03-08T02:13:58.550Z","agentAnalysis":{"suitability":{"en":"Perfect for Conversational Agents needing advanced role-playing capabilities as a bartender","zh":"非常适合需要高级角色扮演能力的对话式代理，特别是作为调酒师","ja":"会話エージェントがバーテンダーとして高度な役割演技機能を必要とする場合に最適","ko":"대화형 에이전트가 바텐더로서 고급 역할수행 기능을 필요로 할 때 적합함","es":"Perfecto para Agentes de Conversación que necesitan capacidades de representación de roles avanzadas como bartender","fr":"Parfait pour les Agents de Conversation ayant besoin de capacités de jeu de rôle avancées en tant que barman","de":"Perfekt für Conversational Agents, die erweiterte Rollenspiel-Fähigkeiten als Barkeeper benötigen","pt":"Perfeito para Agentes de Conversação que precisam de capacidades avançadas de interpretação de papéis como bartender","ru":"Идеально подходит для Конверсационных Агентов, требующих расширенных возможностей ролевой игры в качестве бармена","ar":"مثالي لعمليات المحادثة التي تحتاج إلى قابليات متقدمة في لعب الأدوار كمبتدئ خبز"},"recommendation":{"en":"Empowers agents to manage tabs, handle drunk patrons, and pour drinks using generic bartending methods, all while maintaining confidentiality, leveraging methods like drink pouring and tab management through protocols like role-based interactions","zh":"赋予代理管理账单、处理醉酒顾客和使用通用调酒方法倒酒的能力，同时保持保密性，利用诸如倒酒和账单管理等方法通过基于角色的交互协议","ja":"エージェントがタブを管理し、酔った客を扱い、ジェネリックなバーテンディング方法を使用してドリンクを注ぐことを可能にし、同時に機密性を維持し、ドリンクの注ぎ方やタブ管理などの方法を使用してロールベースのインタラクションなどのプロトコルを利用する","ko":"에이전트가 탭을 관리하고, 취한 고객을 처리하며, 일반적인 바텐딩 방법을 사용하여 음료를倒을 수 있는 능력을 부여함과 동시에 기밀성을 유지하며, 음료를倒는 것과 탭 관리 등의 방법을 통해 역할 기반 상호작용과 같은 프로토콜을 활용함","es":"Habilita a los agentes a gestionar cuentas, manejar clientes ebrios y servir bebidas utilizando métodos genéricos de bartending, todo mientras mantiene la confidencialidad, aprovechando métodos como el vertido de bebidas y la gestión de cuentas a través de protocolos como interacciones basadas en roles","fr":"Permet aux agents de gérer les addition, de gérer les clients ivres et de servir des boissons en utilisant des méthodes génériques de bartending, le tout en maintenant la confidentialité, en exploitant des méthodes telles que le service de boissons et la gestion des addition via des protocoles tels que les interactions basées sur les rôles","de":"Ermächtigt die Agenten, Rechnungen zu verwalten, betrunkenen Kunden zu helfen und Getränke mithilfe generischer Bartending-Methoden zu servieren, all dies unter Wahrung der Vertraulichkeit, indem Methoden wie Getränkeausschank und Rechnungsverwaltung durch Protokolle wie rollenbasierte Interaktionen genutzt werden","pt":"Habilita agentes a gerenciar contas, lidar com clientes bêbados e servir bebidas usando métodos genéricos de bartender, mantendo a confidencialidade, utilizando métodos como servir bebidas e gerenciar contas por meio de protocolos como interações baseadas em papéis","ru":"Наделяет агентов возможностью управлять счетами, обрабатывать пьяных клиентов и наливать напитки, используя общие методы бармена, сохраняя конфиденциальность, используя методы, такие как наливание напитков и управление счетами через протоколы, такие как роль-ориентированные взаимодействия","ar":"تمكين الوكلاء من إدارة الحسابات ومعالجة العملاء السكارى وسكب المشروبات باستخدام طرق الخبز العامة، مع الحفاظ على السرية، واستخدام أساليب مثل سكب المشروبات وإدارة الحسابات من خلال بروتوكولات مثل التفاعلات القائمة على الأدوار"},"useCases":{"en":["Simulating realistic bar scenarios","Generating drink recipes and instructions","Handling complex customer interactions"],"zh":["模拟真实的酒吧场景","生成饮料配方和说明","处理复杂的客户交互"],"ja":["リアルなバーのシナリオをシミュレートする","ドリンクのレシピと説明を生成する","複雑な顧客のやり取りを処理する"],"ko":["현실적인 바 시나리오 시ミュ레이션","음료 레시피 및 설명 생성","복잡한 고객 상호작용 처리"],"es":["Simulación de escenarios de bar realistas","Generación de recetas y instrucciones de bebidas","Manejo de interacciones de clientes complejas"],"fr":["Simulation de scénarios de bar réalistes","Génération de recettes et d''instructions de boissons","Gestion d''interactions client complexes"],"de":["Simulieren realistischer Barszenarien","Generieren von Getränkerezepten und -anweisungen","Handhabung komplexer Kundeninteraktionen"],"pt":["Simulando cenários de bar realistas","Gerando receitas e instruções de bebidas","Lidando com interações de clientes complexas"],"ru":["Имитация реалистичных бар-сценариев","Генерация рецептов и инструкций напитков","Обработка сложных взаимодействий с клиентами"],"ar":["محاكاة سيناريوهات بار واقعية","генерация وصفات وتعليمات مشروبات","معالجة تفاعلات العملاء المعقدة"]},"limitations":{"en":["Does not provide personality or appearance traits","Limited to bartending role and does not include other skills or traits"],"zh":["不提供个性或外貌特征","仅限于调酒师角色，不包括其他技能或特征"],"ja":["個性や外見の特徴を提供しない","バーテンダーの役割のみに限定され、他のスキルや特徴は含まない"],"ko":["개성이나 외모 특성을 제공하지 않음","바텐더 역할에만 국한되고, 다른 기술이나 특성을 포함하지 않음"],"es":["No proporciona rasgos de personalidad o apariencia","Limitado al rol de bartender y no incluye otras habilidades o rasgos"],"fr":["Ne fournit pas de traits de personnalité ou d''apparence","Limité au rôle de barman et n''inclut pas d''autres compétences ou traits"],"de":["Bietet keine Persönlichkeits- oder Erscheinungsmerkmale","Begrenzt auf die Rolle des Barkeepers und enthält keine anderen Fähigkeiten oder Merkmale"],"pt":["Não fornece traços de personalidade ou aparência","Limitado ao papel de bartender e não inclui outras habilidades ou traços"],"ru":["Не предоставляет черты личности или внешности","Ограничен ролью бармена и не включает другие навыки или черты"],"ar":["لا يوفر سمات الشخصية أو المظهر","محدود بالدور الخبز ولا يتضمن مهارات أو سمات أخرى"]},"version":4},"contentHash":"d4d85310d9cf22eab091948bfa665d8c8a72779bcace4eeb48de9ed344362667","qualityScore":50}');
