INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SimHacker/moollm/bartender', 'bartender', 'SimHacker', 'moollm', 'community', 'bartender SimHacker moollm community The bartender skill provides generic bartending capabilities for AI agents, including methods for pouring drinks and managing tabs. This role-based skill is ideal for developers looking to create characters with bartending abilities. AI调酒师技能提供基本的调酒服务功能，包括倒饮料、管理订单和处理醉酒客户。 バーテンダーAIエージェントは、基本的なバーテンダー機能を提供します。飲み物の注ぎ方、注文の管理、酔った客の対応など AI 바텐더 에이전트는 기본적인 바텐더 기능을 제공합니다.飲料를倒는 방법, 주문 관리,醉한 고객 처리 등 El bartender es una habilidad de rol que proporciona métodos y comportamientos para la gestión de tabernas, incluyendo la preparación de bebidas y la gestión de cuentas Le bartender est une compétence de rôle qui fournit des méthodes et des comportements pour la gestion de bars, notamment la préparation de boissons et la gestion de comptes Der bartender ist eine Rolle, die Methoden und Verhaltensweisen für die Getränkeverwaltung bereitstellt, einschließlich der Zubereitung von Getränken und der Verwaltung von Konten O skill de bartender fornece métodos e comportamentos para gerenciar drinks e tabs. Implemente essas capacidades em seu projeto para melhorar a experiência do usuário. Навык бармена предоставляет методы и поведения для управления напитками и счетами. Реализуйте эти возможности в вашем проекте, чтобы улучшить опыт пользователя с помощью ИИ Агентов. تمتلك مهارة بارمان أساليب وسلوكيات لتنظيم المشروبات والفواتير. قم بتمكين هذه القدرات في مشروعك لتحسين تجربة المستخدم باستخدام أدوات الذكاء الاصطناعي. how to use bartender skill what is bartender skill bartender skill alternative bartender skill vs mixology bartender skill install bartender skill setup guide generic bartending capabilities AI agent bartending AI调酒师技能 调酒服务功能 ROLE技能 AIエージェント バーテンダー機能 Provides methods for pouring drinks Enables management of tabs Handles drunk behavior Includes knowledge of existing drinks Supports role-based character development Bartender is a role-based skill that provides methods and behaviors for generic bartending capabilities, including drink pouring and tab management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NammDev/goads-coss/ck:skill-creator', 'community', 'NammDev', 'goads-coss', 'NammDev/goads-coss', 'ck:skill-creator', 0, 0, 50, '2026-03-07T20:04:18Z', '2026-03-08T02:14:18.833Z', '9e3302d8170b4412c93b066f5aa46b7fe5d382af022427943924b646893a6e58', '{"id":"NammDev/goads-coss/ck:skill-creator","name":"ck:skill-creator","description":{"en":"The ck:skill-creator skill enables developers to create effective, benchmark-optimized Claude skills using progressive disclosure. It teaches Claude how to perform tasks, not what tools are, and activates multiple skills automatically based on metadata quality.","zh":"ck:skill-creator允许开发者使用进阶披露创建高效、基准优化的Claude技能。该技能提供了创建实用指令的能力","ja":"ck:skill-creatorは、開発者がプログレッシブディスクロージャーを使用して効率的なClaudeスキルを作成できるようにします。このスキルは、実用的指令の作成能力を提供する","ko":"ck:skill-creator는 개발자가渐进披露를 사용하여 효율적인 Claude 스킬을 생성할 수 있도록 합니다. 이 스킬은 실제적 지침의 생성 능력을 제공합니다","es":"ck:skill-creator es una habilidad que permite crear instrucciones prácticas para Claude con disclosure progresivo, inspirado en coss ui y shadcn studio","fr":"ck:skill-creator est une compétence qui permet de créer des instructions pratiques pour Claude avec divulgation progressive, inspirée par coss ui et shadcn studio","de":"ck:skill-creator ist eine Fähigkeit, die das Erstellen von praktischen Anweisungen für Claude mit progressiver Aufdeckung ermöglicht, inspiriert von coss ui und shadcn studio","pt":"O ck:skill-creator é uma ferramenta para criar habilidades práticas e otimizadas para o Claude, inspirada em coss ui e shadcn studio.","ru":"ИИ Агент ck:skill-creator предназначен для создания практических и оптимизированных навыков для Claude, вдохновленный coss ui и shadcn studio","ar":"وحدة الذكاء الاصطناعي ck:skill-creator هي أداة لإنشاء مهارات عملية ومحسّنة لبرنامج Claude، وتستند إلى مكتبات coss ui و shadcn studio"},"seo":{"title":{"en":"ck:s