INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NammDev/goads-coss/ck:skill-creator', 'ck:skill-creator', 'NammDev', 'goads-coss', 'community', 'ck:skill-creator NammDev goads-coss community The ck:skill-creator skill enables developers to create effective, benchmark-optimized Claude skills using progressive disclosure. It teaches Claude how to perform tasks, not what tools are, and activates multiple skills automatically based on metadata quality. ck:skill-creator允许开发者使用进阶披露创建高效、基准优化的Claude技能。该技能提供了创建实用指令的能力 ck:skill-creatorは、開発者がプログレッシブディスクロージャーを使用して効率的なClaudeスキルを作成できるようにします。このスキルは、実用的指令の作成能力を提供する ck:skill-creator는 개발자가渐进披露를 사용하여 효율적인 Claude 스킬을 생성할 수 있도록 합니다. 이 스킬은 실제적 지침의 생성 능력을 제공합니다 ck:skill-creator es una habilidad que permite crear instrucciones prácticas para Claude con disclosure progresivo, inspirado en coss ui y shadcn studio ck:skill-creator est une compétence qui permet de créer des instructions pratiques pour Claude avec divulgation progressive, inspirée par coss ui et shadcn studio ck:skill-creator ist eine Fähigkeit, die das Erstellen von praktischen Anweisungen für Claude mit progressiver Aufdeckung ermöglicht, inspiriert von coss ui und shadcn studio O ck:skill-creator é uma ferramenta para criar habilidades práticas e otimizadas para o Claude, inspirada em coss ui e shadcn studio. ИИ Агент ck:skill-creator предназначен для создания практических и оптимизированных навыков для Claude, вдохновленный coss ui и shadcn studio وحدة الذكاء الاصطناعي ck:skill-creator هي أداة لإنشاء مهارات عملية ومحسّنة لبرنامج Claude، وتستند إلى مكتبات coss ui و shadcn studio how to use ck:skill-creator ck:skill-creator alternative ck:skill-creator setup guide what is ck:skill-creator ck:skill-creator vs other AI skills ck:skill-creator install progressive disclosure in AI skills Claude skill creation best practices benchmark-optimized AI skills AI工具 ck:skill-creator 进阶披露 Claude技能 基准优化 实用指令 元数据质量 SKILL.md Creates skills as practical instructions, not documentation Teaches Claude how to perform tasks, not what tools are Activates multiple skills automatically based on metadata quality Utilizes progressive disclosure for optimized skills Follows a structured approach: Metadata → SKILL.md → Bundled resources Enforces a description limit of <200 characters for clarity ck:skill-creator is a skill that creates effective, benchmark-optimized Claude skills using progressive disclosure, enabling developers to teach Claude how to perform tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SS2608-dev/Resilience/Plugin Settings', 'community', 'SS2608-dev', 'Resilience', 'SS2608-dev/Resilience', 'Plugin Settings', 0, 0, 50, '2026-03-07T19:24:32Z', '2026-03-08T02:14:27.862Z', 'c6767a395d656799235d64120f57ea1f6b16d8118a1c5d86e4c8d622aa33e497', '{"id":"SS2608-dev/Resilience/Plugin Settings","name":"Plugin Settings","description":{"en":"Plugin Settings enables developers to store user-configurable settings and state in .claude/plugin-name.local.md files. This skill benefits developers working with Claude Code Plugins.","zh":"Plugin Settings允许在项目目录中存储用户可配置的设置和状态，使用YAML前置内容和Markdown正文","ja":"Plugin Settingsにより、プロジェクトディレクトリ内にユーザー設定可能な設定と状態を保存できます。YAMLフロントマターとMarkdownボディを使用します","ko":"Plugin Settings를 사용하면 프로젝트 디렉토리 내에 사용자 구성 가능한 설정 및 상태를 저장할 수 있습니다. YAML 프론트 매터와 Markdown 본문을 사용합니다","es":"Plugin Settings permite a los plugins almacenar configuraciones y estado personalizables en archivos `.claude/plugin-name.local.md`. Utiliza YAML y markdown para estructurar la configuración y el contenido.","fr":"Les paramètres de Plugin Settings permettent aux plugins de stocker des configurations et des états personnalisables dans des fichiers `.claude/plugin-name.local.md`. Il utilise YAML et markdown pour structurer la configuration et le contenu.","de":"Die Plugin-Settings-Einstellungen ermöglichen es Plugins, benutzerdefinierte Konfigurationen und Zustände in Dateien `.claude/plugin-name.local.md` zu speichern. Sie verwenden YAML und Markdown, um die Konfiguration und den Inhalt zu strukturieren.","pt":"O padrão de configuração de plugin para Claude Code permite armazenar configurações e estado do usuário em arquivos `.claude/plugin-name.local.md`","ru":"Шаблон настройки плагина для Claude Code позволяет хранить настройки и состояние пользователя в файлах `.claude/plugin-name.local.md`","ar":"نمط إعدادات البرنامج المساعد لـ Claude Code يسمح بتخزين إعدادات وحالة المستخدم في الملفات `.claude/plugin-name.local.md`"},"seo":{"title":{"en":"Plugin Settings: Configuration Setup Guide | AI Agent Skill","zh":"AI工具 Plugin Settings 配置指南","ja":"AIエージェント Plugin Settings 導入ベストプラクティス","ko":"AI 에이전트 Plugin Settings 설정 가이드","es":"Configuración de Plugin Settings: Guía de Implementación","fr":"Paramètres de Plugin Settings : Meilleures Pratiques","de":"Plugin Settings Konfiguration: Einrichtungsleitfaden","pt":"Configuração de Plugin: Guia de Configuração para Ferrame...","ru":"Настройка Плагина: Руководство по Настройке для ИИ Агентов","ar":"إعدادات البرنامج المساعد: دليل الإعداد للوكلاء الذكيين"},"description":{"en":"Discover how to leverage Plugin Settings for per-project configuration and state management. Learn to optimize your Claude Code Plugins with YAML frontmatter...","zh":"了解Plugin Settings的工作原理，实现项目目录中的用户可配置设置和状态存储","ja":"Plugin Settingsを使用して、プロジェクトディレクトリ内のユーザー設定可能な設定と状態を保存する方法を学びます","ko":"Plugin Settings를 사용하여 프로젝트 디렉토리 내의 사용자 구성 가능한 설정 및 상태를 저장하는 방법을 알아보세요","es":"Aprende a configurar Plugin Settings para Claude Code Plugins con YAML y markdown. Mejora la personalización y el estado de tus plugins.","fr":"Découvrez comment configurer les paramètres de Plugin Settings pour les plugins Claude Code avec YAML et markdown. Améliorez la personnalisation et l''état de...","de":"Erfahren Sie, wie Sie Plugin Settings für Claude Code-Plugins mit YAML und Markdown konfigurieren. Verbessern Sie die Anpassung und den Status Ihrer Plugins.","pt":"Aprenda a configurar plugins com o padrão de configuração de plugin para Claude Code, incluindo YAML frontmatter e markdown body","ru":"Узнайте, как настроить плагины с помощью шаблона настройки плагина для Claude Code, включая YAML frontmatter и markdown body","ar":"تعرف على كيفية تعريف البرامج المساعدة باستخدام نمط إعدادات البرنامج المساعد لـ Claude Code، بما في ذلك YAML frontmatter و markdown body"},"definition":{"en":"Plugin Settings is a pattern for storing per-project plugin configuration and state in YAML frontmatter and markdown content within .claude/plugin-name.local.md files.","zh":"Plugin Settings是一种存储用户可配置设置和状态的模式，使用YAML前置内容和Markdown正文","ja":"Plugin Settingsは、ユーザー設定可能な設定と状態を保存するためのパターンです。YAMLフロントマターとMarkdownボディを使用します","ko":"Plugin Settings는 사용자 구성 가능한 설정 및 상태를 저장하기 위한 패턴입니다. YAML 프론트 매터와 Markdown 본문을 사용합니다","es":"Plugin Settings es un patrón de configuración para plugins que almacena configuraciones y estado en archivos `.claude/plugin-name.local.md`","fr":"Les paramètres de Plugin Settings sont un modèle de configuration pour les plugins qui stockent des configurations et des états dans des fichiers `.claude/plugin-name.local.md`","de":"Die Plugin-Settings-Einstellungen sind ein Konfigurationsmuster für Plugins, das Konfigurationen und Zustände in Dateien `.claude/plugin-name.local.md` speichert","pt":"O que é configuração de plugin? É um padrão para armazenar configurações e estado do usuário em arquivos YAML e markdown","ru":"Что такое настройка плагина? Это шаблон для хранения настроек и состояния пользователя в файлах YAML и markdown","ar":"ما هي إعدادات البرنامج المساعد؟ هو نمط لتخزين إعدادات وحالة المستخدم في ملفات YAML و markdown"},"features":{"en":["Stores user-configurable settings in .claude/plugin-name.local.md files","Utilizes YAML frontmatter for structured configuration","Supports markdown content for prompts or additional context","Enables per-project plugin configuration and state management","Uses file location .claude/plugin-name.local.md in project root","Combines YAML frontmatter and markdown body for plugin settings"],"zh":["使用YAML前置内容进行结构化配置","使用Markdown正文进行提示或额外上下文","文件位置在项目根目录下的.claude/plugin-name.local.md","用于每个项目的插件配置和状态","支持用户可配置的设置和状态"],"ja":["YAMLフロントマターを使用した構造化されたコンフィグレーション","Markdownボディを使用したプロンプトまたは追加のコンテキスト","ファイルの場所はプロジェクトルートディレクトリ内の.claude/plugin-name.local.md","各プロジェクトのプラグインコンフィグレーションと状態","ユーザー設定可能な設定と状態のサポート"],"ko":["YAML 프론트 매터를 사용한 구조화된 구성","Markdown 본문을 사용한 프롬프트 또는 추가 컨텍스트","파일 위치는 프로젝트 루트 디렉토리 내의 .claude/plugin-name.local.md","각 프로젝트의 플러그인 구성 및 상태","사용자 구성 가능한 설정 및 상태 지원"],"es":["Almacenamiento de configuraciones en archivos `.claude/plugin-name.local.md`","Uso de YAML frontmatter para estructurar la configuración","Uso de markdown para contenido adicional","Permite personalización y estado por proyecto","Utiliza la estructura de directorios del proyecto","Soporta plugins de Claude Code"],"fr":["Stockage des configurations dans des fichiers `.claude/plugin-name.local.md`","Utilisation de YAML frontmatter pour structurer la configuration","Utilisation de markdown pour le contenu supplémentaire","Permet la personnalisation et l''état par projet","Utilise la structure de répertoires du projet","Prend en charge les plugins Claude Code"],"de":["Speicherung von Konfigurationen in Dateien `.claude/plugin-name.local.md`","Verwendung von YAML-Frontmatter zur Strukturierung der Konfiguration","Verwendung von Markdown für zusätzlichen Inhalt","Ermöglicht Anpassung und Zustand pro Projekt","Verwendet die Verzeichnisstruktur des Projekts","Unterstützt Claude Code-Plugins"],"pt":["Armazenamento de configurações em arquivos `.claude/plugin-name.local.md`","Uso de YAML frontmatter para configuração estruturada","Uso de markdown body para prompts ou contexto adicional","Localização em `.claude/` no diretório do projeto","Padrão de configuração para plugins Claude Code"],"ru":["Хранение настроек в файлах `.claude/plugin-name.local.md`","Использование YAML frontmatter для структурированной конфигурации","Использование markdown body для подсказок или дополнительного контекста","Расположение в `.claude/` в корне проекта","Шаблон настройки для плагинов Claude Code"],"ar":["تخزين الإعدادات في الملفات `.claude/plugin-name.local.md`","استخدام YAML frontmatter لإعدادات هيكلية","استخدام markdown body لتعليمات أو سياق إضافي","الوضع في `.claude/` في 根 المشروع","نمط إعدادات للبرامج المساعدة Claude Code"]},"keywords":{"en":["how to use Plugin Settings","Plugin Settings setup guide","what is Plugin Settings","Plugin Settings alternative","Plugin Settings vs Claude Code","Plugin Settings install","YAML frontmatter for plugin settings","markdown content for plugin configuration","per-project plugin configuration"],"zh":["AI工具","Plugin Settings","YAML前置内容","Markdown正文","项目目录","用户可配置设置","状态存储","插件配置"],"ja":["AIエージェント","Plugin Settings","YAMLフロントマター","Markdownボディ","プロジェクトディレクトリ","ユーザー設定可能な設定","状態保存","プラグインコンフィグレーション"],"ko":["AI 에이전트","Plugin Settings","YAML 프론트 매터","Markdown 본문","프로젝트 디렉토리","사용자 구성 가능한 설정","상태 저장","플러그인 구성"],"es":["Plugin Settings","configuración de plugins","Claude Code","YAML","markdown","personalización de plugins","estado de plugins","Herramientas de AI","Agentes de inteligencia artificial"],"fr":["Paramètres de Plugin Settings","configuration de plugins","Claude Code","YAML","markdown","personnalisation de plugins","état de plugins","Outils d''IA","Agents d''intelligence artificielle"],"de":["Plugin-Settings-Einstellungen","Plugin-Konfiguration","Claude Code","YAML","Markdown","Anpassung von Plugins","Zustand von Plugins","KI-Tools","Künstliche Intelligenz Agenten"],"pt":["configuração de plugin","ferramentas de ia","claude code","yaml frontmatter","markdown body","armazenamento de configurações","padrão de configuração","desenvolvimento de plugins"],"ru":["настройка плагина","ии агенты","claude code","yaml frontmatter","markdown body","хранение настроек","шаблон настройки","разработка плагинов"],"ar":["إعدادات البرنامج المساعد","الوكلاء الذكيين","claude code","yaml frontmatter","markdown body","تخزين الإعدادات","نمط إعدادات","تطوير البرامج المساعدة"]}},"owner":"SS2608-dev","repo":"Resilience","repoPath":"SS2608-dev/Resilience","stars":0,"forks":0,"updatedAt":"2026-03-07T19:24:32Z","topics":[],"category":"community","skillMd":{"name":"Plugin Settings","description":"This skill should be used when the user asks about plugin settings, store plugin configuration, user-configurable plugin, .local.md files, plugin state files, read YAML frontmatter, per-project plugin settings, or wants to make plugin behavior configurable. Documents the .claude/plugin-name.local.md pattern for storing plugin-specific configuration with YAML frontmatter and markdown content.","version":"0.1.0","bodyPreview":"# Plugin Settings Pattern for Claude Code Plugins\n\n## Overview\n\nPlugins can store user-configurable settings and state in `.claude/plugin-name.local.md` files within the project directory. This pattern uses YAML frontmatter for structured configuration and markdown content for prompts or additional context.\n\n**Key characteristics:**\n\n- File location: `.claude/plugin-name.local.md` in project root\n- Structure: YAML frontmatter + markdown body\n- Purpose: Per-project plugin configuration and state","body":"# Plugin Settings Pattern for Claude Code Plugins\n\n## Overview\n\nPlugins can store user-configurable settings and state in `.claude/plugin-name.local.md` files within the project directory. This pattern uses YAML frontmatter for structured configuration and markdown content for prompts or additional context.\n\n**Key characteristics:**\n\n- File location: `.claude/plugin-name.local.md` in project root\n- Structure: YAML frontmatter + markdown body\n- Purpose: Per-project plugin configuration and state\n- Usage: Read from hooks, commands, and agents\n- Lifecycle: User-managed (not in git, should be in `.gitignore`)\n\n## File Structure\n\n### Basic Template\n\n```markdown\n---\nenabled: true\nsetting1: value1\nsetting2: value2\nnumeric_setting: 42\nlist_setting: [\"item1\", \"item2\"]\n---\n\n# Additional Context\n\nThis markdown body can contain:\n\n- Task descriptions\n- Additional instructions\n- Prompts to feed back to Claude\n- Documentation or notes\n```\n\n### Example: Plugin State File\n\n**.claude/my-plugin.local.md:**\n\n```markdown\n---\nenabled: true\nstrict_mode: false\nmax_retries: 3\nnotification_level: info\ncoordinator_session: team-leader\n---\n\n# Plugin Configuration\n\nThis plugin is configured for standard validation mode.\nContact @team-lead with questions.\n```\n\n## Reading Settings Files\n\n### From Hooks (Bash Scripts)\n\n**Pattern: Check existence and parse frontmatter**\n\n```bash\n#!/bin/bash\nset -euo pipefail\n\n# Define state file path\nSTATE_FILE=\".claude/my-plugin.local.md\"\n\n# Quick exit if file doesn''t exist\nif [[ ! -f \"$STATE_FILE\" ]]; then\n  exit 0  # Plugin not configured, skip\nfi\n\n# Parse YAML frontmatter (between --- markers)\nFRONTMATTER=$(sed -n ''/^---$/,/^---$/{ /^---$/d; p; }'' \"$STATE_FILE\")\n\n# Extract individual fields\nENABLED=$(echo \"$FRONTMATTER\" | grep ''^enabled:'' | sed ''s/enabled: *//'' | sed ''s/^\"\\(.*\\)\"$/\\1/'')\nSTRICT_MODE=$(echo \"$FRONTMATTER\" | grep ''^strict_mode:'' | sed ''s/strict_mode: *//'' | sed ''s/^\"\\(.*\\)\"$/\\1/'')\n\n# Check if enabled\nif [[ \"$ENABLED\" != \"true\" ]]; then\n  exit 0  # Disabled\nfi\n\n# Use configuration in hook logic\nif [[ \"$STRICT_MODE\" == \"true\" ]]; then\n  # Apply strict validation\n  # ...\nfi\n```\n\nSee `examples/read-settings-hook.sh` for complete working example.\n\n### From Commands\n\nCommands can read settings files to customize behavior:\n\n```markdown\n---\ndescription: Process data with plugin\nallowed-tools: [\"Read\", \"Bash\"]\n---\n\n# Process Command\n\nSteps:\n\n1. Check if settings exist at `.claude/my-plugin.local.md`\n2. Read configuration using Read tool\n3. Parse YAML frontmatter to extract settings\n4. Apply settings to processing logic\n5. Execute with configured behavior\n```\n\n### From Agents\n\nAgents can reference settings in their instructions:\n\n```markdown\n---\nname: configured-agent\ndescription: Agent that adapts to project settings\n---\n\nCheck for plugin settings at `.claude/my-plugin.local.md`.\nIf present, parse YAML frontmatter and adapt behavior according to:\n\n- enabled: Whether plugin is active\n- mode: Processing mode (strict, standard, lenient)\n- Additional configuration fields\n```\n\n## Parsing Techniques\n\n### Extract Frontmatter\n\n```bash\n# Extract everything between --- markers\nFRONTMATTER=$(sed -n ''/^---$/,/^---$/{ /^---$/d; p; }'' \"$FILE\")\n```\n\n### Read Individual Fields\n\n**String fields:**\n\n```bash\nVALUE=$(echo \"$FRONTMATTER\" | grep ''^field_name:'' | sed ''s/field_name: *//'' | sed ''s/^\"\\(.*\\)\"$/\\1/'')\n```\n\n**Boolean fields:**\n\n```bash\nENABLED=$(echo \"$FRONTMATTER\" | grep ''^enabled:'' | sed ''s/enabled: *//'')\n# Compare: if [[ \"$ENABLED\" == \"true\" ]]; then\n```\n\n**Numeric fields:**\n\n```bash\nMAX=$(echo \"$FRONTMATTER\" | grep ''^max_value:'' | sed ''s/max_value: *//'')\n# Use: if [[ $MAX -gt 100 ]]; then\n```\n\n### Read Markdown Body\n\nExtract content after second `---`:\n\n```bash\n# Get everything after closing ---\nBODY=$(awk ''/^---$/{i++; next} i>=2'' \"$FILE\")\n```\n\n## Common Patterns\n\n### Pattern 1: Temporarily Active Hooks\n\nUse settings file to control hook activation:\n\n```bash\n#!/bin/bash\nSTATE_FILE=\".claude/security-scan.local.md\"\n\n# Quick exit if not configured\nif [[ ! -f \"$STATE_FILE\" ]]; then\n  exit 0\nfi\n\n# Read enabled flag\nFRONTMATTER=$(sed -n ''/^---$/,/^---$/{ /^---$/d; p; }'' \"$STATE_FILE\")\nENABLED=$(echo \"$FRONTMATTER\" | grep ''^enabled:'' | sed ''s/enabled: *//'')\n\nif [[ \"$ENABLED\" != \"true\" ]]; then\n  exit 0  # Disabled\nfi\n\n# Run hook logic\n# ...\n```\n\n**Use case:** Enable/disable hooks without editing hooks.json (requires restart).\n\n### Pattern 2: Agent State Management\n\nStore agent-specific state and configuration:\n\n**.claude/multi-agent-swarm.local.md:**\n\n```markdown\n---\nagent_name: auth-agent\ntask_number: 3.5\npr_number: 1234\ncoordinator_session: team-leader\nenabled: true\ndependencies: [\"Task 3.4\"]\n---\n\n# Task Assignment\n\nImplement JWT authentication for the API.\n\n**Success Criteria:**\n\n- Authentication endpoints created\n- Tests passing\n- PR created and CI green\n```\n\nRead from hooks to coordinate agents:\n\n```bash\nAGENT_NAME=$(echo \"$FRONTMATTER\" | grep ''^agent_name:'' | sed ''s/agent_name: *//'')\nCOORDINATOR=$(echo \"$FRONTMATTER\" | grep ''^coordinator_session:'' | sed ''s/coordinator_session: *//'')\n\n# Send notification to coordinator\ntmux send-keys -t \"$COORDINATOR\" \"Agent $AGENT_NAME completed task\" Enter\n```\n\n### Pattern 3: Configuration-Driven Behavior\n\n**.claude/my-plugin.local.md:**\n\n```markdown\n---\nvalidation_level: strict\nmax_file_size: 1000000\nallowed_extensions: [\".js\", \".ts\", \".tsx\"]\nenable_logging: true\n---\n\n# Validation Configuration\n\nStrict mode enabled for this project.\nAll writes validated against security policies.\n```\n\nUse in hooks or commands:\n\n```bash\nLEVEL=$(echo \"$FRONTMATTER\" | grep ''^validation_level:'' | sed ''s/validation_level: *//'')\n\ncase \"$LEVEL\" in\n  strict)\n    # Apply strict validation\n    ;;\n  standard)\n    # Apply standard validation\n    ;;\n  lenient)\n    # Apply lenient validation\n    ;;\nesac\n```\n\n## Creating Settings Files\n\n### From Commands\n\nCommands can create settings files:\n\n```markdown\n# Setup Command\n\nSteps:\n\n1. Ask user for configuration preferences\n2. Create `.claude/my-plugin.local.md` with YAML frontmatter\n3. Set appropriate values based on user input\n4. Inform user that settings are saved\n5. Remind user to restart Claude Code for hooks to recognize changes\n```\n\n### Template Generation\n\nProvide template in plugin README:\n\n```markdown\n## Configuration\n\nCreate `.claude/my-plugin.local.md` in your project:\n\n## \\`\\`\\`markdown\n\nenabled: true\nmode: standard\nmax_retries: 3\n\n---\n\n# Plugin Configuration\n\nYour settings are active.\n\\`\\`\\`\n\nAfter creating or editing, restart Claude Code for changes to take effect.\n```\n\n## Best Practices\n\n### File Naming\n\n✅ **DO:**\n\n- Use `.claude/plugin-name.local.md` format\n- Match plugin name exactly\n- Use `.local.md` suffix for user-local files\n\n❌ **DON''T:**\n\n- Use different directory (not `.claude/`)\n- Use inconsistent naming\n- Use `.md` without `.local` (might be committed)\n\n### Gitignore\n\nAlways add to `.gitignore`:\n\n```gitignore\n.claude/*.local.md\n.claude/*.local.json\n```\n\nDocument this in plugin README.\n\n### Defaults\n\nProvide sensible defaults when settings file doesn''t exist:\n\n```bash\nif [[ ! -f \"$STATE_FILE\" ]]; then\n  # Use defaults\n  ENABLED=true\n  MODE=standard\nelse\n  # Read from file\n  # ...\nfi\n```\n\n### Validation\n\nValidate settings values:\n\n```bash\nMAX=$(echo \"$FRONTMATTER\" | grep ''^max_value:'' | sed ''s/max_value: *//'')\n\n# Validate numeric range\nif ! [[ \"$MAX\" =~ ^[0-9]+$ ]] || [[ $MAX -lt 1 ]] || [[ $MAX -gt 100 ]]; then\n  echo \"⚠️  Invalid max_value in settings (must be 1-100)\" >&2\n  MAX=10  # Use default\nfi\n```\n\n### Restart Requirement\n\n**Important:** Settings changes require Claude Code restart.\n\nDocument in your README:\n\n```markdown\n## Changing Settings\n\nAfter editing `.claude/my-plugin.local.md`:\n\n1. Save the file\n2. Exit Claude Code\n3. Restart: `claude` or `cc`\n4. New settings will be loaded\n```\n\nHooks cannot be hot-swapped within a session.\n\n## Security Considerations\n\n### Sanitize User Input\n\nWhen writing settings files from user input:\n\n```bash\n# Escape quotes in user input\nSAFE_VALUE=$(echo \"$USER_INPUT\" | sed ''s/\"/\\\\\"/g'')\n\n# Write to file\ncat > \"$STATE_FILE\" <<EOF\n---\nuser_setting: \"$SAFE_VALUE\"\n---\nEOF\n```\n\n### Validate File Paths\n\nIf settings contain file paths:\n\n```bash\nFILE_PATH=$(echo \"$FRONTMATTER\" | grep ''^data_file:'' | sed ''s/data_file: *//'')\n\n# Check for path traversal\nif [[ \"$FILE_PATH\" == *\"..\"* ]]; then\n  echo \"⚠️  Invalid path in settings (path traversal)\" >&2\n  exit 2\nfi\n```\n\n### Permissions\n\nSettings files should be:\n\n- Readable by user only (`chmod 600`)\n- Not committed to git\n- Not shared between users\n\n## Real-World Examples\n\n### multi-agent-swarm Plugin\n\n**.claude/multi-agent-swarm.local.md:**\n\n```markdown\n---\nagent_name: auth-implementation\ntask_number: 3.5\npr_number: 1234\ncoordinator_session: team-leader\nenabled: true\ndependencies: [\"Task 3.4\"]\nadditional_instructions: Use JWT tokens, not sessions\n---\n\n# Task: Implement Authentication\n\nBuild JWT-based authentication for the REST API.\nCoordinate with auth-agent on shared types.\n```\n\n**Hook usage (agent-stop-notification.sh):**\n\n- Checks if file exists (line 15-18: quick exit if not)\n- Parses frontmatter to get coordinator_session, agent_name, enabled\n- Sends notifications to coordinator if enabled\n- Allows quick activation/deactivation via `enabled: true/false`\n\n### ralph-wiggum Plugin\n\n**.claude/ralph-loop.local.md:**\n\n```markdown\n---\niteration: 1\nmax_iterations: 10\ncompletion_promise: \"All tests passing and build successful\"\n---\n\nFix all the linting errors in the project.\nMake sure tests pass after each fix.\n```\n\n**Hook usage (stop-hook.sh):**\n\n- Checks if file exists (line 15-18: quick exit if not active)\n- Reads iteration count and max_iterations\n- Extracts completion_promise for loop termination\n- Reads body as the prompt to feed back\n- Updates iteration count on each loop\n\n## Quick Reference\n\n### File Location\n\n```\nproject-root/\n└── .claude/\n    └── plugin-name.local.md\n```\n\n### Frontmatter Parsing\n\n```bash\n# Extract frontmatter\nFRONTMATTER=$(sed -n ''/^---$/,/^---$/{ /^---$/d; p; }'' \"$FILE\")\n\n# Read field\nVALUE=$(echo \"$FRONTMATTER\" | grep ''^field:'' | sed ''s/field: *//'' | sed ''s/^\"\\(.*\\)\"$/\\1/'')\n```\n\n### Body Parsing\n\n```bash\n# Extract body (after second ---)\nBODY=$(awk ''/^---$/{i++; next} i>=2'' \"$FILE\")\n```\n\n### Quick Exit Pattern\n\n```bash\nif [[ ! -f \".claude/my-plugin.local.md\" ]]; then\n  exit 0  # Not configured\nfi\n```\n\n## Additional Resources\n\n### Reference Files\n\nFor detailed implementation patterns:\n\n- **`references/parsing-techniques.md`** - Complete guide to parsing YAML frontmatter and markdown bodies\n- **`references/real-world-examples.md`** - Deep dive into multi-agent-swarm and ralph-wiggum implementations\n\n### Example Files\n\nWorking examples in `examples/`:\n\n- **`read-settings-hook.sh`** - Hook that reads and uses settings\n- **`create-settings-command.md`** - Command that creates settings file\n- **`example-settings.md`** - Template settings file\n\n### Utility Scripts\n\nDevelopment tools in `scripts/`:\n\n- **`validate-settings.sh`** - Validate settings file structure\n- **`parse-frontmatter.sh`** - Extract frontmatter fields\n\n## Implementation Workflow\n\nTo add settings to a plugin:\n\n1. Design settings schema (which fields, types, defaults)\n2. Create template file in plugin documentation\n3. Add gitignore entry for `.claude/*.local.md`\n4. Implement settings parsing in hooks/commands\n5. Use quick-exit pattern (check file exists, check enabled field)\n6. Document settings in plugin README with template\n7. Remind users that changes require Claude Code restart\n\nFocus on keeping settings simple and providing good defaults when settings file doesn''t exist.\n"},"lastSynced":"2026-03-08T02:14:27.862Z","agentAnalysis":{"suitability":{"en":"Ideal for Claude Code Agents requiring customizable plugin configurations and state management.","zh":"适用于需要自定义插件配置和状态管理的 Claude Code Agents。","ja":"カスタマイズ可能なプラグイン構成と状態管理を必要とする Claude Code Agents に適しています。","ko":"사용자 지정 플러그인 구성 및 상태 관리가 필요한 Claude Code Agents 에 적합합니다.","es":"Ideal para agentes de Claude Code que requieren configuraciones de plugin personalizables y gestión de estado.","fr":"Idéal pour les agents Claude Code nécessitant des configurations de plugin personnalisables et une gestion d''état.","de":"Ideal für Claude Code-Agents, die benutzerdefinierte Plugin-Konfigurationen und Statusverwaltung erfordern.","pt":"Ideal para Agentes de Código Claude que exigem configurações de plug-in personalizáveis e gerenciamento de estado.","ru":"Идеально для агентов Claude Code, требующих настраиваемых конфигураций плагинов и управления состоянием.","ar":"مثالي لعميل كلود كود الذي يتطلب تكوين إضافات مخصص وقيمة إدارة الحالة."},"recommendation":{"en":"Empowers agents to store user-configurable settings and state in .claude/plugin-name.local.md files using YAML frontmatter for structured configuration and markdown content for prompts or additional context, enhancing plugin functionality with per-project configuration capabilities.","zh":"使得代理能够使用 YAML 前置内容存储用户可配置的设置和状态在 .claude/plugin-name.local.md 文件中，并使用 markdown 内容用于提示或其他上下文，增强插件功能以每个项目的配置能力。","ja":"エージェントが YAML フロントマターを使用して構造化された構成とマークダウン コンテンツを使用してプロンプトまたは追加のコンテキストを .claude/plugin-name.local.md ファイルに保存できるようにし、プラグインの機能をプロジェクトごとの構成能力で強化します。","ko":"에이전트가 YAML 프롬트매터를 사용하여 구조화된 구성과 마크다운 콘텐츠를 사용하여 프롬프트 또는 추가 컨텍스트를 .claude/plugin-name.local.md 파일에 저장할 수 있도록 하여 플러그인 기능을 프로젝트별 구성 기능으로 강화합니다.","es":"Permite a los agentes almacenar configuraciones y estado personalizables por el usuario en archivos .claude/plugin-name.local.md utilizando YAML frontmatter para una configuración estructurada y contenido de markdown para prompts o contexto adicional, mejorando la funcionalidad del plugin con capacidades de configuración por proyecto.","fr":"Permet aux agents de stocker des paramètres et un état configurables par l''utilisateur dans des fichiers .claude/plugin-name.local.md en utilisant YAML frontmatter pour une configuration structurée et du contenu markdown pour les invites ou le contexte supplémentaire, améliorant les fonctionnalités du plugin avec des capacités de configuration par projet.","de":"Ermöglicht es den Agents, benutzerdefinierte Einstellungen und Status in Dateien .claude/plugin-name.local.md zu speichern, indem YAML-Frontmatter für eine strukturierte Konfiguration und Markdown-Inhalt für Prompts oder zusätzlichen Kontext verwendet wird, wodurch die Plug-in-Funktionalität mit projektspezifischen Konfigurationsmöglichkeiten erweitert wird.","pt":"Habilita os agentes a armazenar configurações personalizadas pelo usuário e estado em arquivos .claude/plugin-name.local.md usando YAML frontmatter para configuração estruturada e conteúdo markdown para prompts ou contexto adicional, aprimorando a funcionalidade do plug-in com capacidades de configuração por projeto.","ru":"Предоставляет агентам возможность хранить настраиваемые пользователем параметры и состояние в файлах .claude/plugin-name.local.md, используя YAML frontmatter для структурированной конфигурации и содержимое markdown для подсказок или дополнительного контекста, расширяя функциональность плагина возможностями конфигурации для каждого проекта.","ar":"يمنح الوكلاء القدرة على تخزين الإعدادات التي يمكن تخصيصها بواسطة المستخدم والحالة في ملفات .claude/plugin-name.local.md باستخدام YAML frontmatter للتهيئة المنظمة والمحتوى markdown لملحوظات أو سياق إضافي ، مما يعزز وظائف الإضافة مع القدرات التكوينية لكل مشروع."},"useCases":{"en":["Configuring plugins for specific projects","Storing user preferences in markdown files","Managing plugin state across different projects"],"zh":["为特定项目配置插件","在 markdown 文件中存储用户首选项","在不同项目中管理插件状态"],"ja":["特定のプロジェクトのプラグインを構成する","マークダウン ファイルにユーザー設定を保存する","異なるプロジェクト間でプラグイン状態を管理する"],"ko":["특정 프로젝트의 플러그인을 구성하는 것","마크다운 파일에 사용자 설정을 저장하는 것","다른 프로젝트 간에 플러그인 상태를 관리하는 것"],"es":["Configuración de plugins para proyectos específicos","Almacenamiento de preferencias de usuario en archivos de markdown","Administración del estado del plugin en diferentes proyectos"],"fr":["Configuration de plugins pour des projets spécifiques","Stockage des préférences de l''utilisateur dans des fichiers markdown","Gestion de l''état du plugin sur différents projets"],"de":["Konfiguration von Plug-ins für bestimmte Projekte","Speicherung von Benutzervorlieben in Markdown-Dateien","Verwaltung des Plug-in-Status über verschiedene Projekte hinweg"],"pt":["Configurando plug-ins para projetos específicos","Armazenando preferências do usuário em arquivos markdown","Gerenciando estado do plug-in em diferentes projetos"],"ru":["Настройка плагинов для конкретных проектов","Хранение предпочтений пользователя в файлах markdown","Управление состоянием плагина в разных проектах"],"ar":["تكوين الإضافات لمشاريع محددة","تخزين تفضيلات المستخدم في ملفات markdown","إدارة حالة الإضافة في مشاريع مختلفة"]},"limitations":{"en":["Requires Claude Code Plugin environment","Filesystem access needed for .claude/plugin-name.local.md files"],"zh":["需要 Claude Code Plugin 环境","需要文件系统访问 .claude/plugin-name.local.md 文件"],"ja":["Claude Code Plugin 環境が必要",".claude/plugin-name.local.md ファイルへのファイルシステムアクセスが必要"],"ko":["Claude Code Plugin 환경이 필요",".claude/plugin-name.local.md 파일에 대한 파일 시스템 접근이 필요"],"es":["Requiere entorno de Claude Code Plugin","Acceso al sistema de archivos necesario para archivos .claude/plugin-name.local.md"],"fr":["Nécessite un environnement de plugin Claude Code","Accès au système de fichiers nécessaire pour les fichiers .claude/plugin-name.local.md"],"de":["Benötigt Claude Code-Plug-in-Umgebung","Zugriff auf das Dateisystem erforderlich für Dateien .claude/plugin-name.local.md"],"pt":["Exige ambiente de plug-in Claude Code","Acesso ao sistema de arquivos necessário para arquivos .claude/plugin-name.local.md"],"ru":["Требует среды плагина Claude Code","Требуется доступ к файловой системе для файлов .claude/plugin-name.local.md"],"ar":["يتطلب بيئة إضافة كلود كود","يتطلب الوصول إلى نظام الملفات لملفات .claude/plugin-name.local.md"]},"version":4},"contentHash":"c6767a395d656799235d64120f57ea1f6b16d8118a1c5d86e4c8d622aa33e497","qualityScore":50}');
