INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SS2608-dev/Resilience/Plugin Settings', 'Plugin Settings', 'SS2608-dev', 'Resilience', 'community', 'Plugin Settings SS2608-dev Resilience community Plugin Settings enables developers to store user-configurable settings and state in .claude/plugin-name.local.md files. This skill benefits developers working with Claude Code Plugins. Plugin Settings允许在项目目录中存储用户可配置的设置和状态，使用YAML前置内容和Markdown正文 Plugin Settingsにより、プロジェクトディレクトリ内にユーザー設定可能な設定と状態を保存できます。YAMLフロントマターとMarkdownボディを使用します Plugin Settings를 사용하면 프로젝트 디렉토리 내에 사용자 구성 가능한 설정 및 상태를 저장할 수 있습니다. YAML 프론트 매터와 Markdown 본문을 사용합니다 Plugin Settings permite a los plugins almacenar configuraciones y estado personalizables en archivos `.claude/plugin-name.local.md`. Utiliza YAML y markdown para estructurar la configuración y el contenido. Les paramètres de Plugin Settings permettent aux plugins de stocker des configurations et des états personnalisables dans des fichiers `.claude/plugin-name.local.md`. Il utilise YAML et markdown pour structurer la configuration et le contenu. Die Plugin-Settings-Einstellungen ermöglichen es Plugins, benutzerdefinierte Konfigurationen und Zustände in Dateien `.claude/plugin-name.local.md` zu speichern. Sie verwenden YAML und Markdown, um die Konfiguration und den Inhalt zu strukturieren. O padrão de configuração de plugin para Claude Code permite armazenar configurações e estado do usuário em arquivos `.claude/plugin-name.local.md` Шаблон настройки плагина для Claude Code позволяет хранить настройки и состояние пользователя в файлах `.claude/plugin-name.local.md` نمط إعدادات البرنامج المساعد لـ Claude Code يسمح بتخزين إعدادات وحالة المستخدم في الملفات `.claude/plugin-name.local.md` how to use Plugin Settings Plugin Settings setup guide what is Plugin Settings Plugin Settings alternative Plugin Settings vs Claude Code Plugin Settings install YAML frontmatter for plugin settings markdown content for plugin configuration per-project plugin configuration AI工具 Plugin Settings YAML前置内容 Markdown正文 项目目录 用户可配置设置 状态存储 插件配置 Stores user-configurable settings in .claude/plugin-name.local.md files Utilizes YAML frontmatter for structured configuration Supports markdown content for prompts or additional context Enables per-project plugin configuration and state management Uses file location .claude/plugin-name.local.md in project root Combines YAML frontmatter and markdown body for plugin settings Plugin Settings is a pattern for storing per-project plugin configuration and state in YAML frontmatter and markdown content within .claude/plugin-name.local.md files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanakkiyan-s/django-food-delivery-backend/Django REST Framework Master Rules', 'community', 'sanakkiyan-s', 'django-food-delivery-backend', 'sanakkiyan-s/django-food-delivery-backend', 'Django REST Framework Master Rules', 0, 0, 50, '2026-03-03T12:52:19Z', '2026-03-08T02:18:39.852Z', '04251c85b7ea14a793ff735e509142edb626205c0806971cfb68ac2de4b77504', '{"id":"sanakkiyan-s/django-food-delivery-backend/Django REST Framework Master Rules","name":"Django REST Framework Master Rules","description":{"en":"Django REST Framework Master Rules provides a set of guidelines for building enterprise-level Django projects, enabling expert-level backend engineers to create scalable and maintainable applications.","zh":"Django REST Framework Master 规则提供了高级的架构模板和最佳实践，用于构建企业级别的 API。","ja":"Django REST Framework マスター ルールは、エンタープライズ レベルの API を構築するための高度なアーキテクチャ テンプレートとベスト プラクティスを提供します。","ko":"Django REST Framework 마스터 규칙은 기업 수준의 API를 구축하기 위한 고급 아키텍처 템플릿과 최적화된 개발 방법을 제공합니다.","es":"Las reglas maestras de Django REST Framework proporcionan una arquitectura de backend empresarial robusta para proyectos Django","fr":"Les règles maîtres de Django REST Framework offrent une architecture backend d''entreprise robuste pour les projets Django","de":"Die Master-Regeln von Django REST Framework bieten eine robuste Unternehmens-Backend-Architektur für Django-Projekte","pt":"O Django REST Framework Master Rules é um conjunto de regras avançadas para a configuração de projetos Django. Ele fornece uma arquitetura de projeto escalável e padrões de codificação.","ru":"Django REST Framework Master Rules - это набор передовых правил для настройки проектов Django. Он обеспечивает масштабируемую архитектуру проекта и шаблоны кодирования для ИИ Агентов","ar":"Django REST Framework Master Rules هو مجموعة من القواعد المتقدمة لتهيئة مشاريع Django. يوفر بنية مشروع قابلة للتحجيم ونمط التشفير للوكلاء الذكيين"},"seo":{"title":{"en":"Django REST Framework Master Rules: Setup Guide for AI Ag...","zh":"Django REST Framework Master 规则设置指南","ja":"Django REST Framework マスター ルール設定ガイド - AIエージェント","ko":"Django REST Framework 마스터 규칙 설정 가이드 - AI 도구","es":"Reglas Maestras de Django REST Framework: Guía de Configu...","fr":"Règles Maîtres de Django REST Framework: Guide de Mise en...","de":"Django REST Framework Master-Regeln: Einrichtungsleitfaden","pt":"Django REST Framework Master Rules: Guia de Configuração ...","ru":"Django REST Framework Master Rules: Руководство по настро...","ar":"Django REST Framework Master Rules: دليل إعداد الوكلاء ال..."},"description":{"en":"Unlock expert-level enterprise backend engineering with Django REST Framework Master Rules. Learn the critical rules for project scaffolding and core archite...","zh":"了解 Django REST Framework 的高级架构模板和最佳实践，提高您的 API 开发效率","ja":"Django REST Framework のエンタープライズ レベルのアーキテクチャ テンプレートとベスト プラクティスを学び、API 開発の効率を上げる - AIエージェント","ko":"Django REST Framework의 고급 아키텍처 템플릿과 최적화된 개발 방법을 학습하여 API 개발 효율성을 높여보세요 - AI 도구","es":"Aprende a configurar proyectos Django con las reglas maestras de Django REST Framework para una arquitectura de backend empresarial robusta","fr":"Découvrez comment configurer des projets Django avec les règles maîtres de Django REST Framework pour une architecture backend d''entreprise robuste","de":"Erfahren Sie, wie Sie Django-Projekte mit den Master-Regeln von Django REST Framework für eine robuste Unternehmens-Backend-Architektur konfigurieren","pt":"Aprenda a configurar o Django REST Framework com regras avançadas de arquitetura de projeto e padrões de codificação","ru":"Узнайте, как настроить Django REST Framework с помощью передовых правил архитектуры проекта и шаблонов кодирования для ИИ Агентов","ar":"تعلم كيفية設定 Django REST Framework باستخدام قواعد متقدمة لتصميم المشروع ونمط التشفير للوكلاء الذكيين"},"definition":{"en":"Django REST Framework Master Rules is a set of architecture templates and guidelines for building Django projects using enterprise abstractions.","zh":"Django REST Framework Master 规则是一套用于构建企业级别 API 的高级架构模板和最佳实践","ja":"Django REST Framework マスター ルールは、エンタープライズ レベルの API を構築するための高度なアーキテクチャ テンプレートとベスト プラクティスです","ko":"Django REST Framework 마스터 규칙은 기업 수준의 API를 구축하기 위한 고급 아키텍처 템플릿과 최적화된 개발 방법입니다","es":"Reglas maestras de Django REST Framework: un conjunto de patrones de arquitectura para proyectos Django","fr":"Règles maîtres de Django REST Framework: un ensemble de patrons d''architecture pour les projets Django","de":"Master-Regeln von Django REST Framework: ein Satz von Architekturmuster für Django-Projekte","pt":"Django REST Framework Master Rules é um conjunto de regras para a configuração de projetos Django","ru":"Django REST Framework Master Rules - это набор правил для настройки проектов Django для ИИ Агентов","ar":"Django REST Framework Master Rules هو مجموعة من القواعد لتهيئة مشاريع Django"},"features":{"en":["Enforces project scaffolding using custom architecture templates","Implements core architecture using enterprise-level Django REST Framework abstractions","Avoids standard DRF `APIVIEW` usage for improved scalability","Utilizes expert-level backend engineering best practices for Django projects","Provides guidelines for adding code to existing Django projects while maintaining enterprise-level architecture"],"zh":["企业级别的 API 架构模板","高级的项目骨架和核心架构","避免使用标准的 DRF API 视图","使用企业级别的抽象来构建项目"],"ja":["エンタープライズ レベルの API アーキテクチャ テンプレート","高度なプロジェクトのスケルトンとコア アーキテクチャ","標準の DRF API ビューを使用しない","エンタープライズ レベルの抽象を使用してプロジェクトを構築"],"ko":["기업 수준의 API 아키텍처 템플릿","고급 프로젝트 스케ルトン과 코어 아키텍처","표준 DRF API 뷰를 사용하지 않음","企業 수준의 추상화를 사용하여 프로젝트를 구축"],"es":["Arquitectura de proyecto escalable","Uso de abstracciones de empresa","Evitación de código vanilla DRF","Implementación de reglas maestras para proyectos Django","Uso de Django REST Framework para proyectos de backend","Creación de una arquitectura de backend robusta"],"fr":["Architecture de projet évolutif","Utilisation d''abstractions d''entreprise","Évitement de code vanilla DRF","Mise en œuvre de règles maîtres pour les projets Django","Utilisation de Django REST Framework pour les projets de backend","Création d''une architecture backend robuste"],"de":["Skalierbare Projekarchitektur","Verwendung von Unternehmensabstraktionen","Vermeidung von Vanilla-DRF-Code","Implementierung von Master-Regeln für Django-Projekte","Verwendung von Django REST Framework für Backend-Projekte","Erstellung einer robusten Backend-Architektur"],"pt":["Arquitetura de projeto escalável","Padrões de codificação avançados","Integração com Django REST Framework","Suporte a projetos enterprise","Melhores práticas de codificação"],"ru":["Масштабируемая архитектура проекта","Передовые шаблоны кодирования","Интеграция с Django REST Framework для ИИ Агентов","Поддержка проектов enterprise","Лучшие практики кодирования"],"ar":["بنية مشروع قابلة للتحجيم","نمط التشفير المتقدم","التكامل مع Django REST Framework للوكلاء الذكيين","دعم المشاريع التجارية","أفضل الممارسات لتشفير البرامج"]},"keywords":{"en":["how to use Django REST Framework Master Rules","Django REST Framework Master Rules setup guide","Django REST Framework Master Rules alternative","Django REST Framework Master Rules vs Django REST Framework","Django REST Framework Master Rules install","what is Django REST Framework Master Rules"],"zh":["Django REST Framework","企业级别 API","高级架构模板","项目骨架","核心架构","DRF API 视图"],"ja":["Django REST Framework","エンタープライズ レベルの API","高度なアーキテクチャ テンプレート","プロジェクトのスケルトン","コア アーキテクチャ","DRF API ビュー"],"ko":["Django REST Framework","기업 수준의 API","고급 아키텍처 템플릿","프로젝트 스케ルトン","코어 아키텍처","DRF API 뷰"],"es":["Django REST Framework","reglas maestras","arquitectura de backend","proyectos Django","abstracciones de empresa","desarrollo de backend","Django REST Framework tutorial","reglas maestras de Django","arquitectura de proyecto Django"],"fr":["Django REST Framework","règles maîtres","architecture backend","projets Django","abstractions d''entreprise","développement de backend","tutoriel Django REST Framework","règles maîtres de Django","architecture de projet Django"],"de":["Django REST Framework","Master-Regeln","Backend-Architektur","Django-Projekte","Unternehmensabstraktionen","Backend-Entwicklung","Django REST Framework Tutorial","Master-Regeln von Django","Projektarchitektur Django"],"pt":["Django REST Framework","arquitetura de projeto","padrões de codificação","projetos enterprise","melhores práticas de codificação","configuração de projetos Django","desenvolvimento de software","Python","Django"],"ru":["Django REST Framework","архитектура проекта","шаблоны кодирования","проекты enterprise","лучшие практики кодирования","настройка проектов Django","разработка программного обеспечения","Python","Django","ИИ Агенты"],"ar":["Django REST Framework","بنية المشروع","نمط التشفير","المشاريع التجارية","أفضل الممارسات لتشفير البرامج","تهيئة مشاريع Django","تطوير البرمجيات","Python","Django","الوكلاء الذكيين"]}},"owner":"sanakkiyan-s","repo":"django-food-delivery-backend","repoPath":"sanakkiyan-s/django-food-delivery-backend","stars":0,"forks":0,"updatedAt":"2026-03-03T12:52:19Z","topics":[],"category":"community","skillMd":{"name":"Django REST Framework Master Rules","description":"Advanced enterprise-level architecture rules for Django REST Framework (DRF) projects, including custom base classes, responses, security, and performance.","bodyPreview":"# Advanced Django REST Framework Master Rules\n# ---------------------------------------------------------\n# INSTRUCTIONS FOR AI ASSISTANT:\n# You are an Expert-Level Enterprise Backend Engineer.\n# When initiating a new Django project or adding code to an existing one, \n# you MUST abide by this architecture template. Do not write \"tutorial-level\" \n# vanilla DRF code. Build the project using these enterprise abstractions.\n\n## 1. Project Scaffolding & Core Architecture\n- NEVER use standard DRF `APIV","body":"# Advanced Django REST Framework Master Rules\n# ---------------------------------------------------------\n# INSTRUCTIONS FOR AI ASSISTANT:\n# You are an Expert-Level Enterprise Backend Engineer.\n# When initiating a new Django project or adding code to an existing one, \n# you MUST abide by this architecture template. Do not write \"tutorial-level\" \n# vanilla DRF code. Build the project using these enterprise abstractions.\n\n## 1. Project Scaffolding & Core Architecture\n- NEVER use standard DRF `APIView`, `ModelViewSet`, or `ModelSerializer` directly in feature apps.\n- ALL projects must start with a `common` or `core` app that houses Custom Base Classes.\n- Every feature app MUST inherit from your custom base classes.\n\n## 2. The Custom Base View Layer\nYou must immediately generate a module (e.g., `core/views/generic.py`) containing wrappers for DRF generic views:\n- `AppAPIView` (wraps `APIView` for custom endpoints)\n- `AppModelListAPIViewSet` (wraps `ListModelMixin, GenericViewSet` + Pagination + Filters)\n- `AppModelCUDAPIViewSet` (wraps `CreateModelMixin, UpdateModelMixin, DestroyModelMixin, GenericViewSet`)\n- `AppModelRetrieveAPIViewSet` (wraps `RetrieveModelMixin, GenericViewSet`)\n\n## 3. The Custom Base Serializer Layer\nYou must immediately generate a module (e.g., `core/serializers/base.py`) containing wrapped serializers:\n- `AppModelSerializer` (wraps `serializers.ModelSerializer`)\n- `AppReadOnlyModelSerializer` (Overrides `to_representation` or fields for GET performance)\n- `AppWriteOnlyModelSerializer` (Optimized for POST/PUT/PATCH validation)\n\n## 4. API Response Wrapping (The Mixin)\n- NEVER return a raw `Response({\"data\": ...})` from a view.\n- Create an `AppViewMixin` class that all `App*` views inherit from.\n- `AppViewMixin` must contain standardization functions:\n  - `def send_response(self, data, status=200, message=\"Success\"):`\n  - `def send_error_response(self, data, status=400, message=\"Error\"):`\n- ALL JSON responses from the server must follow exactly one unified structure mapped by these functions.\n\n## 5. Security & RBAC (Role-Based Access Control)\n- DO NOT rely solely on `IsAuthenticated` or `IsAdminUser`.\n- Create a `Feature` model (list of all API modules) and a `UserRole` model.\n- Create generic Permission Classes (e.g., `AllowAdminOnly`) that read the user''s Token, lookup their `UserRole`, and verify if they have Create/Retrieve/Update/Delete access to the View''s declared `feature = \"X\"` string.\n- Apply these custom Permission Classes globally or per-view.\n\n## 6. Audit Logging (System Trails)\n- Production apps must record WHO changed WHAT and WHEN.\n- Create an `AuditLog` database model and a `LoggingMixin`.\n- When manually overriding `create()`, `update()`, or `destroy()` in your `AppWriteOnlyModelSerializer`s, you MUST trigger the logger:\n  - e.g., `LoggingMixin.log_update(self, old_instance, new_instance)`\n- This ensures any hacker or rogue admin is permanently tracked.\n\n## 7. Bulk Operations (Performance)\n- When building APIs representing bulk data (e.g., uploading 100 products), DO NOT force the frontend to call the API 100 times.\n- Override `get_serializer()` in the view: inject `kwargs[\"many\"] = True` if the incoming payload is a JSON Array instead of an Object.\n- Build a custom `serializers.ListSerializer` to catch the array, validate items, and execute a high-speed Postgres `bulk_create` or `bulk_update` query.\n- NOTE: If Audit Logging or Django Signals are required for the models involved, manually loop and save objects inside the `ListSerializer` rather than using `bulk_create`. \n\n## 8. Dynamic File Upload APIs\n- File uploads require repetitive logic for file-size validation, format checking, and S3 uploading.\n- Create a Factory Function (e.g. `def get_upload_api_view(meta_model, max_size_mb=3):`) that dynamically generates and returns a complete File Upload API View class for whatever database Model is passed to it.\n\n## 9. Error Handling\n- Intercept 500 Server Errors gracefully using a Custom Exception Handler in `settings.py`.\n- Translate database errors (like `IntegrityError` or `UniqueViolation`) into user-friendly JSON messages that pass through the `send_error_response` wrapper.\n\n## 10. Database Query Optimization (The N+1 Problem)\n- NEVER allow N+1 queries in List Views.\n- When overriding `get_queryset()` in your `AppModelListAPIViewSet`, you MUST aggressively use `select_related()` for ForeignKeys and `prefetch_related()` for ManyToMany/Reverse relations.\n- If a Serializer contains a `SerializerMethodField` that hits the database, rewrite the view''s query to use Django''s `annotate()` instead, pushing the math down to Postgres.\n- Use `only()` and `defer()` if a table has massive text/JSON fields that are not needed in a list response (e.g., pulling a list of blog titles without pulling the HTML body).\n\n## 11. Caching Strategies\n- Implement Redis for caching.\n- Cache heavily-read, rarely-written endpoints (e.g., Homepage Banners, Base Product Categories) using Django''s `@method_decorator(cache_page(...))` or custom manual caching inside the view.\n- When an Admin updates a cached entity (e.g., via `AppModelCUDAPIViewSet.update`), you MUST automatically invalidate the associated Redis cache keys in the `update()` or `create()` method.\n- Store complex calculations (like a user''s total wallet balance or unread notification count) in the cache, and invalidate the cache when a transaction occurs.\n\n## 12. Asynchronous Processing (Celery)\n- NEVER put long-running tasks inside the main HTTP Request/Response cycle.\n- If an API triggers emails, SMS, push notifications, heavy Excel exports, or third-party payment verifications, immediately offload the task to a Celery worker using `.delay()`.\n- Return an instant HTTP 200/202 to the user, and let Celery handle the heavy lifting in the background.\n\n## 13. Soft Deletes (Never Lose Data)\n- In production, NEVER use Django''s default `Model.delete()` which permanently destroys data.\n- Create a `BaseModel` abstract class with: `is_deleted = BooleanField(default=False)`, `deleted_at = DateTimeField(null=True)`, `deleted_by = ForeignKey(User, null=True)`.\n- ALL project models must inherit from this `BaseModel`.\n- Override the default Django `Manager` with a custom `SoftDeleteManager` that automatically filters out `is_deleted=True` rows from every query (`get_queryset().filter(is_deleted=False)`).\n- When the `DestroyModelMixin` (inside `AppModelCUDAPIViewSet`) runs, override `perform_destroy()` to set `is_deleted=True` and `deleted_at=timezone.now()` instead of calling `.delete()`.\n- Create a separate Admin-only \"Trash\" endpoint to list and restore soft-deleted items if needed.\n\n## 14. API Documentation (Swagger / OpenAPI)\n- Install `drf-spectacular` and configure it in `settings.py` under `REST_FRAMEWORK.DEFAULT_SCHEMA_CLASS`.\n- Every ViewSet MUST have a docstring explaining its purpose.\n- Use `@extend_schema(tags=[\"Module Name\"])` on every action/method to group endpoints logically in the Swagger UI.\n- Use `@extend_schema(request=..., responses=...)` to explicitly document non-obvious request/response bodies.\n- Generate the Swagger UI at `/api/docs/` and the raw OpenAPI JSON at `/api/schema/` so the frontend team can auto-generate TypeScript types from it.\n\n## 15. Rate Limiting / Throttling\n- Configure DRF''s built-in throttle classes in `settings.py` under `REST_FRAMEWORK.DEFAULT_THROTTLE_CLASSES` and `DEFAULT_THROTTLE_RATES`.\n- Set sensible defaults: e.g., `\"anon\": \"20/minute\"` for unauthenticated users, `\"user\": \"100/minute\"` for authenticated users.\n- For sensitive endpoints (Login, OTP, Password Reset, Payment), apply stricter per-view throttles using `throttle_classes = [ScopedRateThrottle]` with custom scopes like `\"login\": \"5/minute\"`.\n- This prevents brute-force attacks, API abuse, and accidental DDoS from buggy frontend code.\n\n## 16. Database Transactions (Atomic Operations)\n- Any API endpoint that writes to MORE THAN ONE table in a single request MUST be wrapped inside `from django.db import transaction` → `with transaction.atomic():`.\n- This guarantees that if the second table write fails (e.g., creating an `OrderItem` after an `Order`), the first table write is automatically rolled back and the database stays clean.\n- NEVER leave multi-table writes unprotected. A server crash mid-write without `atomic()` will leave the database in a corrupted half-finished state.\n- For Celery tasks that involve multi-step database writes, use `transaction.on_commit()` to ensure the Celery task only fires AFTER the database transaction has fully committed.\n\n## 17. Real-Time Communication (WebSockets / Django Channels)\n- For features requiring instant updates (order notifications, live chat, dashboards), use Django Channels with WebSocket Consumers. NEVER use HTTP polling (setInterval).\n- Configure ASGI (`asgi.py`) with `ProtocolTypeRouter` to route HTTP traffic to Django and WebSocket traffic to Channels.\n- Create a `WebSocketAuthMiddleware` that reads the JWT token from the WebSocket handshake query string and authenticates the user before allowing the connection.\n- Use Channel Layer Groups (backed by Redis) for broadcasting messages to multiple connected clients (e.g., `group_send(\"kitchen_order_group\", {...})`).\n- Use `async_to_sync()` to send WebSocket messages from synchronous Django code (like serializers or helper functions).\n\n## 18. Testing Standards\n- Every new feature MUST ship with tests. No exceptions.\n- **Unit Tests (Serializers):** Test validation logic, custom `create()`, and `update()` methods in isolation using `APITestCase`. Verify that invalid data raises `ValidationError` and valid data saves correctly.\n- **Integration Tests (Views):** Use DRF''s `APIClient` to send actual HTTP requests (`client.post(...)`, `client.get(...)`) and assert status codes, response structure, and database state.\n- **Permission Tests:** For every endpoint, write at least one test proving that an unauthorized user (wrong role, no token) receives a `403 Forbidden`.\n- **Edge Case Tests:** Test empty payloads, duplicate entries, boundary values (e.g., `discount = 101%`), and concurrent requests where applicable.\n- Use `factory_boy` or `model_bakery` to generate test data instead of manually creating fixtures.\n\n## 19. Environment Configuration & Secrets\n- NEVER hardcode database passwords, API keys, secret keys, or third-party credentials anywhere in the codebase.\n- Use `django-environ` to load all sensitive values from a `.env` file: `env = environ.Env()` → `SECRET_KEY = env(\"SECRET_KEY\")`.\n- Maintain separate settings files for different environments: `settings/base.py` (shared), `settings/local.py` (development), `settings/production.py` (live server).\n- The `.env` file MUST be listed in `.gitignore`. Provide a `.env.example` with placeholder values so new developers know which keys are required.\n- For production deployments, inject secrets via environment variables from the hosting platform (Docker, AWS, etc.) instead of `.env` files.\n\n## 20. Idempotency (Payment & Order Safety)\n- For any endpoint that creates resources with side effects (Payments, Orders, Wallet Transactions), require an `Idempotency-Key` header from the frontend.\n- Before processing the request, check Redis/DB for that key. If the key already exists, return the cached response immediately without re-executing the logic.\n- After successfully processing the request, store the key + response in Redis with a TTL (e.g., 24 hours).\n- This prevents duplicate orders when the user''s internet drops mid-request and the frontend automatically retries.\n\n## 21. Optimistic Locking (Concurrency Control)\n- For models that can be edited by multiple admins simultaneously (Products, Orders, Inventory), add a `version = PositiveIntegerField(default=1)` field.\n- The frontend must send the current `version` number with every update request.\n- In the serializer''s `update()` method, compare the incoming `version` against the database version. If they don''t match, another user edited the record first — raise a `ValidationError(\"This record was modified by another user. Please refresh and try again.\")`.\n- On successful update, increment the `version` field by 1.\n\n## 22. API Versioning (Future-Proofing)\n- Configure URL-based versioning in `settings.py`: `DEFAULT_VERSIONING_CLASS = \"rest_framework.versioning.URLPathVersioning\"`.\n- Structure all API URLs as `/api/v1/...`. When breaking changes are needed, create `/api/v2/...` routes pointing to new ViewSets while keeping `v1` alive for older app versions.\n- NEVER remove or rename existing response fields in an active version. Only add new fields. If a field must be removed, do it in the next version.\n- Document which API version each mobile app release uses, so the backend team knows when it is safe to deprecate old versions.\n\n## 23. Database-Level Validation (Constraints)\n- Serializer validation runs in Python. It can be bypassed by Celery tasks, management commands, or Django shell. The database is the LAST line of defense.\n- Use `unique=True`, `unique_together`, and `UniqueConstraint` to prevent duplicate data at the database level.\n- Use `CheckConstraint` for business rules that must NEVER be violated: e.g., `models.CheckConstraint(check=Q(discount__gte=0) & Q(discount__lte=100), name=\"valid_discount_range\")`.\n- Use `models.PositiveIntegerField()` instead of `IntegerField()` for values that should never be negative (price, quantity, stock).\n- Always define `on_delete` behavior explicitly on ForeignKeys (`CASCADE`, `SET_NULL`, `PROTECT`) based on business logic.\n\n## 24. Celery Hardening (Background Job Reliability)\n- Every Celery task MUST have a `time_limit` and `soft_time_limit` to prevent zombie tasks from hanging forever.\n- Use automatic retries with exponential backoff for tasks that call external APIs: `@shared_task(bind=True, autoretry_for=(Exception,), retry_backoff=True, max_retries=3)`.\n- Log task failures with full context (task name, arguments, exception traceback) so they can be debugged from Grafana/Sentry.\n- Use `transaction.on_commit(lambda: my_task.delay(id))` to ensure Celery tasks only fire AFTER the database transaction commits. Without this, Celery may try to read a row that hasn''t been saved yet.\n\n## 25. Security Hardening\n- **JWT Tokens:** Implement short-lived access tokens (15-30 minutes) with long-lived refresh tokens. Maintain a blacklist of revoked refresh tokens in Redis.\n- **CORS:** Configure `django-cors-headers` with an explicit whitelist of allowed origins. NEVER use `CORS_ALLOW_ALL_ORIGINS = True` in production.\n- **File Uploads:** Validate file MIME types server-side (not just extensions). Reject executables, scripts, and suspicious file types. Enforce strict size limits.\n- **Raw SQL:** NEVER use raw SQL queries (`cursor.execute(...)`) unless absolutely necessary. Always use Django ORM to prevent SQL injection. If raw SQL is unavoidable, use parameterized queries exclusively.\n- **Sensitive Data:** Never return passwords, tokens, or internal IDs in API responses. Use `write_only=True` on serializer fields for sensitive inputs.\n\n## 26. Timezone & Localization\n- ALWAYS set `USE_TZ = True` in `settings.py`. This forces Django to store all `DateTimeField` values in UTC in the database.\n- NEVER use `datetime.now()`. ALWAYS use `django.utils.timezone.now()` which automatically returns timezone-aware UTC datetimes.\n- The frontend is responsible for converting UTC timestamps to the user''s local timezone for display. The backend must NEVER store local times.\n- For date-based filtering (e.g., \"orders placed today\"), convert the user''s local date boundaries to UTC before querying the database.\n\n## 27. Health Checks & Readiness Probes\n- Create lightweight endpoints for infrastructure monitoring (required for Docker, Kubernetes, and load balancers):\n  - `/health/live/` — Returns `200 OK` if the Django process is running (no DB check needed).\n  - `/health/ready/` — Returns `200 OK` only if the database, Redis, and Celery are all reachable. Returns `503` if any dependency is down.\n- These endpoints must be excluded from authentication, throttling, and audit logging.\n\n## 28. Large File Handling (Pre-Signed URLs)\n- For files larger than 5MB (videos, high-res images, CSV exports), DO NOT pass the file through Django.\n- Instead, generate a pre-signed S3 upload URL from the backend and return it to the frontend. The frontend uploads directly to S3, bypassing the Django server entirely.\n- After the upload completes, the frontend sends the S3 object key back to Django to save in the database.\n- This prevents Django from running out of memory and dramatically reduces server bandwidth costs.\n\n## 29. Observability (Structured Logging & Tracing)\n- Use structured JSON logging (not plain text) so logs can be parsed by Loki, ELK, or CloudWatch: `logger.info(\"order_created\", extra={\"user_id\": user.id, \"order_id\": order.id, \"amount\": total})`.\n- Add a custom middleware that generates a unique `trace_id` (UUID) for every incoming HTTP request and attaches it to all log entries during that request''s lifecycle. This allows you to trace every log line from a single user action.\n- Integrate error tracking (Sentry or similar) to automatically capture and alert on 500 errors in production.\n- Monitor slow queries using Django''s database logging: `settings.LOGGING` → log any query taking longer than 200ms.\n\n# ---------------------------------------------------------\n# ENFORCEMENT\n# When asked to scaffold a new feature, automatically generate the ViewSets and Serializers\n# by inheriting from these Base Classes, ensuring all routing is:\n# ✅ Tightly controlled (custom views, not raw DRF)\n# ✅ Fully audited (LoggingMixin on every mutation)\n# ✅ Strictly permissioned (RBAC + custom permission classes)\n# ✅ Aggressively optimized (select_related, prefetch_related, caching)\n# ✅ Fully tested (unit, integration, and permission tests)\n# ✅ Production-hardened (idempotency, transactions, retries, health checks)\n"},"lastSynced":"2026-03-08T02:18:39.852Z","agentAnalysis":{"suitability":{"en":"Perfect for Enterprise Backend Agents needing scalable and maintainable Django applications with advanced REST Framework capabilities.","zh":"非常适合需要可扩展和可维护的Django应用程序以及高级REST Framework功能的企业后端代理。","ja":"エンタープライズバックエンドエージェントがスケーラブルでメンテナンスの容易なDjangoアプリケーションと高度なREST Framework機能を必要とする場合に最適です。","ko":"확장 가능하고 유지 보수가 쉬운 Django 애플리케이션 및 고급 REST Framework 기능이 필요한 엔터프라이즈 백엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes de Backend Empresarial que necesitan aplicaciones Django escalables y mantenibles con capacidades avanzadas de REST Framework.","fr":"Parfait pour les agents de backend d''entreprise ayant besoin d''applications Django évolutives et maintenables avec des capacités avancées de REST Framework.","de":"Perfekt für Enterprise-Backend-Agents, die skalierbare und wartbare Django-Anwendungen mit erweiterten REST Framework-Funktionen benötigen.","pt":"Perfeito para agentes de backend de empresa que necessitam de aplicações Django escaláveis e mantidas com capacidades avançadas de React Framework.","ru":"Идеально для агентов企业-бэкенда, которым необходимы масштабируемые и поддерживаемые приложения Django с расширенными возможностями REST Framework.","ar":"مثالي لعميل الخلفية الشركاتي الذي يحتاج إلى تطبيقات Django قابلة للتوسيع وقابلة للصيانة مع إمكانيات إطار REST متقدمة."},"recommendation":{"en":"Empowers agents to build enterprise-level Django projects using expert-level backend engineering guidelines, providing scalable and maintainable applications with Django REST Framework Master Rules, enabling the use of advanced Django project scaffolding and core architecture techniques.","zh":"使代理能够使用专家级后端工程指南构建企业级Django项目，提供可扩展和可维护的应用程序，并使用Django REST Framework主规则，实现高级Django项目脚手架和核心架构技术的使用。","ja":"エージェントがエキスパートレベルのバックエンドエンジニアリングガイドラインを使用してエンタープライズレベルのDjangoプロジェクトを構築できるようにし、スケーラブルでメンテナンスの容易なアプリケーションを提供し、Django REST Frameworkマスタールールを使用して、高度なDjangoプロジェクトスキャフォールディングとコアアーキテクチャ技術を使用できるようにします。","ko":"에이전트가 전문가 수준의 백엔드 엔지니어링 지침을 사용하여 엔터프라이즈 수준의 Django 프로젝트를 구축할 수 있도록 하여 확장 가능하고 유지 보수가 쉬운 애플리케이션을 제공하고 Django REST Framework 마스터 규칙을 사용하여 고급 Django 프로젝트 스캐폴딩 및 핵심 아키텍처 기술을 사용할 수 있도록 합니다.","es":"Habilita a los agentes a construir proyectos de Django de nivel empresarial utilizando pautas de ingeniería de backend de nivel experto, proporcionando aplicaciones escalables y mantenibles con Reglas maestras de Django REST Framework, permitiendo el uso de técnicas de arquitectura y estructuración de proyectos Django avanzadas.","fr":"Permet aux agents de construire des projets Django de niveau entreprise en utilisant des lignes directrices d''ingénierie de backend de niveau expert, fournissant des applications évolutives et maintenables avec des règles maîtres de Django REST Framework, permettant l''utilisation de techniques d''architecture et de structuration de projets Django avancées.","de":"Ermächtigt Agenten, Unternehmensprojekte mit Django auf Basis von Backend-Engineering-Richtlinien auf Expertenniveau zu erstellen, indem sie skalierbare und wartbare Anwendungen mit Master-Regeln des Django-REST-Frameworks bereitstellen, und ermöglicht so die Verwendung von erweiterten Techniken für die Architektur und die Grundstruktur von Django-Projekten.","pt":"Habilita os agentes a construir projetos de nível empresarial Django usando diretrizes de engenharia de backend de nível expert, fornecendo aplicações escaláveis e mantidas com Regras Mestras do Django REST Framework, permitindo o uso de técnicas avançadas de estrutura de projeto Django e arquitetura central.","ru":"Наделяет агентов возможностью создавать проекты Django уровня предприятия, используя рекомендации по экспертному бэкенд-инжинирингу, обеспечивая масштабируемые и поддерживаемые приложения с помощью Мастер-правил Django REST Framework, позволяя использовать продвинутые техники создания проектов Django и основной архитектуры.","ar":"تمكين العميل من بناء مشاريع Django على مستوى الشركات باستخدام إرشادات هندسة الخلفية على مستوى الخبراء، وتوفير تطبيقات قابلة للتوسيع وقابلة للصيانة مع قواعد إطار REST الرئيسية، مما يسمح باستخدام تقنيات متقدمة للهيكل الأساسي للمشروع Django وعمارة النواة."},"useCases":{"en":["Building scalable Django applications","Implementing enterprise-level REST API design","Maintaining large-scale Django projects with advanced architecture templates"],"zh":["构建可扩展的Django应用程序","实施企业级REST API设计","使用高级架构模板维护大规模Django项目"],"ja":["スケーラブルなDjangoアプリケーションの構築","エンタープライズレベルのREST API設計の実装","高度なアーキテクチャテンプレートを使用した大規模なDjangoプロジェクトのメンテナンス"],"ko":["확장 가능한 Django 애플리케이션 구축","엔터프라이즈 수준의 REST API 설계 구현","고급 아키텍처 템플릿을 사용한 대규모 Django 프로젝트 유지 보수"],"es":["Construcción de aplicaciones Django escalables","Implementación de diseños de API REST de nivel empresarial","Mantenimiento de proyectos Django a gran escala con plantillas de arquitectura avanzadas"],"fr":["Construire des applications Django évolutives","Mettre en œuvre des conceptions d''API REST de niveau entreprise","Maintenir des projets Django à grande échelle avec des modèles d''architecture avancés"],"de":["Erstellung von skalierbaren Django-Anwendungen","Implementierung von Unternehmens-REST-API-Designs","Wartung von groß angelegten Django-Projekten mit erweiterten Architekturvorgaben"],"pt":["Construção de aplicações Django escaláveis","Implementação de design de API REST de nível empresarial","Manutenção de projetos Django em grande escala com modelos de arquitetura avançados"],"ru":["Создание масштабируемых приложений Django","Реализация дизайна REST API уровня предприятия","Обслуживание крупномасштабных проектов Django с продвинутыми шаблонами архитектуры"],"ar":["بناء تطبيقات Django قابلة للتوسيع","تنفيذ تصميم واجهة برمجة التطبيقات REST على مستوى الشركات","صيانة مشاريع Django على نطاق واسع مع قوالب بنية متقدمة"]},"limitations":{"en":["Requires Django and Django REST Framework expertise","Python 3.x compatibility required"],"zh":["需要Django和Django REST Framework的专业知识","需要Python 3.x的兼容性"],"ja":["DjangoおよびDjango REST Frameworkの専門知識が必要","Python 3.xの互換性が必要"],"ko":["Django 및 Django REST Framework의 전문 지식이 필요","Python 3.x의 호환성이 필요"],"es":["Requiere experiencia en Django y Django REST Framework","Se requiere compatibilidad con Python 3.x"],"fr":["Nécessite une expertise en Django et Django REST Framework","Compatibilité Python 3.x requise"],"de":["Benötigt Erfahrung mit Django und Django-REST-Framework","Python 3.x-Kompatibilität erforderlich"],"pt":["Requer expertise em Django e Django REST Framework","Compatibilidade com Python 3.x necessária"],"ru":["Требуется экспертиза в Django и Django REST Framework","Необходима совместимость с Python 3.x"],"ar":["يتطلبخبرة في Django وإطار REST الخاص به","مطلوبة توافقية مع Python 3.x"]},"version":4},"contentHash":"04251c85b7ea14a793ff735e509142edb626205c0806971cfb68ac2de4b77504","qualityScore":50}');
