INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sanakkiyan-s/django-food-delivery-backend/Django REST Framework Master Rules', 'Django REST Framework Master Rules', 'sanakkiyan-s', 'django-food-delivery-backend', 'community', 'Django REST Framework Master Rules sanakkiyan-s django-food-delivery-backend community Django REST Framework Master Rules provides a set of guidelines for building enterprise-level Django projects, enabling expert-level backend engineers to create scalable and maintainable applications. Django REST Framework Master 规则提供了高级的架构模板和最佳实践，用于构建企业级别的 API。 Django REST Framework マスター ルールは、エンタープライズ レベルの API を構築するための高度なアーキテクチャ テンプレートとベスト プラクティスを提供します。 Django REST Framework 마스터 규칙은 기업 수준의 API를 구축하기 위한 고급 아키텍처 템플릿과 최적화된 개발 방법을 제공합니다. Las reglas maestras de Django REST Framework proporcionan una arquitectura de backend empresarial robusta para proyectos Django Les règles maîtres de Django REST Framework offrent une architecture backend d''entreprise robuste pour les projets Django Die Master-Regeln von Django REST Framework bieten eine robuste Unternehmens-Backend-Architektur für Django-Projekte O Django REST Framework Master Rules é um conjunto de regras avançadas para a configuração de projetos Django. Ele fornece uma arquitetura de projeto escalável e padrões de codificação. Django REST Framework Master Rules - это набор передовых правил для настройки проектов Django. Он обеспечивает масштабируемую архитектуру проекта и шаблоны кодирования для ИИ Агентов Django REST Framework Master Rules هو مجموعة من القواعد المتقدمة لتهيئة مشاريع Django. يوفر بنية مشروع قابلة للتحجيم ونمط التشفير للوكلاء الذكيين how to use Django REST Framework Master Rules Django REST Framework Master Rules setup guide Django REST Framework Master Rules alternative Django REST Framework Master Rules vs Django REST Framework Django REST Framework Master Rules install what is Django REST Framework Master Rules Django REST Framework 企业级别 API 高级架构模板 项目骨架 核心架构 DRF API 视图 Enforces project scaffolding using custom architecture templates Implements core architecture using enterprise-level Django REST Framework abstractions Avoids standard DRF `APIVIEW` usage for improved scalability Utilizes expert-level backend engineering best practices for Django projects Provides guidelines for adding code to existing Django projects while maintaining enterprise-level architecture Django REST Framework Master Rules is a set of architecture templates and guidelines for building Django projects using enterprise abstractions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kunish/wheel/openspec-continue-change', 'community', 'kunish', 'wheel', 'kunish/wheel', 'openspec-continue-change', 0, 0, 50, '2026-03-07T12:46:33.423Z', '2026-03-07T12:54:01.973Z', '0e210eee9ea4a305d24490c6fa5c07956279840822751ccf1dd3b9b2f6d2f1da', '{"id":"kunish/wheel/openspec-continue-change","name":"openspec-continue-change","description":{"en":"The openspec-continue-change skill allows developers to continue working on a change by creating the next artifact, streamlining their workflow. It benefits developers working with Wheel and LLM API Gateway.","zh":"openspec-continue-change是用于继续工作的变更，通过创建下一个工件来实现高效的变更管理","ja":"openspec-continue-changeは、変更を続行するために次のアーティファクトを作成することで、効率的な変更管理を実現します","ko":"openspec-continue-change는 다음 아티팩트를 생성하여 변경을 계속 작업할 수 있는 기능으로, 효율적인 변경 관리를 제공합니다","es":"openspec-continue-change es una herramienta que permite a los desarrolladores continuar trabajando en un cambio creando el próximo artifacto","fr":"openspec-continue-change est un outil qui permet aux développeurs de continuer à travailler sur un changement en créant le prochain artifact","de":"openspec-continue-change ist ein Tool, das es Entwicklern ermöglicht, an einem Änderungsprozess weiterzuarbeiten, indem sie das nächste Artifact erstellen","pt":"O openspec-continue-change é uma ferramenta para continuar trabalhando em uma mudança, criando o próximo artifact com base no contexto da conversa.","ru":"openspec-continue-change — это инструмент для продолжения работы над изменением, создавая следующий артефакт на основе контекста разговора.","ar":"openspec-continue-change أداة للاستكمال التغييرات من خلال إنشاء الملفات القادمة بناءً على سياق المحادثة"},"seo":{"title":{"en":"openspec-continue-change: Setup Guide for AI Agents | AI ...","zh":"openspec-continue-change setup guide","ja":"openspec-continue-change のベストプラクティス - AIエージェント","ko":"openspec-continue-change 설정 가이드 - AI 도구","es":"Guía de configuración de openspec-continue-change para de...","fr":"Mise en route de openspec-continue-change pour les dévelo...","de":"Einrichtungsleitfaden für openspec-continue-change für En...","pt":"Guia de Configuração do openspec-continue-change para Des...","ru":"Настройка openspec-continue-change: Руководство для Разра...","ar":"دليل إعداد openspec-continue-change للاستكمال التغييرات"},"description":{"en":"Discover how openspec-continue-change simplifies workflow by aggregating and balancing changes. Learn how to implement this skill and boost your development ...","zh":"了解openspec-continue-change的技术细节，包括输入、步骤和工具，实现高效的变更管理","ja":"openspec-continue-changeの詳細をみてみよう - 変更の管理を効率化するためのステップとツール","ko":"openspec-continue-change의 기능과 기술을 살펴보세요 - 변경 관리를 효율적으로 수행하는 방법","es":"Aprende a continuar cambios con openspec-continue-change, una herramienta de Agente de Inteligencia Artificial para desarrolladores","fr":"Découvrez comment continuer des changements avec openspec-continue-change, un outil d''Agent d''Intelligence Artificielle pour développeurs","de":"Erfahren Sie, wie Sie Änderungen mit openspec-continue-change fortsetzen, einem Tool für künstliche Intelligenz-Agenten für Entwickler","pt":"Aprenda a usar o openspec-continue-change para criar o próximo artifact de uma mudança, com ou sem nome de mudança especificado.","ru":"Узнайте, как использовать openspec-continue-change для продолжения работы над изменением, создавая следующий артефакт.","ar":"تعرف على كيفية استخدام openspec-continue-change لاستكمال التغييرات من خلال إنشاء الملفات القادمة"},"definition":{"en":"openspec-continue-change is a skill that enables developers to continue working on a change by creating the next artifact, utilizing commands like openspec list --json.","zh":"openspec-continue-change是一种用于继续工作的变更的技术，通过命令行工具和API网关来实现","ja":"openspec-continue-changeは、変更を続行するための技術であり、コマンドラインツールとAPIゲートウェイを使用します","ko":"openspec-continue-change는 변경을 계속 작업하기 위한 기술로, 명령줄 도구와 API 게이트웨이를 사용합니다","es":"openspec-continue-change es una función de Agente de Inteligencia Artificial que continúa un cambio","fr":"openspec-continue-change est une fonction d''Agent d''Intelligence Artificielle qui continue un changement","de":"openspec-continue-change ist eine Funktion von künstlicher Intelligenz-Agenten, die einen Änderungsprozess fortsetzt","pt":"O que é openspec-continue-change? É uma ferramenta para continuar mudanças, criando artifacts subsequentes.","ru":"Что такое openspec-continue-change? Это инструмент для продолжения изменений, создавая следующие артефакты.","ar":"ما هو openspec-continue-change؟ أداة لاستكمال التغييرات من خلال إنشاء الملفات القادمة"},"features":{"en":["Runs openspec list --json to get available changes sorted by most recently modified","Utilizes the AskUserQuestion tool to let users select which change to work on","Presents the top 3-5 available changes for user selection","Optionally accepts a change name as input","Infers the change name from conversation context if omitted","Prompts for selection if the change name is vague or ambiguous"],"zh":["支持通过命令行工具openspec list进行变更管理","可以使用AskUserQuestion工具让用户选择要工作的变更","支持通过API网关Aggregate、Balance、Observe","可以根据最近修改时间对变更进行排序","支持用户选择要工作的变更"],"ja":["openspec listコマンドラインツールを使用した変更管理","AskUserQuestionツールを使用してユーザーに変更の選択を促す","APIゲートウェイを使用したAggregate、Balance、Observe","最近の変更時間に基づいて変更を並べ替える","ユーザーが変更を選択できる"],"ko":["openspec list 명령줄 도구를 사용한 변경 관리","AskUserQuestion 도구를 사용하여 사용자가 변경을 선택하도록 함","API 게이트웨이를 사용한 Aggregate, Balance, Observe","最近 수정한 시간에 따라 변경을 정렬","사용자가 변경을 선택할 수 있음"],"es":["Permite continuar trabajando en un cambio sin especificar el nombre del cambio","Utiliza la herramienta AskUserQuestion para seleccionar el cambio a trabajar","Ejecuta el comando ''openspec list --json'' para obtener los cambios disponibles","Presenta los 3 cambios más recientes","Integra con la API Gateway de LLM","Soporta la creación de artefactos"],"fr":["Permet de continuer à travailler sur un changement sans spécifier le nom du changement","Utilise l''outil AskUserQuestion pour sélectionner le changement à travailler","Exécute la commande ''openspec list --json'' pour obtenir les changements disponibles","Présente les 3 changements les plus récents","Intègre avec la passerelle API de LLM","Prend en charge la création d''artefacts"],"de":["Ermöglicht es, an einem Änderungsprozess weiterzuarbeiten, ohne den Namen des Änderungsprozesses anzugeben","Verwendet das Tool AskUserQuestion, um den Änderungsprozess auszuwählen","Führt den Befehl ''openspec list --json'' aus, um die verfügbaren Änderungen zu erhalten","Präsentiert die 3 zuletzt geänderten Änderungen","Integriert mit der LLM-API-Gateway","Unterstützt die Erstellung von Artefakten"],"pt":["Criação de artifacts subsequentes","Suporte a seleção de mudanças via CLI","Integração com o AskUserQuestion tool","Compatibilidade com openspec list --json","Suporte a inferência de contexto de conversa"],"ru":["Создание следующих артефактов","Поддержка выбора изменений через CLI","Интеграция с инструментом AskUserQuestion","Совместимость с openspec list --json","Поддержка вывода контекста разговора"],"ar":["إنشاء الملفات القادمة","دعم اختيار التغييرات عبر واجهة سطر الأوامر","التكامل مع أداة AskUserQuestion","التوافق مع openspec list --json","دعم استنتاج سياق المحادثة"]},"keywords":{"en":["how to use openspec-continue-change","openspec-continue-change setup guide","openspec-continue-change vs Wheel","openspec-continue-change install","what is openspec-continue-change","openspec-continue-change alternative","LLM API Gateway integration","openspec-continue-change tutorial","openspec-continue-change documentation"],"zh":["openspec-continue-change","AI工具","变更管理","命令行工具","API网关","Aggregate","Balance","Observe","AskUserQuestion"],"ja":["openspec-continue-change","AIエージェント","変更管理","コマンドラインツール","APIゲートウェイ","Aggregate","Balance","Observe","AskUserQuestion"],"ko":["openspec-continue-change","AI 도구","변경 관리","명령줄 도구","API 게이트웨이","Aggregate","Balance","Observe","AskUserQuestion"],"es":["openspec-continue-change","Agente de Inteligencia Artificial","desarrollo de software","API Gateway de LLM","AskUserQuestion","artefactos","cambio de código","desarrollo de aplicaciones","herramientas de desarrollo"],"fr":["openspec-continue-change","Agent d''Intelligence Artificielle","développement de logiciels","passerelle API de LLM","AskUserQuestion","artefacts","changement de code","développement d''applications","outils de développement"],"de":["openspec-continue-change","künstliche Intelligenz-Agenten","Software-Entwicklung","LLM-API-Gateway","AskUserQuestion","Artefakte","Code-Änderung","Anwendungs-Entwicklung","Entwickler-Tools"],"pt":["openspec-continue-change","ferramentas de desenvolvimento","CLI","AskUserQuestion","openspec list --json","desenvolvimento de software","ferramentas de linha de comando","integração de ferramentas","desenvolvedores de software"],"ru":["openspec-continue-change","инструменты разработки","CLI","AskUserQuestion","openspec list --json","разработка программного обеспечения","инструменты командной строки","интеграция инструментов","разработчики программного обеспечения","ИИ Агенты"],"ar":["openspec-continue-change","أدوات التطوير","واجهة سطر الأوامر","AskUserQuestion","openspec list --json","تطوير البرمجيات","أدوات سطر الأوامر","تكامل الأدوات","مطورو البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"kunish","repo":"wheel","repoPath":"kunish/wheel","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.423Z","topics":[],"category":"community","skillMd":{"name":"openspec-continue-change","description":"Continue working on an OpenSpec change by creating the next artifact. Use when the user wants to progress their change, create the next artifact, or continue their workflow.","version":"1.0","bodyPreview":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-","body":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-4 most recently modified changes as options, showing:\n   - Change name\n   - Schema (from `schema` field if present, otherwise \"spec-driven\")\n   - Status (e.g., \"0/5 tasks\", \"complete\", \"no tasks\")\n   - How recently it was modified (from `lastModified` field)\n\n   Mark the most recently modified change as \"(Recommended)\" since it''s likely what the user wants to continue.\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check current status**\n\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n\n   Parse the JSON to understand current state. The response includes:\n   - `schemaName`: The workflow schema being used (e.g., \"spec-driven\")\n   - `artifacts`: Array of artifacts with their status (\"done\", \"ready\", \"blocked\")\n   - `isComplete`: Boolean indicating if all artifacts are complete\n\n3. **Act based on status**:\n\n   ***\n\n   **If all artifacts are complete (`isComplete: true`)**:\n   - Congratulate the user\n   - Show final status including the schema used\n   - Suggest: \"All artifacts created! You can now implement this change or archive it.\"\n   - STOP\n\n   ***\n\n   **If artifacts are ready to create** (status shows artifacts with `status: \"ready\"`):\n   - Pick the FIRST artifact with `status: \"ready\"` from the status output\n   - Get its instructions:\n     ```bash\n     openspec instructions <artifact-id> --change \"<name>\" --json\n     ```\n   - Parse the JSON. The key fields are:\n     - `context`: Project background (constraints for you - do NOT include in output)\n     - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n     - `template`: The structure to use for your output file\n     - `instruction`: Schema-specific guidance\n     - `outputPath`: Where to write the artifact\n     - `dependencies`: Completed artifacts to read for context\n   - **Create the artifact file**:\n     - Read any completed dependency files for context\n     - Use `template` as the structure - fill in its sections\n     - Apply `context` and `rules` as constraints when writing - but do NOT copy them into the file\n     - Write to the output path specified in instructions\n   - Show what was created and what''s now unlocked\n   - STOP after creating ONE artifact\n\n   ***\n\n   **If no artifacts are ready (all blocked)**:\n   - This shouldn''t happen with a valid schema\n   - Show status and suggest checking for issues\n\n4. **After creating an artifact, show progress**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter each invocation, show:\n\n- Which artifact was created\n- Schema workflow being used\n- Current progress (N/M complete)\n- What artifacts are now unlocked\n- Prompt: \"Want to continue? Just ask me to continue or tell me what to do next.\"\n\n**Artifact Creation Guidelines**\n\nThe artifact types and their purpose depend on the schema. Use the `instruction` field from the instructions output to understand what to create.\n\nCommon artifact patterns:\n\n**spec-driven schema** (proposal → specs → design → tasks):\n\n- **proposal.md**: Ask user about the change if not clear. Fill in Why, What Changes, Capabilities, Impact.\n  - The Capabilities section is critical - each capability listed will need a spec file.\n- **specs/<capability>/spec.md**: Create one spec per capability listed in the proposal''s Capabilities section (use the capability name, not the change name).\n- **design.md**: Document technical decisions, architecture, and implementation approach.\n- **tasks.md**: Break down implementation into checkboxed tasks.\n\nFor other schemas, follow the `instruction` field from the CLI output.\n\n**Guardrails**\n\n- Create ONE artifact per invocation\n- Always read dependency artifacts before creating a new one\n- Never skip artifacts or create out of order\n- If context is unclear, ask the user before creating\n- Verify the artifact file exists after writing before marking progress\n- Use the schema''s artifact sequence, don''t assume specific artifact names\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n"},"lastSynced":"2026-03-07T12:54:01.973Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined workflow automation with Wheel and LLM API Gateway","zh":"适用于需要使用 Wheel 和 LLM API Gateway 实现工作流自动化的开发代理","ja":"Wheel と LLM API Gateway を使用したワークフローの自動化を必要とする開発エージェントに最適","ko":"Wheel 및 LLM API Gateway를 사용하여 워크플로 자동화를 필요로 하는 개발 에이전트에 적합","es":"Ideal para Agentes de Desarrollo que requieren una automatización de flujo de trabajo optimizada con Wheel y LLM API Gateway","fr":"Idéal pour les agents de développement nécessitant une automatisation du flux de travail simplifiée avec Wheel et LLM API Gateway","de":"Ideal für Entwicklungssagenten, die eine optimierte Workflow-Automatisierung mit Wheel und LLM API Gateway benötigen","pt":"Ideal para Agentes de Desenvolvimento que exigem automação de fluxo de trabalho otimizada com Wheel e LLM API Gateway","ru":"Идеально для агентов разработки, требующих автоматизации рабочего процесса с помощью Wheel и LLM API Gateway","ar":"مثالي للوكلاء التطوير الذين يتطلبون تيار عمل آلي مع Wheel و LLM API Gateway"},"recommendation":{"en":"Empowers agents to continue working on a change by creating the next artifact, utilizing the openspec list command and AskUserQuestion tool for seamless workflow integration, and supporting JSON output for efficient data exchange","zh":"赋予代理继续处理更改的能力，通过创建下一个工件，利用 openspec 列表命令和 AskUserQuestion 工具实现无缝的工作流集成，并支持 JSON 输出以实现高效的数据交换","ja":"エージェントが変更を続ける能力を付与し、次のアーティファクトを作成し、openspec リスト コマンドと AskUserQuestion ツールを使用してシームレスなワークフロー統合を実現し、効率的なデータ交換のために JSON 出力をサポート","ko":"에이전트가 변경을 계속 할 수 있는 능력을 부여하고 다음 아티팩트를 생성하며 openspec 목록 명령과 AskUserQuestion 도구를 사용하여 무缝한 워크플로 통합을实现하며 효율적인 데이터 교환을 위한 JSON 출력을 지원","es":"Permite a los agentes continuar trabajando en un cambio creando el siguiente artifacto, utilizando el comando openspec list y la herramienta AskUserQuestion para una integración de flujo de trabajo sin problemas, y admitiendo salida JSON para un intercambio de datos eficiente","fr":"Permet aux agents de continuer à travailler sur un changement en créant le prochain artifact, en utilisant la commande openspec list et l''outil AskUserQuestion pour une intégration de flux de travail sans problème, et en prenant en charge la sortie JSON pour un échange de données efficace","de":"Ermöglicht es den Agenten, an einem Change weiterzuarbeiten, indem sie das nächste Artifact erstellen, den openspec-Befehl und das Tool AskUserQuestion für eine nahtlose Workflow-Integration verwenden und JSON-Ausgabe für einen effizienten Datenaustausch unterstützen","pt":"Habilita os agentes a continuar trabalhando em uma alteração, criando o próximo artefato, utilizando o comando openspec list e a ferramenta AskUserQuestion para integração de fluxo de trabalho sem interrupções, e suportando saída JSON para troca de dados eficiente","ru":"Наделяет агентов возможностью продолжать работу над изменением, создавая следующий артефакт, используя команду openspec list и инструмент AskUserQuestion для бесшовной интеграции рабочего процесса, и поддерживая вывод JSON для эффективного обмена данными","ar":"يمنح الوكلاء القدرة على الاستمرار في العمل على تغيير عن طريق إنشاء الملف القادم، باستخدام أمر openspec list وأداة AskUserQuestion من أجل دمج سير العمل دون انقطاع، ودعم الإخراج JSON من أجل تبادل البيانات بكفاءة"},"useCases":{"en":["Automating change management workflows","Generating next artifacts in a development pipeline","Streamlining developer workflow with Wheel and LLM API Gateway"],"zh":["自动化更改管理工作流","在开发管道中生成下一个工件","使用 Wheel 和 LLM API Gateway 流线化开发者工作流"],"ja":["変更管理ワークフローの自動化","開発パイプラインでの次のアーティファクトの生成","Wheel と LLM API Gateway を使用した開発者ワークフローのストリーミング"],"ko":["변경 관리 워크플로 자동화","개발 파이프라인에서 다음 아티팩트 생성","Wheel 및 LLM API Gateway를 사용하여 개발자 워크플로 스트리밍"],"es":["Automatización de flujos de trabajo de gestión de cambios","Generación de los siguientes artifactos en una canalización de desarrollo","Optimización del flujo de trabajo del desarrollador con Wheel y LLM API Gateway"],"fr":["Automatisation des flux de travail de gestion des changements","Génération des prochains artifactes dans une canalisation de développement","Optimisation du flux de travail du développeur avec Wheel et LLM API Gateway"],"de":["Automatisierung von Änderungsmanagement-Workflows","Erstellung der nächsten Artefakte in einer Entwicklungspipeline","Optimierung des Entwickler-Workflows mit Wheel und LLM API Gateway"],"pt":["Automatizar fluxos de trabalho de gerenciamento de alterações","Gerar os próximos artefatos em um pipeline de desenvolvimento","Otimizar o fluxo de trabalho do desenvolvedor com Wheel e LLM API Gateway"],"ru":["Автоматизация рабочих процессов управления изменениями","Генерация следующих артефактов в конвейере разработки","Оптимизация рабочего процесса разработчика с помощью Wheel и LLM API Gateway"],"ar":["تأتميم تدفقات العمل لإدارة التغييرات","توليد الملفات التالية في трубة التطوير","تحسين تدفق عمل المطور مع Wheel و LLM API Gateway"]},"limitations":{"en":["Requires Wheel and LLM API Gateway setup","Needs conversation context or user input for change name inference","Limited to openspec-compatible changes"],"zh":["需要 Wheel 和 LLM API Gateway 设置","需要对话上下文或用户输入以推断更改名称","仅限 openspec 兼容的更改"],"ja":["Wheel と LLM API Gateway の設定が必要","変更名の推論に会話のコンテキストまたはユーザー入力が必要","openspec 互換の変更のみ"],"ko":["Wheel 및 LLM API Gateway 설정 필요","변경 이름 추론에 대화 컨텍스트 또는 사용자 입력 필요","openspec 호환 변경만"],"es":["Requiere configuración de Wheel y LLM API Gateway","Necesita contexto de conversación o entrada de usuario para inferencia de nombre de cambio","Limitado a cambios compatibles con openspec"],"fr":["Nécessite une configuration de Wheel et LLM API Gateway","A besoin d''un contexte de conversation ou d''une entrée utilisateur pour l''inférence du nom de changement","Limité aux changements compatibles avec openspec"],"de":["Benötigt Wheel- und LLM-API-Gateway-Konfiguration","Benötigt Konversationskontext oder Benutzereingabe für die Ableitung des Änderungsnamens","Begrenzt auf openspec-kompatible Änderungen"],"pt":["Exige configuração do Wheel e LLM API Gateway","Necessita de contexto de conversa ou entrada do usuário para inferência do nome da alteração","Limitado a alterações compatíveis com openspec"],"ru":["Требует настройки Wheel и LLM API Gateway","Требует контекста разговора или ввода пользователя для вывода имени изменения","Ограничен изменением, совместимым с openspec"],"ar":["يتطلب إعداد Wheel و LLM API Gateway","يحتاج إلى سياق المحادثة أو إدخال المستخدم لاستنتاج اسم التغيير","محدود بالتغييرات المتوافقة مع openspec"]},"version":4},"contentHash":"0e210eee9ea4a305d24490c6fa5c07956279840822751ccf1dd3b9b2f6d2f1da","qualityScore":50}');
