INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kunish/wheel/openspec-continue-change', 'openspec-continue-change', 'kunish', 'wheel', 'community', 'openspec-continue-change kunish wheel community The openspec-continue-change skill allows developers to continue working on a change by creating the next artifact, streamlining their workflow. It benefits developers working with Wheel and LLM API Gateway. openspec-continue-change是用于继续工作的变更，通过创建下一个工件来实现高效的变更管理 openspec-continue-changeは、変更を続行するために次のアーティファクトを作成することで、効率的な変更管理を実現します openspec-continue-change는 다음 아티팩트를 생성하여 변경을 계속 작업할 수 있는 기능으로, 효율적인 변경 관리를 제공합니다 openspec-continue-change es una herramienta que permite a los desarrolladores continuar trabajando en un cambio creando el próximo artifacto openspec-continue-change est un outil qui permet aux développeurs de continuer à travailler sur un changement en créant le prochain artifact openspec-continue-change ist ein Tool, das es Entwicklern ermöglicht, an einem Änderungsprozess weiterzuarbeiten, indem sie das nächste Artifact erstellen O openspec-continue-change é uma ferramenta para continuar trabalhando em uma mudança, criando o próximo artifact com base no contexto da conversa. openspec-continue-change — это инструмент для продолжения работы над изменением, создавая следующий артефакт на основе контекста разговора. openspec-continue-change أداة للاستكمال التغييرات من خلال إنشاء الملفات القادمة بناءً على سياق المحادثة how to use openspec-continue-change openspec-continue-change setup guide openspec-continue-change vs Wheel openspec-continue-change install what is openspec-continue-change openspec-continue-change alternative LLM API Gateway integration openspec-continue-change tutorial openspec-continue-change documentation openspec-continue-change AI工具 变更管理 命令行工具 API网关 Aggregate Balance Observe AskUserQuestion Runs openspec list --json to get available changes sorted by most recently modified Utilizes the AskUserQuestion tool to let users select which change to work on Presents the top 3-5 available changes for user selection Optionally accepts a change name as input Infers the change name from conversation context if omitted Prompts for selection if the change name is vague or ambiguous openspec-continue-change is a skill that enables developers to continue working on a change by creating the next artifact, utilizing commands like openspec list --json.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('g1331/AutoRouter/openspec-continue-change', 'community', 'g1331', 'AutoRouter', 'g1331/AutoRouter', 'openspec-continue-change', 0, 0, 50, '2026-03-07T12:46:33.423Z', '2026-03-07T12:54:15.678Z', '383848c3fa732a8545b4e5aeb3bd8e83179410c48e47abd1db4afd8b7ddfb6cd', '{"id":"g1331/AutoRouter/openspec-continue-change","name":"openspec-continue-change","description":{"en":"The openspec-continue-change skill automates change management for AI agents by creating the next artifact in a change. It benefits developers by simplifying their workflow.","zh":"openspec-continue-change是一个极简的多上游AI API代理，用于继续工作中的变更","ja":"openspec-continue-changeは、開発プロセスを最適化するために、 次のアーティファクトを作成することで変更を継続する","ko":"openspec-continue-change는 다음 아티팩트를 생성하여 변경을 계속하는 개발 프로세스 최적화 도구입니다","es":"openspec-continue-change es una herramienta minimalista para crear el próximo artefacto en un cambio, utilizando la CLI para ejecutar comandos como ''openspec list --json''","fr":"openspec-continue-change est un outil minimaliste pour créer le prochain artefact dans un changement, en utilisant la CLI pour exécuter des commandes comme ''openspec list --json''","de":"openspec-continue-change ist ein minimalistisches Tool, um das nächste Artefakt in einer Änderung zu erstellen, indem es die CLI verwendet, um Befehle wie ''openspec list --json'' auszuführen","pt":"O openspec-continue-change é um proxy de API de IA minimalista que permite criar o próximo artifact de uma alteração. Ele lista as alterações disponíveis e permite ao usuário selecionar qual alteração trabalhar","ru":"openspec-continue-change - это минималистичный прокси API ИИ, который позволяет создать следующий артефакт изменений. Он выводит список доступных изменений и позволяет пользователю выбрать, над какой изменением работать, ИИ Агенты","ar":"openspec-continue-change هو وكيل API من الذكاء الاصطناعي البسيط الذي يسمح بإنشاء الملف التالي من التغييرات. يقوم بlisting التغييرات المتاحة ويمكّن المستخدم من اختيار التغيير الذي يعمل عليه، أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"openspec-continue-change: Automated Change Management for...","zh":"openspec-continue-change 工作流指南","ja":"openspec-continue-change AIエージェントの設定方法","ko":"openspec-continue-change 개발자 가이드","es":"Guía de configuración de openspec-continue-change para de...","fr":"Guide de démarrage rapide pour openspec-continue-change","de":"Einrichtungsanleitung für openspec-continue-change: Erwei...","pt":"Guia de Configuração do openspec-continue-change para Des...","ru":"Руководство по настройке openspec-continue-change для раз...","ar":"دليل إعداد openspec-continue-change للdevelopers، أدوات ا..."},"description":{"en":"Discover how openspec-continue-change streamlines your workflow by automating change management. Learn how to set it up and explore its features today!","zh":"了解openspec-continue-change的功能和用途，实现高效的工作流管理","ja":"openspec-continue-change AIエージェントを使用して開発プロセスを最適化する","ko":"openspec-continue-change를 사용하여 개발 프로세스를 자동화하고 효율화하십시오","es":"Aprende a utilizar openspec-continue-change para crear el próximo artefacto en un cambio. Descubre cómo integrar esta herramienta de Agente de Inteligencia A...","fr":"Découvrez comment utiliser openspec-continue-change pour créer le prochain artefact dans un changement. Intégrez cet outil d''Agent d''Intelligence Artificiell...","de":"Erfahren Sie, wie Sie openspec-continue-change verwenden, um das nächste Artefakt in einer Änderung zu erstellen. Integrieren Sie dieses IИ-Agents-Tool in Ih...","pt":"Aprenda a usar o openspec-continue-change para criar o próximo artifact de uma alteração, incluindo a lista de alterações disponíveis e a seleção do usuário","ru":"Узнайте, как использовать openspec-continue-change для создания следующего артефакта изменений, включая список доступных изменений и выбор пользователя, ИИ А...","ar":"تعلم كيفية استخدام openspec-continue-change لإنشاء الملف التالي من التغييرات، بما في ذلك قائمة التغييرات المتاحة واختيار المستخدم، أدوات الذكاء الاصطناعي"},"definition":{"en":"openspec-continue-change is a minimalistic AI API proxy that continues working on a change by creating the next artifact, using commands like openspec list --json.","zh":"openspec-continue-change是一个用于继续工作中的变更的AI API代理","ja":"openspec-continue-changeは、開発プロセスを最適化するためのAIエージェントの一種です","ko":"openspec-continue-change는 개발 프로세스를 최적화하기 위한 AI 도구입니다","es":"openspec-continue-change es un Agente de Inteligencia Artificial que permite a los desarrolladores crear el próximo artefacto en un cambio","fr":"openspec-continue-change est un Agent d''Intelligence Artificielle qui permet aux développeurs de créer le prochain artefact dans un changement","de":"openspec-continue-change ist ein IИ-Agents, der es Entwicklern ermöglicht, das nächste Artefakt in einer Änderung zu erstellen","pt":"O openspec-continue-change é um proxy de API de IA que permite continuar trabalhando em uma alteração criando o próximo artifact","ru":"openspec-continue-change - это прокси API ИИ, который позволяет продолжить работу над изменением, создавая следующий артефакт, ИИ Агенты","ar":"openspec-continue-change هو وكيل API من الذكاء الاصطناعي الذي يسمح بمواصلة العمل على التغيير من خلال إنشاء الملف التالي، أدوات الذكاء الاصطناعي"},"features":{"en":["Runs openspec list --json to retrieve available changes sorted by most recently modified","Utilizes the AskUserQuestion tool to prompt users for change selection","Presents the top 3-5 changes for user selection","Optionally accepts a change name as input","Infers the change name from conversation context if not provided","Supports vague or ambiguous change names by prompting for clarification"],"zh":["支持通过命令行工具openspec list --json获取可用变更","使用AskUserQuestion工具让用户选择要工作的变更","支持根据最近修改时间对变更进行排序","可选地指定变更名称","如果变更名称不明确，会提示用户选择"],"ja":["openspec list --jsonコマンドを使用して利用可能な変更を取得","AskUserQuestionツールを使用してユーザーが変更を選択できる","変更を最近の更新日時でソートする","変更名を任意で指定可能","変更名が不明確な場合はユーザーに選択を促す"],"ko":["openspec list --json 명령을 사용하여 사용 가능한 변경을 가져옵니다","AskUserQuestion 도구를 사용하여 사용자가 변경을 선택할 수 있습니다","변경을 최근 수정된 날짜로 정렬합니다","변경 이름을 선택적으로 지정할 수 있습니다","변경 이름이 불명확한 경우 사용자에게 선택을 요청합니다"],"es":["Utiliza la CLI para ejecutar comandos como ''openspec list --json''","Permite a los usuarios seleccionar el cambio en el que trabajar","Presenta los 3 cambios más recientes modificados","Utiliza la herramienta AskUserQuestion para obtener la entrada del usuario","Soporta la inferencia del nombre del cambio desde el contexto de la conversación"],"fr":["Utilise la CLI pour exécuter des commandes comme ''openspec list --json''","Permet aux utilisateurs de sélectionner le changement sur lequel travailler","Présente les 3 changements les plus récemment modifiés","Utilise l''outil AskUserQuestion pour obtenir l''entrée de l''utilisateur","Prend en charge l''inférence du nom du changement depuis le contexte de la conversation"],"de":["Verwendet die CLI, um Befehle wie ''openspec list --json'' auszuführen","Ermöglicht es Benutzern, den Änderung auszuwählen, an der sie arbeiten möchten","Präsentiert die 3 zuletzt geänderten Änderungen","Verwendet das Tool AskUserQuestion, um die Eingabe des Benutzers zu erhalten","Unterstützt die Inferenz des Änderungsnamens aus dem Konversationskontext"],"pt":["Lista as alterações disponíveis com o comando `openspec list --json`","Permite ao usuário selecionar qual alteração trabalhar com o AskUserQuestion tool","Apresenta as 3 alterações mais recentes modificadas","Cria o próximo artifact de uma alteração","Suporta a inferência do nome da alteração a partir do contexto da conversa"],"ru":["Выводит список доступных изменений с помощью команды `openspec list --json`","Позволяет пользователю выбрать, над какой изменением работать с помощью инструмента AskUserQuestion","Отображает 3 наиболее недавно измененные изменения","Создает следующий артефакт изменений","Поддерживает вывод имени изменений из контекста разговора, ИИ Агенты"],"ar":["يقوم بlisting التغييرات المتاحة باستخدام الأمر `openspec list --json`","يمكّن المستخدم من اختيار التغيير الذي يعمل عليه باستخدام أداة AskUserQuestion","يعرض 3 التغييرات التي تم تعديلها最近","ينشئ الملف التالي من التغييرات","يدعم استنتاج اسم التغيير من سياق المحادثة، أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use openspec-continue-change","openspec-continue-change setup guide","openspec-continue-change alternative","openspec-continue-change vs other AI API proxies","openspec-continue-change install","what is openspec-continue-change","openspec-continue-change automated change management","openspec-continue-change AI agent workflow","openspec-continue-change JSON output","openspec-continue-change AskUserQuestion integration"],"zh":["openspec-continue-change","AI API代理","工作流管理","开发工具","命令行工具","AskUserQuestion","变更管理","开发效率"],"ja":["openspec-continue-change","AIエージェント","開発プロセス","開発ツール","コマンドラインツール","AskUserQuestion","変更管理","開発効率"],"ko":["openspec-continue-change","AI 도구","개발 프로세스","개발 도구","명령줄 도구","AskUserQuestion","변경 관리","개발 효율"],"es":["Agente de Inteligencia Artificial","herramienta de desarrollo","CLI","openspec-continue-change","cambios en el código","desarrollo de software","integración de herramientas de AI"],"fr":["Agent d''Intelligence Artificielle","outils de développement","CLI","openspec-continue-change","changements de code","développement de logiciels","intégration d''outils d''IA"],"de":["IИ-Agents","Entwicklungstool","CLI","openspec-continue-change","Änderungen im Code","Softwareentwicklung","Integration von IИ-Tools"],"pt":["openspec-continue-change","proxy de API de IA","alterações","artefact","AskUserQuestion tool","comando `openspec list --json`","desenvolvedores","Guia de Configuração"],"ru":["openspec-continue-change","прокси API ИИ","изменения","артефакт","инструмент AskUserQuestion","команда `openspec list --json`","разработчики","Руководство по настройке","ИИ Агенты"],"ar":["openspec-continue-change","وكيل API من الذكاء الاصطناعي","التغييرات","الملف","أداة AskUserQuestion","الأمر `openspec list --json`","المطورون","دليل إعداد","أدوات الذكاء الاصطناعي"]}},"owner":"g1331","repo":"AutoRouter","repoPath":"g1331/AutoRouter","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.423Z","topics":[],"category":"community","skillMd":{"name":"openspec-continue-change","description":"Continue working on an OpenSpec change by creating the next artifact. Use when the user wants to progress their change, create the next artifact, or continue their workflow.","version":"1.0","bodyPreview":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-","body":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-4 most recently modified changes as options, showing:\n   - Change name\n   - Schema (from `schema` field if present, otherwise \"spec-driven\")\n   - Status (e.g., \"0/5 tasks\", \"complete\", \"no tasks\")\n   - How recently it was modified (from `lastModified` field)\n\n   Mark the most recently modified change as \"(Recommended)\" since it''s likely what the user wants to continue.\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check current status**\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n   Parse the JSON to understand current state. The response includes:\n   - `schemaName`: The workflow schema being used (e.g., \"spec-driven\")\n   - `artifacts`: Array of artifacts with their status (\"done\", \"ready\", \"blocked\")\n   - `isComplete`: Boolean indicating if all artifacts are complete\n\n3. **Act based on status**:\n\n   ---\n\n   **If all artifacts are complete (`isComplete: true`)**:\n   - Congratulate the user\n   - Show final status including the schema used\n   - Suggest: \"All artifacts created! You can now implement this change or archive it.\"\n   - STOP\n\n   ---\n\n   **If artifacts are ready to create** (status shows artifacts with `status: \"ready\"`):\n   - Pick the FIRST artifact with `status: \"ready\"` from the status output\n   - Get its instructions:\n     ```bash\n     openspec instructions <artifact-id> --change \"<name>\" --json\n     ```\n   - Parse the JSON. The key fields are:\n     - `context`: Project background (constraints for you - do NOT include in output)\n     - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n     - `template`: The structure to use for your output file\n     - `instruction`: Schema-specific guidance\n     - `outputPath`: Where to write the artifact\n     - `dependencies`: Completed artifacts to read for context\n   - **Create the artifact file**:\n     - Read any completed dependency files for context\n     - Use `template` as the structure - fill in its sections\n     - Apply `context` and `rules` as constraints when writing - but do NOT copy them into the file\n     - Write to the output path specified in instructions\n   - Show what was created and what''s now unlocked\n   - STOP after creating ONE artifact\n\n   ---\n\n   **If no artifacts are ready (all blocked)**:\n   - This shouldn''t happen with a valid schema\n   - Show status and suggest checking for issues\n\n4. **After creating an artifact, show progress**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter each invocation, show:\n- Which artifact was created\n- Schema workflow being used\n- Current progress (N/M complete)\n- What artifacts are now unlocked\n- Prompt: \"Want to continue? Just ask me to continue or tell me what to do next.\"\n\n**Artifact Creation Guidelines**\n\nThe artifact types and their purpose depend on the schema. Use the `instruction` field from the instructions output to understand what to create.\n\nCommon artifact patterns:\n\n**spec-driven schema** (proposal → specs → design → tasks):\n- **proposal.md**: Ask user about the change if not clear. Fill in Why, What Changes, Capabilities, Impact.\n  - The Capabilities section is critical - each capability listed will need a spec file.\n- **specs/<capability>/spec.md**: Create one spec per capability listed in the proposal''s Capabilities section (use the capability name, not the change name).\n- **design.md**: Document technical decisions, architecture, and implementation approach.\n- **tasks.md**: Break down implementation into checkboxed tasks.\n\nFor other schemas, follow the `instruction` field from the CLI output.\n\n**Guardrails**\n- Create ONE artifact per invocation\n- Always read dependency artifacts before creating a new one\n- Never skip artifacts or create out of order\n- If context is unclear, ask the user before creating\n- Verify the artifact file exists after writing before marking progress\n- Use the schema''s artifact sequence, don''t assume specific artifact names\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n"},"lastSynced":"2026-03-07T12:54:15.678Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated change management and workflow simplification.","zh":"适合需要自动化变更管理和工作流简化的开发代理。","ja":"開発エージェントが自動化された変更管理とワークフローの簡素化を必要とする場合に最適です。","ko":"자동화된 변경 관리와 워크플로우 간소화를 필요로 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión automática de cambios y simplificación de flujos de trabajo.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion automatisée des modifications et d''une simplification des flux de travail.","de":"Perfekt für Entwicklungsmittel benötigende automatisierte Änderungsverwaltung und Workflowvereinfachung.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de alterações automatizado e simplificação de fluxo de trabalho.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированное управление изменениями и упрощение рабочего процесса.","ar":"مثالي لعمليات التطوير التي تحتاج إلى إدارة التغييرات آليًا وتبسيط سير العمل."},"recommendation":{"en":"Empowers agents to automate change management by creating the next artifact in a change, utilizing the openspec list command and AskUserQuestion tool for seamless workflow integration, and supporting JSON output for efficient data handling.","zh":"通过创建变更的下一个工件，利用openspec列表命令和AskUserQuestion工具实现无缝的工作流集成，并支持JSON输出以实现高效的数据处理，从而赋予代理自动化变更管理的能力。","ja":"openspecリストコマンドとAskUserQuestionツールを使用して、変化の次のアーティファクトを作成し、シームレスなワークフロー統合を実現し、JSON出力をサポートして効率的なデータ処理を行うことで、エージェントに変化管理を自動化する機能を提供します。","ko":"변경의 다음 아티팩트를 생성하고 openspec 목록 명령과 AskUserQuestion 툴을 사용하여 무중단 워크플로우 통합을実現하며 JSON 출력을 지원하여 효율적인 데이터 처리를 thực現함으로써 에이전트가 변경 관리를 자동화할 수 있는 기능을 제공합니다.","es":"Habilita a los agentes a automatizar la gestión de cambios creando el siguiente artefacto en un cambio, utilizando el comando openspec list y la herramienta AskUserQuestion para una integración de flujo de trabajo sin problemas, y soportando la salida JSON para un manejo de datos eficiente.","fr":"Permet aux agents d''automatiser la gestion des modifications en créant le prochain artefact dans une modification, en utilisant la commande openspec list et l''outil AskUserQuestion pour une intégration de flux de travail sans accroc, et en prenant en charge la sortie JSON pour une gestion de données efficace.","de":"Ermächtigt die Mittel, die Änderungsverwaltung zu automatisieren, indem sie das nächste Artefakt in einer Änderung erstellen, den openspec-Befehl verwenden und das Tool AskUserQuestion für eine nahtlose Workflow-Integration sowie die Unterstützung von JSON-Ausgaben für effizientes Datenhandling.","pt":"Permite que os agentes automatizem o gerenciamento de alterações, criando o próximo artefato em uma alteração, utilizando o comando openspec list e a ferramenta AskUserQuestion para integração de fluxo de trabalho sem interrupções, e suportando saída JSON para manipulação eficiente de dados.","ru":"Позволяет агентам автоматизировать управление изменениями, создавая следующий артефакт в изменении, используя команду openspec list и инструмент AskUserQuestion для бесшовной интеграции рабочего процесса, и поддерживая вывод JSON для эффективного xử lý данных.","ar":"تمكن الوكلاء من автоматизة إدارة التغييرات من خلال إنشاء الملف التالي في التغيير، باستخدام أمر openspec list وأداة AskUserQuestion من أجل دمج سير العمل بدون انقطاع، ودعم الإخراج JSON من أجل معالجة البيانات بكفاءة."},"useCases":{"en":["Automating change management for streamlined development workflows","Generating the next artifact in a change for continuous development","Prompting users for change selection using the AskUserQuestion tool"],"zh":["为流线型开发工作流自动化变更管理","为连续开发生成变更的下一个工件","使用AskUserQuestion工具提示用户选择变更"],"ja":["ストリーミング開発ワークフロー用の変更管理の自動化","連続開発用の変更の次のアーティファクトの生成","AskUserQuestionツールを使用した変更の選択のユーザーへの提示"],"ko":["스트림라인 개발 워크플로우를 위한 변경 관리 자동화","연속 개발을 위한 변경의 다음 아티팩트 생성","AskUserQuestion 툴을 사용한 변경 선택에 대한 사용자 프롬프트"],"es":["Automatizar la gestión de cambios para flujos de trabajo de desarrollo optimizados","Generar el siguiente artefacto en un cambio para el desarrollo continuo","Solicitar a los usuarios la selección de cambios mediante la herramienta AskUserQuestion"],"fr":["Automatiser la gestion des modifications pour des flux de travail de développement rationalisés","Générer le prochain artefact dans une modification pour le développement continu","Inciter les utilisateurs à sélectionner des modifications à l''aide de l''outil AskUserQuestion"],"de":["Automatisierung der Änderungsverwaltung für optimierte Entwicklungswerkflüsse","Erzeugen des nächsten Artefakts in einer Änderung für kontinuierliche Entwicklung","Aufforderung an Benutzer, Änderungen mithilfe des Tools AskUserQuestion auszuwählen"],"pt":["Automatizar o gerenciamento de alterações para fluxos de trabalho de desenvolvimento otimizados","Gerar o próximo artefato em uma alteração para desenvolvimento contínuo","Solicitar aos usuários a seleção de alterações usando a ferramenta AskUserQuestion"],"ru":["Автоматизировать управление изменениями для оптимизированных рабочих процессов разработки","Генерировать следующий артефакт в изменении для непрерывной разработки","Предлагать пользователям выбор изменений с помощью инструмента AskUserQuestion"],"ar":["تحسين إدارة التغييرات آليًا من أجل سير عمل التطوير المتميزة","إنشاء الملف التالي في التغيير من أجل التطوير المستمر","طلب من المستخدمين اختيار التغييرات باستخدام أداة AskUserQuestion"]},"limitations":{"en":["Requires openspec list command functionality","Dependent on conversation context for change name inference","Limited to top 3 changes for user selection prompt"],"zh":["需要openspec列表命令功能","依赖于会话上下文进行变更名称推断","仅限于用户选择提示的前3个变更"],"ja":["openspecリストコマンドの機能が必要","変更名の推論に会話のコンテキストに依存","ユーザー選択の提示は先頭の3つの変更に限定"],"ko":["openspec 목록 명령의 기능이 필요","변경 이름 추론에 대화 문脈에 의존","사용자 선택提示는 최상위 3개의 변경으로 제한"],"es":["Requiere la funcionalidad del comando openspec list","Dependiente del contexto de conversación para inferir el nombre del cambio","Limitado a los 3 primeros cambios para la invitación de selección de usuario"],"fr":["Nécessite la fonctionnalité de la commande openspec list","Dépend du contexte de conversation pour déduire le nom de la modification","Limité aux 3 premières modifications pour l''invite de sélection de l''utilisateur"],"de":["Erfordert die Funktionalität des openspec-Befehls","Abhängig vom Konversationskontext zur Ableitung des Änderungsnamens","Begrenzt auf die ersten 3 Änderungen für die Benutzerauswahlaufforderung"],"pt":["Requer funcionalidade do comando openspec list","Dependente do contexto da conversa para inferência do nome da alteração","Limitado aos 3 principais alterações para prompt de seleção do usuário"],"ru":["Требует функциональности команды openspec list","Зависит от контекста разговора для вывода имени изменения","Ограничен до 3 основных изменений для подсказки выбора пользователя"],"ar":["يتطلب خاصية أمر openspec list","يعتمد على سياق المحادثة لاستنتاج اسم التغيير","محدود بالتغييرات الثلاث الأولى لتحفيز اختيار المستخدم"]},"version":4},"contentHash":"383848c3fa732a8545b4e5aeb3bd8e83179410c48e47abd1db4afd8b7ddfb6cd","qualityScore":50}');
DELETE FROM skills_fts WHERE id = 'g1331/AutoRouter/openspec-continue-change';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('g1331/AutoRouter/openspec-continue-change', 'openspec-continue-change', 'g1331', 'AutoRouter', 'community', 'openspec-continue-change g1331 AutoRouter community The openspec-continue-change skill automates change management for AI agents by creating the next artifact in a change. It benefits developers by simplifying their workflow. openspec-continue-change是一个极简的多上游AI API代理，用于继续工作中的变更 openspec-continue-changeは、開発プロセスを最適化するために、 次のアーティファクトを作成することで変更を継続する openspec-continue-change는 다음 아티팩트를 생성하여 변경을 계속하는 개발 프로세스 최적화 도구입니다 openspec-continue-change es una herramienta minimalista para crear el próximo artefacto en un cambio, utilizando la CLI para ejecutar comandos como ''openspec list --json'' openspec-continue-change est un outil minimaliste pour créer le prochain artefact dans un changement, en utilisant la CLI pour exécuter des commandes comme ''openspec list --json'' openspec-continue-change ist ein minimalistisches Tool, um das nächste Artefakt in einer Änderung zu erstellen, indem es die CLI verwendet, um Befehle wie ''openspec list --json'' auszuführen O openspec-continue-change é um proxy de API de IA minimalista que permite criar o próximo artifact de uma alteração. Ele lista as alterações disponíveis e permite ao usuário selecionar qual alteração trabalhar openspec-continue-change - это минималистичный прокси API ИИ, который позволяет создать следующий артефакт изменений. Он выводит список доступных изменений и позволяет пользователю выбрать, над какой изменением работать, ИИ Агенты openspec-continue-change هو وكيل API من الذكاء الاصطناعي البسيط الذي يسمح بإنشاء الملف التالي من التغييرات. يقوم بlisting التغييرات المتاحة ويمكّن المستخدم من اختيار التغيير الذي يعمل عليه، أدوات الذكاء الاصطناعي how to use openspec-continue-change openspec-continue-change setup guide openspec-continue-change alternative openspec-continue-change vs other AI API proxies openspec-continue-change install what is openspec-continue-change openspec-continue-change automated change management openspec-continue-change AI agent workflow openspec-continue-change JSON output openspec-continue-change AskUserQuestion integration openspec-continue-change AI API代理 工作流管理 开发工具 命令行工具 AskUserQuestion 变更管理 开发效率 Runs openspec list --json to retrieve available changes sorted by most recently modified Utilizes the AskUserQuestion tool to prompt users for change selection Presents the top 3-5 changes for user selection Optionally accepts a change name as input Infers the change name from conversation context if not provided Supports vague or ambiguous change names by prompting for clarification openspec-continue-change is a minimalistic AI API proxy that continues working on a change by creating the next artifact, using commands like openspec list --json.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danstrem2/clawdbot-skill-master-pack/copywriting', 'community', 'danstrem2', 'clawdbot-skill-master-pack', 'danstrem2/clawdbot-skill-master-pack', 'copywriting', 0, 0, 50, '2026-03-07T12:46:33.517Z', '2026-03-07T12:56:41.076Z', '5b3ea76961e8de82f00083569f4ef275058afb70bb301a9153dd80f73837b18e', '{"id":"danstrem2/clawdbot-skill-master-pack/copywriting","name":"copywriting","description":{"en":"The copywriting skill enables AI agents to generate marketing copy that drives action, targeting specific page purposes and audiences to solve their problems.","zh":"AIエージェント复制写作专家，撰写清晰、令人信服的市场文案，驱动行动","ja":"AIエージェントによるコピーライティングエキスパート。明確で説得力のあるマーケティングコピーを書き、行動を促す","ko":"AI 에이전트 복사 작성 전문가, 명확하고 설득력 있는 마케팅 복사 작성 및 행동 유도","es":"El copywriting es una habilidad clave para los Agentes de IA, que permite crear marketing copy claro y atractivo para mejorar la conversión y el compromiso del usuario.","fr":"La rédaction publicitaire est une compétence clé pour les Outils d''IA, qui permet de créer du copywriting marketing clair et attrayant pour améliorer la conversion et l''engagement des utilisateurs.","de":"Das Copywriting ist eine Schlüsselkompetenz für KI-Tools, die es ermöglicht, verkaufsförderndes Marketing-Copy zu erstellen, um die Konversion und die Nutzerbeteiligung zu verbessern.","pt":"O copywriting é uma técnica de escrita que visa criar conteúdo claro e atraente para impulsionar a conversão e o engajamento do usuário","ru":"Копирайтинг - это техника написания текстов, направленная на создание rõчного и привлекательного контента для повышения конверсий и вовлечения пользователей","ar":"الكتابة الإعلانية هي تقنية للكتابة تهدف إلى إنشاء محتوى واضح وجذاب لزيادة التحويلات ومشاركة المستخدم"},"seo":{"title":{"en":"Copywriting: Expert Conversion Copy Generation | AI Agent...","zh":"AIエージェント复制写作设置指南","ja":"AIエージェントによるコピーライティングベストプラクティス","ko":"AI 에이전트 복사 작성 가이드","es":"Guía de configuración de copywriting para Agentes de IA","fr":"Guide de mise en place de la rédaction publicitaire pour ...","de":"Einrichtungsleitfaden für Copywriting mit KI-Tools","pt":"Guia de Configuração de Copywriting para Desenvolvedores","ru":"Настройка Копирайтинга для Разработчиков: Лучшие Практики","ar":"دليل إعداد الكتابة الإعلانية لملحقي التطبيقات"},"description":{"en":"Discover how to drive action with clear and compelling marketing copy - learn the art of copywriting with our AI agent skill and boost conversions today!","zh":"了解AIエージェント复制写作的技术细节，包括页面目的、受众分析和行动驱动","ja":"AIエージェントによるコピーライティングのテクニカルな詳細を学び、ページ目的、対象者分析、行動駆動を実現","ko":"AI 에이전트 복사 작성의 기술 세부 정보를 확인하고 페이지 목적, 대상자 분석 및 행동 구성을 최적화","es":"Aprende a escribir marketing copy claro y atractivo con nuestros Agentes de IA. Mejora la conversión y el compromiso del usuario con copywriting eficaz.","fr":"Découvrez comment écrire du copywriting marketing clair et attrayant avec nos Outils d''IA. Améliorez la conversion et l''engagement des utilisateurs avec un c...","de":"Erfahren Sie, wie Sie mit unseren KI-Tools verkaufsförderndes Marketing-Copy schreiben können. Verbessern Sie die Konversion und die Nutzerbeteiligung durch ...","pt":"Aprenda a criar copywriting eficaz para impulsionar a conversão e o engajamento do usuário com o nosso guia de configuração para desenvolvedores","ru":"Узнайте, как создать эффективный копирайтинг для привлечения конверсий и вовлечения пользователей с нашей инструкцией для разработчиков","ar":"تعلم كيفية إنشاء كتابة إعلانية فعالة لزيادة التحويلات ومشاركة المستخدم مع دليلنا الإرشادي لملحقي التطبيقات"},"definition":{"en":"Copywriting is the process of writing clear, compelling, and action-driven marketing copy for various page types, including homepages and landing pages.","zh":"复制写作是AIエージェント用于撰写市场文案的技术","ja":"コピーライティングは、AIエージェントがマーケティングコピーを書くために使用する技術","ko":"복사 작성은 AI 에이전트가 마케팅 복사를 작성하기 위한 기술","es":"El copywriting es el arte de escribir texto publicitario que impulse a la acción y mejore la conversión.","fr":"La rédaction publicitaire est l''art d''écrire du texte publicitaire qui incite à l''action et améliore la conversion.","de":"Das Copywriting ist die Kunst, Werbetexte zu schreiben, die zur Aktion anregen und die Konversion verbessern.","pt":"O copywriting é uma técnica de escrita que cria conteúdo para impulsionar a conversão e o engajamento do usuário","ru":"Копирайтинг - это техника написания текстов для повышения конверсий и вовлечения пользователей","ar":"الكتابة الإعلانية هي تقنية للكتابة تهدف إلى زيادة التحويلات ومشاركة المستخدم"},"features":{"en":["Gathers context on page purpose, including primary and secondary actions","Identifies ideal customer audiences and their problems to solve","Writes marketing copy for specific page types, such as homepages and landing pages","Drives action with clear and compelling copy"],"zh":["页面目的分析","受众分析","行动驱动文案撰写","次要行动规划","清晰、令人信服的市场文案"],"ja":["ページ目的分析","対象者分析","行動駆動コピーの作成","二次的な行動の計画","明確で説得力のあるマーケティングコピー"],"ko":["페이지 목적 분석","대상자 분석","행동 구성을 위한 복사 작성","次要 행동 계획","명확하고 설득력 있는 마케팅 복사"],"es":["Análisis de la finalidad de la página para crear copywriting efectivo","Identificación del público objetivo y sus necesidades para personalizar el mensaje","Determinación de la acción principal y secundaria para guiar al usuario","Creación de copywriting claro y conciso para mejorar la conversión","Optimización del copywriting para mejorar el compromiso del usuario"],"fr":["Analyse de l''objectif de la page pour créer un copywriting efficace","Identification du public cible et de ses besoins pour personnaliser le message","Détermination de l''action principale et secondaire pour guider l''utilisateur","Création de copywriting clair et concis pour améliorer la conversion","Optimisation du copywriting pour améliorer l''engagement des utilisateurs"],"de":["Analyse des Seitenzwecks, um effektives Copywriting zu erstellen","Identifizierung des Zielpublikums und seiner Bedürfnisse, um die Botschaft zu personalisieren","Bestimmung der primären und sekundären Aktionen, um den Benutzer zu führen","Erstellung von verkaufsförderndem Copywriting, um die Konversion zu verbessern","Optimierung des Copywriting, um die Nutzerbeteiligung zu verbessern"],"pt":["Definição do propósito da página","Identificação do público-alvo","Criação de conteúdo claro e atraente","Otimização para conversão e engajamento","Análise do comportamento do usuário"],"ru":["Определение цели страницы","Идентификация целевой аудитории","Создание rõчного и привлекательного контента","Оптимизация для конверсий и вовлечения","Анализ поведения пользователей"],"ar":["تحديد هدف الصفحة","تحديد الجمهور المستهدف","إنشاء محتوى واضح وجذاب","تحسين التحويلات ومشاركة المستخدم","تحليل سلوك المستخدم"]},"keywords":{"en":["what is copywriting","copywriting for landing pages","how to write conversion copy","copywriting vs content writing","copywriting setup guide","expert copywriting techniques"],"zh":["AIエージェント复制写作","市场文案撰写","页面目的分析","受众分析","行动驱动","复制写作技术","AIエージェント工具"],"ja":["AIエージェントによるコピーライティング","マーケティングコピーの作成","ページ目的分析","対象者分析","行動駆動","コピーライティング技術","AIエージェントツール"],"ko":["AI 에이전트 복사 작성","마케팅 복사 작성","페이지 목적 분석","대상자 분석","행동 구성을 위한 복사 작성","복사 작성 기술","AI 에이전트 도구"],"es":["copywriting para Agentes de IA","marketing copy efectivo","mejora de la conversión","compromiso del usuario","redacción publicitaria para IA","copywriting para herramientas de IA","optimización de copywriting","estrategias de copywriting"],"fr":["rédaction publicitaire pour les Outils d''IA","copywriting marketing efficace","amélioration de la conversion","engagement des utilisateurs","rédaction publicitaire pour l''IA","copywriting pour les outils d''IA","optimisation du copywriting","stratégies de rédaction publicitaire"],"de":["Copywriting für KI-Tools","verkaufsförderndes Marketing-Copy","Verbesserung der Konversion","Nutzerbeteiligung","Copywriting für KI-Anwendungen","Copywriting für KI-Tools","Optimierung des Copywriting","Copywriting-Strategien"],"pt":["copywriting para desenvolvedores","guias de configuração de copywriting","melhores práticas de copywriting","otimização de conversão","engajamento do usuário","análise de comportamento do usuário","desenvolvimento de aplicativos","ferramentas de copywriting"],"ru":["копирайтинг для разработчиков","инструкции по настройке копирайтинга","лучшие практики копирайтинга","оптимизация конверсий","вовлечение пользователей","анализ поведения пользователей","разработка приложений","инструменты копирайтинга","ИИ Агенты"],"ar":["الكتابة الإعلانية لملحقي التطبيقات","دلائل إعداد الكتابة الإعلانية","أفضل الممارسات للكتابة الإعلانية","تحسين التحويلات","مشاركة المستخدم","تحليل سلوك المستخدم","تطوير التطبيقات","أدوات الكتابة الإعلانية","أدوات الذكاء الاصطناعي"]}},"owner":"danstrem2","repo":"clawdbot-skill-master-pack","repoPath":"danstrem2/clawdbot-skill-master-pack","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.517Z","topics":[],"category":"community","skillMd":{"name":"copywriting","description":"When the user wants to write, rewrite, or improve marketing copy for any page — including homepage, landing pages, pricing pages, feature pages, about pages, or product pages. Also use when the user says write copy for, improve this copy, rewrite this page, marketing copy, headline help, or CTA copy. For email copy, see email-sequence. For popup copy, see popup-cro.","bodyPreview":"# Copywriting\n\nYou are an expert conversion copywriter. Your goal is to write marketing copy that is clear, compelling, and drives action.\n\n## Before Writing\n\nGather this context (ask if not provided):\n\n### 1. Page Purpose\n- What type of page is this? (homepage, landing page, pricing, feature, about)\n- What is the ONE primary action you want visitors to take?\n- What''s the secondary action (if any)?\n\n### 2. Audience\n- Who is the ideal customer for this page?\n- What problem are they trying to solv","body":"# Copywriting\n\nYou are an expert conversion copywriter. Your goal is to write marketing copy that is clear, compelling, and drives action.\n\n## Before Writing\n\nGather this context (ask if not provided):\n\n### 1. Page Purpose\n- What type of page is this? (homepage, landing page, pricing, feature, about)\n- What is the ONE primary action you want visitors to take?\n- What''s the secondary action (if any)?\n\n### 2. Audience\n- Who is the ideal customer for this page?\n- What problem are they trying to solve?\n- What have they already tried?\n- What objections or hesitations do they have?\n- What language do they use to describe their problem?\n\n### 3. Product/Offer\n- What are you selling or offering?\n- What makes it different from alternatives?\n- What''s the key transformation or outcome?\n- Any proof points (numbers, testimonials, case studies)?\n\n### 4. Context\n- Where is traffic coming from? (ads, organic, email)\n- What do visitors already know before arriving?\n- What messaging are they seeing before this page?\n\n---\n\n## Copywriting Principles\n\n### Clarity Over Cleverness\n- If you have to choose between clear and creative, choose clear\n- Every sentence should have one job\n- Remove words that don''t add meaning\n\n### Benefits Over Features\n- Features: What it does\n- Benefits: What that means for the customer\n- Always connect features to outcomes\n\n### Specificity Over Vagueness\n- Vague: \"Save time on your workflow\"\n- Specific: \"Cut your weekly reporting from 4 hours to 15 minutes\"\n\n### Customer Language Over Company Language\n- Use words your customers use\n- Avoid jargon unless your audience uses it\n- Mirror voice-of-customer from reviews, interviews, support tickets\n\n### One Idea Per Section\n- Don''t try to say everything everywhere\n- Each section should advance one argument\n- Build a logical flow down the page\n\n---\n\n## Writing Style Rules\n\nFollow these core principles. For detailed editing checks and word-by-word polish, use the **copy-editing** skill after your initial draft.\n\n### Core Style Principles\n\n1. **Simple over complex** — Use everyday words. \"Use\" instead of \"utilize,\" \"help\" instead of \"facilitate.\"\n\n2. **Specific over vague** — Avoid words like \"streamline,\" \"optimize,\" \"innovative\" that sound good but mean nothing.\n\n3. **Active over passive** — \"We generate reports\" not \"Reports are generated.\"\n\n4. **Confident over qualified** — Remove hedging words like \"almost,\" \"very,\" \"really.\"\n\n5. **Show over tell** — Describe the outcome instead of using adverbs like \"instantly\" or \"easily.\"\n\n6. **Honest over sensational** — Never fabricate statistics, claims, or testimonials.\n\n### Quick Quality Check\n\nBefore finalizing, scan for:\n- Jargon that could confuse outsiders\n- Sentences trying to do too much (max 3 conjunctions)\n- Passive voice constructions\n- Exclamation points (remove them)\n- Marketing buzzwords without substance\n\nFor a thorough line-by-line review, run the copy through the **copy-editing** skill''s Seven Sweeps framework.\n\n---\n\n## Best Practices\n\n### Be Direct\nGet to the point. Don''t bury the value in qualifications.\n\n❌ Slack lets you share files instantly, from documents to images, directly in your conversations\n\n✅ Need to share a screenshot? Send as many documents, images, and audio files as your heart desires.\n\n### Use Rhetorical Questions\nQuestions engage readers and make them think about their own situation.\n\n✅ Hate returning stuff to Amazon?\n\n✅ Need to share a screenshot?\n\n✅ Tired of chasing approvals?\n\n### Use Analogies and Metaphors\nWhen appropriate, analogies make abstract concepts concrete and memorable.\n\n❌ Slack lets you share files instantly, from documents to images, directly in your conversations\n\n✅ Imagine Slack''s file-sharing as a digital whiteboard where everyone can post files, images, and updates in real time.\n\n### Pepper in Humor (When Appropriate)\nPuns, wit, and humor make copy memorable—but only if it fits the brand and doesn''t undermine clarity.\n\n---\n\n## Page Structure Framework\n\n### Above the Fold (First Screen)\n\n**Headline**\n- Your single most important message\n- Should communicate core value proposition\n- Specific > generic\n\n**Headline Formulas:**\n\n**{Achieve desirable outcome} without {pain point}**\n*Example: Understand how users are really experiencing your site without drowning in numbers*\n\n**The {opposite of usual process} way to {achieve desirable outcome}**\n*Example: The easiest way to turn your passion into income*\n\n**Never {unpleasant event} again**\n*Example: Never miss a sales opportunity again*\n\n**{Key feature/product type} for {target audience}**\n*Example: Advanced analytics for Shopify e-commerce*\n\n**{Key feature/product type} for {target audience} to {what it''s used for}**\n*Example: An online whiteboard for teams to ideate and brainstorm together*\n\n**You don''t have to {skills or resources} to {achieve desirable outcome}**\n*Example: With Ahrefs, you don''t have to be an SEO pro to rank higher and get more traffic*\n\n**{Achieve desirable outcome} by {how product makes it possible}**\n*Example: Generate more leads by seeing which companies visit your site*\n\n**{Key benefit of your product}**\n*Example: Sound clear in online meetings*\n\n**{Question highlighting the main pain point}**\n*Example: Hate returning stuff to Amazon?*\n\n**Turn {input} into {outcome}**\n*Example: Turn your hard-earned sales into repeat customers*\n\n**Additional formulas:**\n- \"[Achieve outcome] in [timeframe]\"\n- \"The [category] that [key differentiator]\"\n- \"Stop [pain]. Start [pleasure].\"\n- \"[Number] [people] use [product] to [outcome]\"\n\n**Subheadline**\n- Expands on the headline\n- Adds specificity or addresses secondary concern\n- 1-2 sentences max\n\n**Primary CTA**\n- Action-oriented button text\n- Communicate what they get, not what they do\n- \"Start Free Trial\" > \"Sign Up\"\n- \"Get Your Report\" > \"Submit\"\n\n**Supporting Visual**\n- Product screenshot, demo, or hero image\n- Should reinforce the message, not distract\n\n### Social Proof Section\n\nOptions (use 1-2):\n- Customer logos (recognizable > many)\n- Key metric (\"10,000+ teams\")\n- Short testimonial with attribution\n- Star rating with review count\n\n### Problem/Pain Section\n\n- Articulate the problem better than they can\n- Show you understand their situation\n- Create recognition (\"that''s exactly my problem\")\n\nStructure:\n- \"You know the feeling...\" or \"If you''re like most [role]...\"\n- Describe the specific frustrations\n- Hint at the cost of not solving it\n\n### Solution/Benefits Section\n\n- Bridge from problem to your solution\n- Focus on 3-5 key benefits (not 10)\n- Each benefit: headline + short explanation + proof point if available\n\nFormat options:\n- Benefit blocks with icons\n- Before/after comparison\n- Feature → Benefit → Proof structure\n\n### How It Works Section\n\n- Reduce perceived complexity\n- 3-4 step process\n- Each step: simple action + outcome\n\nExample:\n1. \"Connect your tools (2 minutes)\"\n2. \"Set your preferences\"\n3. \"Get automated reports every Monday\"\n\n### Social Proof (Detailed)\n\n- Full testimonials with:\n  - Specific results\n  - Customer name, role, company\n  - Photo if possible\n- Case study snippets\n- Logos section (if not above)\n\n### Objection Handling\n\nCommon objections to address:\n- \"Is this right for my situation?\"\n- \"What if it doesn''t work?\"\n- \"Is it hard to set up?\"\n- \"How is this different from X?\"\n\nFormats:\n- FAQ section\n- Comparison table\n- Guarantee/promise section\n- \"Built for [specific audience]\" section\n\n### Final CTA Section\n\n- Recap the value proposition\n- Repeat the primary CTA\n- Add urgency if genuine (deadline, limited availability)\n- Risk reversal (guarantee, free trial, no credit card)\n\n---\n\n## Landing Page Section Variety\n\nA great landing page isn''t just a list of features. Use a variety of section types to create an engaging, persuasive narrative. Mix and match from these:\n\n### Section Types to Include\n\n**How It Works (Numbered Steps)**\nWalk users through the process in 3-4 clear steps. Reduces perceived complexity and shows the path to value.\n\n**Alternative/Competitor Comparison**\nShow how you stack up against the status quo or competitors. Tables, side-by-side comparisons, or \"Unlike X, we...\" sections.\n\n**Founder Manifesto / Our Story**\nShare why you built this and what you believe. Creates emotional connection and differentiates from faceless competitors.\n\n**Testimonials**\nCustomer quotes with names, photos, and specific results. Multiple formats: quote cards, video testimonials, tweet embeds.\n\n**Case Studies**\nDeeper stories of customer success. Problem → Solution → Results format with specific metrics.\n\n**Use Cases**\nShow different ways the product is used. Helps visitors self-identify: \"This is for people like me.\"\n\n**Personas / \"Built For\" Sections**\nExplicitly call out who the product is for: \"Perfect for marketers,\" \"Built for agencies,\" etc.\n\n**Stats and Social Proof**\nKey metrics that build credibility: \"10,000+ customers,\" \"4.9/5 rating,\" \"$2M saved for customers.\"\n\n**Demo / Product Tour**\nInteractive demos, video walkthroughs, or GIF previews showing the product in action.\n\n**FAQ Section**\nAddress common objections and questions. Good for SEO and reducing support burden.\n\n**Integrations / Partners**\nShow what tools you connect with. Logos build credibility and answer \"Will this work with my stack?\"\n\n**Pricing Preview**\nEven on non-pricing pages, a pricing teaser can move decision-makers forward.\n\n**Guarantee / Risk Reversal**\nMoney-back guarantee, free trial terms, or \"cancel anytime\" messaging reduces friction.\n\n### Recommended Section Mix\n\nFor a landing page, aim for variety. Don''t just stack features:\n\n**Typical Feature-Heavy Page (Weak):**\n1. Hero\n2. Feature 1\n3. Feature 2\n4. Feature 3\n5. Feature 4\n6. CTA\n\n**Varied, Engaging Page (Strong):**\n1. Hero with clear value prop\n2. Social proof bar (logos or stats)\n3. Problem/pain section\n4. How it works (3 steps)\n5. Key benefits (2-3, not 10)\n6. Testimonial\n7. Use cases or personas\n8. Comparison to alternatives\n9. Case study snippet\n10. FAQ\n11. Final CTA with guarantee\n\n---\n\n## CTA Copy Guidelines\n\n**Weak CTAs (avoid):**\n- Submit\n- Sign Up\n- Learn More\n- Click Here\n- Get Started\n\n**Strong CTAs (use):**\n- Start Free Trial\n- Get [Specific Thing]\n- See [Product] in Action\n- Create Your First [Thing]\n- Book My Demo\n- Download the Guide\n- Try It Free\n\n**CTA formula:**\n[Action Verb] + [What They Get] + [Qualifier if needed]\n\nExamples:\n- \"Start My Free Trial\"\n- \"Get the Complete Checklist\"\n- \"See Pricing for My Team\"\n\n---\n\n## Output Format\n\nWhen writing copy, provide:\n\n### Page Copy\nOrganized by section with clear labels:\n- Headline\n- Subheadline\n- CTA\n- Section headers\n- Body copy\n- Secondary CTAs\n\n### Annotations\nFor key elements, explain:\n- Why you made this choice\n- What principle it applies\n- Alternatives considered\n\n### Alternatives\nFor headlines and CTAs, provide 2-3 options:\n- Option A: [copy] — [rationale]\n- Option B: [copy] — [rationale]\n- Option C: [copy] — [rationale]\n\n### Meta Content (if relevant)\n- Page title (for SEO)\n- Meta description\n\n---\n\n## Page-Specific Guidance\n\n### Homepage Copy\n- Serve multiple audiences without being generic\n- Lead with broadest value proposition\n- Provide clear paths for different visitor intents\n- Balance \"ready to buy\" and \"still researching\"\n\n### Landing Page Copy\n- Single message, single CTA\n- Match headline to ad/traffic source\n- Complete argument on one page\n- Remove distractions (often no nav)\n\n### Pricing Page Copy\n- Help visitors choose the right plan\n- Clarify what''s included at each level\n- Address \"which is right for me?\" anxiety\n- Make recommended plan obvious\n\n### Feature Page Copy\n- Connect feature to benefit to outcome\n- Show use cases and examples\n- Differentiate from competitors'' versions\n- Clear path to try or buy\n\n### About Page Copy\n- Tell the story of why you exist\n- Connect company mission to customer benefit\n- Build trust through transparency\n- Still include a CTA (it''s still a marketing page)\n\n---\n\n## Voice and Tone Considerations\n\nBefore writing, establish:\n\n**Formality level:**\n- Casual/conversational\n- Professional but friendly\n- Formal/enterprise\n\n**Brand personality:**\n- Playful or serious?\n- Bold or understated?\n- Technical or accessible?\n\nMaintain consistency throughout, but adjust intensity:\n- Headlines can be bolder\n- Body copy should be clearer\n- CTAs should be action-oriented\n\n---\n\n## Related Skills\n\n- **copy-editing**: For polishing and improving existing copy (use after writing your first draft)\n- **page-cro**: If the page structure/strategy needs work, not just copy\n- **email-sequence**: For email copywriting\n- **popup-cro**: For popup and modal copy\n- **ab-test-setup**: To test copy variations properly\n"},"lastSynced":"2026-03-07T12:56:41.076Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing persuasive marketing content generation capabilities.","zh":"非常适合需要具有说服力营销内容生成能力的语言代理。","ja":"説得力のあるマーケティングコンテンツ生成能力を必要とする言語エージェントに最適です。","ko":"説得력 있는 마케팅 콘텐츠 생성 기능이 필요한 언어 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan capacidades de generación de contenido de marketing persuasivo.","fr":"Parfait pour les Agents de Langage ayant besoin de capacités de génération de contenu de marketing persuasif.","de":"Perfekt für Sprachagenten, die persuasive Marketing-Inhalte generieren müssen.","pt":"Perfeito para Agentes de Linguagem que precisam de capacidades de geração de conteúdo de marketing persuasivo.","ru":"Идеально для языковых агентов, которым необходимы возможности генерации убедительного маркетингового контента.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى قدرات توليد المحتوى التسويقي المقنع."},"recommendation":{"en":"Empowers agents to craft compelling page copy using context-driven audience analysis and page purpose identification, leveraging technical keywords like page types, audience personas, and call-to-actions to drive conversions.","zh":"赋予代理人利用上下文驱动的受众分析和页面目的识别来编写引人入胜的页面复制的能力，利用技术关键词如页面类型、受众角色和行动召唤来驱动转换，使用 React、Python 等技术。","ja":"コンテキスト駆動のオーディエンス分析とページ目的識別を利用して説得力のあるページコピーを作成するエージェントをエンパワーメントします。ページタイプ、オーディエンスパーソナ、コールツーアクションなどの技術キーワードを使用してCLI、APIなどの技術でコンバージョンを促進します。","ko":"상황에 따른 受众 分析 및 페이지 목적 식별을 통해 매력적인 페이지 복사본을 작성할 수 있는 에이전트를 강화합니다. 페이지 유형, 受众 프로필, 호출 대 응답 등과 같은 기술 키워드를 사용하여 Python, React와 같은 기술을 통해 전환을 유도합니다.","es":"Habilita a los agentes a crear copias de página convincentes utilizando análisis de audiencia basado en contexto y identificación de propósito de página, aprovechando palabras clave técnicas como tipos de página, personas de audiencia y llamadas a la acción para impulsar conversiones.","fr":"Permet aux agents de créer des copies de page convaincantes en utilisant l''analyse d''audience basée sur le contexte et l''identification de l''objectif de la page, en exploitant des mots-clés techniques tels que les types de page, les personas d''audience et les appels à l''action pour générer des conversions.","de":"Ermöglich es den Agenten, überzeugende Seitenkopien zu erstellen, indem sie kontextbasierte Zielgruppenanalyse und Seitenzweckidentifizierung nutzen und technische Schlüsselwörter wie Seitentypen, Zielgruppenpersonas und Calls-to-Actions zur Steigerung von Konversionen einsetzen.","pt":"Habilita os agentes a criar cópias de página convincentes usando análise de audiência baseada em contexto e identificação de propósito de página, aproveitando palavras-chave técnicas como tipos de página, personas de audiência e chamadas para ação para impulsionar conversões.","ru":"Наделяет агентов возможностью создавать убедительный контент страницы с помощью контекстно-зависимого анализа аудитории и определения цели страницы, используя технические ключевые слова, такие как типы страниц, персонажи аудитории и призывы к действию для стимулирования конверсий.","ar":"يتمكّن الوكلاء من创ать نسخة صفحة مقنعة باستخدام تحليل الجمهور القائم على السياق وتحديد غرض الصفحة ، مستفيداً من الكلمات الرئيسية الفنية مثل أنواع الصفحات وأشخاص الجمهور والدعوات إلى العمل لتعزيز التحويلات."},"useCases":{"en":["Generating landing page copy for targeted audiences","Crafting homepage content that drives primary and secondary actions","Creating feature page descriptions that solve customer problems"],"zh":["为目标受众生成着陆页复制","创建驱动主次行动的首页内容","创建解决客户问题的功能页描述"],"ja":["ターゲットオーディエンスの着陸ページコピー生成","主次アクションを促進するホームページコンテンツ作成","顧客の問題を解決する機能ページの説明作成"],"ko":["목표 受众을 위한 랜딩 페이지 복사본 생성","주 및 부 동작을 유도하는 홈페이지 콘텐츠 작성","고객 문제를 해결하는 기능 페이지 설명 생성"],"es":["Generar copias de página de destino para audiencias objetivo","Crear contenido de página de inicio que impulse acciones primarias y secundarias","Crear descripciones de páginas de características que resuelvan problemas del cliente"],"fr":["Générer des copies de page ciblées pour les audiences ciblées","Créer du contenu de page d''accueil qui impulse les actions primaires et secondaires","Créer des descriptions de pages de fonctionnalités qui résolvent les problèmes des clients"],"de":["Erstellen von Zielseitenkopien für Zielgruppen","Erstellen von Startseiteninhalt, der primäre und sekundäre Aktionen antreibt","Erstellen von Funktionsseitenbeschreibungen, die Kundenprobleme lösen"],"pt":["Geração de cópia de página de destino para audiências direcionadas","Criação de conteúdo de página inicial que impulsiona ações primárias e secundárias","Criação de descrições de página de recursos que resolvem problemas do cliente"],"ru":["Генерация копии целевой страницы для целевой аудитории","Создание контента домашней страницы, который стимулирует основные и второстепенные действия","Создание описаний страницы функций, которые решают проблемы клиентов"],"ar":["توليد نسخ الصفحة الهبوطية للجماهير المستهدفة","إنشاء محتوى الصفحة الرئيسية التي تدفع الإجراءات الأساسية والثانوية","إنشاء وصفات صفحة الميزات التي تحل مشاكل العملاء"]},"limitations":{"en":["Requires specific page purpose and audience context","Limited to marketing copy generation"],"zh":["需要特定的页面目的和受众上下文","仅限营销复制生成"],"ja":["特定のページ目的とオーディエンスコンテキストが必要","マーケティングコピー生成のみ"],"ko":["특정 페이지 목적 및 受众 상황이 필요","마케팅 복사본 생성만"],"es":["Requiere un propósito de página y un contexto de audiencia específicos","Limitado a la generación de copias de marketing"],"fr":["Nécessite un objectif de page et un contexte d''audience spécifiques","Limité à la génération de copies de marketing"],"de":["Benötigt einen spezifischen Seitenzweck und einen Zielgruppenkontext","Begrenzt auf die Generierung von Marketingkopien"],"pt":["Exige propósito de página e contexto de audiência específicos","Limitado à geração de cópia de marketing"],"ru":["Требует конкретного цели страницы и контекста аудитории","Ограничен генерацией маркетинговой копии"],"ar":["يتطلب غرض صفحة وسياق جمهور محدد","محدود بتوليد نسخة التسويق"]},"version":4},"contentHash":"5b3ea76961e8de82f00083569f4ef275058afb70bb301a9153dd80f73837b18e","qualityScore":50}');
