INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shinpr/agentic-code/ai-development-guide', 'ai-development-guide', 'shinpr', 'agentic-code', 'community', 'ai-development-guide shinpr agentic-code community agent-skills agentic-ai agentic-workflow ai-agents automation codex cursor developer-tools gemini-cli productivity prompt-engineering skills workflow Agentic框架提供系统化、测试优先的工作流程，支持Cursor、Codex、Gemini CLI和AI编码代理 Agenticフレームワークは、システム化されたテスト優先のワークフローを提供し、Cursor、Codex、Gemini CLI、AIコーディングエージェントをサポートします Agentic 프레임워크는 시스템화된 테스트 우선의 워크플로우를 제공하며 Cursor, Codex, Gemini CLI, AI 코딩 에이전트를 지원합니다 El marco de codificación Agentic ofrece flujos de trabajo sistemáticos y puertas de calidad para agentes de IA como Cursor, Codex y Gemini CLI Le cadre de codage Agentic propose des flux de travail systématiques et des portes de qualité pour les agents d''IA tels que Cursor, Codex et Gemini CLI Das Agentic-Codierungsframework bietet systematische Workflows und Qualitätsprüfungen für KI-Agenten wie Cursor, Codex und Gemini CLI O framework de codificação Agentic é uma solução sistemática e test-first para desenvolvedores, com qualidade gates para Cursor, Codex, Gemini CLI e agentes de codificação AI. Фреймворк кодирования Agentic - это систематическое и тест-ориентированное решение для разработчиков, с контрольными воротами для Cursor, Codex, Gemini CLI и ИИ агентов кодирования. إطار العمل التوجيهي Agentic هو حل منهجي وتجارب أولية للمطورين، مع بوابات جودة للفأرة، Codex، Gemini CLI ووكلاء الترميز الذكاء الاصطناعي. Agentic coding framework powered by AGENTS.md — systematic, test-first workflows with quality gates for Cursor, Codex, Gemini CLI, and AI coding agents. AI智能代理开发 Agentic框架 自动化开发工具 如何使用AI代理 AI代理安装指南 AI代理与传统开发工具的比较 Agentic coding framework powered by AGENTS.md — systematic, test-first workflows with quality gates for Cursor, Codex, Gemini CLI, and AI coding agents.');
