INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dipenmagdani/portfolio-v2/programmatic-seo', 'programmatic-seo', 'dipenmagdani', 'portfolio-v2', 'community', 'programmatic-seo dipenmagdani portfolio-v2 community 程序化SEO是一种利用AI智能工具自动化SEO优化的技术，用于提高开发效率和网站性能 プログラムSEOは、AIエージェントを利用してSEO最適化を自動化する技術で、開発効率とウェブサイトパフォーマンスを向上 프로그래밍 SEO는 AI 에이전트를 사용하여 SEO 최적화를 자동화하는 기술로 개발 효율성과 웹사이트 성능을 향상 Mi Portfolio presenta herramientas de SEO programático para desarrolladores, mejorando la optimización de sitios web con AI Agentes Mon Portfolio présente des outils de SEO programmé pour les développeurs, améliorant l''optimisation des sites web avec des agents IA Mein Portfolio präsentiert programmatische SEO-Tools für Entwickler, verbessert die Optimierung von Websites mit KI-Agents O programa de SEO programático oferece soluções técnicas para desenvolvedores ИИ Агенты для программного SEO предоставляют технические решения для разработчиков أدوات إدارة محركات البحث البرمجية تقدم حلول تقنية للمانحين My Portfolio 程序化SEO AI智能工具 SEO优化 开发效率 网站性能 React Node.js CLI工具 My Portfolio');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PaoloQuaranta/Webarmonium/copywriting', 'community', 'PaoloQuaranta', 'Webarmonium', 'PaoloQuaranta/Webarmonium', 'copywriting', 0, 0, 50, '2026-03-05T06:20:06.322Z', '2026-03-05T09:00:53.182Z', '5b3ea76961e8de82f00083569f4ef275058afb70bb301a9153dd80f73837b18e', '{"id":"PaoloQuaranta/Webarmonium/copywriting","name":"copywriting","description":{"zh":"Webarmonium是一种实时音乐生成工具，使用互联网活动数据创建音乐，并支持通过手势进行协作音乐创作","ja":"Webarmoniumは、インターネットアクティビティデータからリアルタイム音楽を生成するツールで、ジェスチャーによるコラボレーション音楽制作を可能にします","ko":"Webarmonium은 인터넷 활동 데이터에서 실시간 음악을 생성하는 도구로, 제스처를 통한 협력 음악 제작을 지원합니다","es":"Webarmonium es una herramienta de inteligencia artificial que genera música en tiempo real a partir de la actividad en internet y permite la creación colaborativa de música","fr":"Webarmonium est un outil d''intelligence artificielle qui génère de la musique en temps réel à partir de l''activité sur internet et permet la création collaborative de musique","de":"Webarmonium ist ein KI-Tool, das in Echtzeit Musik aus Internet-Aktivität generiert und kollaborative Musikgestaltung ermöglicht","pt":"Webarmonium é uma ferramenta de IA que gera música em tempo real a partir de dados da internet, permitindo a criação colaborativa de música por meio de gestos","ru":"Webarmonium - это инструмент ИИ, который генерирует музыку в реальном времени из данных из интернета, ermöglicht совместное создание музыки с помощью жестов","ar":"Webarmonium هي أداة ذكاء اصطناعي ت توليد موسيقى في الوقت الحقيقي من بيانات الإنترنت، وتسمح بالتعاون في إنشاء الموسيقى من خلال الإشارات","en":"Real-time generative music from internet activity.  Webarmonium transforms live data streams into music and enables collaborative music creation through gestures. No account needed, completely free."},"seo":{"title":{"zh":"AI智能音乐工具 - Webarmonium","ja":"AIエージェントによるリアルタイム音楽生成 - Webarmonium","ko":"AI 에이전트를 사용한 실시간 음악 생성 - Webarmonium","es":"Herramientas de inteligencia artificial para copywriting","fr":"Outils d''intelligence artificielle pour la création de co...","de":"KI-Tools für Copywriting und Musikgenerierung","pt":"Ferramentas de IA: Copywriting com Webarmonium","ru":"ИИ Агенты: Copywriting с Webarmonium","ar":"أدوات الذكاء الاصطناعي: كتابة المحتوى مع Webarmonium","en":"copywriting"},"description":{"zh":"Webarmonium是一种实时音乐生成工具，使用互联网活动数据创建音乐，并支持通过手势进行协作音乐创作","ja":"Webarmoniumは、インターネットアクティビティデータからリアルタイム音楽を生成するツールで、ジェスチャーによるコラボレーション音楽制作を可能にします","ko":"Webarmonium은 인터넷 활동 데이터에서 실시간 음악을 생성하는 도구로, 제스처를 통한 협력 음악 제작을 지원합니다","es":"Webarmonium es una herramienta de inteligencia artificial que genera música en tiempo real a partir de la actividad en internet y permite la creación colabor...","fr":"Webarmonium est un outil d''intelligence artificielle qui génère de la musique en temps réel à partir de l''activité sur internet et permet la création collabo...","de":"Webarmonium ist ein KI-Tool, das in Echtzeit Musik aus Internet-Aktivität generiert und kollaborative Musikgestaltung ermöglicht","pt":"Webarmonium é uma ferramenta de IA que gera música em tempo real a partir de dados da internet, permitindo a criação colaborativa de música por meio de gestos","ru":"Webarmonium - это инструмент ИИ, который генерирует музыку в реальном времени из данных из интернета, ermöglicht совместное создание музыки с помощью жестов","ar":"Webarmonium هي أداة ذكاء اصطناعي ت توليد موسيقى في الوقت الحقيقي من بيانات الإنترنت، وتسمح بالتعاون في إنشاء الموسيقى من خلال الإشارات","en":"Real-time generative music from internet activity.  Webarmonium transforms live data streams into music and enables collaborative music creation through gest..."},"definition":{"en":"Real-time generative music from internet activity.  Webarmonium transforms live data streams into music and enables collaborative music creation through gestures. No account needed, completely free."},"features":{"zh":["实时音乐生成","协作音乐创作","无需注册","完全免费","使用互联网活动数据"],"ja":["リアルタイム音楽生成","コラボレーション音楽制作","アカウント不要","完全無料","インターネットアクティビティデータを使用"],"ko":["실시간 음악 생성","협력 음악 제작","회원가입 없이 사용 가능","완전 무료","인터넷 활동 데이터 사용"],"es":["Generación de música en tiempo real","Creación colaborativa de música","Transformación de datos en vivo en música","Gestos para la creación de música","Acceso gratuito sin cuenta necesaria"],"fr":["Génération de musique en temps réel","Création collaborative de musique","Transformation de flux de données en musique","Gestes pour la création de musique","Accès gratuit sans compte nécessaire"],"de":["Echtzeit-Musikgenerierung","Kollaborative Musikgestaltung","Verwandlung von Live-Daten in Musik","Gesten für die Musikgestaltung","Kostenloser Zugang ohne Benutzerkonto"],"pt":["Geração de música em tempo real","Criação colaborativa de música por meio de gestos","Não requer conta ou registro","Completamente gratuito","Transformação de dados da internet em música","Interação em tempo real"],"ru":["Генерация музыки в реальном времени","Совместное создание музыки с помощью жестов","Не требует учетной записи или регистрации","Полностью бесплатно","Преобразование данных из интернета в музыку","Взаимодействие в реальном времени"],"ar":["توليد موسيقى في الوقت الحقيقي","إنشاء موسيقى تعاونية من خلال الإشارات","لا يتطلب حساب أو تسجيل","مجانًا تمامًا","تحويل بيانات الإنترنت إلى موسيقى","التفاعل في الوقت الحقيقي"]},"keywords":{"zh":["AI智能音乐工具","实时音乐生成","协作音乐创作","Webarmonium教程","如何使用Webarmonium","Webarmonium替代品","Webarmonium安装","Webarmonium设置指南"],"ja":["AIエージェントによる音楽生成","リアルタイム音楽生成","コラボレーション音楽制作","Webarmoniumの使い方","Webarmoniumの代替","Webarmoniumのインストール","Webarmoniumの設定方法"],"ko":["AI 에이전트를 사용한 음악 생성","실시간 음악 생성","협력 음악 제작","Webarmonium 사용법","Webarmonium 대안","Webarmonium 설치","Webarmonium 설정 가이드"],"es":["herramientas de inteligencia artificial para copywriting","cómo usar Webarmonium","qué es la generación de música en tiempo real","Webarmonium alternativa","Webarmonium vs otras herramientas de música","instalación de Webarmonium","guía de configuración de Webarmonium"],"fr":["outils d''intelligence artificielle pour la création de contenu","comment utiliser Webarmonium","qu''est-ce que la génération de musique en temps réel","Webarmonium alternative","Webarmonium vs autres outils de musique","installation de Webarmonium","guide de configuration de Webarmonium"],"de":["KI-Tools für Copywriting und Musikgenerierung","wie man Webarmonium verwendet","was ist Echtzeit-Musikgenerierung","Webarmonium-Alternative","Webarmonium vs andere Musik-Tools","Webarmonium-Installation","Webarmonium-Konfigurationsanleitung"],"pt":["ferramentas de IA","copywriting","geração de música em tempo real","criação colaborativa de música","Webarmonium alternative","Webarmonium vs outras ferramentas de IA","como usar Webarmonium","o que é Webarmonium","Webarmonium instalação","Webarmonium setup guide"],"ru":["ИИ Агенты","copywriting","генерация музыки в реальном времени","совместное создание музыки","Webarmonium альтернатива","Webarmonium vs другие инструменты ИИ","как использовать Webarmonium","что такое Webarmonium","Webarmonium установка","Webarmonium руководство по настройке"],"ar":["أدوات الذكاء الاصطناعي","كتابة المحتوى","توليد موسيقى في الوقت الحقيقي","إنشاء موسيقى تعاونية","Webarmonium بديل","Webarmonium مقابل أدوات الذكاء الاصطناعي الأخرى","كيفية استخدام Webarmonium","ما هو Webarmonium","Webarmonium تثبيت","Webarmonium دليل الإعداد"]}},"owner":"PaoloQuaranta","repo":"Webarmonium","repoPath":"PaoloQuaranta/Webarmonium","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.322Z","topics":[],"category":"community","skillMd":{"name":"copywriting","description":"When the user wants to write, rewrite, or improve marketing copy for any page — including homepage, landing pages, pricing pages, feature pages, about pages, or product pages. Also use when the user says write copy for, improve this copy, rewrite this page, marketing copy, headline help, or CTA copy. For email copy, see email-sequence. For popup copy, see popup-cro.","bodyPreview":"# Copywriting\n\nYou are an expert conversion copywriter. Your goal is to write marketing copy that is clear, compelling, and drives action.\n\n## Before Writing\n\nGather this context (ask if not provided):\n\n### 1. Page Purpose\n- What type of page is this? (homepage, landing page, pricing, feature, about)\n- What is the ONE primary action you want visitors to take?\n- What''s the secondary action (if any)?\n\n### 2. Audience\n- Who is the ideal customer for this page?\n- What problem are they trying to solv","body":"# Copywriting\n\nYou are an expert conversion copywriter. Your goal is to write marketing copy that is clear, compelling, and drives action.\n\n## Before Writing\n\nGather this context (ask if not provided):\n\n### 1. Page Purpose\n- What type of page is this? (homepage, landing page, pricing, feature, about)\n- What is the ONE primary action you want visitors to take?\n- What''s the secondary action (if any)?\n\n### 2. Audience\n- Who is the ideal customer for this page?\n- What problem are they trying to solve?\n- What have they already tried?\n- What objections or hesitations do they have?\n- What language do they use to describe their problem?\n\n### 3. Product/Offer\n- What are you selling or offering?\n- What makes it different from alternatives?\n- What''s the key transformation or outcome?\n- Any proof points (numbers, testimonials, case studies)?\n\n### 4. Context\n- Where is traffic coming from? (ads, organic, email)\n- What do visitors already know before arriving?\n- What messaging are they seeing before this page?\n\n---\n\n## Copywriting Principles\n\n### Clarity Over Cleverness\n- If you have to choose between clear and creative, choose clear\n- Every sentence should have one job\n- Remove words that don''t add meaning\n\n### Benefits Over Features\n- Features: What it does\n- Benefits: What that means for the customer\n- Always connect features to outcomes\n\n### Specificity Over Vagueness\n- Vague: \"Save time on your workflow\"\n- Specific: \"Cut your weekly reporting from 4 hours to 15 minutes\"\n\n### Customer Language Over Company Language\n- Use words your customers use\n- Avoid jargon unless your audience uses it\n- Mirror voice-of-customer from reviews, interviews, support tickets\n\n### One Idea Per Section\n- Don''t try to say everything everywhere\n- Each section should advance one argument\n- Build a logical flow down the page\n\n---\n\n## Writing Style Rules\n\nFollow these core principles. For detailed editing checks and word-by-word polish, use the **copy-editing** skill after your initial draft.\n\n### Core Style Principles\n\n1. **Simple over complex** — Use everyday words. \"Use\" instead of \"utilize,\" \"help\" instead of \"facilitate.\"\n\n2. **Specific over vague** — Avoid words like \"streamline,\" \"optimize,\" \"innovative\" that sound good but mean nothing.\n\n3. **Active over passive** — \"We generate reports\" not \"Reports are generated.\"\n\n4. **Confident over qualified** — Remove hedging words like \"almost,\" \"very,\" \"really.\"\n\n5. **Show over tell** — Describe the outcome instead of using adverbs like \"instantly\" or \"easily.\"\n\n6. **Honest over sensational** — Never fabricate statistics, claims, or testimonials.\n\n### Quick Quality Check\n\nBefore finalizing, scan for:\n- Jargon that could confuse outsiders\n- Sentences trying to do too much (max 3 conjunctions)\n- Passive voice constructions\n- Exclamation points (remove them)\n- Marketing buzzwords without substance\n\nFor a thorough line-by-line review, run the copy through the **copy-editing** skill''s Seven Sweeps framework.\n\n---\n\n## Best Practices\n\n### Be Direct\nGet to the point. Don''t bury the value in qualifications.\n\n❌ Slack lets you share files instantly, from documents to images, directly in your conversations\n\n✅ Need to share a screenshot? Send as many documents, images, and audio files as your heart desires.\n\n### Use Rhetorical Questions\nQuestions engage readers and make them think about their own situation.\n\n✅ Hate returning stuff to Amazon?\n\n✅ Need to share a screenshot?\n\n✅ Tired of chasing approvals?\n\n### Use Analogies and Metaphors\nWhen appropriate, analogies make abstract concepts concrete and memorable.\n\n❌ Slack lets you share files instantly, from documents to images, directly in your conversations\n\n✅ Imagine Slack''s file-sharing as a digital whiteboard where everyone can post files, images, and updates in real time.\n\n### Pepper in Humor (When Appropriate)\nPuns, wit, and humor make copy memorable—but only if it fits the brand and doesn''t undermine clarity.\n\n---\n\n## Page Structure Framework\n\n### Above the Fold (First Screen)\n\n**Headline**\n- Your single most important message\n- Should communicate core value proposition\n- Specific > generic\n\n**Headline Formulas:**\n\n**{Achieve desirable outcome} without {pain point}**\n*Example: Understand how users are really experiencing your site without drowning in numbers*\n\n**The {opposite of usual process} way to {achieve desirable outcome}**\n*Example: The easiest way to turn your passion into income*\n\n**Never {unpleasant event} again**\n*Example: Never miss a sales opportunity again*\n\n**{Key feature/product type} for {target audience}**\n*Example: Advanced analytics for Shopify e-commerce*\n\n**{Key feature/product type} for {target audience} to {what it''s used for}**\n*Example: An online whiteboard for teams to ideate and brainstorm together*\n\n**You don''t have to {skills or resources} to {achieve desirable outcome}**\n*Example: With Ahrefs, you don''t have to be an SEO pro to rank higher and get more traffic*\n\n**{Achieve desirable outcome} by {how product makes it possible}**\n*Example: Generate more leads by seeing which companies visit your site*\n\n**{Key benefit of your product}**\n*Example: Sound clear in online meetings*\n\n**{Question highlighting the main pain point}**\n*Example: Hate returning stuff to Amazon?*\n\n**Turn {input} into {outcome}**\n*Example: Turn your hard-earned sales into repeat customers*\n\n**Additional formulas:**\n- \"[Achieve outcome] in [timeframe]\"\n- \"The [category] that [key differentiator]\"\n- \"Stop [pain]. Start [pleasure].\"\n- \"[Number] [people] use [product] to [outcome]\"\n\n**Subheadline**\n- Expands on the headline\n- Adds specificity or addresses secondary concern\n- 1-2 sentences max\n\n**Primary CTA**\n- Action-oriented button text\n- Communicate what they get, not what they do\n- \"Start Free Trial\" > \"Sign Up\"\n- \"Get Your Report\" > \"Submit\"\n\n**Supporting Visual**\n- Product screenshot, demo, or hero image\n- Should reinforce the message, not distract\n\n### Social Proof Section\n\nOptions (use 1-2):\n- Customer logos (recognizable > many)\n- Key metric (\"10,000+ teams\")\n- Short testimonial with attribution\n- Star rating with review count\n\n### Problem/Pain Section\n\n- Articulate the problem better than they can\n- Show you understand their situation\n- Create recognition (\"that''s exactly my problem\")\n\nStructure:\n- \"You know the feeling...\" or \"If you''re like most [role]...\"\n- Describe the specific frustrations\n- Hint at the cost of not solving it\n\n### Solution/Benefits Section\n\n- Bridge from problem to your solution\n- Focus on 3-5 key benefits (not 10)\n- Each benefit: headline + short explanation + proof point if available\n\nFormat options:\n- Benefit blocks with icons\n- Before/after comparison\n- Feature → Benefit → Proof structure\n\n### How It Works Section\n\n- Reduce perceived complexity\n- 3-4 step process\n- Each step: simple action + outcome\n\nExample:\n1. \"Connect your tools (2 minutes)\"\n2. \"Set your preferences\"\n3. \"Get automated reports every Monday\"\n\n### Social Proof (Detailed)\n\n- Full testimonials with:\n  - Specific results\n  - Customer name, role, company\n  - Photo if possible\n- Case study snippets\n- Logos section (if not above)\n\n### Objection Handling\n\nCommon objections to address:\n- \"Is this right for my situation?\"\n- \"What if it doesn''t work?\"\n- \"Is it hard to set up?\"\n- \"How is this different from X?\"\n\nFormats:\n- FAQ section\n- Comparison table\n- Guarantee/promise section\n- \"Built for [specific audience]\" section\n\n### Final CTA Section\n\n- Recap the value proposition\n- Repeat the primary CTA\n- Add urgency if genuine (deadline, limited availability)\n- Risk reversal (guarantee, free trial, no credit card)\n\n---\n\n## Landing Page Section Variety\n\nA great landing page isn''t just a list of features. Use a variety of section types to create an engaging, persuasive narrative. Mix and match from these:\n\n### Section Types to Include\n\n**How It Works (Numbered Steps)**\nWalk users through the process in 3-4 clear steps. Reduces perceived complexity and shows the path to value.\n\n**Alternative/Competitor Comparison**\nShow how you stack up against the status quo or competitors. Tables, side-by-side comparisons, or \"Unlike X, we...\" sections.\n\n**Founder Manifesto / Our Story**\nShare why you built this and what you believe. Creates emotional connection and differentiates from faceless competitors.\n\n**Testimonials**\nCustomer quotes with names, photos, and specific results. Multiple formats: quote cards, video testimonials, tweet embeds.\n\n**Case Studies**\nDeeper stories of customer success. Problem → Solution → Results format with specific metrics.\n\n**Use Cases**\nShow different ways the product is used. Helps visitors self-identify: \"This is for people like me.\"\n\n**Personas / \"Built For\" Sections**\nExplicitly call out who the product is for: \"Perfect for marketers,\" \"Built for agencies,\" etc.\n\n**Stats and Social Proof**\nKey metrics that build credibility: \"10,000+ customers,\" \"4.9/5 rating,\" \"$2M saved for customers.\"\n\n**Demo / Product Tour**\nInteractive demos, video walkthroughs, or GIF previews showing the product in action.\n\n**FAQ Section**\nAddress common objections and questions. Good for SEO and reducing support burden.\n\n**Integrations / Partners**\nShow what tools you connect with. Logos build credibility and answer \"Will this work with my stack?\"\n\n**Pricing Preview**\nEven on non-pricing pages, a pricing teaser can move decision-makers forward.\n\n**Guarantee / Risk Reversal**\nMoney-back guarantee, free trial terms, or \"cancel anytime\" messaging reduces friction.\n\n### Recommended Section Mix\n\nFor a landing page, aim for variety. Don''t just stack features:\n\n**Typical Feature-Heavy Page (Weak):**\n1. Hero\n2. Feature 1\n3. Feature 2\n4. Feature 3\n5. Feature 4\n6. CTA\n\n**Varied, Engaging Page (Strong):**\n1. Hero with clear value prop\n2. Social proof bar (logos or stats)\n3. Problem/pain section\n4. How it works (3 steps)\n5. Key benefits (2-3, not 10)\n6. Testimonial\n7. Use cases or personas\n8. Comparison to alternatives\n9. Case study snippet\n10. FAQ\n11. Final CTA with guarantee\n\n---\n\n## CTA Copy Guidelines\n\n**Weak CTAs (avoid):**\n- Submit\n- Sign Up\n- Learn More\n- Click Here\n- Get Started\n\n**Strong CTAs (use):**\n- Start Free Trial\n- Get [Specific Thing]\n- See [Product] in Action\n- Create Your First [Thing]\n- Book My Demo\n- Download the Guide\n- Try It Free\n\n**CTA formula:**\n[Action Verb] + [What They Get] + [Qualifier if needed]\n\nExamples:\n- \"Start My Free Trial\"\n- \"Get the Complete Checklist\"\n- \"See Pricing for My Team\"\n\n---\n\n## Output Format\n\nWhen writing copy, provide:\n\n### Page Copy\nOrganized by section with clear labels:\n- Headline\n- Subheadline\n- CTA\n- Section headers\n- Body copy\n- Secondary CTAs\n\n### Annotations\nFor key elements, explain:\n- Why you made this choice\n- What principle it applies\n- Alternatives considered\n\n### Alternatives\nFor headlines and CTAs, provide 2-3 options:\n- Option A: [copy] — [rationale]\n- Option B: [copy] — [rationale]\n- Option C: [copy] — [rationale]\n\n### Meta Content (if relevant)\n- Page title (for SEO)\n- Meta description\n\n---\n\n## Page-Specific Guidance\n\n### Homepage Copy\n- Serve multiple audiences without being generic\n- Lead with broadest value proposition\n- Provide clear paths for different visitor intents\n- Balance \"ready to buy\" and \"still researching\"\n\n### Landing Page Copy\n- Single message, single CTA\n- Match headline to ad/traffic source\n- Complete argument on one page\n- Remove distractions (often no nav)\n\n### Pricing Page Copy\n- Help visitors choose the right plan\n- Clarify what''s included at each level\n- Address \"which is right for me?\" anxiety\n- Make recommended plan obvious\n\n### Feature Page Copy\n- Connect feature to benefit to outcome\n- Show use cases and examples\n- Differentiate from competitors'' versions\n- Clear path to try or buy\n\n### About Page Copy\n- Tell the story of why you exist\n- Connect company mission to customer benefit\n- Build trust through transparency\n- Still include a CTA (it''s still a marketing page)\n\n---\n\n## Voice and Tone Considerations\n\nBefore writing, establish:\n\n**Formality level:**\n- Casual/conversational\n- Professional but friendly\n- Formal/enterprise\n\n**Brand personality:**\n- Playful or serious?\n- Bold or understated?\n- Technical or accessible?\n\nMaintain consistency throughout, but adjust intensity:\n- Headlines can be bolder\n- Body copy should be clearer\n- CTAs should be action-oriented\n\n---\n\n## Related Skills\n\n- **copy-editing**: For polishing and improving existing copy (use after writing your first draft)\n- **page-cro**: If the page structure/strategy needs work, not just copy\n- **email-sequence**: For email copywriting\n- **popup-cro**: For popup and modal copy\n- **ab-test-setup**: To test copy variations properly\n"},"lastSynced":"2026-03-05T09:00:53.182Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing persuasive marketing content generation.","zh":"非常适合需要说服性营销内容生成的语言代理。","ja":"説得力のあるマーケティングコンテンツ生成が必要な言語エージェントに最適。","ko":"説得력을 가진 마케팅 콘텐츠 생성이 필요한 언어 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan generación de contenido de marketing persuasivo.","fr":"Parfait pour les Agents de Langage ayant besoin de génération de contenu de marketing persuasif.","de":"Perfekt für Sprachagenten, die persuasive Marketing-Inhalte generieren müssen.","pt":"Perfeito para Agentes de Linguagem que precisam de geração de conteúdo de marketing persuasivo.","ru":"Идеально подходит для языковых агентов, которым требуется создание убедительного маркетингового контента.","ar":"مثالي لعميل اللغة الذي يحتاج إلى إنشاء محتوى تسويقي مقنع."},"recommendation":{"en":"Empowers agents to craft compelling landing pages using clear and actionable language, driving visitor conversions through optimized page purposes and targeted audience analysis, leveraging context-aware copywriting techniques.","zh":"赋予代理人使用清晰和可行的语言来创建引人入胜的登陆页面的能力，通过优化页面用途和目标受众分析来驱动访问者转化，并利用上下文感知的复制写作技术。","ja":"エージェントが明確で実行可能な言語を使用して魅力的なランディングページを作成する能力を付与し、ページの目的とターゲットオーディエンス分析を最適化して訪問者を転換させ、コンテキストアウェアのコピーライティング技術を利用する。","ko":"에이전트가 명확하고 실행 가능한 언어를 사용하여 매력적인 랜딩 페이지를 생성하도록 하는 기능을 제공하여 방문자 전환을 최적화된 페이지 목적과 대상 오디언스 분석을 통해 구동하며, 컨텍스트 인식 복사 작성 기술을 활용합니다.","es":"Habilita a los agentes a crear páginas de destino atractivas utilizando un lenguaje claro y accionable, impulsando las conversiones de visitantes a través de propósitos de página optimizados y análisis de audiencia dirigida, aprovechando técnicas de redacción de copias conscientes del contexto.","fr":"Permet aux agents de créer des pages de destination convaincantes en utilisant un langage clair et actionnable, stimulant les conversions de visiteurs à travers des objectifs de page optimisés et une analyse d''audience ciblée, en exploitant des techniques de rédaction de copies sensibles au contexte.","de":"Ermächtigt Agenten, überzeugende Landingpages mit klarer und handlungsorientierter Sprache zu erstellen, um Besucherumwandlungen durch optimierte Seitenzwecke und zielgruppenspezifische Analyse zu fördern, indem kontextbewusste Kopierschreibtechniken genutzt werden.","pt":"Habilita os agentes a criar páginas de destino atraentes usando linguagem clara e ação, impulsionando conversões de visitantes por meio de propósitos de página otimizados e análise de público-alvo direcionada, aproveitando técnicas de criação de cópias sensíveis ao contexto.","ru":"Наделяет агентов возможностью создавать привлекательные страницы приземления, используя ясный и действенный язык, стимулируя конверсии посетителей за счет оптимизированных целей страниц и целевой анализа аудитории, используя контекстно-зависимые методы копирайтинга.","ar":"يمنح الوكلاء khảية إنشاء صفحات هبوط جذابة باستخدام لغة واضحة وفعّالة، مما يدفع تحويلات الزوار من خلال أغراض صفحة محسنة وتحليل جمهور مستهدف، واستخدام تقنيات كتابة نسخ متوافقة مع السياق."},"useCases":{"en":["Generating high-converting homepage copy","Crafting engaging landing page content","Optimizing feature page descriptions for clarity"],"zh":["生成高转化率的首页复制","创建引人入胜的登陆页面内容","优化功能页面描述以提高清晰度"],"ja":["高転換率のホームページコピーを生成する","魅力的なランディングページコンテンツを作成する","機能ページの説明を明確化するために最適化する"],"ko":["고 전환률의 홈페이지 복사 생성"," 매력적인 랜딩 페이지 콘텐츠 작성","기능 페이지 설명을 명확하게 하기 위한 최적화"],"es":["Generación de copias de inicio de página de alta conversión","Creación de contenido de página de destino atractivo","Optimización de descripciones de página de características para mayor claridad"],"fr":["Génération de copies de page d''accueil à forte conversion","Création de contenu de page de destination engageant","Optimisation des descriptions de page de fonctionnalités pour plus de clarté"],"de":["Generierung von hochkonvertierenden Startseitencopys","Erstellung von ansprechendem Landingpage-Inhalt","Optimierung von Beschreibungen von Funktionsseiten für bessere Klarheit"],"pt":["Geração de cópia de página inicial de alto rendimento","Criação de conteúdo de página de destino atraente","Otimização de descrições de página de recursos para clareza"],"ru":["Генерация копии домашней страницы с высоким уровнем конверсии","Создание привлекательного контента страницы приземления","Оптимизация описаний страницы функций для ясности"],"ar":["إنشاء نسخة صفحة رئيسية تحويل عالية","إنشاء محتوى صفحة هبوط جذاب","تحسين وصفات صفحة الميزات للوضوح"]},"limitations":{"en":["Requires specific audience and page purpose context","Limited to text-based marketing content"],"zh":["需要特定的受众和页面用途上下文","仅限于基于文本的营销内容"],"ja":["特定のオーディエンスとページ目的のコンテキストが必要","テキストベースのマーケティングコンテンツのみ"],"ko":["특정 오디언스와 페이지 목적의 컨텍스트가 필요","텍스트 기반 마케팅 콘텐츠에만 제한"],"es":["Requiere un contexto específico de audiencia y propósito de página","Limitado a contenido de marketing basado en texto"],"fr":["Nécessite un contexte spécifique d''audience et d''objectif de page","Limité au contenu de marketing basé sur le texte"],"de":["Benötigt einen spezifischen Kontext für Zielgruppe und Seitenzweck","Begrenzt auf textbasierten Marketing-Inhalt"],"pt":["Exige contexto específico de público e propósito da página","Limitado a conteúdo de marketing baseado em texto"],"ru":["Требует конкретного контекста аудитории и цели страницы","Ограничен контентом маркетинга на основе текста"],"ar":["يتطلب سياقًا محددًا للجمهور وغرض الصفحة","محدود بمحتوى التسويق القائم على النص"]},"version":3},"contentHash":"5b3ea76961e8de82f00083569f4ef275058afb70bb301a9153dd80f73837b18e","qualityScore":50}');
