INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PaoloQuaranta/Webarmonium/copywriting', 'copywriting', 'PaoloQuaranta', 'Webarmonium', 'community', 'copywriting PaoloQuaranta Webarmonium community Webarmonium是一种实时音乐生成工具，使用互联网活动数据创建音乐，并支持通过手势进行协作音乐创作 Webarmoniumは、インターネットアクティビティデータからリアルタイム音楽を生成するツールで、ジェスチャーによるコラボレーション音楽制作を可能にします Webarmonium은 인터넷 활동 데이터에서 실시간 음악을 생성하는 도구로, 제스처를 통한 협력 음악 제작을 지원합니다 Webarmonium es una herramienta de inteligencia artificial que genera música en tiempo real a partir de la actividad en internet y permite la creación colaborativa de música Webarmonium est un outil d''intelligence artificielle qui génère de la musique en temps réel à partir de l''activité sur internet et permet la création collaborative de musique Webarmonium ist ein KI-Tool, das in Echtzeit Musik aus Internet-Aktivität generiert und kollaborative Musikgestaltung ermöglicht Webarmonium é uma ferramenta de IA que gera música em tempo real a partir de dados da internet, permitindo a criação colaborativa de música por meio de gestos Webarmonium - это инструмент ИИ, который генерирует музыку в реальном времени из данных из интернета, ermöglicht совместное создание музыки с помощью жестов Webarmonium هي أداة ذكاء اصطناعي ت توليد موسيقى في الوقت الحقيقي من بيانات الإنترنت، وتسمح بالتعاون في إنشاء الموسيقى من خلال الإشارات Real-time generative music from internet activity. Webarmonium transforms live data streams into music and enables collaborative music creation through gestures. No account needed, completely free. AI智能音乐工具 实时音乐生成 协作音乐创作 Webarmonium教程 如何使用Webarmonium Webarmonium替代品 Webarmonium安装 Webarmonium设置指南 Real-time generative music from internet activity. Webarmonium transforms live data streams into music and enables collaborative music creation through gestures. No account needed, completely free.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/binary-re', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'binary-re', 0, 0, 50, '2026-02-20T04:13:19.574Z', '2026-02-20T04:33:33.382Z', '779a12efde05da3712fd34fa2dfcc7e6377da29ba17e2346fc24534951365a04', '{"id":"aiskillstore/marketplace/binary-re","name":"binary-re","description":{"zh":"二进制逆向工程是一种分析二进制代码的方法。这个技能提供了综合的方法、哲学和参考资料。","ja":"バイナリリバースエンジニアリングは、バイナリコードを分析する方法です。このスキルは、包括的な方法、哲学、参考資料を提供します。","ko":"이진 역공학은 이진 코드를 분석하는 방법입니다. 이 스킬은 종합적인 방법, 철학 및 참고 자료를 제공합니다.","es":"Guía completa para ingeniería inversa de binarios, cubriendo la metodología, filosofía y materiales de referencia. Incluye enlaces a habilidades relacionadas para fases específicas.","fr":"Guide complet pour l''ingénierie inverse de binaires, couvrant la méthodologie, la philosophie et les matériaux de référence. Inclut des liens vers des compétences liées pour des phases spécifiques.","de":"Umfassender Leitfaden für Binär-Reversing, der Methodik, Philosophie und Referenzmaterial abdeckt. Enthält Links zu verwandten Fähigkeiten für spezifische Phasen.","pt":"Engenharia reversa de binários é uma técnica usada para entender e analisar código binário. Nossa guia fornece uma visão geral da metodologia e filosofia por trás dessa técnica.","ru":"Обратная инженерия бинарных файлов - это метод, используемый для понимания и анализа бинарного кода. Наша гида дает обзор методологии и философии, лежащих в основе этого метода.","ar":"هندسة عكسية ثنائية هي تقنية تستخدم لفهم وتحليل الشفرة الثنائية. دليلنا يوفر نظرة عامة على المنهجية والفلسفة وراء هذه التقنية.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"二进制逆向工程 - 全面指南","ja":"バイナリリバースエンジニアリング - 包括的なガイド","ko":"이진 역공학 - 종합 가이드","es":"Ingeniería inversa de binarios: Guía y recursos","fr":"Ingénierie inverse de binaires : Guide et ressources","de":"Binär-Reversing: Leitfaden und Ressourcen","pt":"Engenharia Reversa de Binários","ru":"Обратная Инженерия Бинарных Файлов","ar":"هندسة عكسية ثنائية","en":"binary-re"},"description":{"zh":"二进制逆向工程是一种分析二进制代码的方法。这个技能提供了综合的方法、哲学和参考资料。","ja":"バイナリリバースエンジニアリングは、バイナリコードを分析する方法です。このスキルは、包括的な方法、哲学、参考資料を提供します。","ko":"이진 역공학은 이진 코드를 분석하는 방법입니다. 이 스킬은 종합적인 방법, 철학 및 참고 자료를 제공합니다.","es":"Guía completa para ingeniería inversa de binarios, cubriendo la metodología, filosofía y materiales de referencia. Incluye enlaces a habilidades relacionadas...","fr":"Guide complet pour l''ingénierie inverse de binaires, couvrant la méthodologie, la philosophie et les matériaux de référence. Inclut des liens vers des compét...","de":"Umfassender Leitfaden für Binär-Reversing, der Methodik, Philosophie und Referenzmaterial abdeckt. Enthält Links zu verwandten Fähigkeiten für spezifische Ph...","pt":"Engenharia reversa de binários é uma técnica usada para entender e analisar código binário. Nossa guia fornece uma visão geral da metodologia e filosofia por...","ru":"Обратная инженерия бинарных файлов - это метод, используемый для понимания и анализа бинарного кода. Наша гида дает обзор методологии и философии, лежащих в ...","ar":"هندسة عكسية ثنائية هي تقنية تستخدم لفهم وتحليل الشفرة الثنائية. دليلنا يوفر نظرة عامة على المنهجية والفلسفة وراء هذه التقنية.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"definition":{"en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"features":{"zh":["全面指南","快速指纹识别","静态分析","方法和哲学","参考资料"],"ja":["包括的なガイド","高速フィンガープリント認識","静的分析","方法と哲学","参考資料"],"ko":["종합 가이드","빠른 지문 인식","정적 분석","방법과 철학","참고 자료"],"es":["Metodología de ingeniería inversa de binarios","Análisis de código binario con r2 y Ghidra","Identificación rápida de tipo de archivo y función","Desensamblado y descompilación de código","Recursos verificados para seguridad y calidad"],"fr":["Méthodologie d''ingénierie inverse de binaires","Analyse de code binaire avec r2 et Ghidra","Identification rapide du type de fichier et de la fonction","Désassemblage et décompilation de code","Ressources vérifiées pour la sécurité et la qualité"],"de":["Methodik für Binär-Reversing","Analyse von Binärcode mit r2 und Ghidra","Schnelle Identifizierung von Dateityp und Funktion","Disassemblieren und Dekompilieren von Code","Verifizierte Ressourcen für Sicherheit und Qualität"],"pt":["Metodologia de engenharia reversa de binários","Análise estática com r2 e Ghidra","Fingerprinting rápido","Identificação de tipo de arquivo","Desmontagem e Decompilação"],"ru":["Методология обратной инженерии бинарных файлов","Статический анализ с помощью r2 и Ghidra","Быстрое определение типа файла","Определение типа файла","Дизассемблирование и декомпиляция"],"ar":["منهجية هندسة عكسية ثنائية","تحليل ثابت باستخدام r2 و Ghidra","تحديد سريع لنوع الملف","تحديد نوع الملف","فك التجميع وافك التشفير"]},"keywords":{"zh":["二进制逆向工程","二进制代码分析","快速指纹识别","静态分析","逆向工程","代码分析"],"ja":["バイナリリバースエンジニアリング","バイナリコード分析","高速フィンガープリント認識","静的分析","逆向エンジニアリング","コード分析"],"ko":["이진 역공학","이진 코드 분석","빠른 지문 인식","정적 분석","역공학","코드 분석"],"es":["ingeniería inversa de binarios","análisis de código binario","seguridad informática","desensamblado de código","descompilación de código","r2","Ghidra","identificación de tipo de archivo"],"fr":["ingénierie inverse de binaires","analyse de code binaire","sécurité informatique","désassemblage de code","décompilation de code","r2","Ghidra","identification du type de fichier"],"de":["Binär-Reversing","Analyse von Binärcode","IT-Sicherheit","Disassemblieren von Code","Dekompilieren von Code","r2","Ghidra","Dateityp-Erkennung"],"pt":["engenharia reversa de binários","análise estática","r2","Ghidra","fingerprinting","identificação de tipo de arquivo","desmontagem","decompilação"],"ru":["обратная инженерия бинарных файлов","статический анализ","r2","Ghidra","быстрое определение типа файла","определение типа файла","дизассемблирование","декомпиляция"],"ar":["هندسة عكسية ثنائية","تحليل ثابت","r2","Ghidra","تحديد سريع لنوع الملف","تحديد نوع الملف","فك التجميع","افك التشفير"]}},"owner":"aiskillstore","repo":"marketplace","repoPath":"aiskillstore/marketplace","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.574Z","topics":[],"category":"community","skillMd":{"name":"binary-re","description":"This skill should be used when analyzing binaries, executables, or bytecode to understand what they do or how they work. Triggers on binary, executable, ELF, what does this do, reverse engineer, disassemble, decompile, pyc file, python bytecode, analyze binary, figure out, marshal. Routes to sub-skills for triage, static analysis, dynamic analysis, synthesis, or tool setup.","bodyPreview":"# Binary Reverse Engineering\n\n## Purpose\n\nComprehensive guide for binary reverse engineering. This skill provides the overall methodology, philosophy, and reference material. Related skills handle specific phases:\n\n## Related Skills\n\n| Skill | Purpose | Trigger Keywords |\n|-------|---------|------------------|\n| `binary-re:triage` | Fast fingerprinting | \"what is this binary\", \"identify\", \"file type\" |\n| `binary-re:static-analysis` | r2 + Ghidra analysis | \"disassemble\", \"decompile\", \"functions\"","body":"# Binary Reverse Engineering\n\n## Purpose\n\nComprehensive guide for binary reverse engineering. This skill provides the overall methodology, philosophy, and reference material. Related skills handle specific phases:\n\n## Related Skills\n\n| Skill | Purpose | Trigger Keywords |\n|-------|---------|------------------|\n| `binary-re:triage` | Fast fingerprinting | \"what is this binary\", \"identify\", \"file type\" |\n| `binary-re:static-analysis` | r2 + Ghidra analysis | \"disassemble\", \"decompile\", \"functions\" |\n| `binary-re:dynamic-analysis` | QEMU + GDB + Frida | \"run\", \"execute\", \"debug\", \"trace\" |\n| `binary-re:synthesis` | Report generation | \"summarize\", \"report\", \"document findings\" |\n| `binary-re:tool-setup` | Install tools | \"install\", \"setup\", \"tool not found\" |\n\n**Note:** Each skill auto-detects based on keywords. You don''t need to explicitly route - just ask what you need.\n\n## Pre-Flight Verification\n\n**Before beginning any analysis, verify tooling availability:**\n\n### Core Tools (Required)\n```bash\nrabin2 -v  # Should show version\nr2 -v      # Should show version\n```\n\n### Decompilation (Optional)\n```bash\n# Check r2ghidra availability\nr2 -qc ''pdg?'' - 2>/dev/null | grep -q Usage && echo \"r2ghidra OK\" || echo \"r2ghidra missing - install with: r2pm -ci r2ghidra\"\n```\n\n### Dynamic Analysis Platform Check\n| Host Platform | Method | Setup Required |\n|---------------|--------|----------------|\n| Linux x86_64 | Native QEMU | `apt install qemu-user` |\n| macOS (any) | Docker + binfmt | See `binary-re-tool-setup` skill |\n| Windows | WSL2 | Use Linux method inside WSL |\n\n**If dynamic tools unavailable:** Proceed with static-only analysis, note reduced confidence in synthesis phase.\n\n### Fallback Tooling (No r2/Ghidra)\n\nWhen radare2 or Ghidra aren''t available, use standard binutils/LLVM tools:\n\n```bash\n# Metadata (replaces rabin2 -I)\nreadelf -h binary              # ELF header\nreadelf -d binary              # Dynamic section (dependencies)\nfile binary                    # Quick identification\n\n# Imports/Exports (replaces rabin2 -i/-E)\nreadelf -Ws binary | grep -E \"FUNC|OBJECT\" | awk ''{print $8}''\nnm -D binary 2>/dev/null       # Dynamic symbols\n\n# Strings (replaces rabin2 -zz)\nstrings -a -n 8 binary | grep -Ei ''http|ftp|/etc|/var|error|pass|key|token|api''\n\n# Disassembly (replaces r2 pdf)\nobjdump -d -M intel binary | head -500\n# Or LLVM (better cross-arch support):\nllvm-objdump -d --no-show-raw-insn binary | head -500\n\n# Dependencies (replaces rabin2 -l)\nldd binary 2>/dev/null || readelf -d binary | grep NEEDED\n```\n\n**Limitations of fallback approach:**\n- No cross-references (axt/axf) - must trace manually\n- No decompilation - assembly only\n- No function boundary detection - raw disassembly\n- Reduced accuracy for stripped binaries\n\n---\n\n## Philosophy\n\n**The LLM drives analysis; the human provides context.**\n\nHuman provides:\n- Platform info (device type, OS, hardware)\n- Suspected purpose (what the binary might do)\n- Constraints (no network, isolated env, etc.)\n\nLLM executes:\n- Tool selection and invocation\n- Hypothesis formation from evidence\n- Experiment design\n- Knowledge synthesis\n\n## The Agentic Loop\n\n```\n┌─────────────────────────────────────────────────┐\n│           HYPOTHESIS-DRIVEN ANALYSIS            │\n├─────────────────────────────────────────────────┤\n│                                                 │\n│  0. I/O SANITY → Compare known inputs/outputs   │\n│  1. OBSERVE → Gather facts via tools            │\n│  2. HYPOTHESIZE → Form theories from facts      │\n│  3. PLAN → Design experiments to test theories  │\n│  4. EXECUTE → Run tools (gate risky ops)        │\n│  5. RECORD → Capture observations               │\n│  6. UPDATE → Confirm/refute hypotheses          │\n│  7. LOOP → Until understanding sufficient       │\n│                                                 │\n└─────────────────────────────────────────────────┘\n```\n\n### Step 0: Compare Known I/O First (CRITICAL)\n\n**Before diving into code analysis, always check if known inputs/outputs exist.**\n\nThis step prevents hours of wasted analysis by establishing ground truth first.\n\n⚠️ **REQUIRES HUMAN APPROVAL** - Even for I/O comparison, get explicit approval before execution.\n\n```bash\n# SAFE: Use emulation for cross-arch binaries (after human approval)\n# ARM32 example:\nqemu-arm -L /usr/arm-linux-gnueabihf -- ./binary input.txt > actual_output.txt\n\n# x86-64 native (still requires approval):\n./binary input.txt > actual_output.txt\n\n# Docker-based (macOS - safest option):\ndocker run --rm --platform linux/arm/v7 -v ~/samples:/work:ro \\\n  arm32v7/debian:bullseye-slim /work/binary /work/input.txt > actual_output.txt\n\n# Compare outputs:\ndiff expected_output.txt actual_output.txt\ncmp -l expected_output.txt actual_output.txt | head -20  # Byte-level\n\n# Document the delta:\n# - Where does output first diverge?\n# - What pattern appears in the corruption?\n# - Does file size match (logic bug) or differ (truncation)?\n```\n\n**Record as FACT:**\n```\nFACT: Output differs at byte {N}, expected \"{X}\" got \"{Y}\" (source: diff/cmp)\nFACT: File sizes match/differ by {N} bytes (source: ls -l)\n```\n\nThis single step often reveals the bug category before any disassembly.\n\n## Knowledge Model\n\nThroughout analysis, maintain structured knowledge via **episodic memory**:\n\n```\nFACTS: Verified observations with tool attribution\nHYPOTHESES: Theories with confidence and evidence\nQUESTIONS: Open unknowns blocking progress\nEXPERIMENTS: Planned tool invocations\nOBSERVATIONS: Results from experiments\nDECISIONS: Human-approved choices with rationale\n```\n\n### Episodic Memory Integration\n\nKnowledge persists across sessions via episodic memory. Use consistent tagging:\n\n```\n[BINARY-RE:{phase}] {artifact_name} (sha256: {hash})\nFACT: {observation} (source: {tool})\nHYPOTHESIS: {theory} (confidence: {0.0-1.0})\nQUESTION: {unknown}\nDECISION: {choice} (rationale: {why})\n```\n\n**Starting analysis:** Search episodic memory for artifact hash first\n**After each phase:** Findings are automatically captured in conversation\n**Resuming:** Search `[BINARY-RE] {artifact_name}` to restore context\n\n## Human-in-the-Loop Triggers\n\n**ALWAYS ask human before:**\n\n1. **Executing the binary** - Even under QEMU, confirm sandbox\n2. **Network operations** - Prevent unintended phone-home\n3. **Conflicting evidence** - Resolve contradictory findings\n4. **Privileged operations** - Device access, root actions\n5. **Major direction changes** - Significant analysis pivots\n\n## Session Management\n\n### Starting New Analysis\n\n```\n1. Compute artifact hash: sha256sum binary\n2. Search episodic memory: \"[BINARY-RE] sha256:{hash}\"\n3. If previous analysis found:\n   → \"Found previous analysis from {date}. Resume or start fresh?\"\n4. If resuming: Load facts/hypotheses, continue from last phase\n5. If fresh: Begin with triage phase\n```\n\n### Resuming Interrupted Analysis\n\n```\nUser: \"Continue analyzing that thermostat binary\"\n\nClaude:\n1. Invoke episodic-memory:search-conversations\n   Query: \"[BINARY-RE] thermostat\"\n2. Retrieve previous session findings\n3. Summarize: \"Last session identified ARM32/musl, found network\n   functions. We were about to run dynamic analysis.\"\n4. Continue from that phase\n```\n\n### Searching Past Analyses\n\n```\nUser: \"Have we analyzed any ARM binaries with hardcoded passwords?\"\n\nClaude:\n1. Search: \"[BINARY-RE] FACT: hardcoded\" or \"[BINARY-RE] ARM\"\n2. Return matching artifacts and findings\n```\n\n## Standard Analysis Flow\n\nFor typical unknown binary analysis:\n\n```\n1. Triage (binary-re-triage)\n   └─ Architecture, ABI, dependencies, capabilities\n\n2. Static Analysis (binary-re-static-analysis)\n   └─ Functions, strings, xrefs, decompilation\n\n3. Dynamic Analysis (binary-re-dynamic-analysis) - if safe\n   └─ Syscalls, network, file access\n\n4. Synthesis (binary-re-synthesis)\n   └─ Structured report with evidence\n```\n\n## Quick Reference\n\n### Essential Commands\n\n```bash\n# Fast triage\nrabin2 -I binary              # Metadata\nrabin2 -l binary              # Dependencies\nrabin2 -zz binary             # Strings\n\n# Static analysis\nr2 -q -c ''aa; aflj'' binary    # Functions\nr2 -q -c ''izj'' binary         # Strings\n\n# Dynamic (ARM example)\nqemu-arm -L /usr/arm-linux-gnueabihf -strace ./binary\n```\n\n### Architecture Detection\n\n| Indicator | Architecture | QEMU Binary | Ghidra Processor |\n|-----------|--------------|-------------|------------------|\n| `e_machine=EM_386 (3)` | x86 32-bit | `qemu-i386` or Docker `--platform linux/i386` | `x86:LE:32:default` |\n| `e_machine=EM_ARM (40)` | ARM 32-bit | `qemu-arm` or Docker `--platform linux/arm/v7` | `ARM:LE:32:v7` |\n| `e_machine=EM_AARCH64 (183)` | ARM 64-bit | `qemu-aarch64` or Docker `--platform linux/arm64` | `AARCH64:LE:64:v8A` |\n| `e_machine=EM_X86_64 (62)` | x86-64 | Native or Docker `--platform linux/amd64` | `x86:LE:64:default` |\n| `e_machine=EM_MIPS (8)` | MIPS 32 LE | `qemu-mipsel` | `MIPS:LE:32:default` |\n| `e_machine=EM_MIPS (8)` BE | MIPS 32 BE | `qemu-mips` | `MIPS:BE:32:default` |\n| `e_machine=EM_RISCV (243)` | RISC-V 64 | `qemu-riscv64` | `RISCV:LE:64:RV64I` |\n| `e_machine=EM_RISCV (243)` 32 | RISC-V 32 | `qemu-riscv32` | `RISCV:LE:32:RV32I` |\n\n### Libc Detection\n\n| Interpreter | Libc |\n|-------------|------|\n| `ld-linux-armhf.so.3` | glibc (ARM hard-float) |\n| `ld-musl-arm.so.1` | musl |\n| `ld-uClibc.so.0` | uClibc |\n\n## Error Recovery\n\n| Situation | Action |\n|-----------|--------|\n| Tool not found | Use `binary-re-tool-setup` skill |\n| Wrong architecture | Re-run triage, verify file output |\n| QEMU fails | Try Qiling, Unicorn, or on-device |\n| Analysis timeout | Reduce scope, use `aa` not `aaa` |\n| Conflicting evidence | Ask human, document both interpretations |\n\n## Documentation\n\nSee companion docs:\n- `docs/r2-commands.md` - Complete r2 reference for LLMs\n- `docs/ghidra-headless.md` - Ghidra scripting guide\n- `docs/arch-adapters.md` - Per-architecture quirks\n- `docs/python-bytecode-re.md` - Python .pyc/marshal obfuscation patterns\n\n## Integration\n\nWorks with other plugins:\n- **remote-system-maintenance**: Extract binaries from devices via SSH\n- **fresh-eyes-review**: Validate conclusions before documenting\n- **scenario-testing**: Create reproducible analysis environments\n"},"lastSynced":"2026-02-20T04:33:33.382Z","agentAnalysis":{"suitability":{"en":"Perfect for Cybersecurity Agents needing advanced binary reverse engineering capabilities with r2 and Ghidra analysis","zh":"非常适合需要使用r2和Ghidra分析进行高级二进制逆向工程的网络安全代理","ja":"サイバーセキュリティエージェントがr2およびGhidra分析を使用した高度なバイナリ逆向エンジニアリング機能を必要とする場合に最適","ko":"r2와 Ghidra 분석을 사용하여 고급 바이너리 역공학 기능이 필요한 사이버 보안 에이전트에게 적합","es":"Perfecto para agentes de ciberseguridad que necesitan capacidades avanzadas de ingeniería inversa de binarios con análisis r2 y Ghidra","fr":"Parfait pour les agents de cybersécurité ayant besoin de capacités avancées d''ingénierie inverse de binaires avec analyse r2 et Ghidra","de":"Perfekt für Cybersicherheitsagenten, die erweiterte Binär-Rückingenieur-Kapazitäten mit r2- und Ghidra-Analyse benötigen","pt":"Perfeito para Agentes de Cibersegurança que necessitam de capacidades avançadas de engenharia reversa de binários com análise r2 e Ghidra","ru":"Идеально для агентов кибербезопасности, которым необходимы продвинутые возможности обратного инжиниринга бинарных файлов с помощью анализа r2 и Ghidra","ar":" مثالي لعميل الأمن السيبراني الذي يحتاج إلى إمكانيات متقدمة لتحليل الثنائيات العكسي باستخدام تحليل r2 و Ghidra"},"recommendation":{"en":"Empowers agents to perform fast fingerprinting and static analysis of binaries using triggers like ''what is this binary'' and ''disassemble'', enabling comprehensive binary reverse engineering with quality-verified methodologies","zh":"赋予代理快速执行二进制指纹识别和静态分析的能力，使用诸如''这是什么二进制''和''反汇编''等触发器，实现全面二进制逆向工程，具有质量验证的方法论","ja":"エージェントが''これは何のバイナリですか''や''逆アセンブル''などのトリガーを使用して、高速なバイナリフィンガープリントと静的分析を実行できるようにし、品質保証済みの方法論を使用した包括的なバイナリ逆向エンジニアリングを可能にします","ko":"에이전트가 ''이 바이너리는 무엇인가'' 또는 ''逆조립''과 같은 트리거를 사용하여 빠른 바이너리 지문 분석 및 정적 분석을 수행할 수 있도록 하며, 품질 검증된 방법론을 사용하여 포괄적인 바이너리 역공학을 가능하게 합니다","es":"Habilita a los agentes a realizar una identificación rápida y un análisis estático de binarios utilizando desencadenadores como ''¿qué es este binario'' y ''desensamblar'', lo que permite una ingeniería inversa de binarios integral con metodologías verificadas de calidad","fr":"Permet aux agents d''effectuer une identification rapide et une analyse statique de binaires à l''aide de déclencheurs tels que ''qu''est-ce que ce binaire'' et ''désassembler'', permettant ainsi une ingénierie inverse de binaires complète avec des méthodologies vérifiées de qualité","de":"Ermächtigt die Agenten, eine schnelle Identifizierung und eine statische Analyse von Binärdateien mithilfe von Auslösern wie ''was ist dieser Binärdatei'' und ''disassemblieren'' durchzuführen, wodurch eine umfassende Binär-Rückingenieur-Analyse mit qualitätsgeprüften Methoden ermöglicht wird","pt":"Habilita os agentes a realizar identificação rápida e análise estática de binários usando gatilhos como ''o que é este binário'' e ''desmontar'', permitindo uma engenharia reversa de binários abrangente com metodologias verificadas por qualidade","ru":"Наделяет агентов возможностью быстро определять и проводить статический анализ бинарных файлов с помощью триггеров, таких как ''что это за бинарный файл'' и ''дизассемблировать'', обеспечивая комплексную обратную инженерию бинарных файлов с методологиями, проверенными на качество","ar":"تمكّن العميل من إجراء تحديد سريع وتحليل ثابت للثنائيات باستخدام الزنادات مثل ''ما هذا الملف الثنائي'' و ''فك التجميع''، مما يتيح تحليل الثنائيات العكسي الشامل باستخدام منهجيات محكّمة الجودة"},"useCases":{"en":["Automating binary identification with ''binary-re:triage''","Performing in-depth static analysis with ''binary-re:static-analysis''","Debugging binaries using Ghidra and r2"],"zh":["使用''二进制-再:分诊''自动执行二进制识别","使用''二进制-再:静态分析''执行深入的静态分析","使用Ghidra和r2调试二进制文件"],"ja":["''バイナリ-再:トリアージ''を使用してバイナリ識別を自動化する","''バイナリ-再:静的分析''を使用して詳細な静的分析を実行する","Ghidraとr2を使用してバイナリをデバッグする"],"ko":["''바이너리-재:트리아지''를 사용하여 바이너리 식별을 자동화하는 것","''바이너리-재:정적 분석''을 사용하여 심층 정적 분석을 수행하는 것","Ghidra와 r2를 사용하여 바이너리를 디버깅하는 것"],"es":["Automatizar la identificación de binarios con ''binary-re:triage''","Realizar un análisis estático en profundidad con ''binary-re:static-analysis''","Depurar binarios utilizando Ghidra y r2"],"fr":["Automatiser l''identification de binaires avec ''binary-re:triage''","Effectuer une analyse statique en profondeur avec ''binary-re:static-analysis''","Déboguer des binaires à l''aide de Ghidra et r2"],"de":["Automatisieren der Identifizierung von Binärdateien mit ''binary-re:triage''","Durchführen einer tiefen statischen Analyse mit ''binary-re:static-analysis''","Debuggen von Binärdateien mit Ghidra und r2"],"pt":["Automatizar a identificação de binários com ''binary-re:triage''","Realizar análise estática aprofundada com ''binary-re:static-analysis''","Depurar binários usando Ghidra e r2"],"ru":["Автоматизировать определение бинарных файлов с помощью ''binary-re:triage''","Проводить глубокий статический анализ с помощью ''binary-re:static-analysis''","Отлаживать бинарные файлы с помощью Ghidra и r2"],"ar":["تحديد الثنائيات تلقائيًا باستخدام ''binary-re:triage''","إجراء تحليل ثابت متعمق باستخدام ''binary-re:static-analysis''","تصحيح الثنائيات باستخدام Ghidra و r2"]},"limitations":{"en":["Requires specific trigger keywords for skill activation","Limited to binary reverse engineering tasks"],"zh":["需要特定的触发关键字来激活技能","仅限于二进制逆向工程任务"],"ja":["スキルをアクティブにするには特定のトリガーキーワードが必要","バイナリ逆向エンジニアリングタスクのみ"],"ko":["스킬을 활성화하려면 특정 트리거 키워드가 필요","바이너리 역공학 작업만"],"es":["Requiere palabras clave de activación de habilidad específicas","Limitado a tareas de ingeniería inversa de binarios"],"fr":["Nécessite des mots clés d''activation de compétence spécifiques","Limité aux tâches d''ingénierie inverse de binaires"],"de":["Erfordert spezifische Trigger-Schlüsselwörter für die Fähigkeitsaktivierung","Begrenzt auf Binär-Rückingenieur-Aufgaben"],"pt":["Requer palavras-chave de gatilho específicas para ativação da habilidade","Limitado a tarefas de engenharia reversa de binários"],"ru":["Требует конкретных ключевых слов триггера для активации навыка","Ограничен задачами обратного инжиниринга бинарных файлов"],"ar":["يتطلب كلمات مفتاح زناد محددة لتفعيل المهارة","محدود بمهام تحليل الثنائيات العكسي"]},"version":3},"contentHash":"779a12efde05da3712fd34fa2dfcc7e6377da29ba17e2346fc24534951365a04","qualityScore":50}');
