INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/binary-re', 'binary-re', 'aiskillstore', 'marketplace', 'community', 'binary-re aiskillstore marketplace community 二进制逆向工程是一种分析二进制代码的方法。这个技能提供了综合的方法、哲学和参考资料。 バイナリリバースエンジニアリングは、バイナリコードを分析する方法です。このスキルは、包括的な方法、哲学、参考資料を提供します。 이진 역공학은 이진 코드를 분석하는 방법입니다. 이 스킬은 종합적인 방법, 철학 및 참고 자료를 제공합니다. Guía completa para ingeniería inversa de binarios, cubriendo la metodología, filosofía y materiales de referencia. Incluye enlaces a habilidades relacionadas para fases específicas. Guide complet pour l''ingénierie inverse de binaires, couvrant la méthodologie, la philosophie et les matériaux de référence. Inclut des liens vers des compétences liées pour des phases spécifiques. Umfassender Leitfaden für Binär-Reversing, der Methodik, Philosophie und Referenzmaterial abdeckt. Enthält Links zu verwandten Fähigkeiten für spezifische Phasen. Engenharia reversa de binários é uma técnica usada para entender e analisar código binário. Nossa guia fornece uma visão geral da metodologia e filosofia por trás dessa técnica. Обратная инженерия бинарных файлов - это метод, используемый для понимания и анализа бинарного кода. Наша гида дает обзор методологии и философии, лежащих в основе этого метода. هندسة عكسية ثنائية هي تقنية تستخدم لفهم وتحليل الشفرة الثنائية. دليلنا يوفر نظرة عامة على المنهجية والفلسفة وراء هذه التقنية. Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. 二进制逆向工程 二进制代码分析 快速指纹识别 静态分析 逆向工程 代码分析 Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/bdg', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'bdg', 0, 0, 50, '2026-02-20T04:13:19.578Z', '2026-02-20T04:57:20.782Z', '90fdf1deecdc10c40c0913a5bc389a64e304c219da904b1d1b3e1fa9974b889a', '{"id":"majiayu000/claude-skill-registry/bdg","name":"bdg","description":{"zh":"bdg 是一个浏览器自动化 CLI 工具，支持网页截图、会话管理等功能","ja":"bdg は Web ページの自動化を実現するブラウザ自動化 CLI 工具です","ko":"bdg는 웹 페이지 자동화를 구현하는 브라우저 자동화 CLI 도구입니다","es":"bdg es una herramienta de automatización de navegador que permite lanzar sesiones en Chrome y realizar tareas como capturas de pantalla","fr":"bdg est un outil d''automatisation de navigateur qui permet de lancer des sessions dans Chrome et de réaliser des tâches comme des captures d''écran","de":"bdg ist ein Browser-Automatisierungstool, das das Starten von Sitzungen in Chrome und das Ausführen von Aufgaben wie Screenshots ermöglicht","pt":"O bdg é uma ferramenta de automação de navegador que permite iniciar sessões, capturar telas e executar comandos via CLI.","ru":"Bdg - это инструмент для автоматизации браузера, который позволяет запускать сеансы, делать скриншоты и выполнять команды через CLI.","ar":"bdg هو أداة أتمتة متصفح تسمح ببدء جلسات وتصوير الشاشة وتنفيذ أوامر عبر واجهة سطر الأوامر.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"bdg 浏览器自动化 CLI","ja":"bdg ブラウザ自動化 CLI","ko":"bdg 브라우저 자동화 CLI","es":"Automatización de navegador con bdg","fr":"Automatisation du navigateur avec bdg","de":"Browser-Automatisierung mit bdg","pt":"bdg: Automatize Navegadores com CLI","ru":"bdg: Автоматизация браузеров с помощью CLI","ar":"bdg: آلي للإنترنت مع واجهة سطر الأوامر","en":"bdg"},"description":{"zh":"bdg 是一个浏览器自动化 CLI 工具，支持网页截图、会话管理等功能","ja":"bdg は Web ページの自動化を実現するブラウザ自動化 CLI 工具です","ko":"bdg는 웹 페이지 자동화를 구현하는 브라우저 자동화 CLI 도구입니다","es":"bdg es una herramienta de automatización de navegador que permite lanzar sesiones en Chrome y realizar tareas como capturas de pantalla","fr":"bdg est un outil d''automatisation de navigateur qui permet de lancer des sessions dans Chrome et de réaliser des tâches comme des captures d''écran","de":"bdg ist ein Browser-Automatisierungstool, das das Starten von Sitzungen in Chrome und das Ausführen von Aufgaben wie Screenshots ermöglicht","pt":"O bdg é uma ferramenta de automação de navegador que permite iniciar sessões, capturar telas e executar comandos via CLI.","ru":"Bdg - это инструмент для автоматизации браузера, который позволяет запускать сеансы, делать скриншоты и выполнять команды через CLI.","ar":"bdg هو أداة أتمتة متصفح تسمح ببدء جلسات وتصوير الشاشة وتنفيذ أوامر عبر واجهة سطر الأوامر.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["支持网页截图","会话管理","支持 headless 模式","支持可见浏览器窗口","支持会话状态检查"],"ja":["Web ページのスクリーンショットをサポート","セッション管理","ヘッドレスモードをサポート","可視ブラウザウィンドウをサポート","セッション状態の確認をサポート"],"ko":["웹 페이지 스크린샷 지원","세션 관리","헤드리스 모드 지원","가시 브라우저 창 지원","세션 상태 확인 지원"],"es":["Lanzar sesiones en Chrome","Realizar capturas de pantalla","Gestión de sesiones","Modo headless","Ventana de navegador visible"],"fr":["Lancer des sessions dans Chrome","Réalisser des captures d''écran","Gestion des sessions","Mode headless","Fenêtre de navigateur visible"],"de":["Sitzungen in Chrome starten","Screenshots erstellen","Sitzungsverwaltung","Headless-Modus","Sichtbare Browser-Fenster"],"pt":["Inicie sessões de navegador com facilidade","Capture telas de páginas web"," Execute comandos via CLI","Controle de sessões de navegador","Modos headless e visível"],"ru":["Запускайте сеансы браузера с легкостью","Делайте скриншоты веб-страниц","Выполняйте команды через CLI","Контроль сеансов браузера","Режимы headless и видимого окна"],"ar":["ابدأ جلسات المتصفح بسهولة","تصوير الشاشة من صفحات الويب","تنفيذ أوامر عبر واجهة سطر الأوامر","مراقبة جلسات المتصفح","الوضع الخفي والمرئي"]},"keywords":{"zh":["浏览器自动化","CLI 工具","网页截图","会话管理","headless 模式","可见浏览器窗口"],"ja":["ブラウザ自動化","CLI ツール","Web ページのスクリーンショット","セッション管理","ヘッドレスモード","可視ブラウザウィンドウ"],"ko":["브라우저 자동화","CLI 도구","웹 페이지 스크린샷","세션 관리","헤드리스 모드","가시 브라우저 창"],"es":["automatización de navegador","bdg","chrome","captura de pantalla","gestión de sesiones","modo headless"],"fr":["automatisation de navigateur","bdg","chrome","capture d''écran","gestion des sessions","mode headless"],"de":["browser-automatisierung","bdg","chrome","screenshot","sitzungsverwaltung","headless-modus"],"pt":["automação de navegador","CLI","bdg","ferramenta de automação","navegador headless","captura de tela"],"ru":["автоматизация браузера","CLI","bdg","утилита автоматизации","браузер headless","скриншот"],"ar":["أتمتة متصفح","واجهة سطر الأوامر","bdg","أداة أتمتة","متصفح خفي","تصوير الشاشة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"bdg","description":"Use bdg CLI for browser automation via Chrome DevTools Protocol. Provides direct CDP access (60+ domains, 300+ methods) for DOM queries, navigation, screenshots, network control, and JavaScript execution. Use this skill when you need to automate browsers, scrape dynamic content, or interact with web pages programmatically.","bodyPreview":"# bdg - Browser Automation CLI\n\n## Quick Start\n\n```bash\nbdg https://example.com          # Start session (launches Chrome)\nbdg dom screenshot /tmp/page.png # Take screenshot\nbdg stop                         # End session\n```\n\n## Session Management\n\n```bash\nbdg <url>                  # Start session (1920x1080, headless if no display)\nbdg <url> --headless       # Force headless mode\nbdg <url> --no-headless    # Force visible browser window\nbdg status                 # Check session status\nbdg pee","body":"# bdg - Browser Automation CLI\n\n## Quick Start\n\n```bash\nbdg https://example.com          # Start session (launches Chrome)\nbdg dom screenshot /tmp/page.png # Take screenshot\nbdg stop                         # End session\n```\n\n## Session Management\n\n```bash\nbdg <url>                  # Start session (1920x1080, headless if no display)\nbdg <url> --headless       # Force headless mode\nbdg <url> --no-headless    # Force visible browser window\nbdg status                 # Check session status\nbdg peek                   # Preview data without stopping\nbdg stop                   # Stop and save output\nbdg cleanup --force        # Kill stale session\nbdg cleanup --aggressive   # Kill all Chrome processes\n```\n\n**Sessions run indefinitely by default** (no timeout). With HMR/hot-reload dev servers, keep the session running:\n\n```bash\nbdg http://localhost:5173      # Start once\n# ... make code changes, HMR updates the page ...\nbdg dom screenshot /tmp/s.png  # Check anytime\nbdg peek                       # Preview collected data\n# No need to stop/restart - Chrome stays on the page\n```\n\n## Screenshots\n\nAlways use `bdg dom screenshot` (raw CDP is blocked):\n\n```bash\nbdg dom screenshot /tmp/page.png                    # Full page\nbdg dom screenshot /tmp/viewport.png --no-full-page # Viewport only\nbdg dom screenshot /tmp/el.png --selector \"#main\"   # Element only\nbdg dom screenshot /tmp/scroll.png --scroll \"#target\" # Scroll to element first\n```\n\n## Form Interaction\n\n```bash\n# Discover forms\nbdg dom form --brief              # Quick scan: field names, types, required\n\n# Fill and interact\nbdg dom fill \"input[name=''user'']\" \"myuser\"    # Fill by selector\nbdg dom fill 0 \"value\"                         # Fill by index (from query)\nbdg dom click \"button.submit\"                  # Click element\nbdg dom submit \"form\" --wait-navigation        # Submit and wait for page load\nbdg dom pressKey \"input\" Enter                 # Press Enter key\n\n# Options\n--no-wait          # Skip network stability wait\n--wait-navigation  # Wait for page navigation (traditional forms)\n--wait-network <ms> # Wait for network idle (SPA forms)\n--index <n>        # Select nth element when multiple match\n```\n\n## DOM Inspection\n\n```bash\nbdg dom query \"selector\"     # Find elements, returns [0], [1], [2]...\nbdg dom get \"selector\"       # Get semantic a11y info (token-efficient)\nbdg dom get \"selector\" --raw # Get full HTML\nbdg dom eval \"js expression\" # Run JavaScript\n```\n\n## CDP Access\n\nDirect access to Chrome DevTools Protocol:\n\n```bash\n# Execute any CDP method\nbdg cdp Runtime.evaluate --params ''{\"expression\": \"document.title\", \"returnByValue\": true}''\nbdg cdp Page.navigate --params ''{\"url\": \"https://example.com\"}''\nbdg cdp Page.reload --params ''{\"ignoreCache\": true}''\n\n# Discovery\nbdg cdp --list                    # List all 53 domains\nbdg cdp Network --list            # List methods in domain\nbdg cdp Network.getCookies --describe  # Show method schema\nbdg cdp --search cookie           # Search methods\n```\n\n**Important**: Always use `returnByValue: true` for Runtime.evaluate to get serialized values.\n\n## Common Patterns\n\n### Login Flow\n```bash\nbdg https://example.com/login\nbdg dom form --brief\nbdg dom fill \"input[name=''username'']\" \"$USER\"\nbdg dom fill \"input[name=''password'']\" \"$PASS\"\nbdg dom submit \"button[type=''submit'']\" --wait-navigation\nbdg dom screenshot /tmp/result.png\nbdg stop\n```\n\n### Wait for Element\n```bash\nfor i in {1..20}; do\n  EXISTS=$(bdg cdp Runtime.evaluate --params ''{\n    \"expression\": \"document.querySelector(\\\"#target\\\") !== null\",\n    \"returnByValue\": true\n  }'' | jq -r ''.result.value'')\n  [ \"$EXISTS\" = \"true\" ] && break\n  sleep 0.5\ndone\n```\n\n### Extract Data\n```bash\nbdg cdp Runtime.evaluate --params ''{\n  \"expression\": \"Array.from(document.querySelectorAll(\\\"a\\\")).map(a => ({text: a.textContent, href: a.href}))\",\n  \"returnByValue\": true\n}'' | jq ''.result.value''\n```\n\n## Exit Codes\n\n| Code | Meaning | Action |\n|------|---------|--------|\n| 0 | Success | - |\n| 1 | Blocked command | Read error message, use suggested alternative |\n| 81 | Invalid arguments | Check command syntax |\n| 83 | Resource not found | Element/session doesn''t exist |\n| 101 | CDP connection failure | Run `bdg cleanup --aggressive` and retry |\n| 102 | CDP timeout | Increase timeout or check page load |\n\n## Troubleshooting\n\n```bash\nbdg status --verbose      # Full diagnostics\nbdg cleanup --force       # Kill stale session\nbdg cleanup --aggressive  # Kill all Chrome processes\n```\n\n**Chrome won''t launch?** Run `bdg cleanup --aggressive` then retry.\n\n**Session stuck?** Run `bdg cleanup --force` to reset.\n\n### Custom Chrome Flags\n\nUse `--chrome-flags` or `BDG_CHROME_FLAGS` for self-signed certificates, CORS, etc.:\n\n```bash\n# CLI option\nbdg https://localhost:5173 --chrome-flags=\"--ignore-certificate-errors\"\n\n# Environment variable\nBDG_CHROME_FLAGS=\"--ignore-certificate-errors\" bdg https://localhost:5173\n\n# Multiple flags\nbdg https://example.com --chrome-flags=\"--ignore-certificate-errors --disable-web-security\"\n```\n\n**Common flags for development:**\n- `--ignore-certificate-errors` - Self-signed SSL certs\n- `--disable-web-security` - CORS issues in development\n- `--allow-insecure-localhost` - Insecure localhost\n- `--disable-features=IsolateOrigins,site-per-process` - Cross-origin iframes\n\n## Verification Best Practices\n\n**Prefer DOM queries over screenshots** for verification:\n\n```bash\n# GOOD: Fast, precise, scriptable\nbdg cdp Runtime.evaluate --params ''{\n  \"expression\": \"document.querySelector(\\\".error-message\\\")?.textContent\",\n  \"returnByValue\": true\n}''\n\n# GOOD: Check element exists\nbdg dom query \".submit-btn\"\n\n# GOOD: Check text content\nbdg cdp Runtime.evaluate --params ''{\n  \"expression\": \"document.body.innerText.includes(\\\"Success\\\")\",\n  \"returnByValue\": true\n}''\n\n# AVOID: Screenshots for simple verification (slow, requires visual inspection)\nbdg dom screenshot /tmp/check.png  # Only use when you need visual proof\n```\n\n**When to use screenshots:**\n- Visual regression testing\n- Capturing proof for user review\n- Debugging layout issues\n- When DOM structure is unknown\n\n**When to use DOM queries:**\n- Verifying text content appeared\n- Checking element exists/visible\n- Validating form state\n- Counting elements\n- Any programmatic assertion\n\n## When NOT to Use bdg\n\n- **Static HTML** - Use `curl` + `htmlq`/`pq`\n- **API calls** - Use `curl` + `jq`\n- **Simple HTTP** - Use `wget`/`curl`\n\nUse bdg when you need: JavaScript execution, dynamic content, browser APIs, screenshots, or network manipulation.\n"},"lastSynced":"2026-02-20T04:57:20.782Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing advanced browser automation capabilities via CLI.","zh":"适用于需要高级浏览器自动化功能的自动化代理，通过CLI实现浏览器自动化。","ja":"CLI経由で高度なブラウザ自動化機能を必要とする自動化エージェントに適しています。","ko":"고급 브라우저 자동화 기능을 필요로 하는 자동화 에이전트에게 적합하며, CLI를 통해 브라우저 자동화를 구현합니다.","es":"Perfecto para Agentes de Automatización que necesitan capacidades de automatización de navegador avanzadas a través de la CLI.","fr":"Parfait pour les Agents d''Automatisation qui ont besoin de capacités d''automatisation de navigateur avancées via la CLI.","de":"Perfekt für Automatisierungsagenten, die erweiterte Browser-Automatisierungsfunktionen über die CLI benötigen.","pt":"Perfeito para Agentes de Automação que necessitam de capacidades avançadas de automação de navegador via CLI.","ru":"Идеально для агентов автоматизации, которым необходимы расширенные возможности автоматизации браузера через CLI.","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى قدرات متقدمة في أتمتة المتصفح عبر CLI."},"recommendation":{"en":"Empowers agents to automate browser interactions using Chrome, enabling features like headless mode, screenshot capture, and session management via protocols such as HTTPS, utilizing libraries and tools for browser automation.","zh":"使代理能够使用Chrome自动化浏览器交互，实现诸如无头模式、截图捕获和会话管理等功能，通过HTTPS等协议，并利用浏览器自动化的库和工具。","ja":"エージェントがChromeを使用してブラウザの相互作用を自動化できるようにし、ヘッドレスモード、スクリーンショットのキャプチャ、セッション管理などの機能を実現し、HTTPSなどのプロトコルを使用し、ブラウザ自動化のライブラリやツールを利用します。","ko":"에이전트가 Chrome을 사용하여 브라우저 상호작용을 자동화할 수 있도록 하며, 헤드리스 모드, 스크린샷 캡처, 세션 관리 등의 기능을 구현하며, HTTPS 등의 프로토콜을 사용하며, 브라우저 자동화 라이브러리 및 도구를 활용합니다.","es":"Permite a los agentes automatizar las interacciones del navegador mediante Chrome, habilitando características como el modo sin cabeza, la captura de pantalla y la administración de sesiones a través de protocolos como HTTPS, utilizando bibliotecas y herramientas para la automatización del navegador.","fr":"Permet aux agents d''automatiser les interactions de navigateur à l''aide de Chrome, activant des fonctionnalités telles que le mode sans tête, la capture d''écran et la gestion de session via des protocoles tels que HTTPS, en utilisant des bibliothèques et des outils pour l''automatisation du navigateur.","de":"Ermöglicht es den Agenten, Browser-Interaktionen mithilfe von Chrome zu automatisieren, wodurch Funktionen wie den headless-Modus, die Screenshot-Erfassung und die Sitzungsverwaltung über Protokolle wie HTTPS aktiviert werden, unter Verwendung von Bibliotheken und Tools für die Browser-Automatisierung.","pt":"Habilita os agentes a automatizar interações do navegador usando o Chrome, permitindo recursos como modo headless, captura de tela e gerenciamento de sessão via protocolos como HTTPS, utilizando bibliotecas e ferramentas para automação de navegador.","ru":"Наделяет агентов возможностью автоматизировать взаимодействия браузера с помощью Chrome, обеспечивая функции, такие как режим headless, захват экрана и управление сессиями через протоколы, такие как HTTPS, используя библиотеки и инструменты для автоматизации браузера.","ar":"يمنح الوكلاء القدرة على أتمتة تفاعلات المتصفح باستخدام كروم، وتمكين الميزات مثل وضع غير متصل، وتقاطع الشاشة، وإدارة الجلسات عبر بروتوكولات مثل HTTPS، باستخدام المكتبات والأدوات لأتمتة المتصفح."},"useCases":{"en":["Automating web page interactions for data scraping","Generating screenshots of web pages for visual testing","Debugging web applications in headless browser environments"],"zh":["用于数据抓取的网页交互自动化","用于视觉测试的网页截图生成","在无头浏览器环境中调试Web应用程序"],"ja":["データスクレイピングのためのWebページの相互作用の自動化","ビジュアルテストのためのWebページのスクリーンショットの生成","ヘッドレスブラウザ環境でのWebアプリケーションのデバッグ"],"ko":["데이터 스크레이핑을 위한 웹 페이지 상호작용 자동화","시각적 테스트를 위한 웹 페이지 스크린샷 생성","헤드리스 브라우저 환경에서 웹 애플리케이션 디버깅"],"es":["Automatizar las interacciones de la página web para la extracción de datos","Generar capturas de pantalla de páginas web para pruebas visuales","Depurar aplicaciones web en entornos de navegador sin cabeza"],"fr":["Automatiser les interactions de page Web pour le scraping de données","Générer des captures d''écran de pages Web pour des tests visuels","Déboguer des applications Web dans des environnements de navigateur sans tête"],"de":["Automatisieren von Webseiten-Interaktionen für das Daten-Scraping","Erzeugen von Screenshots von Webseiten für visuelle Tests","Debuggen von Webanwendungen in headless-Browser-Umgebungen"],"pt":["Automação de interações de página web para extração de dados","Geração de telas de páginas web para teste visual","Depuração de aplicações web em ambientes de navegador headless"],"ru":["Автоматизация взаимодействий веб-страниц для сбора данных","Генерация экранов веб-страниц для визуального тестирования","Отладка веб-приложений в средах браузера headless"],"ar":["أتمتة تفاعلات صفحة الويب لاستخراج البيانات","تحغيل لقطات من صفحات الويب للاختبار المرئي","تصحيح أخطاء التطبيقات الويب في بيئات المتصفح غير متصل"]},"limitations":{"en":["Requires Chrome browser installation","Limited to HTTP and HTTPS protocols","Needs display for non-headless mode"],"zh":["需要安装Chrome浏览器","仅限HTTP和HTTPS协议","非无头模式需要显示"],"ja":["Chromeブラウザのインストールが必要","HTTPとHTTPSプロトコルのみ","ヘッドレスモード以外では表示が必要"],"ko":["Chrome 브라우저 설치가 필요함","HTTP 및 HTTPS 프로토콜만 지원","헤드리스 모드가 아닌 경우에는 표시가 필요"],"es":["Requiere la instalación del navegador Chrome","Limitado a los protocolos HTTP y HTTPS","Necesita una pantalla para el modo no sin cabeza"],"fr":["Nécessite l''installation du navigateur Chrome","Limité aux protocoles HTTP et HTTPS","Nécessite un écran pour le mode non sans tête"],"de":["Benötigt die Installation des Chrome-Browsers","Begrenzt auf die Protokolle HTTP und HTTPS","Benötigt einen Bildschirm für den nicht-headless-Modus"],"pt":["Requer instalação do navegador Chrome","Limitado aos protocolos HTTP e HTTPS","Necessita de exibição para modo não headless"],"ru":["Требует установки браузера Chrome","Ограничен протоколами HTTP и HTTPS","Требует дисплея для режима не-headless"],"ar":["يتطلب تثبيت متصفح كروم","محدود ببروتوكولات HTTP و HTTPS","يحتاج إلى شاشة للوضع غير متصل"]},"version":3},"contentHash":"90fdf1deecdc10c40c0913a5bc389a64e304c219da904b1d1b3e1fa9974b889a","qualityScore":50}');
