INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/bdg', 'bdg', 'majiayu000', 'claude-skill-registry', 'community', 'bdg majiayu000 claude-skill-registry community bdg 是一个浏览器自动化 CLI 工具，支持网页截图、会话管理等功能 bdg は Web ページの自動化を実現するブラウザ自動化 CLI 工具です bdg는 웹 페이지 자동화를 구현하는 브라우저 자동화 CLI 도구입니다 bdg es una herramienta de automatización de navegador que permite lanzar sesiones en Chrome y realizar tareas como capturas de pantalla bdg est un outil d''automatisation de navigateur qui permet de lancer des sessions dans Chrome et de réaliser des tâches comme des captures d''écran bdg ist ein Browser-Automatisierungstool, das das Starten von Sitzungen in Chrome und das Ausführen von Aufgaben wie Screenshots ermöglicht O bdg é uma ferramenta de automação de navegador que permite iniciar sessões, capturar telas e executar comandos via CLI. Bdg - это инструмент для автоматизации браузера, который позволяет запускать сеансы, делать скриншоты и выполнять команды через CLI. bdg هو أداة أتمتة متصفح تسمح ببدء جلسات وتصوير الشاشة وتنفيذ أوامر عبر واجهة سطر الأوامر. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 浏览器自动化 CLI 工具 网页截图 会话管理 headless 模式 可见浏览器窗口 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
