INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/exe', 'exe', 'majiayu000', 'claude-skill-registry', 'community', 'exe majiayu000 claude-skill-registry community exe.dev 是一个 VM 主机平台，提供持久存储和默认 HTTPS。您可以轻松地将您的 Vibes 应用部署到 exe.dev exe.dev は、永続的なストレージとデフォルトのHTTPSを備えたVMホスティングプラットフォームです。Vibes アプリをexe.devに簡単にデプロイできます exe.dev는 영속적인 저장소와 기본 HTTPS를 갖춘 VM 호스팅 플랫폼입니다. Vibes 애플리케이션을 exe.dev에 쉽게 배포할 수 있습니다 El despliegue de aplicaciones en exe.dev es un proceso sencillo que requiere una clave SSH, una cuenta en exe.dev y una aplicación Vibes generada Le déploiement d''applications sur exe.dev est un processus simple qui nécessite une clé SSH, un compte sur exe.dev et une application Vibes générée Die Bereitstellung von Anwendungen auf exe.dev ist ein einfacher Prozess, der einen SSH-Schlüssel, ein Konto auf exe.dev und eine generierte Vibes-Anwendung erfordert O exe.dev é uma plataforma de hospedagem de VM que oferece armazenamento persistente e HTTPS por padrão. Aprenda a implantar seu aplicativo Vibes com facilidade. exe.dev - это платформа для хостинга виртуальных машин, обеспечивающая постоянное хранилище и HTTPS по умолчанию. Узнайте, как развернуть свое приложение Vibes. exe.dev هي منصة استضافة افتراضية توفر تخزينًا مستمرًا و HTTPS افتراضيًا. تعلم كيفية تثبيت تطبيق Vibes الخاص بك بسهولة. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app exe.dev Vibes 应用 VM 主机 持久存储 默认 HTTPS SSH 密钥 部署指南 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/opi', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'opi', 0, 0, 50, '2026-02-20T04:13:19.578Z', '2026-02-20T04:58:14.937Z', 'eac42ebcb705510ef0afcef2e6fee12dcce8ea7d54ec36ead1ae13b327ce7abc', '{"id":"majiayu000/claude-skill-registry/opi","name":"opi","description":{"zh":"Opi 是一个自动学习提取器，帮助开发者从最近的工作中自动提取学习成果，改善未来的 Claude 会话。它提供了一系列命令来收集学习材料","ja":"Opi は、最近の作業から学習成果を自動的に抽出するツールです。開発者は、将来的に Claude セッションを改善するために、Opi を使用して学習材料を収集できます","ko":"Opi는 자동 학습 추출기로, 개발자가 최근 작업에서 학습 결과를 자동으로 추출하여 향후 Claude 세션을 개선하는 데 도움을 줍니다. 명령어를 통해 학습 자료를 수집할 수 있습니다","es":"Opi es un skill que extrae automáticamente aprendizajes de commits recientes para mejorar futuras sesiones de Claude","fr":"Opi est un skill qui extrait automatiquement les apprentissages à partir de commits récents pour améliorer les futures sessions Claude","de":"Opi ist ein Skill, der Lernerfahrungen aus aktuellen Commits automatisch extrahiert, um zukünftige Claude-Sitzungen zu verbessern","pt":"Opi é um skill que extrai aprendizados de trabalhos recentes para melhorar futuras sessões do Claude","ru":"Opi - это навык, который извлекает обучение из недавних работ для улучшения будущих сессий Claude","ar":"أوبي هو مهارة تقوم باستخراج التعلم من الأعمال الحديثة لتحسين جلسات كلود المستقبلية","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Opi - 自动学习提取器","ja":"Opi - 学習自動抽出ツール","ko":"Opi - 자동 학습 추출기","es":"Opi: Extracción Automática de Aprendizaje para Desarrolla...","fr":"Opi : Extracteur d''Apprentissage Automatique pour les Dév...","de":"Opi: Automatischer Lern-Extraktor für Entwickler","pt":"Opi: Extração Automática de Aprendizado","ru":"Opi: Автоматический Извлекатель Обучения","ar":"أوبي: مستخرج التعلم الآلي","en":"opi"},"description":{"zh":"Opi 是一个自动学习提取器，帮助开发者从最近的工作中自动提取学习成果，改善未来的 Claude 会话。它提供了一系列命令来收集学习材料","ja":"Opi は、最近の作業から学習成果を自動的に抽出するツールです。開発者は、将来的に Claude セッションを改善するために、Opi を使用して学習材料を収集できます","ko":"Opi는 자동 학습 추출기로, 개발자가 최근 작업에서 학습 결과를 자동으로 추출하여 향후 Claude 세션을 개선하는 데 도움을 줍니다. 명령어를 통해 학습 자료를 수집할 수 있습니다","es":"Opi es un skill que extrae automáticamente aprendizajes de commits recientes para mejorar futuras sesiones de Claude","fr":"Opi est un skill qui extrait automatiquement les apprentissages à partir de commits récents pour améliorer les futures sessions Claude","de":"Opi ist ein Skill, der Lernerfahrungen aus aktuellen Commits automatisch extrahiert, um zukünftige Claude-Sitzungen zu verbessern","pt":"Opi é um skill que extrai aprendizados de trabalhos recentes para melhorar futuras sessões do Claude","ru":"Opi - это навык, который извлекает обучение из недавних работ для улучшения будущих сессий Claude","ar":"أوبي هو مهارة تقوم باستخراج التعلم من الأعمال الحديثة لتحسين جلسات كلود المستقبلية","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["自动提取学习成果","收集学习材料","改善 Claude 会话","支持 Git 命令","自动分析 fixCommits"],"ja":["学習成果の自動抽出","学習材料の収集","Claude セッションの改善","Git コマンドのサポート","fixCommits の自動分析"],"ko":["학습 결과 자동 추출","학습 자료 수집","Claude 세션 개선","Git 명령어 지원","fixCommits 자동 분석"],"es":["Extracción automática de aprendizajes","Mejora de las sesiones de Claude","Análisis de commits recientes","Soporte para múltiples formatos de commits","Integración con el registro de código de Claude"],"fr":["Extraction automatique des apprentissages","Amélioration des sessions Claude","Analyse des commits récents","Prise en charge de plusieurs formats de commits","Intégration avec l''enregistrement de code de Claude"],"de":["Automatische Extraktion von Lernerfahrungen","Verbesserung von Claude-Sitzungen","Analyse aktueller Commits","Unterstützung für mehrere Commit-Formate","Integration mit dem Code-Registrier-System von Claude"],"pt":["Extração automática de aprendizado","Análise de commits recentes","Identificação de commits de fixação","Melhoria de sessões do Claude","Integração com git","Automatização de workflows"],"ru":["Автоматическое извлечение обучения","Анализ недавних коммитов","Определение коммитов исправления","Улучшение сессий Claude","Интеграция с git","Автоматизация рабочих процессов"],"ar":["استخراج التعلم الآلي","تحليل الالتزامات الحديثة","تحديد الالتزامات التصحيحية","تحسين جلسات كلود","دمج مع جيت","تأتمة سير العمل"]},"keywords":{"zh":["Opi","自动学习提取器","Claude 会话","Git 命令","学习材料","fixCommits"],"ja":["Opi","学習自動抽出ツール","Claude セッション","Git コマンド","学習材料","fixCommits"],"ko":["Opi","자동 학습 추출기","Claude 세션","Git 명령어","학습 자료","fixCommits"],"es":["Opi","Claude","extracción de aprendizaje","commits","desarrollo de software","automatización","eficiencia","registro de código"],"fr":["Opi","Claude","extraction d''apprentissage","commits","développement de logiciels","automatisation","efficacité","enregistrement de code"],"de":["Opi","Claude","Lern-Extraktion","Commits","Software-Entwicklung","Automatisierung","Effizienz","Code-Registrierung"],"pt":["Opi","Extração de aprendizado","Claude","Git","Commits","Fixação","Refatoração","Desenvolvimento de software","Automatização"],"ru":["Opi","Извлечение обучения","Claude","Git","Коммиты","Исправление","Рефакторинг","Разработка программного обеспечения","Автоматизация"],"ar":["أوبي","استخراج التعلم","كلود","جيت","الالتزامات","التصحيح","إعادة هيكلة","تطوير البرمجيات","تأتمة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"opi","description":"|","bodyPreview":"# Opi - Learning Extractor\n\nAutomatically extract learnings from recent work to improve future Claude sessions.\n\n## Workflow\n\n### Step 1: Gather Sources\n\nRun these commands to collect learning material:\n\n```bash\n# Recent commits (last 20)\ngit log --oneline -20\n\n# Today''s commits with details\ngit log --since=\"midnight\" --format=\"%h %s\"\n\n# Commits with \"fix\", \"korjaus\", \"refactor\"\ngit log --oneline -50 | grep -iE \"(fix|korja|refactor|bugfix)\"\n```\n\n### Step 2: Analyze Fix Commits\n\nFor each fix/refa","body":"# Opi - Learning Extractor\n\nAutomatically extract learnings from recent work to improve future Claude sessions.\n\n## Workflow\n\n### Step 1: Gather Sources\n\nRun these commands to collect learning material:\n\n```bash\n# Recent commits (last 20)\ngit log --oneline -20\n\n# Today''s commits with details\ngit log --since=\"midnight\" --format=\"%h %s\"\n\n# Commits with \"fix\", \"korjaus\", \"refactor\"\ngit log --oneline -50 | grep -iE \"(fix|korja|refactor|bugfix)\"\n```\n\n### Step 2: Analyze Fix Commits\n\nFor each fix/refactor commit, examine what changed:\n\n```bash\ngit show <commit-hash> --stat\ngit show <commit-hash> -- \"*.tsx\" \"*.ts\"  # Code changes\n```\n\nLook for patterns:\n- **What was wrong?** (the bug/issue)\n- **What fixed it?** (the solution)\n- **Why?** (root cause)\n\n### Step 3: Check Current Conversation\n\nReview current conversation for:\n- User corrections (\"ei, tee näin...\" / \"no, do it this way...\")\n- Failed attempts that were fixed\n- Non-obvious solutions discovered\n- Repeated patterns\n\n### Step 4: Categorize Learnings\n\nDetermine where each learning belongs:\n\n| Learning Type | Destination |\n|--------------|-------------|\n| React/TypeScript pattern | `.claude/LEARNINGS.md` |\n| Supabase/DB pattern | `.claude/LEARNINGS.md` |\n| CI/CD specific | `ci-doctor/references/learnings.md` |\n| Lint specific | `lint-fixer/references/learnings.md` |\n| Test specific | `test-writer/references/learnings.md` |\n| Skill-specific | `[skill]/references/learnings.md` |\n\n### Step 5: Propose Learnings\n\nFormat each learning proposal:\n\n```markdown\n## Proposed Learning\n\n**Source:** commit abc123 / conversation\n**Category:** [Global / Skill-specific]\n**File:** [target file path]\n\n### [Issue Title]\n- **Pattern:** What triggers this\n- **Wrong:** ❌ The incorrect approach\n- **Right:** ✅ The correct approach\n- **Why:** Root cause\n```\n\n### Step 6: Get Approval & Write\n\n1. Present all proposed learnings to user\n2. User approves/rejects each\n3. Write approved learnings to appropriate files\n4. Commit changes\n\n## Learning Quality Criteria\n\nOnly propose learnings that are:\n\n- [ ] **Non-obvious** - Claude wouldn''t know this without being told\n- [ ] **Actionable** - Can be applied in future situations\n- [ ] **Specific** - Has concrete wrong/right examples\n- [ ] **Recurring** - Likely to come up again\n\nSkip:\n- Typo fixes\n- One-off configuration issues\n- Project-specific constants\n- Things Claude already knows\n\n## Example Session\n\n```\nUser: /opi\n\nClaude: Let me analyze recent commits...\n\nFound 3 potential learnings:\n\n1. **useCallback for useEffect deps** (commit a1b2c3)\n   - Source: AdminTranslationsPage infinite loop fix\n   - File: .claude/LEARNINGS.md\n   - Pattern: Functions in useEffect deps cause re-renders\n\n2. **GitHub API dismiss format** (commit d4e5f6)\n   - Source: CodeQL alert dismissal\n   - File: ci-doctor/references/learnings.md\n   - Pattern: Use \"false positive\" not \"false_positive\"\n\n3. **Controlled Tabs state** (conversation)\n   - Source: Feedback popup tab fix\n   - File: .claude/LEARNINGS.md\n   - Pattern: Radix Tabs need value+onValueChange for control\n\nAdd these learnings? [Y/n for each]\n```\n\n## Commands Reference\n\n```bash\n# Commits since specific date\ngit log --since=\"2025-01-10\" --oneline\n\n# Commits by pattern\ngit log --all --oneline | grep -i \"fix\"\n\n# Show specific commit\ngit show <hash> --name-only\n\n# Diff for a commit\ngit diff <hash>^..<hash>\n```\n"},"lastSynced":"2026-02-20T04:58:14.937Z","agentAnalysis":{"suitability":{"en":"Perfect for Claude Code Agents needing automated learning extraction and improvement of future sessions.","zh":"非常适合需要自动化学习提取和改进未来会话的 Claude Code Agents。","ja":"Claude Code Agents が自動化された学習の抽出と将来のセッションの改善が必要な場合に最適です。","ko":" 将来的 세션의 자동화된 학습 추출 및 개선이 필요한 Claude Code 에이전트에 적합합니다.","es":"Perfecto para agentes de código Claude que necesitan extracción de aprendizaje automatizada y mejora de sesiones futuras.","fr":"Parfait pour les agents de code Claude qui ont besoin d''une extraction d''apprentissage automatisée et d''une amélioration des sessions futures.","de":"Perfekt für Claude-Code-Agents, die eine automatisierte Lernextraktion und Verbesserung zukünftiger Sitzungen benötigen.","pt":"Perfeito para Agentes de Código Claude que necessitam de extração de aprendizado automatizado e melhoria de sessões futuras.","ru":"Идеально для агентов Claude Code, которым необходим автоматизированный вывод обучения и улучшение будущих сессий.","ar":"مثالي لعميل كلود كود الذي يحتاج إلى استخلاص تعليمات自动ي وتحسين الجلسات المستقبلية."},"recommendation":{"en":"Empowers agents to automatically extract learnings from recent work using Git commands, such as analyzing fix commits and recent code changes, to improve future Claude sessions with enhanced workflow efficiency and accuracy through protocols like Git log and grep.","zh":"赋予代理自动从最近的工作中提取学习成果的能力，使用 Git 命令，例如分析 fix 提交和最近的代码更改，以提高未来的 Claude 会话的工作流效率和准确性，通过 Git 日志和 grep 等协议。","ja":"エージェントに、Git コマンドを使用して最近の作業から学習を自動的に抽出する能力を与え、fix コミットや最近のコード変更を分析して、Git ログや grep などのプロトコルを通じて、将来の Claude セッションのワークフロー効率と精度を向上させます。","ko":"에이전트가 Git 명령을 사용하여 최근 작업에서 학습을 자동으로 추출할 수 있도록 하여, 수정 커밋 및 최근 코드 변경을 분석하고 Git 로그 및 grep과 같은 프로토콜을 통해 향후 Claude 세션의 워크플로 효율성과 정확성을 향상시킵니다.","es":"Permite a los agentes extraer automáticamente los conocimientos de trabajos recientes utilizando comandos Git, como analizar commits de corrección y cambios de código recientes, para mejorar las sesiones futuras de Claude con una mayor eficiencia y precisión del flujo de trabajo a través de protocolos como Git log y grep.","fr":"Permet aux agents d''extraire automatiquement les apprentissages des travaux récents en utilisant des commandes Git, telles que l''analyse des commits de correction et des changements de code récents, pour améliorer les sessions futures de Claude avec une efficacité et une précision accrues du flux de travail via des protocoles tels que Git log et grep.","de":"Ermöglicht es den Agenten, Lerninhalte aus aktuellen Arbeiten automatisch mithilfe von Git-Befehlen zu extrahieren, wie z.B. die Analyse von Korrektur-Commits und aktuellen Code-Änderungen, um zukünftige Claude-Sitzungen mit verbesserter Workflow-Effizienz und Genauigkeit durch Protokolle wie Git-Log und grep zu verbessern.","pt":"Habilita os agentes a extrair automaticamente conhecimentos do trabalho recente usando comandos Git, como análise de commits de correção e alterações de código recentes, para melhorar as futuras sessões do Claude com eficiência de fluxo de trabalho aprimorada e precisão por meio de protocolos como Git log e grep.","ru":"Наделяет агентов возможностью автоматически извлекать знания из недавней работы, используя команды Git, такие как анализ исправляющих коммитов и недавних изменений кода, для улучшения будущих сессий Claude с повышенной эффективностью рабочего процесса и точностью с помощью протоколов, таких как Git log и grep.","ar":"يتمكّن الوكلاء من استخلاص المعارف تلقائيًا من العمل الحديث باستخدام أوامر Git، مثل تحليل تعديلات الإصلاح والتعديلات الأخيرة على الشفرة، لتحسين جلسات كلود المستقبلية بفعالية وحساسية محسّنة من خلال بروتوكولات مثل سجل Git و grep."},"useCases":{"en":["Automating learning extraction from recent commits","Analyzing fix commits for improved code quality","Generating summaries of recent code changes"],"zh":["自动从最近的提交中提取学习成果","分析 fix 提交以改进代码质量","生成最近代码更改的摘要"],"ja":["最近のコミットから学習を自動的に抽出する","fix コミットを分析してコード品質を向上させる","最近のコード変更の要約を生成する"],"ko":["최근 커밋에서 학습을 자동으로 추출하는 것","수정 커밋을 분석하여 코드 품질을 개선하는 것","최근 코드 변경의 요약을 생성하는 것"],"es":["Automatizar la extracción de aprendizaje de commits recientes","Analizar commits de corrección para mejorar la calidad del código","Generar resúmenes de cambios de código recientes"],"fr":["Automatiser l''extraction d''apprentissage des commits récents","Analyser les commits de correction pour améliorer la qualité du code","Générer des résumés des changements de code récents"],"de":["Automatisierung der Lernextraktion aus aktuellen Commits","Analyse von Korrektur-Commits zur Verbesserung der Code-Qualität","Generierung von Zusammenfassungen aktueller Code-Änderungen"],"pt":["Automatizar a extração de aprendizado de commits recentes","Analisar commits de correção para melhorar a qualidade do código","Gerar resumos de alterações de código recentes"],"ru":["Автоматизировать извлечение обучения из недавних коммитов","Анализировать исправляющие коммиты для улучшения качества кода","Генерировать сводки недавних изменений кода"],"ar":["تأتميم استخلاص التعلم من التعديلات الحديثة","تحليل تعديلات الإصلاح لتحسين جودة الشفرة","إنتاج ملخصات للتعديلات الحديثة على الشفرة"]},"limitations":{"en":["Requires Git access and configuration","Limited to analyzing recent commits and fix/refactor logs"],"zh":["需要 Git 访问和配置","仅限分析最近的提交和 fix/refactor 日志"],"ja":["Git アクセスと設定が必要","最近のコミットと fix/refactor ログのみを分析可能"],"ko":["Git 접근 및 구성이 필요하다","최근 커밋 및 수정/리팩토링 로그만 분석 가능"],"es":["Requiere acceso y configuración de Git","Limitado al análisis de commits y registros de corrección/refactorización recientes"],"fr":["Nécessite un accès et une configuration Git","Limité à l''analyse des commits et des journaux de correction/refactorisation récents"],"de":["Benötigt Git-Zugriff und -Konfiguration","Begrenzt auf die Analyse von Commits und Korrektur/Refaktorisierungs-Logs"],"pt":["Requer acesso e configuração do Git","Limitado à análise de commits recentes e logs de fix/refatoração"],"ru":["Требует доступа и настройки Git","Ограничен анализом недавних коммитов и журналов исправления/рефакторинга"],"ar":["يتطلب الوصول إلى تكوين Git","محدود بتحليل التعديلات الحديثة وسجلات الإصلاح/إعادة الهيكلة"]},"version":3},"contentHash":"eac42ebcb705510ef0afcef2e6fee12dcce8ea7d54ec36ead1ae13b327ce7abc","qualityScore":50}');
