INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/opi', 'opi', 'majiayu000', 'claude-skill-registry', 'community', 'opi majiayu000 claude-skill-registry community Opi 是一个自动学习提取器，帮助开发者从最近的工作中自动提取学习成果，改善未来的 Claude 会话。它提供了一系列命令来收集学习材料 Opi は、最近の作業から学習成果を自動的に抽出するツールです。開発者は、将来的に Claude セッションを改善するために、Opi を使用して学習材料を収集できます Opi는 자동 학습 추출기로, 개발자가 최근 작업에서 학습 결과를 자동으로 추출하여 향후 Claude 세션을 개선하는 데 도움을 줍니다. 명령어를 통해 학습 자료를 수집할 수 있습니다 Opi es un skill que extrae automáticamente aprendizajes de commits recientes para mejorar futuras sesiones de Claude Opi est un skill qui extrait automatiquement les apprentissages à partir de commits récents pour améliorer les futures sessions Claude Opi ist ein Skill, der Lernerfahrungen aus aktuellen Commits automatisch extrahiert, um zukünftige Claude-Sitzungen zu verbessern Opi é um skill que extrai aprendizados de trabalhos recentes para melhorar futuras sessões do Claude Opi - это навык, который извлекает обучение из недавних работ для улучшения будущих сессий Claude أوبي هو مهارة تقوم باستخراج التعلم من الأعمال الحديثة لتحسين جلسات كلود المستقبلية The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Opi 自动学习提取器 Claude 会话 Git 命令 学习材料 fixCommits The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
