INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/vcf', 'vcf', 'majiayu000', 'claude-skill-registry', 'community', 'vcf majiayu000 claude-skill-registry community VCF 是 VC Finish 的别名，用于调用 vc-phase-loop。请参考相关文档以获取更多信息 VCF は VC Finish のエイリアスで、vc-phase-loop を呼び出すために使用されます。詳細は関連ドキュメントを参照してください VCF는 VC Finish의 별칭으로, vc-phase-loop를 호출하는 데 사용됩니다. 자세한 정보는 관련 문서를 참조하십시오 VCF es un alias para vc-phase-loop, utilizado en el registro de habilidades de Claude Code para simplificar la invocación de la habilidad. VCF est un alias pour vc-phase-loop, utilisé dans le registre des compétences de Claude Code pour simplifier l''invocation de la compétence. VCF ist ein Alias für vc-phase-loop, der im Claude Code-Skill-Register verwendet wird, um die Aufrufung der Fähigkeit zu vereinfachen. O VCF é um alias para vc-phase-loop, permitindo a execução de comandos de forma simplificada. Leia mais sobre como usá-lo VCF — псевдоним для vc-phase-loop, позволяющий выполнять команды в упрощенном виде. Узнайте больше о его использовании VCF هو اسم مستعار ل vc-phase-loop، مما يسمح بتنفيذ أوامر بشكل مبسط. اقرأ المزيد حول كيفية استخدامه The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app VCF VC Finish vc-phase-loop 别名 开发者资源 综合技能注册 Web Search 技能注册 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/tech', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'tech', 0, 0, 50, '2026-02-20T04:13:19.579Z', '2026-02-20T04:59:23.681Z', '17dcf823473304b6256e4a7382a1e5f324562fe15fb4dbb3177e1c9429d04968', '{"id":"majiayu000/claude-skill-registry/tech","name":"tech","description":{"zh":"该技能帮助维护技术资料，通过研究和验证技术信息","ja":"このスキルは、技術情報を研究し検証することで、技術資料を維持するのに役立ちます","ko":"이 스킬은 기술 정보를 연구하고 검증하여 기술 자료를 유지하는 데 도움이 됩니다","es":"La habilidad de tecnología ayuda a mantener el directorio de tecnologías con perfiles actualizados y validados","fr":"La compétence technique aide à maintenir le répertoire de technologies avec des profils à jour et validés","de":"Die technische Fähigkeit hilft, das Technologieverzeichnis mit aktuellen und validierten Profilen zu pflegen","pt":"O skill Tech ajuda a manter o diretório de tecnologias, pesquisando e validando perfis de tecnologia.","ru":"Навык Tech помогает поддерживать каталог технологий, исследуя и проверяя профили технологий.","ar":"تساعد مهارة التكنولوجيا في الحفاظ على دليل التقنيات، من خلال البحث والتحقق من ملفات تعريف التقنيات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":" Claude Code 技术技能","ja":"Claude Code 技術スキル","ko":"Claude Code 기술 스킬","es":"Habilidad de tecnología para desarrolladores","fr":"Compétence technique pour les développeurs","de":"Technische Fähigkeit für Entwickler","pt":"Skill Tech: Registro de Tecnologias","ru":"Навык Tech: Реестр Технологий","ar":"مهارة التكنولوجيا: سجل التقنيات","en":"tech"},"description":{"zh":"该技能帮助维护技术资料，通过研究和验证技术信息","ja":"このスキルは、技術情報を研究し検証することで、技術資料を維持するのに役立ちます","ko":"이 스킬은 기술 정보를 연구하고 검증하여 기술 자료를 유지하는 데 도움이 됩니다","es":"La habilidad de tecnología ayuda a mantener el directorio de tecnologías con perfiles actualizados y validados","fr":"La compétence technique aide à maintenir le répertoire de technologies avec des profils à jour et validés","de":"Die technische Fähigkeit hilft, das Technologieverzeichnis mit aktuellen und validierten Profilen zu pflegen","pt":"O skill Tech ajuda a manter o diretório de tecnologias, pesquisando e validando perfis de tecnologia.","ru":"Навык Tech помогает поддерживать каталог технологий, исследуя и проверяя профили технологий.","ar":"تساعد مهارة التكنولوجيا في الحفاظ على دليل التقنيات، من خلال البحث والتحقق من ملفات تعريف التقنيات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["研究和验证技术信息","维护技术资料","支持多种技术信息来源","包括公式名、描述、网站和源代码仓库"],"ja":["技術情報の研究と検証","技術資料の維持","複数の技術情報源のサポート","公式名、説明、ウェブサイト、ソースコードリポジトリの含む"],"ko":["기술 정보의 연구와 검증","기술 자료의 유지","다중 기술 정보원의 지원","공식 이름, 설명, 웹사이트, 소스 코드 저장소의 포함"],"es":["Investigación y validación de tecnologías","Creación de perfiles de tecnologías","Actualización del directorio de tecnologías","Búsqueda web para recopilar información","Validación de datos de tecnologías"],"fr":["Recherche et validation de technologies","Création de profils de technologies","Mise à jour du répertoire de technologies","Recherche web pour collecter des informations","Validation des données de technologies"],"de":["Recherche und Validierung von Technologien","Erstellung von Technologieprofilen","Aktualisierung des Technologieverzeichnisses","Web-Suche zur Informationsbeschaffung","Validierung von Technologiedaten"],"pt":["Pesquisa de tecnologias","Validação de perfis de tecnologia","Criação de perfis de tecnologia","Pesquisa na web","Verificação de sites oficiais e documentação"],"ru":["Исследование технологий","Проверка профилей технологий","Создание профилей технологий","Поиск в интернете","Проверка официальных сайтов и документации"],"ar":["البحث عن التقنيات","التحقق من ملفات تعريف التقنيات","إنشاء ملفات تعريف التقنيات","البحث على الويب","التحقق من المواقع الرسمية والتوثيق"]},"keywords":{"zh":["技术技能","Claude Code","技术资料","研究和验证","维护技术信息","公式名","描述","网站","源代码仓库"],"ja":["技術スキル","Claude Code","技術資料","研究と検証","技術情報の維持","公式名","説明","ウェブサイト","ソースコードリポジトリ"],"ko":["기술 스킬","Claude Code","기술 자료","연구와 검증","기술 정보의 유지","공식 이름","설명","웹사이트","소스 코드 저장소"],"es":["tecnología para desarrolladores","habilidad de tecnología","desarrollo de software","tecnologías de vanguardia","registros de tecnologías","búsqueda web"],"fr":["compétence technique pour les développeurs","technologie pour les développeurs","développement de logiciels","technologies de pointe","répertoires de technologies","recherche web"],"de":["technische Fähigkeit für Entwickler","Technologie für Entwickler","Software-Entwicklung","Technologien der Zukunft","Technologieverzeichnisse","Web-Suche"],"pt":["tecnologia","desenvolvimento de software","registro de tecnologias","pesquisa de tecnologias","validação de tecnologias","criação de perfis de tecnologia"],"ru":["технологии","разработка программного обеспечения","реестр технологий","исследование технологий","проверка технологий","создание профилей технологий"],"ar":["التكنولوجيا","تطوير البرمجيات","سجل التقنيات","البحث عن التقنيات","التحقق من التقنيات","إنشاء ملفات تعريف التقنيات"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.579Z","topics":[],"category":"community","skillMd":{"name":"tech","description":"Research, validate, and set up technology profiles in content/technologies. Handles both new entries and updates to existing ones.","bodyPreview":"This skill helps maintain the `content/technologies` directory by researching, validating, and creating technology profiles.\n\nWhen the user asks to add or check a technology (e.g., \"Add Bun\", \"Check Kubernetes\"), follow this process:\n\n## 1. Research & Discovery\n\nUse `WebSearch` to gather the following information about the technology:\n\n- **Official Name** and **Description** (1-2 paragraphs summary).\n- **Official Website** and **Documentation** URLs.\n- **Source Code Repository** (GitHub/GitLab)","body":"This skill helps maintain the `content/technologies` directory by researching, validating, and creating technology profiles.\n\nWhen the user asks to add or check a technology (e.g., \"Add Bun\", \"Check Kubernetes\"), follow this process:\n\n## 1. Research & Discovery\n\nUse `WebSearch` to gather the following information about the technology:\n\n- **Official Name** and **Description** (1-2 paragraphs summary).\n- **Official Website** and **Documentation** URLs.\n- **Source Code Repository** (GitHub/GitLab) and **License** (e.g., Apache-2.0, MIT).\n- **Logos**: Look for official vector logos (SVG preferred). You will need paths for `icon`, `horizontal`, and `stacked`. (Note: You won''t be able to download them directly to the specific filenames without `FetchUrl` or `curl`, so for now, just identify if they exist or create placeholders).\n- **Key Features**: What are the main selling points?\n- **Use Cases**: When should someone use this?\n- **Core Concepts**: What are the main building blocks?\n- **Ecosystem**: Related tools or integrations.\n\n## 2. Check Existence\n\nCheck if `content/technologies/<slug>` exists. The slug should be the kebab-case version of the technology name.\n\n## 3. Action: Create New (If it doesn''t exist)\n\n1.  Create the directory: `content/technologies/<slug>`.\n2.  Create `index.mdx` with the following structure. **Strictly follow the frontmatter format.**\n\n```yaml\n---\nname: \"Technology Name\"\ndescription: |\n  A comprehensive description of the technology.\n  It can span multiple lines.\nlogos:\n  icon: ./icon.svg\n  horizontal: ./horizontal.svg\n  stacked: ./stacked.svg\nwebsite: \"https://official-website.com\"\ndocumentation: \"https://docs.url\"\nlicense: \"License-Type\"\ncategories:\n  - \"category-1\"\n  - \"category-2\"\nstatus: \"sandbox\" # Default to sandbox for new entries, or ''stable'' if very mature\nradar:\n  status: assess # Default to assess\n---\n\nIntroduction paragraph...\n\n## What is [Technology]?\n...\n\n## Why [Technology] Matters in 2025\n...\n\n## Core [Technology] Concepts\n...\n\n## Getting Started with [Technology]\n...\n\n## Common Use Cases\n...\n\n## Best Practices for Production\n...\n\n## [Technology] Ecosystem and Tools\n...\n\n## Conclusion\n...\n```\n\n3.  **Logos**: Since you cannot browse the web visually to pick the perfect SVG, leave the references in the frontmatter as `./icon.svg`, etc., but explicitly tell the user **\"I have created the file structure. You will need to manually add the `icon.svg`, `horizontal.svg`, and `stacked.svg` files to the `content/technologies/<slug>` directory.\"**\n\n## 4. Action: Validate & Update (If it exists)\n\n1.  Read the existing `index.mdx`.\n2.  Compare the `website`, `documentation`, and `license` fields with your research.\n3.  If they differ, update them.\n4.  Check if the content is outdated (e.g., refers to old versions or years). If so, propose updates to the \"Why it matters\" or \"What is\" sections.\n5.  Report back to the user with a summary of what was validated and what was updated.\n\n## General Guidelines\n\n- **Tone**: informative, technical, and objective.\n- **Formatting**: Use proper Markdown.\n- **Files**: Do not create other files unless specifically asked.\n"},"lastSynced":"2026-02-20T04:59:23.681Z","agentAnalysis":{"suitability":{"en":"Perfect for Knowledge Agents needing comprehensive technology research capabilities for GitHub, GitLab, and web-based resources.","zh":"非常适合需要对 GitHub、GitLab 和基于 Web 的资源进行全面技术研究的知识代理。","ja":"GitHub、GitLab、Web ベースのリソースに対する包括的な技術研究機能を必要とするナレッジ エージェントに最適です。","ko":"GitHub, GitLab 및 웹 기반 리소스에 대한 종합적인 기술 연구 기능을 필요로 하는 지식 에이전트에게 적합합니다.","es":"Perfecto para agentes de conocimiento que necesitan capacidades de investigación tecnológica integral para GitHub, GitLab y recursos web.","fr":"Parfait pour les agents de connaissance qui ont besoin de capacités de recherche technologique complètes pour GitHub, GitLab et les ressources web.","de":"Perfekt für Wissensagenten, die umfassende Technologieforschungsmöglichkeiten für GitHub, GitLab und webbasierte Ressourcen benötigen.","pt":"Perfeito para Agentes de Conhecimento que necessitam de capacidades de pesquisa tecnológica abrangentes para GitHub, GitLab e recursos baseados na web.","ru":"Идеально подходит для агентов знаний, которым необходимы всесторонние возможности технологических исследований для GitHub, GitLab и веб-ресурсов.","ar":"مثالي للوكلاء المعرفيين الذين يحتاجون إلى قدرات بحث تقني شامل ل GitHub و GitLab والموارد القائمة على الويب."},"recommendation":{"en":"Empowers agents to research and validate technology profiles using WebSearch, gathering official names, descriptions, websites, documentation, and source code repositories, thereby enhancing their knowledge graph with accurate and up-to-date tech information.","zh":"赋予代理研究和验证技术配置文件的能力，使用 WebSearch 收集官方名称、描述、网站、文档和源代码仓库，从而用准确和最新的技术信息增强其知识图谱。","ja":"WebSearch を使用して、公式名称、説明、ウェブサイト、ドキュメント、およびソースコードリポジトリを収集することで、エージェントが技術プロファイルを研究および検証する能力を提供し、正確で最新のテクノロジー情報でそのナレッジ グラフを強化する。","ko":"웹 검색을 사용하여 공식 이름, 설명, 웹사이트, 문서 및 소스 코드 저장소를 수집하여 에이전트가 기술 프로필을 연구 및 확인할 수 있는 능력을 제공하여 정확하고 최신 기술 정보로 지식 그래프를 강화합니다.","es":"Permite a los agentes investigar y validar perfiles de tecnología utilizando la búsqueda web, recopilando nombres oficiales, descripciones, sitios web, documentación y repositorios de código fuente, lo que mejora su grafo de conocimiento con información técnica precisa y actualizada.","fr":"Permet aux agents de rechercher et de valider des profils de technologie en utilisant la recherche web, en rassemblant des noms officiels, des descriptions, des sites web, une documentation et des référentiels de code source, améliorant ainsi leur graphe de connaissances avec des informations techniques précises et à jour.","de":"Ermöglicht es Agenten, Technologieprofile mithilfe der Websuche zu recherchieren und zu validieren, indem sie offizielle Namen, Beschreibungen, Websites, Dokumentationen und Quellcode-Repositorys sammeln, wodurch ihr Wissensgraph mit genauen und aktuellen Technologieinformationen erweitert wird.","pt":"Habilita os agentes a pesquisar e validar perfis de tecnologia usando a pesquisa na web, reunindo nomes oficiais, descrições, sites, documentação e repositórios de código-fonte, melhorando assim seu gráfico de conhecimento com informações técnicas precisas e atualizadas.","ru":"Наделяет агентов возможностью исследовать и проверить профили технологий с помощью веб-поиска, собирая официальные названия, описания, сайты, документацию и репозитории исходного кода, тем самым улучшая их граф знаний точной и актуальной технической информацией.","ar":"يُمكّن الوكلاء من البحث والتحقق من ملفات تعريف التكنولوجيا باستخدام البحث على الويب، وجمع الأسماء الرسمية والوصف والمواقع والتوثيق ومستودعات الشفرة المصدرية، وبالتالي تحسين مخطط معرفتهم بمعلومات تقنية دقيقة ومحدثة."},"useCases":{"en":["Researching emerging technologies like Bun","Validating Kubernetes documentation","Creating technology profiles for the skills registry"],"zh":["研究新兴技术，如 Bun","验证 Kubernetes 文档","为技能注册表创建技术配置文件"],"ja":["Bun などの新興テクノロジーの研究","Kubernetes ドキュメントの検証","スキル登録簿のテクノロジー プロファイルの作成"],"ko":["Bun과 같은 새로운 기술 연구","쿠버네티스 문서 확인","스킬 레지스트리의 기술 프로필 생성"],"es":["Investigación de tecnologías emergentes como Bun","Validación de la documentación de Kubernetes","Creación de perfiles de tecnología para el registro de habilidades"],"fr":["Recherche de technologies émergentes comme Bun","Validation de la documentation Kubernetes","Création de profils de technologie pour le registre des compétences"],"de":["Recherche nach aufkommenden Technologien wie Bun","Validierung der Kubernetes-Dokumentation","Erstellung von Technologieprofilen für das Fähigkeitsregister"],"pt":["Pesquisando tecnologias emergentes como Bun","Validando documentação do Kubernetes","Criando perfis de tecnologia para o registro de habilidades"],"ru":["Изучение появляющихся технологий, таких как Bun","Проверка документации Kubernetes","Создание профилей технологий для реестра навыков"],"ar":["البحث في التكنولوجيا الناشئة مثل Bun","التحقق من توثيق Kubernetes","إنشاء ملفات تعريف التكنولوجيا لسجل المهارات"]},"limitations":{"en":["Requires WebSearch functionality","Dependent on publicly available web data"],"zh":["需要 WebSearch 功能","依赖于公开可用的 Web 数据"],"ja":["WebSearch 機能が必要","公開可能な Web データに依存"],"ko":["웹 검색 기능이 필요","공개 가능한 웹 데이터에 의존"],"es":["Requiere la funcionalidad de búsqueda web","Dependiente de los datos web públicamente disponibles"],"fr":["Nécessite la fonctionnalité de recherche web","Dépend des données web publiquement disponibles"],"de":["Benötigt die Websuchfunktion","Abhängig von öffentlich verfügbaren Webdaten"],"pt":["Exige funcionalidade de pesquisa na web","Dependente de dados públicos da web"],"ru":["Требует функциональности веб-поиска","Зависит от публично доступных веб-данных"],"ar":["يتطلب وظيفة بحث على الويب","يعتمد على بيانات الويب العامة"]},"version":3},"contentHash":"17dcf823473304b6256e4a7382a1e5f324562fe15fb4dbb3177e1c9429d04968","qualityScore":50}');
